private typealias DisplayBrightnessCallback = @convention(c) (UnsafeRawPointer?, UnsafeMutableRawPointer?, UnsafeRawPointer?, UnsafeRawPointer?, UnsafeRawPointer?) -> Void
@_silgen_name("rium_observe_display_brightness")
private func rustObserveDisplayBrightness(_ display: UInt32, _ callback: DisplayBrightnessCallback?) -> Int32
private let displayBrightnessChanged: DisplayBrightnessCallback = { _, observer, _, _, _ in
    guard let display = UInt32(exactly: UInt(bitPattern: observer)), display != 0 else { return }
    DispatchQueue.main.async {
        (NSApp?.delegate as? AppDelegate)?.model.handleBrightnessChange(on: display)
    }
}
