struct Account: Identifiable {
    let id: String
    var name: String
    var usage = "확인 전"
    var detail = ""
    var additionalUsage: [String] = []
    var connected = false
    var remaining: CodexRemainingWindow?
}
struct CodexRemainingWindow {
    let percent: Int
    let reset: Date?

    init?(_ payload: Any?) {
        guard let window = payload as? [String: Any], let used = window["usedPercent"] as? Double,
              (0...100).contains(used) else { return nil }
        percent = Int((100 - used).rounded())
        if let time = window["resetsAt"] as? Double, time.isFinite, time > 0 {
            reset = Date(timeIntervalSince1970: time)
        } else {
            reset = nil
        }
    }
}
struct ClipboardMetadata: Decodable { let id: UInt64; let kind: String; let size: Int; let pinned: Bool?; let copiedAtMs: UInt64? }
func clipboardImageSize(_ count: Int) -> String {
    if count < 1024 { return "\(max(0, count))바이트" }
    if count < 1024 * 1024 { return String(format: "%.1f KB", Double(count) / 1024) }
    return String(format: "%.1f MB", Double(count) / (1024 * 1024))
}
struct ClipboardRecord: Identifiable {
    enum Content: Equatable { case text(String), files([URL]), image(Data, NSPasteboard.PasteboardType) }
    let id: UInt64
    let content: Content
    var pinned: Bool = false
    var copiedAt: Date? = nil

    func dragProvider() -> NSItemProvider {
        switch content {
        case .text(let value):
            return NSItemProvider(object: value as NSString)
        case .files(let urls):
            guard urls.count == 1 else { return NSItemProvider() }
            return NSItemProvider(object: urls[0] as NSURL)
        case .image(let data, let type):
            let provider = NSItemProvider()
            provider.suggestedName = "클립보드 이미지"
            provider.registerDataRepresentation(forTypeIdentifier: type.rawValue, visibility: .all) { completion in
                completion(data, nil)
                return nil
            }
            return provider
        }
    }
}

struct PendingClipboardRetry {
    let generation: UInt64
    var removed: [ClipboardRecord.Content] = []
    func allows(_ content: ClipboardRecord.Content) -> Bool { !removed.contains(content) }
}

enum ClipboardFilter: String, CaseIterable, Identifiable {
    case all, text, link, image, color
    var id: String { rawValue }
    var title: String {
        switch self { case .all: return "전체"; case .text: return "텍스트"; case .link: return "링크"; case .image: return "이미지"; case .color: return "색상" }
    }
}

// shortcut: hex and integer RGB only; add percentages or alpha after reference verification.
func clipboardColor(_ value: String) -> NSColor? {
    let text = value.trimmingCharacters(in: .whitespacesAndNewlines)
    if text.hasPrefix("#") {
        let digits = String(text.dropFirst())
        guard [3, 6].contains(digits.count), digits.unicodeScalars.allSatisfy({ (48...57).contains($0.value) || (65...70).contains($0.value) || (97...102).contains($0.value) }),
              let number = UInt32(digits, radix: 16) else { return nil }
        let r: UInt32, g: UInt32, b: UInt32
        if digits.count == 3 { r = ((number >> 8) & 15) * 17; g = ((number >> 4) & 15) * 17; b = (number & 15) * 17 }
        else { r = (number >> 16) & 255; g = (number >> 8) & 255; b = number & 255 }
        return NSColor(srgbRed: CGFloat(r) / 255, green: CGFloat(g) / 255, blue: CGFloat(b) / 255, alpha: 1)
    }
    let pattern = #"(?i)^rgb\(\s*(\d{1,3})\s*,\s*(\d{1,3})\s*,\s*(\d{1,3})\s*\)$"#
    guard let regex = try? NSRegularExpression(pattern: pattern),
          let match = regex.firstMatch(in: text, range: NSRange(text.startIndex..., in: text)) else { return nil }
    let source = text as NSString
    let values = (1...3).map { Int(source.substring(with: match.range(at: $0))) ?? -1 }
    guard values.allSatisfy({ (0...255).contains($0) }) else { return nil }
    return NSColor(srgbRed: CGFloat(values[0]) / 255, green: CGFloat(values[1]) / 255, blue: CGFloat(values[2]) / 255, alpha: 1)
}

func clipboardKind(_ record: ClipboardRecord) -> ClipboardFilter {
    switch record.content {
    case .image: return .image
    case .files: return .link
    case .text(let value):
        if clipboardColor(value) != nil { return .color }
        let text = value.trimmingCharacters(in: .whitespacesAndNewlines)
        if let url = URLComponents(string: text), let scheme = url.scheme?.lowercased(),
           ["http", "https"].contains(scheme), let host = url.host, !host.isEmpty { return .link }
        return .text
    }
}

func clipboardMatches(_ record: ClipboardRecord, filter: ClipboardFilter, query: String) -> Bool {
    guard filter == .all || clipboardKind(record) == filter else { return false }
    let needle = query.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !needle.isEmpty else { return true }
    switch record.content {
    case .text(let value): return value.localizedCaseInsensitiveContains(needle)
    case .files(let urls): return urls.contains { $0.lastPathComponent.localizedCaseInsensitiveContains(needle) }
    case .image: return "이미지".localizedCaseInsensitiveContains(needle)
    }
}

