func clipboardPasteTargetMatches(frontmost: pid_t?, focused: pid_t, own: pid_t, secure: Bool) -> Bool {
    guard let frontmost = frontmost, frontmost > 0, frontmost != own else { return false }
    return frontmost == focused && !secure
}
