enum ClipboardPeekKind: Equatable { case copied, pasted }
struct ClipboardPeekContent: Equatable {
    let text: String
    let symbol: String
}
func clipboardPeekContent(_ content: ClipboardRecord.Content) -> ClipboardPeekContent? {
    let value: String
    let symbol: String
    switch content {
    case .text(let text):
        value = text
        switch clipboardKind(ClipboardRecord(id: 0, content: content)) {
        case .link: symbol = "link"
        case .color: symbol = "eyedropper"
        default: symbol = "doc.on.clipboard"
        }
    case .files(let urls):
        guard let first = urls.first else { return nil }
        value = urls.count == 1 ? first.lastPathComponent : "\(first.lastPathComponent) 외 \(urls.count - 1)개"
        symbol = "doc"
    case .image:
        return ClipboardPeekContent(text: "이미지", symbol: "photo.on.rectangle.angled")
    }
    let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !trimmed.isEmpty else { return nil }
    let preview = trimmed.prefix(42).map { character in
        character.isNewline || character.unicodeScalars.contains { $0.value < 0x20 || (0x7f...0x9f).contains($0.value) }
            ? " " : String(character)
    }.joined()
    return ClipboardPeekContent(text: preview, symbol: symbol)
}
