struct AgentToolEvent: Equatable {
    let marker: UInt64
    let activity: String
    var kind: Int32? = nil
    var offset: UInt64? = nil
    var transcriptIdentity: String? = nil
    var transcriptLength: UInt64? = nil
    var verifiedAnchorMarker: UInt64? = nil
    var verifiedAnchorOffset: UInt64? = nil
}
func unseenAgentToolEvents(markers: inout [UInt64], current: [AgentToolEvent]) -> [AgentToolEvent] {
    var known = Set(markers)
    var fresh: [AgentToolEvent] = []
    for event in current where known.insert(event.marker).inserted {
        fresh.append(event); markers.append(event.marker)
    }
    if markers.count > 64 { markers.removeFirst(markers.count - 64) }
    return fresh
}
func agentToolHistoryChanged(previous: AgentToolEvent?, current: AgentToolEvent?) -> Bool {
    if let oldID = previous?.transcriptIdentity, let newID = current?.transcriptIdentity, oldID != newID { return true }
    if let oldLength = previous?.transcriptLength, let newLength = current?.transcriptLength, newLength < oldLength { return true }
    return false
}
func actionableAgentToolEvents(previous: [AgentToolEvent], current: [AgentToolEvent], unseen: [AgentToolEvent]) -> [AgentToolEvent] {
    if agentToolHistoryChanged(previous: previous.last, current: current.last) { return [] }
    if let marker = previous.last?.marker, let anchor = current.lastIndex(where: { $0.marker == marker }) {
        let later = Set(current.dropFirst(anchor + 1).map(\.marker))
        return unseen.filter { later.contains($0.marker) }
    }
    if let prior = previous.last, let identity = prior.transcriptIdentity, let offset = prior.offset,
       let oldLength = prior.transcriptLength, let latest = current.last,
       latest.transcriptIdentity == identity, let newLength = latest.transcriptLength,
       latest.verifiedAnchorMarker == prior.marker, latest.verifiedAnchorOffset == offset,
       offset < oldLength, newLength >= oldLength {
        return unseen.filter { $0.transcriptIdentity == identity && $0.transcriptLength == newLength &&
                               $0.offset.map { $0 >= oldLength && $0 < newLength } == true }
    }
    guard previous.isEmpty else { return [] }
    guard let last = current.last, unseen.contains(where: { $0.marker == last.marker }) else { return [] }
    return [last]
}
func agentToolBurstIsFresh(queuedAt: TimeInterval, now: TimeInterval) -> Bool {
    // shortcut: the two-second limit favors current activity until the reference's backlog policy is known.
    queuedAt.isFinite && now.isFinite && now >= queuedAt && now - queuedAt <= 2
}
func agentToolBurstDelay(queuedAt: TimeInterval, now: TimeInterval, tokensRemaining: Int) -> TimeInterval {
    guard agentToolBurstIsFresh(queuedAt: queuedAt, now: now), tokensRemaining > 0 else { return 0 }
    return min(0.07, max(0, 2 - (now - queuedAt)) / Double(tokensRemaining))
}
func agentPulseCanAnimate(active: Bool, waiting: Bool, completed: Bool, reduceMotion: Bool) -> Bool {
    active && !waiting && !completed && !reduceMotion
}
