struct AgentSessionKey: Hashable {
    let source: String
    let id: String
    init(source: String, id: String) { self.source = source; self.id = id }
    init(_ item: AgentActivity) { source = item.source; id = item.id }
}
enum AgentSwitcherKey: Equatable {
    case open, move(Int32), confirm, cancel

    init?(code: UInt16, flags: NSEvent.ModifierFlags, repeated: Bool, active: Bool) {
        let modifiers = flags.intersection([.control, .option, .command, .shift])
        if code == 49 && modifiers == [.control, .option] && !repeated {
            self = .open
            return
        }
        guard active, modifiers.isEmpty else { return nil }
        switch code {
        case 125: self = .move(1)
        case 126: self = .move(-1)
        case 36, 76: self = .confirm
        case 53: self = .cancel
        default: return nil
        }
    }
}
func sameAgentSession(_ first: AgentActivity, _ second: AgentActivity) -> Bool {
    AgentSessionKey(first) == AgentSessionKey(second)
