struct RecentAgentTools {
    private struct Record {
        var markers: [UInt64] = []
        var lastEvent: AgentToolEvent?
        var observedAt: TimeInterval?
        var seen: TimeInterval
    }
    private var sessions: [AgentSessionKey: Record] = [:]
    func anchors() -> [[String: Any]] {
        sessions.sorted { $0.value.seen > $1.value.seen }.prefix(64).compactMap { entry in
            guard let event = entry.value.lastEvent, let offset = event.offset, let identity = event.transcriptIdentity else { return nil }
            return ["id": entry.key.id, "source": entry.key.source, "identity": identity, "offset": offset, "marker": event.marker]
        }
    }
    mutating func observe(_ item: AgentActivity, now: TimeInterval) -> TimeInterval? {
        guard now.isFinite, now >= 0, !item.id.isEmpty else { return nil }
        sessions = sessions.filter { now >= $0.value.seen && now - $0.value.seen <= 15 }
        let key = item.sessionKey
        let existed = sessions[key] != nil
        var record = sessions[key] ?? Record(seen: now)
        let replaced = agentToolHistoryChanged(previous: record.lastEvent, current: item.toolEvents.last)
        if replaced { record.markers.removeAll(); record.lastEvent = nil; record.observedAt = nil }
        let fresh = unseenAgentToolEvents(markers: &record.markers, current: item.toolEvents)
        let actionable = actionableAgentToolEvents(previous: record.lastEvent.map { [$0] } ?? [], current: item.toolEvents, unseen: fresh)
        let last = item.toolEvents.last?.marker
        if last == nil { record.observedAt = nil }
        else if existed, !replaced, let last = last, actionable.contains(where: { $0.marker == last }) { record.observedAt = now }
        else if !fresh.isEmpty || record.lastEvent?.marker != last { record.observedAt = nil }
        if let latest = item.toolEvents.last { record.lastEvent = latest }
        record.seen = now; sessions[key] = record
        if sessions.count > 256, let oldest = sessions.min(by: { $0.value.seen < $1.value.seen })?.key { sessions.removeValue(forKey: oldest) }
        return record.observedAt
    }
    mutating func clear() { sessions.removeAll() }
}
