func agentIsRunning(_ state: String) -> Bool {
    ["작업 중", "활동 감지", "도구 실행 감지", "도구 실행 중"].contains(state)
}
func agentEnteredStall(_ item: AgentActivity, previous: [AgentActivity], initialized: Bool) -> Bool {
    initialized && item.state.hasPrefix("응답 지연") &&
        previous.contains { sameAgentSession($0, item) && !$0.state.hasPrefix("응답 지연") }
}
func transientPeekMatches(_ peek: AgentTransientPeek, activity: AgentActivity) -> Bool {
    guard sameAgentSession(peek.agent, activity) else { return false }
    switch peek.kind {
    case .running: return agentIsRunning(activity.state)
    case .completed: return activity.state == "완료"
    case .failed: return activity.state == "실패"
    case .interrupted: return activity.state == "중단됨"
    case .stalled: return activity.state.hasPrefix("응답 지연")
    }
}
func visiblePeekRemaining(_ remaining: TimeInterval, elapsed: TimeInterval, visible: Bool) -> TimeInterval {
    guard remaining.isFinite, elapsed.isFinite else { return 0 }
    return max(0, remaining - (visible ? max(0, elapsed) : 0))
}
// Keep the bounded age from advancing while the longer focus alarm covers the peek.
func agentTransientStart(_ startedAt: TimeInterval, elapsed: TimeInterval, focusCovered: Bool) -> TimeInterval {
    guard startedAt.isFinite, elapsed.isFinite, elapsed >= 0 else { return startedAt }
    return startedAt + (focusCovered ? elapsed : 0)
}
// shortcut: the maximum age needs comparison with the reference interruption policy.
func agentTransientRemaining(_ remaining: TimeInterval, elapsed: TimeInterval, visible: Bool, age: TimeInterval) -> TimeInterval {
    guard age.isFinite, age >= 0, age < 30 else { return 0 }
    return visiblePeekRemaining(remaining, elapsed: elapsed, visible: visible)
}
