    let session = item.source == "claude" && item.id.hasPrefix("claude-") ? String(item.id.dropFirst("claude-".count)) : item.id
    return "peek:\(item.source):\(session)"
}
// Prefer a task needing attention or currently active over a completed one.
func agentStateRank(_ state: String) -> Int {
    if state.hasPrefix("승인 대기") { return 0 }
    if state.hasPrefix("질문 대기") || state.hasPrefix("입력 대기") { return 1 }
    return ["도구 실행 감지", "작업 중", "활동 감지", "실패", "응답 지연 추정", "완료", "중단됨", "최근 활동"]
        .firstIndex(of: state == "도구 실행 중" ? "도구 실행 감지" : state).map { $0 + 2 } ?? 10
}
func collapsedAgent(_ items: [AgentActivity]) -> AgentActivity? {
    return items.enumerated().min { lhs, rhs in
        let left = agentStateRank(lhs.element.state)
        let right = agentStateRank(rhs.element.state)
        return left == right ? lhs.offset < rhs.offset : left < right
    }?.element
}
func externalAgentPrecedesPersonal(_ state: String, assistant: AssistantIndicator, finishing: Bool, outcome: String) -> Bool {
    let personal: String
    switch assistant {
    case .approval: personal = "승인 대기"
    case .question: personal = "질문 대기"
    case .working: personal = "작업 중"
    case .off:
        guard finishing else { return true }
        personal = outcome == "failed" ? "실패" : (outcome == "interrupted" ? "중단됨" : "완료")
    }
    return agentStateRank(state) <= agentStateRank(personal)
}
func agentNeedsAttention(_ state: String) -> Bool {
    state.hasPrefix("승인 대기") || state.hasPrefix("질문 대기") || state.hasPrefix("입력 대기")
}
func homeBandAgentRank(_ item: AgentActivity) -> Int? {
    if agentNeedsAttention(item.state) { return 0 }
    if agentIsRunning(item.state) { return 1 }
    if item.state == "완료", let age = item.ageSeconds, age <= 25 { return 2 }
    return nil
}
private func lumiMood(waiting: Bool, state: String) -> Int32 {
    if state.hasPrefix("질문 대기") || state.hasPrefix("입력 대기") { return 3 }
    if waiting || state.hasPrefix("승인 대기") { return 2 }
    if state == "완료" { return 4 }
    if state == "실패" || state == "오류" { return 5 }
    if state == "재시도" { return 6 }
    if state == "중단됨" { return 7 }
    if state.hasPrefix("응답 지연") { return 8 }
    if agentIsRunning(state) { return 1 }
    return 0
}
func agentCanInterrupt(_ state: String) -> Bool {
    agentNeedsAttention(state) || agentIsRunning(state)
}
func stopStillPending(_ session: AgentSessionKey, in items: [AgentActivity]) -> Bool {
    let matching = items.filter { $0.sessionKey == session }
    return matching.isEmpty || matching.contains { !["완료", "실패", "중단됨"].contains($0.state) }
}
func activeAgentSessionCount(_ items: [AgentActivity], assistant: AssistantIndicator = .off, assistantThread: String? = nil) -> Int32 {
    let active = items.filter {
        agentIsRunning($0.state) || agentNeedsAttention($0.state)
    }
    let sessions = Set(active.map(\.sessionKey))
    let alreadyObserved = assistantThread.map { sessions.contains(AgentSessionKey(source: "codex", id: $0)) } ?? false
    return Int32(clamping: sessions.count + (assistant == .off || alreadyObserved ? 0 : 1))
}

// AgentStore's running, needs-you, done and hard-failure colors recovered
// from the installed reference binary.
// shortcut: mapping Rium-only states to this palette needs reference comparison.
enum AgentStatusPalette {
    static let running = Color(red: 0.30, green: 0.68, blue: 1.00)
    static let attention = Color(red: 1.00, green: 0.55, blue: 0.05)
    static let done = Color(red: 0.20, green: 0.82, blue: 0.48)
    static let failure = Color(red: 1.00, green: 0.30, blue: 0.30)
}

func agentStateColor(_ state: String) -> Color {
    if agentNeedsAttention(state) { return AgentStatusPalette.attention }
    if state == "실패" { return AgentStatusPalette.failure }
    if state == "중단됨" || state == "최근 활동" || state.hasPrefix("응답 지연") { return .gray }
    if state == "완료" { return AgentStatusPalette.done }
    if agentIsRunning(state) { return AgentStatusPalette.running }
    return .gray
}
// Stable per-session offset, so multiple characters do not blink in lockstep.
// The source pose combines its time and a per-character phase in seconds.
func agentAnimationPhase(_ id: String) -> Double {
    guard !id.isEmpty else { return 0 }
    var hash: UInt64 = 14_695_981_039_346_656_037
    for byte in id.utf8 { hash = (hash ^ UInt64(byte)) &* 1_099_511_628_211 }
    return Double(hash % 10_000) / 10_000
}
struct AgentLightTransition {
    let session: AgentSessionKey
    let kind: NotchLightCue.Kind
    var agentID: String { session.id }
}
func prioritizedAgentWaveTransitions(_ transitions: [AgentLightTransition]) -> [AgentLightTransition] {
    func priority(_ kind: NotchLightCue.Kind) -> Int {
        switch kind {
        case .agentApproval, .agentQuestion: return 0
        case .agentFailed, .agentInterrupted: return 1
        case .agentDone: return 2
        case .agentMessage: return 3
        case .agentRunning: return 4
        default: return 5
        }
    }
    // shortcut: ordering simultaneous snapshots by urgency is inferred from the existing cue priority.
    return transitions.enumerated().sorted {
        let left = priority($0.element.kind), right = priority($1.element.kind)
        return left == right ? $0.offset < $1.offset : left < right
    }.map(\.element)
}
func agentRecoveryAllows(_ transition: AgentLightTransition, previous: [AgentActivity]) -> Bool {
    if transition.kind == .agentApproval || transition.kind == .agentQuestion { return true }
    guard let prior = previous.first(where: { $0.sessionKey == transition.session }) else { return false }
    return transition.kind != .agentMessage || prior.messageMarker != nil
}
func agentSnapshotRows(_ event: [String: Any]) -> [[String: Any]]? {
    guard event["event"] as? String == "result", let rows = event["data"] as? [[String: Any]],
          rows.allSatisfy({ row in
              guard let id = row["id"] as? String, !id.isEmpty,
                    row["project"] is String, let state = row["state"] as? String, !state.isEmpty else { return false }
              return true
          }) else { return nil }
    return rows
}
enum AgentCommandOutcome: Equatable { case accepted, queued, unknown, failed }
func agentCommandOutcome(_ event: [String: Any]) -> AgentCommandOutcome {
    let kind = event["event"] as? String
    let status = (event["data"] as? [String: Any])?["status"] as? String
    if kind == "result" && status == "accepted" { return .accepted }
    if kind == "result" && status == "queued" { return .queued }
    if kind == "result" || status == "unknown" || status == "accepted" || status == "queued" { return .unknown }
    return .failed
}
func agentScreenWaveCategory(_ kind: NotchLightCue.Kind) -> Int32? {
    switch kind {
    // shortcut: the reference's pacing categories for message and interrupted
    // events are unknown; share the nearest running and failure limits.
    case .agentRunning, .agentMessage: return 0
    case .agentApproval, .agentQuestion: return 1
    case .agentDone: return 2
    case .agentFailed, .agentInterrupted: return 3
    default: return nil
    }
}
func agentHasNewQuestions(previous: AgentActivity?, current: AgentActivity) -> Bool {
    guard let previous = previous, previous.id == current.id, previous.source == current.source else { return false }
    let known = Set(previous.pendingQuestions.map(\.id))
    return current.pendingQuestions.contains { !known.contains($0.id) }
}
private struct ObservedQuestionKey: Hashable {
    let source: String
    let session: String
    let question: String
}
struct RecentAgentQuestions {
    private var seen: [ObservedQuestionKey: TimeInterval] = [:]
    mutating func observe(_ items: [AgentActivity], at now: TimeInterval) -> Set<AgentSessionKey> {
        guard now.isFinite else { return [] }
        // shortcut: retention and capacity are provisional; the reference policy is unknown.
        seen = seen.filter { now >= $0.value && now - $0.value < 900 }
        var newSessions = Set<AgentSessionKey>()
        for item in items {
            for question in item.pendingQuestions {
                let key = ObservedQuestionKey(source: item.source, session: item.id, question: question.id)
                if seen[key] == nil { newSessions.insert(AgentSessionKey(item)) }
                seen[key] = now
            }
        }
        if seen.count > 1024 {
            for entry in seen.sorted(by: { $0.value < $1.value }).prefix(seen.count - 1024) { seen.removeValue(forKey: entry.key) }
        }
        return newSessions
    }
}
struct RecentAgentSnapshots {
    private var seen: [AgentSessionKey: (snapshot: AgentActivity, at: TimeInterval, markerAt: TimeInterval?)] = [:]
    mutating func previous(_ previous: [AgentActivity], current: [AgentActivity], at now: TimeInterval) -> [AgentActivity] {
        guard now.isFinite, now >= 0 else { return previous }
        // shortcut: brief disappearance is treated as the same observation for 15 seconds; verify the reference's policy.
        seen = seen.filter { now >= $0.value.at && now - $0.value.at <= 15 }
        var result = previous
        for index in result.indices where result[index].messageMarker == nil {
            if let record = seen[result[index].sessionKey], let markerAt = record.markerAt,
               now >= markerAt, now - markerAt <= 15 {
                result[index].messageMarker = record.snapshot.messageMarker
                result[index].messageAliases = record.snapshot.messageAliases
            }
        }
        var present = Set(previous.map(\.sessionKey))
        for item in current where present.insert(item.sessionKey).inserted && !agentNeedsAttention(item.state) {
            if let stored = seen[item.sessionKey] {
                var snapshot = stored.snapshot
                if stored.markerAt.map({ now >= $0 && now - $0 <= 15 }) != true {
                    snapshot.messageMarker = nil; snapshot.messageAliases = []
                }
                result.append(snapshot)
            }
        }
        for item in current {
            let old = seen[item.sessionKey]
            let keepMarker = item.messageMarker == nil && (old?.markerAt).map { now >= $0 && now - $0 <= 15 } == true
            let snapshot = AgentActivity(id: item.id, project: "", state: item.state, activity: "", source: item.source,
                                         messageMarker: keepMarker ? old?.snapshot.messageMarker : item.messageMarker,
                                         messageAliases: keepMarker ? (old?.snapshot.messageAliases ?? []) : item.messageAliases)
            let markerAt = item.messageMarker == nil ? (keepMarker ? old?.markerAt : nil) : now
            seen[item.sessionKey] = (snapshot, now, markerAt)
        }
        if seen.count > 256 {
            for entry in seen.sorted(by: { $0.value.at < $1.value.at }).prefix(seen.count - 256) { seen.removeValue(forKey: entry.key) }
        }
        return result
    }
    mutating func clear() { seen.removeAll() }
}
func agentLightTransitions(previous: [AgentActivity], current: [AgentActivity], initialized: Bool, newQuestionSessions: Set<AgentSessionKey>? = nil) -> [AgentLightTransition] {
    guard initialized else { return [] }
    func category(_ state: String) -> NotchLightCue.Kind? {
        if state.hasPrefix("질문 대기") || state.hasPrefix("입력 대기") { return .agentQuestion }
        if agentNeedsAttention(state) { return .agentApproval }
        if agentIsRunning(state) { return .agentRunning }
        if state == "완료" { return .agentDone }
        if state == "실패" { return .agentFailed }
        if state == "중단됨" { return .agentInterrupted }
        return nil
    }
    let old = Dictionary(previous.map { (AgentSessionKey($0), $0) }, uniquingKeysWith: { _, last in last })
    var seen = Set<AgentSessionKey>()
    var changes: [AgentLightTransition] = []
    for item in current where seen.insert(AgentSessionKey(item)).inserted {
        let session = AgentSessionKey(item)
        if let next = category(item.state) {
            let prior = old[session]
            if prior.flatMap({ category($0.state) }) != next ||
               (next == .agentQuestion && (newQuestionSessions?.contains(session) ?? agentHasNewQuestions(previous: prior, current: item))) {
                changes.append(AgentLightTransition(session: session, kind: next))
            }
        }
        if let prior = old[session], let marker = item.messageMarker,
           prior.messageMarker != marker, !prior.messageAliases.contains(marker),
           !(prior.messageMarker.map { item.messageAliases.contains($0) } ?? false) {
            changes.append(AgentLightTransition(session: session, kind: .agentMessage))
        }
    }
    return changes
}
func agentArrivalKinds(_ transitions: [AgentLightTransition]) -> [NotchLightCue.Kind] {
    let changes = transitions.map(\.kind)
    var events: [NotchLightCue.Kind] = []
    if changes.contains(.agentApproval) { events.append(.agentApproval) }
    if changes.contains(.agentQuestion) { events.append(.agentQuestion) }
    if changes.contains(.agentFailed) { events.append(.agentFailed) }
    if changes.contains(.agentInterrupted) { events.append(.agentInterrupted) }
    if changes.contains(.agentDone) { events.append(.agentDone) }
    if changes.contains(.agentMessage) { events.append(.agentMessage) }
    if changes.contains(.agentRunning) { events.append(.agentRunning) }
    return events
}
func agentArrivals(previous: [AgentActivity], current: [AgentActivity], initialized: Bool, newQuestionSessions: Set<AgentSessionKey>? = nil) -> [NotchLightCue.Kind] {
    agentArrivalKinds(agentLightTransitions(previous: previous, current: current, initialized: initialized, newQuestionSessions: newQuestionSessions))
}
func agentArrival(previous: [AgentActivity], current: [AgentActivity], initialized: Bool) -> NotchLightCue.Kind? {
    agentArrivals(previous: previous, current: current, initialized: initialized).first
}
