func lyricsShouldRefresh(sameTrack: Bool, retryAfter: TimeInterval?, now: TimeInterval) -> Bool {
    guard sameTrack else { return true }
    guard let retryAfter = retryAfter, retryAfter.isFinite, now.isFinite else { return false }
    return now >= retryAfter
