func parseLyrics(synced: String?, plain: String?) -> [LyricLine] {
    let timedBytes = Array((synced ?? "").utf8), plainBytes = Array((plain ?? "").utf8)
    let result = timedBytes.withUnsafeBufferPointer { timed in
        plainBytes.withUnsafeBufferPointer { plain in
            rustLyricsParse(timed.baseAddress, timed.count, plain.baseAddress, plain.count)
        }
    }
    guard let result = result else { return [] }
    defer { rustLyricsFree(result) }
    let data = Data(String(cString: result).utf8)
    guard let rows = (try? JSONSerialization.jsonObject(with: data)) as? [[String: Any]] else { return [] }
    return rows.compactMap { row in
        guard let id = row["id"] as? Int, let text = row["text"] as? String else { return nil }
        return LyricLine(id: id, time: row["time"] as? Double, text: text)
    }
}
