struct NotchDisplayPreference {
    let defaults: UserDefaults
    private let storageKey = "rium.notch.display"

    func load(available: [NotchDisplayChoice] = []) -> String? {
        let stored = defaults.object(forKey: storageKey)
        if let value = stored as? String, let uuid = UUID(uuidString: value) { return uuid.uuidString }
        guard let number = stored as? NSNumber, CFGetTypeID(number) != CFBooleanGetTypeID(),
              let id = UInt32(exactly: number.doubleValue), id != 0 else { return nil }
        if let choice = available.first(where: { $0.id == id }), UUID(uuidString: choice.key) != nil {
            save(choice)
            return choice.key
        }
        return String(id)
    }

    func save(_ choice: NotchDisplayChoice?) {
        if let choice {
            if let uuid = UUID(uuidString: choice.key) {
                defaults.set(uuid.uuidString, forKey: storageKey)
            } else {
                defaults.set(NSNumber(value: choice.id), forKey: storageKey)
            }
        } else {
            defaults.removeObject(forKey: storageKey)
        }
    }
}

