func calculateCollapsedNotchSize(cameraWidth: CGFloat, cameraHeight: CGFloat, screenWidth: CGFloat, agent: Bool, timer: Bool, music: Bool, notification: Bool = false, focusAlarm: Bool = false, shelf: Bool = false, shelfMinimumWidth: CGFloat = 0) -> CGSize {
    withUnsafeTemporaryAllocation(of: Double.self, capacity: 2) { size in
        guard rustNotchRegularCompactSize(Double(cameraWidth), Double(cameraHeight), Double(screenWidth),
                                         Double(shelfMinimumWidth), agent ? 1 : 0, timer ? 1 : 0, music ? 1 : 0,
                                         notification ? 1 : 0, focusAlarm ? 1 : 0, shelf ? 1 : 0, size.baseAddress) == 0
        else { return .zero }
        return CGSize(width: size[0], height: size[1])
    }
}
func notchGeometryClose(_ size: CGSize, corners: NotchCorners, targetSize: CGSize,
                        targetCorners: NotchCorners, tolerance: CGFloat) -> Bool {
    guard tolerance.isFinite, tolerance > 0,
          size.width.isFinite, size.height.isFinite, targetSize.width.isFinite, targetSize.height.isFinite,
          corners.bottom.isFinite, corners.shoulder.isFinite, targetCorners.bottom.isFinite, targetCorners.shoulder.isFinite else { return false }
    return abs(size.width - targetSize.width) < tolerance && abs(size.height - targetSize.height) < tolerance
        && abs(corners.bottom - targetCorners.bottom) < tolerance && abs(corners.shoulder - targetCorners.shoulder) < tolerance
}

// The physical camera remains opaque even when a compact preview is narrow.
// Never make the camera gap smaller merely to give both sides more room.
func collapsedHeaderPadding(width: CGFloat, cameraWidth: CGFloat) -> CGFloat {
    let width = width.isFinite ? max(0, width) : 0
    let camera = cameraWidth.isFinite ? max(0, cameraWidth) : 0
    return min(26, max(0, (width - min(width, camera + 8)) / 2))
}
func notchContentHorizontalPadding(floating: Bool, visualExpanded: Bool, assistantPeek: Bool,
                                   width: CGFloat, cameraWidth: CGFloat) -> CGFloat {
    if visualExpanded { return 26 }
    if floating { return 8 }
    if assistantPeek { return 4 }
    return cameraWidth <= 0 ? 26 : collapsedHeaderPadding(width: width, cameraWidth: cameraWidth)
}
func collapsedHeaderMetrics(width: CGFloat, cameraWidth: CGFloat, padding: CGFloat? = nil) -> (side: CGFloat, gap: CGFloat) {
    let width = width.isFinite ? max(0, width) : 0
    let camera = cameraWidth.isFinite ? max(0, cameraWidth) : 0
    let inset = padding.flatMap { $0.isFinite ? min(width / 2, max(0, $0)) : nil } ?? collapsedHeaderPadding(width: width, cameraWidth: camera)
    let available = max(0, width - 2 * inset)
    let gap = min(available, camera + 8)
    return (max(0, (available - gap) / 2), gap)
}
func agentPeekBandMetrics(width: CGFloat, cameraWidth: CGFloat, floating: Bool) -> (side: CGFloat, gap: CGFloat) {
    guard width.isFinite, cameraWidth.isFinite else { return (0, 0) }
    let available = max(0, width)
    let gap = floating ? 0 : min(available, max(0, cameraWidth))
    return ((available - gap) / 2, gap)
}
// RootView.expandFromHover uses the remaining part of a 0.34 s cooldown;
// when no close has just happened, expansion is immediate.
func hoverReopenWait(lastCollapse: TimeInterval?, now: TimeInterval) -> TimeInterval {
    guard let lastCollapse = lastCollapse else { return 0 }
    return rustNotchHoverReopenWait(now - lastCollapse)
}
func notchContainsScreenPoint(_ point: NSPoint, screen: NSRect, expanded: Bool, section: PanelSection, size: CGSize? = nil, corners: NotchCorners = .legacy) -> Bool {
    guard point.x >= screen.minX, point.x < screen.maxX,
          point.y >= screen.minY, point.y <= screen.maxY else { return false }
    let width = size?.width ?? notchWidth(expanded: expanded, displayWidth: screen.width)
    let height = size?.height ?? notchHeight(expanded: expanded, section: section)
    guard width.isFinite, height.isFinite, width > 0, height > 0 else { return false }
    let depth = screen.maxY - point.y
    let x = point.x - (screen.midX - width / 2)
    // During a transition the shoulder can reach beyond a short body.
    guard x >= 0, x <= width, depth <= max(height, corners.shoulder) else { return false }
    // The topmost pointer position can be exactly on the closed path boundary.
    let local = CGPoint(x: x, y: depth == 0 ? min(0.001, height / 2) : depth)
    return NotchSilhouette(corners: corners).path(in: CGRect(x: 0, y: 0, width: width, height: height)).contains(local)
}
func notchContainsDropApproach(_ point: NSPoint, screen: NSRect, size: CGSize, corners: NotchCorners) -> Bool {
    let inset: CGFloat = 14
    let approach = CGSize(width: size.width + inset * 2, height: size.height + inset)
    return notchContainsScreenPoint(point, screen: screen, expanded: false, section: .home, size: approach, corners: corners)
}
func pointerOutlineSize(rendered: CGSize?, target: CGSize) -> CGSize {
    guard let size = rendered, size.width.isFinite, size.height.isFinite, size.width > 0, size.height > 0 else { return target }
    return size
}
func notchContainsInteractivePoint(_ point: NSPoint, screen: NSRect, expanded: Bool, section: PanelSection,
                                   renderedSize: CGSize?, renderedCorners: NotchCorners?,
                                   targetSize: CGSize, targetCorners: NotchCorners) -> Bool {
    let displayedSize = pointerOutlineSize(rendered: renderedSize, target: targetSize)
    guard notchContainsScreenPoint(point, screen: screen, expanded: expanded, section: section,
                                  size: displayedSize, corners: renderedCorners ?? targetCorners) else { return false }
    // A shrinking wing is still visible briefly, but hovering it must not reopen the notch.
    return expanded || notchContainsScreenPoint(point, screen: screen, expanded: false, section: section,
                                                size: targetSize, corners: targetCorners)
}
