    if symbol.contains("sleet") { return symbol.contains("thunder") ? "비와 눈, 천둥" : "비와 눈" }
    if symbol.contains("snow") { return symbol.contains("thunder") ? "눈과 천둥" : "눈" }
    if symbol.contains("rain") { return symbol.contains("thunder") ? "비와 천둥" : "비" }
    if symbol.contains("thunder") { return "천둥" }
    if symbol.contains("fair") || symbol.contains("partlycloudy") { return "구름 조금" }
    if symbol.contains("cloudy") { return "흐림" }
    if symbol.contains("clear") { return "맑음" }
    if symbol.contains("fog") { return "안개" }
    return "날씨 정보 없음"
}
func weatherIcon(_ symbol: String) -> String {
    if symbol.contains("thunder") { return symbol.contains("rain") && !symbol.contains("sleet") ? "cloud.bolt.rain.fill" : "cloud.bolt.fill" }
    if symbol.contains("sleet") { return "cloud.sleet.fill" }
    if symbol.contains("snow") { return "cloud.snow.fill" }
    if symbol.contains("rain") { return "cloud.rain.fill" }
    if symbol.contains("fog") { return "cloud.fog.fill" }
    if symbol.contains("partlycloudy") || symbol.contains("fair") { return symbol.contains("night") ? "cloud.moon.fill" : "cloud.sun.fill" }
    if symbol.contains("cloudy") { return "cloud.fill" }
    if symbol.contains("clear") { return symbol.contains("night") ? "moon.stars.fill" : "sun.max.fill" }
    return "cloud.fill"
}
func weatherHours(_ rows: [[String: Any]]) -> [WeatherHour] {
    let parser = ISO8601DateFormatter()
    var seen = Set<String>()
    return rows.prefix(96).compactMap { row in
        guard let time = row["time"] as? String, let date = parser.date(from: time),
              let temperature = row["temperature"] as? Double, temperature.isFinite,
              seen.insert(time).inserted else { return nil }
        let precipitation = (row["precipitation"] as? Double).flatMap { $0.isFinite && $0 >= 0 ? $0 : nil }
        return WeatherHour(id: time, date: date, temperature: temperature, symbol: row["symbol"] as? String ?? "",
                           precipitation: precipitation, humidity: validWeatherHumidity(row["humidity"]), wind: validWeatherWind(row["wind"]))
    }.sorted { $0.date < $1.date }
}
func currentWeatherHour(_ hours: [WeatherHour], at date: Date) -> WeatherHour? {
    hours.last { $0.date <= date && date.timeIntervalSince($0.date) < 3600 }
}
func weatherHourLabel(_ date: Date, timeZoneID: String?) -> String {
    let formatter = DateFormatter(); formatter.locale = Locale(identifier: "ko_KR")
    formatter.timeZone = timeZoneID.flatMap(TimeZone.init(identifier:)) ?? .current
    formatter.dateFormat = "M/d HH시"
    return formatter.string(from: date)
}
func weatherGeocodeTimeoutApplies(expected: Int, current: Int, inProgress: Bool) -> Bool {
    inProgress && expected == current
}
func weatherMayAutoRefresh(inProgress: Bool, sinceAttempt: TimeInterval, cacheAge: TimeInterval) -> Bool {
    rustWeatherMayAutoRefresh(inProgress ? 1 : 0, sinceAttempt, cacheAge) == 1
}

func previousCurrentLocationWeather(cache: [String: Any]?, wasCurrent: Bool) -> (city: String, data: [String: Any], updated: Date, timeZoneID: String?)? {
    guard wasCurrent, let cache = cache, let city = cache["city"] as? String, !city.isEmpty,
          let updated = cache["updated"] as? Double, updated.isFinite,
          let data = cache["data"] as? [String: Any], let temperature = data["temperature"] as? Double, temperature.isFinite else { return nil }
    return (city, data, Date(timeIntervalSince1970: updated), cache["timezone"] as? String)
}

func notchShellState(expanded: Bool, detail: Bool, status: Bool, media: Bool, shelf: Bool = false) -> Int32 {
    rustNotchShellState(expanded ? 1 : 0, detail ? 1 : 0, status ? 1 : 0, media ? 1 : 0, shelf ? 1 : 0)
}

func assistantTerminalLight(outcome: String, status: String) -> NotchLightCue.Kind? {
    switch (outcome, status) {
    case ("completed", "응답 완료"): return .agentDone
    case ("failed", "작업 실패"): return .agentFailed
    case ("interrupted", "작업 중단됨"): return .agentInterrupted
    default: return nil
    }
}

func assistantBlocksTransientPeek(_ indicator: AssistantIndicator, finishing: Bool) -> Bool {
    finishing || indicator == .approval || indicator == .question
}

func normalizedMediaRate(_ rate: Double?) -> Double {
    guard let rate = rate, rate.isFinite, (-16...16).contains(rate) else { return 1 }
    return rate
}
func mediaCommandWasSent(_ event: [String: Any]) -> Bool {
    event["event"] as? String == "result" && (event["data"] as? [String: Any])?["sent"] as? Bool == true
}
enum SystemMediaKeyEvent: Equatable {
    case skip(forward: Bool, key: UInt32)
    case seekHeld(key: UInt32)
    case volumeNudge(direction: Int32)
    case brightnessNudge(direction: Int32)
}
func systemMediaKeyEvent(subtype: Int, data: Int) -> SystemMediaKeyEvent? {
    let bits = UInt32(truncatingIfNeeded: data)
    guard subtype == 8, (bits >> 8) & 0xff == 10 else { return nil }
    let key = bits >> 16
    switch key {
    case 0: return .volumeNudge(direction: 1)
    case 1: return .volumeNudge(direction: -1)
    case 2: return .brightnessNudge(direction: 1)
    case 3: return .brightnessNudge(direction: -1)
    default: break
    }
    if bits & 1 != 0 { return key == 19 || key == 20 ? .seekHeld(key: key) : nil }
    switch key {
    case 17, 19: return .skip(forward: true, key: key)
    case 18, 20: return .skip(forward: false, key: key)
    default: return nil
    }
}
struct MediaTrackIdentity {
    let identifier: String?
    let source: String?
    let title: String?
    let artist: String
    var identifierKind: String? = nil
    var parentSource: String? = nil
    var applicationIdentifier: String? { parentSource ?? source }
    func hasComparableIdentifier(to other: MediaTrackIdentity) -> Bool {
        identifier != nil && other.identifier != nil && identifierKind == other.identifierKind
    }
}
private func sameMediaApplication(_ previous: MediaTrackIdentity, _ current: MediaTrackIdentity) -> Bool? {
    guard let old = previous.applicationIdentifier, let new = current.applicationIdentifier else { return nil }
    if old == new { return true }
    if previous.parentSource != nil && current.parentSource != nil { return false }
    // The same helper may temporarily omit the parent ID while publishing metadata.
    guard let oldSource = previous.source, let newSource = current.source, oldSource != newSource else { return nil }
    return false
}
func mediaTrackChanged(_ previous: MediaTrackIdentity, _ current: MediaTrackIdentity) -> Bool {
    if sameMediaApplication(previous, current) == false { return true }
    if previous.hasComparableIdentifier(to: current) { return previous.identifier != current.identifier }
    guard let old = previous.title, let new = current.title else { return false }
    return old != new || (!previous.artist.isEmpty && !current.artist.isEmpty && previous.artist != current.artist)
}
func mediaSkipLanded(from previous: MediaTrackIdentity, to current: MediaTrackIdentity, age: TimeInterval) -> Bool {
    // shortcut: matching the HUD timeout to a player's metadata change is inferred.
    guard age.isFinite, (0...trackSkipWaitDuration).contains(age) else { return false }
    return sameMediaApplication(previous, current) == true && mediaTrackChanged(previous, current)
}
func trackSkipLandingDuration(shownFor: TimeInterval) -> TimeInterval {
    guard shownFor.isFinite, shownFor >= 0 else { return 1.5 }
    return max(1.1, 1.5 - shownFor)
}
func projectedMediaElapsed(base: Double, observed: Double, current: Double, duration: Double,
                           playing: Bool, rate: Double, uptime: Double) -> Double {
    guard duration.isFinite, duration >= 0 else { return 0 }
    let elapsed = playing && observed > 0 && uptime.isFinite
        ? base + max(0, uptime - observed) * normalizedMediaRate(rate) : current
    guard elapsed.isFinite else { return 0 }
    return duration > 0 ? min(duration, max(0, elapsed)) : max(0, elapsed)
}
func mediaDisplayPosition(known: Bool, editing: Bool, elapsed: Double, edited: Double, duration: Double) -> Double? {
    guard (known || editing), duration.isFinite, duration > 0 else { return nil }
    let position = editing ? edited : elapsed
    return position.isFinite ? min(duration, max(0, position)) : nil
}
func mediaPositionObservedUptime(_ reported: Double?, received: Double) -> Double {
    guard let reported, reported.isFinite, received.isFinite,
          reported > 0, reported <= received else { return received }
    return reported
}

func menuBarSurfaceIsLight(_ appearance: NSAppearance?) -> Bool {
    guard let match = appearance?.bestMatch(from: [.aqua, .darkAqua, .accessibilityHighContrastAqua, .accessibilityHighContrastDarkAqua]) else { return false }
    return match == .aqua || match == .accessibilityHighContrastAqua
}

