        if let geometry = geometry {
            guard [geometry.frame.minX, geometry.frame.minY, geometry.frame.width, geometry.frame.height, geometry.radius].allSatisfy(\.isFinite),
                  geometry.frame.width > 0, geometry.frame.height > 0, geometry.radius >= 0,
                  geometry.surface == floatingIslandPlacement?.bounds.screen else { return }
        }
        if renderedFloatingIslandGeometry != geometry { renderedFloatingIslandGeometry = geometry }
