              var placement = floatingIslandPlacement, let anchor = session.position(translation: translation) else { return }
        if placement.anchor != anchor {
            placement.anchor = anchor
            floatingIslandPlacement = placement
        }
        if finished, let layoutPreferences {
            FloatingIslandPositions(defaults: layoutPreferences).save(displayID: placement.displayID, centerX: anchor.x,
                                                                       topOffset: anchor.y, bounds: placement.bounds)
        }
