    init(pasteboard: NSPasteboard = .general, startServices: Bool = true, timerPreferences: UserDefaults? = nil, mediaRequester: MediaRequester? = nil, layoutPreferences: UserDefaults? = nil, notes: NotesModel? = nil) {
        self.assistant = AssistantController(startServices: startServices)
        self.pasteboard = pasteboard
        self.servicesEnabled = startServices
        self.timerPreferences = timerPreferences ?? (startServices ? .standard : nil)
        self.mediaRequester = mediaRequester
        self.layoutPreferences = layoutPreferences ?? (startServices ? .standard : nil)
        self.agenda = AgendaModel(autoRefresh: false)
        self.notes = notes ?? NotesModel(startServices: startServices)
        self.assistantAnimationID = personalAssistantAnimationID(assistant.activeConversationID)
        musicSpectrum.waveContext = { [weak self] time in
            self?.musicWaveContext(at: time) ?? .fallback(at: time)
        }
        assistantSpeech.onChange = { [weak self] speaking, wordAt in
            guard let self else { return }
            let wasSpeaking = self.assistantSpeaking
            self.assistantSpeaking = speaking
            self.assistantSpeechWordAt = wordAt
            if speaking && !wasSpeaking {
                self.assistantFinishGeneration += 1
                self.assistantFinishing = false; self.assistantFinishStarted = nil
            } else if !speaking && wasSpeaking && self.assistant.phase == .ready && self.assistant.lastOutcome == "completed"
                        && !self.systemNotificationScreenLocked && !self.systemNotificationSleeping {
                self.assistantFinishGeneration += 1
                let generation = self.assistantFinishGeneration
                self.assistantFinishStarted = ProcessInfo.processInfo.systemUptime
                self.assistantFinishing = true
                DispatchQueue.main.asyncAfter(deadline: .now() + 1.0) { [weak self] in
                    guard let self, self.assistantFinishGeneration == generation else { return }
                    self.assistantFinishing = false; self.assistantFinishStarted = nil
                }
            }
        }
        assistantConversationObservation = assistant.$activeConversationID.receive(on: RunLoop.main).sink { [weak self] id in
            guard let self = self, id == self.assistant.activeConversationID else { return }
            let next = personalAssistantAnimationID(id)
            guard self.assistantAnimationID != next else { return }
            self.preparedDictation?.cancelAssistantCapture()
            self.stopAssistantSpeech()
            self.assistantFinishGeneration += 1; self.assistantFinishing = false; self.assistantFinishStarted = nil
            self.assistantAnimationID = next
        }
        assistantObservation = assistant.$phase.combineLatest(assistant.$requests, assistant.$toolRunning, assistant.$requestOverflow)
            .receive(on: RunLoop.main)
            .sink { [weak self] phase, requests, running, overflow in
                guard let self = self else { return }
                let observed = personalAssistantIndicator(phase: phase, requests: requests, overflow: overflow)
                let active = phase == .running && running
                let current = personalAssistantIndicator(phase: self.assistant.phase, requests: self.assistant.requests, overflow: self.assistant.requestOverflow)
                let currentActive = self.assistant.phase == .running && self.assistant.toolRunning
                guard phase == self.assistant.phase,
                      assistantPresentationMatches(observed: observed, observedTool: active,
                                                   current: current, currentTool: currentActive) else { return }
                if phase != .ready { self.preparedDictation?.cancelAssistantCapture() }
                if phase == .submitting || phase == .connecting || phase == .disconnected || phase == .uncertain { self.stopAssistantSpeech() }
                self.updateAssistantIndicator(observed, phase: phase)
                if self.assistantToolRunning != active { self.assistantToolRunning = active }
            }
        assistant.onWillSend = { [weak self] in
            self?.stopAssistantSpeech()
            self?.assistantSpeechSuppressed.removeAll()
        }
        assistant.onMessageUpdate = { [weak self] id, text, complete in
            self?.speakAssistantUpdate(id: id, text: text, complete: complete)
        }
        assistant.onMessageCompleted = { [weak self] _ in
            guard let self = self, self.servicesEnabled else { return }
            self.showLight(.agentMessage)
            self.playAgentFeedback(.agentMessage)
            self.showAgentScreenWaves([.agentMessage])
        }
        assistant.onTurnCompleted = { [weak self] in
            guard let self else { return }
            if self.assistant.lastOutcome != "completed" { self.stopAssistantSpeech() }
            self.updateAssistantIndicator(.off, phase: .ready, terminalEvent: true)
        }
        restorePomodoroSettings()
        restoreHomeLayout()
        if let preferences = self.layoutPreferences {
            preferredDisplayKey = NotchDisplayPreference(defaults: preferences).load()
        }
        teleprompter.onEditingChange = { [weak self] editing in self?.setPromptEditing(editing) }
        guard startServices else { return }
        agenda.onAdded = { [weak self] addition in
            switch addition {
            case .event: self?.showAgendaLight(.calendarAdded)
            case .reminder: self?.showAgendaLight(.reminderAdded)
            }
        }
        shortcutPeeksEnabled = shortcutPeeksPreference(UserDefaults.standard.object(forKey: "rium.shortcuts.peeks") as? Bool)
        systemNotificationEnabled = UserDefaults.standard.object(forKey: "rium.systemNotifications.enabled") as? Bool ?? true
        caseKeysEnabled = UserDefaults.standard.bool(forKey: "rium.light.caseKeys")
        restoreClipboard()
        restoreTimer()
        timerNotificationsEnabled = UserDefaults.standard.bool(forKey: "rium.timer.notifications")
        if timerNotificationsEnabled { refreshTimerNotificationPermission() }
        agentNotificationsEnabled = UserDefaults.standard.bool(forKey: "rium.agent.notifications")
        if agentNotificationsEnabled { refreshAgentNotificationPermission() }
        weatherAlertsEnabled = UserDefaults.standard.bool(forKey: "rium.weather.alerts")
        lyricsEnabled = UserDefaults.standard.bool(forKey: "rium.lyrics.enabled")
        let savedInterval = UserDefaults.standard.integer(forKey: "rium.monitor.interval")
        hoverEnabled = UserDefaults.standard.object(forKey: "rium.notch.hover") as? Bool ?? true
        autoHideEnabled = UserDefaults.standard.object(forKey: "rium.notch.autoHide") as? Bool ?? true
        if let delay = UserDefaults.standard.object(forKey: "rium.notch.autoHideDelay") as? Double, delay.isFinite {
            autoHideDelay = min(3, max(0.1, delay))
        }
        sampleInterval = [2, 5, 10].contains(savedInterval) ? savedInterval : 2
        monitorAccountID = UserDefaults.standard.string(forKey: "rium.monitor.account")
        if UserDefaults.standard.object(forKey: "rium.monitor.enabled") as? Bool ?? true { setUsageTrackingEnabled(true) }
        if UserDefaults.standard.bool(forKey: "rium.airdrop.enabled") { airDropEnabled = true; airDropMonitor.start() }
        if UserDefaults.standard.bool(forKey: "rium.screenshot.enabled") { screenshotEnabled = true; screenshotMonitor.start() }
        if let cache = UserDefaults.standard.dictionary(forKey: "rium.weather.cache"),
           let data = cache["data"] as? [String: Any], let updated = cache["updated"] as? Double {
            showWeather(city: cache["city"] as? String ?? "선택 도시", data: data, updated: Date(timeIntervalSince1970: updated), timeZoneID: cache["timezone"] as? String)
            refreshStaleWeather()
        }
        let clockTimer = Timer(timeInterval: 1, repeats: true) { [weak self] _ in
            guard let self = self else { return }
            self.updateTimer(); self.advanceMedia(); self.mediaTick += 1
            if self.dictationRecording {
                let hidden = !UserDefaults.standard.bool(forKey: "rium.dictation.previewText") || FeedbackSound.quietForPrivacy
                if self.dictationPreviewHidden != hidden { self.dictationPreviewHidden = hidden }
            }
            if !self.systemNotificationScreenLocked && !self.systemNotificationSleeping &&
                (self.systemNotificationPeek != nil || (self.expanded && !self.homeNotificationInbox.items.isEmpty)) {
                let hidden = FeedbackSound.quietForPrivacy
                if hidden != self.systemNotificationPrivacyHidden { self.systemNotificationPrivacyHidden = hidden }
            }
            if self.deferredServicesStarted && self.mediaTick % 5 == 0 && (self.section == .music || self.section == .home || self.mediaTick % 10 == 0) { self.refreshMedia() }
            if self.deferredServicesStarted && self.mediaTick % 10 == 0 { self.agentWatcher?.reconcileRoots(); self.refreshAgents(); self.agenda.refreshIfAuthorizationChanged(); self.dictation.restoreIfAuthorized() }
            self.expireAgentSnapshotIfNeeded()
            self.musicSpectrum.expireStaleLevels()
            self.refreshWallClock()
            if self.mediaTick % 60 == 0 { self.refreshWeatherAlert() }
            if self.mediaTick % 300 == 0 { self.refreshStaleWeather(); self.agenda.refreshAuthorized() }
        }
        RunLoop.main.add(clockTimer, forMode: .common)
        self.clockTimer = clockTimer
        let hudTimer = Timer(timeInterval: 0.2, repeats: true) { [weak self] _ in
            self?.sampleVolume(); self?.sampleBrightness(); self?.sampleClipboard()
        }
        RunLoop.main.add(hudTimer, forMode: .common)
        self.hudTimer = hudTimer
    }

    func startDeferredServices() {
        guard servicesEnabled, !deferredServicesStarted, !agentWatchingStopped else { return }
        deferredServicesStarted = true
        volumeObserver = AudioOutputVolumeObserver(onChange: { [weak self] in self?.sampleVolume() },
            onPlaybackActivityChange: { [weak self] in self?.refreshMediaOutputActivity() })
        sampleVolume()
        observeBrightness(on: selectedDisplayID)
        if airDropEnabled { airDropSendWatcher.start() }
        dictation.onWillStart = { [weak self] in
            self?.stopAssistantSpeech()
            self?.voiceApproval.cancel()
            if self?.interview.active == true { self?.interview.stop(message: "받아쓰기를 시작해 면접 듣기를 중지했습니다.") }
        }
        dictation.onRecordingChange = { [weak self] recording in
            guard let self = self else { return }
            if recording {
                self.dictationStartedAt = ProcessInfo.processInfo.systemUptime
            } else {
                self.dictationFinalLevel = self.dictationLevel
            }
            self.assistantListening = recording && self.dictation.assistantCaptureActive
            self.dictationPreviewHidden = !recording || self.assistantListening || !UserDefaults.standard.bool(forKey: "rium.dictation.previewText") || FeedbackSound.quietForPrivacy
            self.dictationRecording = recording
        }
        dictation.onFinalizationChange = { [weak self] pending in
            guard let self = self else { return }
            if pending { self.dictationWritingStartedAt = ProcessInfo.processInfo.systemUptime }
            self.dictationFinalizing = pending && !self.dictation.assistantCaptureActive
        }
        dictation.onInputLevel = { [weak self] level in self?.dictationLevel = level }
        power.onEvent = { [weak self] event in self?.showBatteryEvent(event) }
        agenda.start()
        updater.start()
        dictation.restoreIfAuthorized()
        let watcher = AgentActivityWatcher { [weak self] in self?.refreshAgents() }
        agentWatcher = watcher; watcher.start()
        let mediaWatcher = MediaActivityWatcher { [weak self] in self?.refreshMedia() }
        self.mediaWatcher = mediaWatcher; mediaWatcher.start()
        if systemNotificationEnabled && !systemNotificationScreenLocked && !systemNotificationSleeping { systemNotificationMonitor.start() }
        refreshAgents()
        refreshMedia()
    }

    func setHoverEnabled(_ enabled: Bool) {
        hoverEnabled = enabled; UserDefaults.standard.set(enabled, forKey: "rium.notch.hover")
        hoverWork?.cancel(); hoverWork = nil
        let inside = (NSApp.delegate as? AppDelegate)?.pointIsInsideNotch(NSEvent.mouseLocation) ?? !enabled
        if hoverSettingNeedsReconciliation(enabled: enabled, expanded: expanded, autoHide: autoHideEnabled, inside: inside) {
            handleHover(inside)
        }
    }
    func setSystemNotificationEnabled(_ enabled: Bool, preferences: UserDefaults = .standard) {
        systemNotificationEnabled = enabled
        preferences.set(enabled, forKey: "rium.systemNotifications.enabled")
        if enabled && deferredServicesStarted && !systemNotificationScreenLocked && !systemNotificationSleeping {
            systemNotificationStatus = "시스템 알림 확인 중"
            systemNotificationMonitor.start()
        } else {
            systemNotificationMonitor.stop(); clearSystemNotificationPeek()
            if !enabled { homeNotificationInbox = HomeNotificationInbox() }
            systemNotificationStatus = enabled ? "시스템 알림 대기 중" : "시스템 알림 감시 꺼짐"
        }
    }
    func setSystemNotificationScreenLocked(_ locked: Bool) {
        if locked {
            systemNotificationPrivacyHidden = true
            deferredRunningPeek = nil
        }
        systemNotificationScreenLocked = locked
        preparedDictation?.setScreenLocked(locked)
        if locked {
            stopAssistantSpeech()
            clipboardCaptureGeneration &+= 1
            if !clipboardReady { clipboardRestoreInterrupted = true }
            clearClipboardPeek()
            clearTransientLights()
            systemNotificationMonitor.stop(preservingCursor: true); suspendSystemNotificationPeek()
        } else {
            if !systemNotificationSleeping { systemNotificationPrivacyHidden = FeedbackSound.quietForPrivacy }
            clipboardChangeCount = pasteboard.changeCount
            resumeSystemNotificationMonitorIfAvailable()
        }
    }
    func setDictationScreenSleeping(_ sleeping: Bool) {
        dictationScreenSleeping = sleeping
        preparedDictation?.setSleeping(dictationSleeping)
    }
    func setSystemNotificationSleeping(_ sleeping: Bool) {
        if sleeping {
            systemNotificationPrivacyHidden = true
            deferredRunningPeek = nil
        }
        systemNotificationSleeping = sleeping
        preparedDictation?.setSleeping(dictationSleeping)
        if sleeping {
            stopAssistantSpeech()
            FeedbackSound.stopTimerAlarm()
            clipboardCaptureGeneration &+= 1
            if !clipboardReady { clipboardRestoreInterrupted = true }
            clearClipboardPeek()
            clearTransientLights()
            systemNotificationMonitor.stop(preservingCursor: true); suspendSystemNotificationPeek()
        } else {
            if !systemNotificationScreenLocked { systemNotificationPrivacyHidden = FeedbackSound.quietForPrivacy }
            clipboardChangeCount = pasteboard.changeCount
            resumeSystemNotificationMonitorIfAvailable()
        }
    }
    private func resumeSystemNotificationMonitorIfAvailable() {
        guard systemNotificationEnabled, deferredServicesStarted, !systemNotificationScreenLocked, !systemNotificationSleeping else { return }
        systemNotificationMonitor.start(preservingCursor: true)
        if !expanded, systemNotificationPeek == nil, !pendingSystemNotificationPeeks.isEmpty {
            presentSystemNotification(pendingSystemNotificationPeeks.removeFirst())
        }
    }
    private func suspendSystemNotificationPeek() {
        let previous = currentNotchShellState
        if let peek = systemNotificationPeek { suspendSystemNotification(peek, into: &pendingSystemNotificationPeeks) }
        systemNotificationPeekGeneration += 1; systemNotificationPeek = nil
        recordDetailFold(from: previous)
    }
    func stopSystemNotifications() { systemNotificationMonitor.stop(); clearSystemNotificationPeek() }
    fileprivate func clearSystemNotificationPeek() {
        let previous = currentNotchShellState
        systemNotificationPeekGeneration += 1; systemNotificationPeek = nil; pendingSystemNotificationPeeks.removeAll()
        recordDetailFold(from: previous)
    }
    fileprivate func showSystemNotification(_ notification: SystemNotificationPeek) {
        guard systemNotificationEnabled, !systemNotificationScreenLocked, !systemNotificationSleeping else { return }
        var inbox = homeNotificationInbox
        guard inbox.receive(notification) else { return }
        homeNotificationInbox = inbox
        systemNotificationPrivacyHidden = FeedbackSound.quietForPrivacy
        showLight(.systemNotification, notificationTint: SystemNotificationAppearance.accent(for: notification.source))
        if expanded { return }
        if systemNotificationPeek != nil {
            enqueueSystemNotification(notification, into: &pendingSystemNotificationPeeks); return
        }
        presentSystemNotification(notification)
    }
    func homeNotification(for slot: HomeSlot) -> SystemNotificationPeek? {
        guard expanded, section == .home, !homeEditing, !tabEditing, systemNotificationEnabled, !systemNotificationScreenLocked,
              !systemNotificationSleeping, let item = homeNotificationInbox.items.first else { return nil }
        let weather = item.source == "com.apple.weather" || item.source == "app.glance.weather-alert"
        return slot == (weather ? .weather : .calendar) ? item : nil
    }
    var visibleHomeNotifications: [SystemNotificationPeek] {
        guard systemNotificationEnabled, !systemNotificationScreenLocked, !systemNotificationSleeping else { return [] }
        return homeNotificationInbox.items
    }
    var visibleNotificationUnreadCount: Int {
        visibleHomeNotifications.isEmpty ? 0 : homeNotificationInbox.unread.count
    }
    var visibleTimerAlarmTitle: String? {
        guard !systemNotificationScreenLocked, !systemNotificationSleeping else { return nil }
        return timerAlarmTitle
    }
    func openNotificationsPage() {
        guard systemNotificationEnabled, !systemNotificationScreenLocked, !systemNotificationSleeping else { return }
        select(.notifications)
        expanded = true
    }
    func openHomeNotification(_ item: SystemNotificationPeek) {
        guard systemNotificationEnabled, !systemNotificationScreenLocked, !systemNotificationSleeping,
              let url = NSWorkspace.shared.urlForApplication(withBundleIdentifier: item.source) else { return }
        if NSWorkspace.shared.open(url) { dismissHomeNotification(item) }
    }
    func dismissHomeNotification(_ item: SystemNotificationPeek) {
        let key = HomeNotificationInbox.Key(item)
        homeNotificationInbox.dismiss(item)
        pendingSystemNotificationPeeks.removeAll { HomeNotificationInbox.Key($0) == key }
        guard systemNotificationPeek.map(HomeNotificationInbox.Key.init) == key else { return }
        if pendingSystemNotificationPeeks.isEmpty { clearSystemNotificationPeek() }
        else { presentSystemNotification(pendingSystemNotificationPeeks.removeFirst()) }
    }
    @MainActor
    func trackHomeNotificationExposure(_ item: SystemNotificationPeek, in slot: HomeSlot) async {
        guard !Task.isCancelled, homeNotification(for: slot)?.id == item.id else { return }
        if homeNotificationInbox.unread.contains(HomeNotificationInbox.Key(item)) {
            homeNotificationInbox.markRead(item)
        }
        do { try await Task.sleep(nanoseconds: rustHomeNotificationDisplayNanoseconds()) }
        catch { return }
        guard !Task.isCancelled, homeNotification(for: slot)?.id == item.id else { return }
        dismissHomeNotification(item)
    }
    private func presentSystemNotification(_ notification: SystemNotificationPeek) {
        systemNotificationPeekGeneration += 1
        let generation = systemNotificationPeekGeneration
        systemNotificationPrivacyHidden = FeedbackSound.quietForPrivacy
        systemNotificationPeek = notification
        let now = ProcessInfo.processInfo.systemUptime
        expireSystemNotificationPeek(generation: generation, remaining: 4, started: now, last: now)
    }
    private func expireSystemNotificationPeek(generation: Int, remaining: TimeInterval, started: TimeInterval, last: TimeInterval) {
        // shortcut: visibility and the 20-second stale limit need reference comparison.
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.2) { [weak self] in
            guard let self, self.systemNotificationPeekGeneration == generation, self.systemNotificationPeek != nil else { return }
            let now = ProcessInfo.processInfo.systemUptime
            let next = visiblePeekRemaining(remaining, elapsed: now - last, visible: self.visibleSystemNotificationPeek != nil)
            if now < started || now - started >= 20 || next <= 0 {
                if self.pendingSystemNotificationPeeks.isEmpty { self.clearSystemNotificationPeek() }
                else { self.presentSystemNotification(self.pendingSystemNotificationPeeks.removeFirst()) }
            }
            else { self.expireSystemNotificationPeek(generation: generation, remaining: next, started: started, last: now) }
        }
    }
    func setShortcutPeeksEnabled(_ enabled: Bool) {
        shortcutPeeksEnabled = enabled
        UserDefaults.standard.set(enabled, forKey: "rium.shortcuts.peeks")
        if !enabled {
            shortcutPeekGeneration += 1; shortcutPeek = nil
            if clipboardPeek?.kind == .pasted { clearClipboardPeek() }
        }
        (NSApp.delegate as? AppDelegate)?.configureShortcutMonitor()
    }
    func showShortcutPeek(_ action: ShortcutAction) {
        guard notchScreenAvailable, shortcutPeeksEnabled, shortcutActionEnabled(action) else { return }
        if expanded {
            showLight(.shortcut(action))
            return
        }
        let previousState = currentNotchShellState
        shortcutPeekGeneration += 1
        let generation = shortcutPeekGeneration
        shortcutPeekStarted = ProcessInfo.processInfo.systemUptime; shortcutPeek = action
        recordDetailFold(from: previousState)
        showLight(.shortcut(action))
        DispatchQueue.main.asyncAfter(deadline: .now() + 1.15) { [weak self] in
            guard let self = self, self.shortcutPeekGeneration == generation else { return }
            self.shortcutPeek = nil
        }
    }
    private func clearShortcutPeeks() {
        shortcutPeekGeneration += 1; shortcutPeek = nil
        caseKeyPeekGeneration += 1; caseKeyPeek = nil
    }
    func setCaseKeysEnabled(_ enabled: Bool) {
        caseKeysEnabled = enabled
        UserDefaults.standard.set(enabled, forKey: "rium.light.caseKeys")
        if !enabled { caseKeyPeekGeneration += 1; caseKeyPeek = nil; endShiftKeyPeek() }
        (NSApp.delegate as? AppDelegate)?.configureShortcutMonitor()
    }
    func showCaseKeyPeek(_ action: CaseKeyAction) {
        guard caseKeysEnabled else { return }
        if action == .shiftHeld && activeLightCues.contains(where: { $0.kind == .caseKey(.shiftHeld) && $0.duration.isInfinite }) { return }
        if clipboardPeek != nil { clearClipboardPeek() }
        caseKeyPeekGeneration += 1; let generation = caseKeyPeekGeneration
        caseKeyPeek = action; showLight(.caseKey(action))
        if action == .shiftHeld { return }
        DispatchQueue.main.asyncAfter(deadline: .now() + 1.15) { [weak self] in
            guard let self = self, self.caseKeyPeekGeneration == generation else { return }
            self.caseKeyPeek = self.activeLightCues.contains(where: { $0.kind == .caseKey(.shiftHeld) && $0.duration.isInfinite }) ? .shiftHeld : nil
        }
    }
    func endShiftKeyPeek() {
        if caseKeyPeek == .shiftHeld { caseKeyPeekGeneration += 1; caseKeyPeek = nil }
        guard let index = activeLightCues.lastIndex(where: { $0.kind == .caseKey(.shiftHeld) && $0.duration.isInfinite }) else { return }
        let cue = activeLightCues[index].releasingShift(at: ProcessInfo.processInfo.systemUptime)
        activeLightCues[index] = cue
        if lightCue?.id == cue.id { lightCue = cue }
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.2) { [weak self] in
            guard let self else { return }
            self.activeLightCues.removeAll { $0.id == cue.id }
            if self.lightCue?.id == cue.id { self.lightCue = self.activeLightCues.last }
        }
    }
    func setAutoHideEnabled(_ enabled: Bool) {
        autoHideEnabled = enabled; UserDefaults.standard.set(enabled, forKey: "rium.notch.autoHide")
        if !enabled && expanded { hoverWork?.cancel(); hoverWork = nil }
        else if expanded {
            let inside = (NSApp.delegate as? AppDelegate)?.pointIsInsideNotch(NSEvent.mouseLocation) ?? true
            handleHover(inside)
        }
    }
    func setAutoHideDelay(_ delay: Double, pointerInside: Bool? = nil) {
        guard delay.isFinite else { return }
        autoHideDelay = min(3, max(0.1, delay))
        UserDefaults.standard.set(autoHideDelay, forKey: "rium.notch.autoHideDelay")
        if expanded && autoHideEnabled {
            let inside = pointerInside ?? ((NSApp?.delegate as? AppDelegate)?.pointIsInsideNotch(NSEvent.mouseLocation) ?? true)
            handleHover(inside)
        }
    }
    private func updateAssistantIndicator(_ next: AssistantIndicator, phase: AssistantController.Phase, terminalEvent: Bool = false) {
        let previous = assistantIndicator
        guard previous != next || (terminalEvent && next == .off) else { return }
        let mood: Int32
        switch next {
        case .working: mood = 1
        case .approval: mood = 2
        case .question: mood = 3
        case .off: mood = assistant.lastOutcome == "completed" ? 4 : (assistant.lastOutcome == "failed" ? 5 : (assistant.lastOutcome == "interrupted" ? 7 : 0))
        }
        _ = lumiMoodMemory.observe(AgentSessionKey(source: "", id: personalAssistantAnimationID(assistant.activeConversationID)), mood: mood, now: ProcessInfo.processInfo.systemUptime)
        assistantIndicator = next
        if let peek = permissionPeek, isPersonalAssistantSession(peek.sessionKey) { clearPermissionPeek(discardPending: false) }
        if let peek = agentTransientPeek, isPersonalAssistantSession(peek.agent.sessionKey) { clearAgentTransientPeek() }
        assistantFinishGeneration += 1
        assistantFinishStarted = nil
        assistantFinishing = false
        guard servicesEnabled else { return }
        let kind: NotchLightCue.Kind
        switch next {
        case .working: kind = .agentRunning
        case .approval: kind = .agentApproval
        case .question: kind = .agentQuestion
        case .off:
            guard phase == .ready, let terminal = assistantTerminalLight(outcome: assistant.lastOutcome, status: assistant.status) else { return }
            kind = terminal
            assistantFinishStarted = ProcessInfo.processInfo.systemUptime
            assistantFinishing = true
            let generation = assistantFinishGeneration
            let duration = NotchLightCue(kind: kind, started: Date()).duration
            DispatchQueue.main.asyncAfter(deadline: .now() + duration) { [weak self] in
                guard let self = self, self.assistantFinishGeneration == generation else { return }
                self.assistantFinishing = false
                self.assistantFinishStarted = nil
            }
        }
        showLight(kind)
        playAgentFeedback(kind)
        showAgentScreenWaves([kind])
    }
    private func playAgentFeedback(_ cue: NotchLightCue.Kind) {
        switch cue {
        case .agentRunning: FeedbackSound.agentRunning.play(previewVisible: !expanded && showsCollapsedAgent)
        case .agentApproval, .agentQuestion: FeedbackSound.agentAttention.play()
        case .agentDone: FeedbackSound.agentDone.play()
        case .agentFailed, .agentInterrupted: FeedbackSound.agentFailed.play()
        case .agentMessage: FeedbackSound.agentMessage.play()
        default: break
        }
    }
    func showLight(_ kind: NotchLightCue.Kind, notificationTint: NSColor? = nil, previousSystemLevel: Int? = nil, restoringSound: Bool = false) {
        guard !systemNotificationScreenLocked, !systemNotificationSleeping else { return }
        let now = ProcessInfo.processInfo.systemUptime
        if kind == .airDropSent { showEdgeWave(inward: false) }
        if kind == .airDrop {
            let previous = activeLightCues.last { $0.kind == .airDrop }
            if previous.map({ rustAirDropReceiveWaveDue($0.elapsed(at: now)) != 0 }) ?? true {
                showEdgeWave(inward: false)
            }
        }
        let start = systemLevelTransitionStart(previous: previousSystemLevel, next: kind,
                                               active: activeLightCues.last(where: \.isSystemHUD), now: now)
        let pulse = systemLevelPulseEnergy(next: kind, active: activeLightCues.last(where: \.isSystemHUD), now: now)
        let cue = NotchLightCue(kind: kind, started: Date(), referenceUptime: now,
                                notificationTint: notificationTint, previousSystemLevel: start, systemPulseEnergy: pulse,
                                systemDirection: systemLevelDirection(previous: previousSystemLevel, next: kind),
                                restoringSound: restoringSound)
        if cue.isSystemHUD { activeLightCues.removeAll { $0.isSystemHUD } }
        if cue.isBatteryFeedback { activeLightCues.removeAll { $0.isBatteryFeedback } }
        if case .musicSkip = kind {
            activeLightCues.removeAll { if case .musicSkip = $0.kind { return true }; return false }
        }
        lightCue = cue
        activeLightCues.append(cue)
        if kind.isClipboardScreenWave,
           UserDefaults.standard.object(forKey: "rium.light.enabled") as? Bool ?? true,
           UserDefaults.standard.object(forKey: "rium.light.clipboard") as? Bool ?? true,
           UserDefaults.standard.object(forKey: "rium.light.edgeWave") as? Bool ?? true,
           !NSWorkspace.shared.accessibilityDisplayShouldReduceMotion,
           !ProcessInfo.processInfo.isLowPowerModeEnabled {
            let clipboardWaves = notchScreenWaves.filter { $0.kind.isClipboardScreenWave }
            if clipboardWaves.count >= 2, let oldest = clipboardWaves.first {
                notchScreenWaves.removeAll { $0.id == oldest.id }
            }
            enqueueScreenWaves([NotchScreenWave(started: now, kind: kind)])
        }
        if activeLightCues.count > 6, let index = lightCueEvictionIndex(activeLightCues, isEnabled: { lightCueEnabled($0) }) {
            let removed = activeLightCues.remove(at: index)
            if lightCue?.id == removed.id { lightCue = activeLightCues.last }
            if removed.id == cue.id { return }
        }
        if kind == .caseKey(.shiftHeld) { return }
        DispatchQueue.main.asyncAfter(deadline: .now() + cue.duration) { [weak self] in
            guard let self = self else { return }
            self.activeLightCues.removeAll { $0.id == cue.id }
            if self.lightCue?.id == cue.id { self.lightCue = self.activeLightCues.last }
        }
    }
    fileprivate func clearPermissionPeek(discardPending: Bool = true) {
        let previousState = currentNotchShellState
        if let peek = permissionPeek { voiceApproval.cancel(owner: permissionPeekVoiceOwner(peek)) }
        permissionPeekGeneration += 1
        permissionPeek = nil
        if discardPending { pendingPermissionPeeks.removeAll() }
        else {
            while !expanded && !pendingPermissionPeeks.isEmpty {
                let session = pendingPermissionPeeks.removeFirst()
                guard !isPersonalAssistantSession(session),
                      let item = agentItems.first(where: { $0.sessionKey == session && $0.state.hasPrefix("승인 대기") }) else { continue }
                showPermissionPeek(item)
                break
            }
        }
        if permissionPeek == nil { recordDetailFold(from: previousState) }
    }
    fileprivate func showPermissionPeek(_ item: AgentActivity) {
        guard !expanded, !isPersonalAssistantSession(item.sessionKey), item.state.hasPrefix("승인 대기") else { return }
        if let previous = permissionPeek {
            if !sameAgentSession(previous, item) && !pendingPermissionPeeks.contains(item.sessionKey) {
                pendingPermissionPeeks.append(item.sessionKey)
                // shortcut: only the newest 20 waiting sessions retain a preview during a burst.
                if pendingPermissionPeeks.count > 20 { pendingPermissionPeeks.removeFirst() }
            }
            return
        }
        clearAgentTransientPeek()
        permissionPeekGeneration += 1
        let generation = permissionPeekGeneration
        permissionPeek = item
        schedulePermissionPeekExpiry(generation: generation, remaining: 5,
                                     lastCheckedAt: ProcessInfo.processInfo.systemUptime)
    }
    private func schedulePermissionPeekExpiry(generation: Int, remaining: TimeInterval, lastCheckedAt: TimeInterval) {
        // shortcut: the reference's precise interruption policy is unknown;
        // sample visibility to avoid consuming a preview hidden by another cue.
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) { [weak self] in
            guard let self = self, self.permissionPeekGeneration == generation, self.permissionPeek != nil else { return }
            let now = ProcessInfo.processInfo.systemUptime
            let next = visiblePeekRemaining(remaining, elapsed: now - lastCheckedAt,
                                            visible: self.visiblePermissionPeek != nil)
            if next <= 0 { self.clearPermissionPeek(discardPending: false) }
            else { self.schedulePermissionPeekExpiry(generation: generation, remaining: next, lastCheckedAt: now) }
        }
    }
    private func clearAgentTransientPeek() {
        let previousState = currentNotchShellState
        agentTransientPeekGeneration += 1
        agentTransientPeek = nil
        recordDetailFold(from: previousState)
    }
    private func recordDetailFold(from previousState: Int32) {
        guard previousState == 2, currentNotchShellState == 1 else { return }
        detailFoldGeneration += 1
        let generation = detailFoldGeneration
        foldingDetailToStatus = true
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.4) { [weak self] in
            guard let self = self, self.detailFoldGeneration == generation else { return }
            self.foldingDetailToStatus = false
        }
    }
    private func presentDeferredRunningPeek() {
        guard let pending = deferredRunningPeek else { return }
        deferredRunningPeek = nil
        guard notchScreenAvailable, let item = externalAgentItems.first(where: {
            $0.sessionKey == pending && agentIsRunning($0.state)
        }) else { return }
        showAgentTransientPeek(item, kind: .running)
    }

    fileprivate func showAgentTransientPeek(_ item: AgentActivity, kind: AgentTransientKind) {
        guard permissionPeek == nil, !isPersonalAssistantSession(item.sessionKey) else { return }
        if expanded {
            if kind == .running && notchScreenAvailable { deferredRunningPeek = item.sessionKey }
            return
        }
        agentTransientPeekGeneration += 1
        let generation = agentTransientPeekGeneration
        let now = ProcessInfo.processInfo.systemUptime
        agentTransientPeek = AgentTransientPeek(agent: item, kind: kind, started: now)
        // shortcut: other reference preview durations and interruption policies need comparison.
        scheduleAgentTransientPeekExpiry(generation: generation, remaining: rustAgentTransientPeekDuration(),
                                         startedAt: now, lastCheckedAt: now)
    }
    private func scheduleAgentTransientPeekExpiry(generation: Int, remaining: TimeInterval, startedAt: TimeInterval, lastCheckedAt: TimeInterval) {
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.25) { [weak self] in
            guard let self = self, self.agentTransientPeekGeneration == generation,
                  var peek = self.agentTransientPeek else { return }
            let now = ProcessInfo.processInfo.systemUptime
            let elapsed = max(0, now - lastCheckedAt)
            let focusCovered = self.visibleFocusAlarmPeek != nil
            let visible = self.visibleAgentTransientPeek?.id == peek.id && !focusCovered
            let activeStart = agentTransientStart(startedAt, elapsed: elapsed, focusCovered: focusCovered)
            let next = agentTransientRemaining(remaining, elapsed: elapsed, visible: visible, age: now - activeStart)
            if next <= 0 { self.clearAgentTransientPeek(); return }
            if !visible {
                // Keep the preview's own orb animation in step with its
                // visible lifetime when a higher-priority cue covers it.
                peek.started += elapsed
                self.agentTransientPeek = peek
            }
            self.scheduleAgentTransientPeekExpiry(generation: generation, remaining: next, startedAt: activeStart, lastCheckedAt: now)
        }
    }
    private func showAgentScreenWaves(_ events: [NotchLightCue.Kind]) {
        let preferences = UserDefaults.standard
        guard !systemNotificationScreenLocked, !systemNotificationSleeping,
              preferences.object(forKey: "rium.light.enabled") as? Bool ?? true,
              preferences.object(forKey: "rium.light.agent") as? Bool ?? true,
              preferences.object(forKey: "rium.light.agentScreenWave") as? Bool ?? true,
              !ProcessInfo.processInfo.isLowPowerModeEnabled, !events.isEmpty else { return }
        let now = ProcessInfo.processInfo.systemUptime
        let everyEvent = preferences.string(forKey: "rium.light.agentWaveMode") == "every"
        agentScreenWaveHistory.removeAll { now < $0.at || now - $0.at > 60 }
        // The reference counts running and needs_you; our observed state labels
        // approximate those two categories across the available adapters.
        let active = activeAgentSessionCount(agentItems, assistant: assistantIndicator, assistantThread: assistant.observationThreadID)
        var waves: [NotchScreenWave] = []
        for event in events {
            guard let kind = agentScreenWaveCategory(event) else { continue }
            let times = agentScreenWaveHistory.map(\.at), kinds = agentScreenWaveHistory.map(\.kind)
            let admitted = times.withUnsafeBufferPointer { timeBuffer in
                kinds.withUnsafeBufferPointer { kindBuffer in
                    rustAgentWaveAdmit(now, kind, active, power.externalPower == false ? 1 : 0,
                                       everyEvent ? 1 : 0, timeBuffer.baseAddress, kindBuffer.baseAddress, timeBuffer.count)
                }
            }
            guard admitted == 1 else { continue }
            agentScreenWaveHistory.append((now, kind))
            waves.append(NotchScreenWave(started: now, kind: event))
        }
        enqueueScreenWaves(waves)
    }
    private func enqueueScreenWaves(_ waves: [NotchScreenWave]) {
        guard !waves.isEmpty else { return }
        notchScreenWaves.append(contentsOf: waves)
        if notchScreenWaves.count > 64 { notchScreenWaves.removeFirst(notchScreenWaves.count - 64) }
        onEdgeWaveChange?()
        let ids = Set(waves.map(\.id))
        DispatchQueue.main.asyncAfter(deadline: .now() + 2.6) { [weak self] in
            guard let self, self.notchScreenWaves.contains(where: { ids.contains($0.id) }) else { return }
            self.notchScreenWaves.removeAll { ids.contains($0.id) }
            self.onEdgeWaveChange?()
        }
    }
    private func showEdgeWave(inward: Bool) {
        guard !systemNotificationScreenLocked, !systemNotificationSleeping,
              UserDefaults.standard.object(forKey: "rium.light.enabled") as? Bool ?? true,
              UserDefaults.standard.object(forKey: "rium.light.airdrop") as? Bool ?? true,
              UserDefaults.standard.object(forKey: "rium.light.edgeWave") as? Bool ?? true else { return }
        enqueueEdgeWave(EdgeWaveCue(started: ProcessInfo.processInfo.systemUptime, inward: inward))
    }
    fileprivate func enqueueEdgeWave(_ cue: EdgeWaveCue) {
        // shortcut: overlapping AirDrop waves are retained independently; compare
        // their compositing and the limit with the reference during visual QA.
        edgeWaves.append(cue)
        if edgeWaves.count > 6 { edgeWaves.removeFirst(edgeWaves.count - 6) }
        onEdgeWaveChange?()
        DispatchQueue.main.asyncAfter(deadline: .now() + (cue.inward ? 2.6 : 3.0)) { [weak self] in
            guard let self, self.edgeWaves.contains(where: { $0.id == cue.id }) else { return }
            self.edgeWaves.removeAll { $0.id == cue.id }
            self.onEdgeWaveChange?()
        }
    }
    fileprivate func showBatteryEvent(_ event: PowerModel.Event, preferences: UserDefaults = .standard) {
        guard notchScreenAvailable, preferences.object(forKey: "rium.light.battery") as? Bool ?? true else { return }
        let peek: BatteryPeek
        switch event {
        case .source(let percent, let external):
            peek = BatteryPeek(percentage: percent, external: external, critical: nil)
            showLight(.batterySource(percent, external))
        case .warning(let percent, let critical):
            peek = BatteryPeek(percentage: percent, external: false, critical: critical)
            showLight(.batteryWarning(critical))
        }
        batteryPeekGeneration += 1; let generation = batteryPeekGeneration; batteryPeek = peek
        DispatchQueue.main.asyncAfter(deadline: .now() + batteryFeedbackDuration(critical: peek.critical)) { [weak self] in
            guard let self = self, self.batteryPeekGeneration == generation else { return }
            self.batteryPeek = nil
        }
    }
    private func showAgendaLight(_ kind: NotchLightCue.Kind) {
        if expanded {
            if !pendingAgendaLightCues.contains(kind) { pendingAgendaLightCues.append(kind) }
        } else { showLight(kind) }
    }
    func setHoverSuspended(_ suspended: Bool) {
        if hoverSuspended != suspended { hoverSuspended = suspended }
        if suspended {
            hoverWork?.cancel(); hoverWork = nil
            setClipboardSearchEditing(false)
            clipboardPasteGeneration &+= 1
            clipboardHistoryDestination = nil
        }
    }
    private var hoverEditingBlocksCollapse: Bool { tabEditing || notesEditing || promptEditing || assistantEditing || clipboardSearchEditing }

    fileprivate func holdExpandedNotchAfterAgentAction() {
        guard expanded else { return }
        agentActionHoldUntil = ProcessInfo.processInfo.systemUptime + rustNotchAgentActionHoldDuration()
    }

    func beginAgentSwitcher() -> Bool {
        guard !agentSwitcherVisible, notchScreenAvailable, !hoverSuspended, !fileDragActive,
              !dictationDisplayActive, !homeEditing, !hoverEditingBlocksCollapse else { return false }
        hoverWork?.cancel(); hoverWork = nil
        expandedBeforeAgentSwitcher = expanded
        agentSwitcherSelection = externalAgentItems.first?.sessionKey
        agentSwitcherNotice = ""
        agentSwitcherVisible = true
        if !expanded { expanded = true }
        return true
    }

    var selectedSwitcherAgent: AgentActivity? {
        externalAgentItems.first { $0.sessionKey == agentSwitcherSelection }
    }

    func moveAgentSwitcherSelection(by direction: Int32) {
        guard agentSwitcherVisible else { return }
        let items = externalAgentItems
        let current = items.firstIndex { $0.sessionKey == agentSwitcherSelection } ?? -1
        let next = rustNotchAgentSwitcherIndex(items.count, current, direction)
        agentSwitcherSelection = items.indices.contains(next) ? items[next].sessionKey : nil
        agentSwitcherNotice = ""
    }

    func endAgentSwitcher() {
        guard agentSwitcherVisible else { return }
        agentSwitcherVisible = false
        agentSwitcherSelection = nil
        agentSwitcherNotice = ""
        if expanded != expandedBeforeAgentSwitcher { expanded = expandedBeforeAgentSwitcher }
    }

    func handleHover(_ inside: Bool) {
        guard !agentSwitcherVisible, !hoverSuspended, !fileDragActive,
              !hoverExpansionBlocked, inside || !hoverEditingBlocksCollapse else { return }
        hoverWork?.cancel()
        guard menuTrackingDepth == 0 else { return }
        if inside && !hoverEnabled { return }
        guard inside != expanded else { return }
        if !inside && !autoHideEnabled { return }
        let delay = inside ? hoverReopenWait(lastCollapse: lastCollapse, now: ProcessInfo.processInfo.systemUptime)
                           : rustNotchHoverCloseDelay(autoHideDelay, homeEditing ? 1 : 0)
        if delay <= 0 { expanded = inside; return }
        scheduleHoverTransition(inside, after: delay)
    }

    private func scheduleHoverTransition(_ inside: Bool, after delay: TimeInterval) {
        let task = DispatchWorkItem { [weak self] in
            guard let self = self else { return }
            self.hoverWork = nil
            let pointer = (NSApp?.delegate as? AppDelegate)?.pointIsInsideNotch(NSEvent.mouseLocation)
            let locked = self.hoverSuspended || self.fileDragActive || self.hoverExpansionBlocked ||
                         self.menuTrackingDepth != 0 || self.hoverEditingBlocksCollapse
            guard hoverTransitionAllowed(inside: inside, expanded: self.expanded, hoverEnabled: self.hoverEnabled,
                                         autoHide: self.autoHideEnabled, interactionLocked: locked, pointerInside: pointer) else { return }
            let holdRemaining = self.agentActionHoldUntil - ProcessInfo.processInfo.systemUptime
            if !inside && holdRemaining > 0 {
                self.scheduleHoverTransition(false, after: holdRemaining)
                return
            }
            self.expanded = inside
        }
        hoverWork = task; DispatchQueue.main.asyncAfter(deadline: .now() + delay, execute: task)
    }

    func beginMenuTracking() {
        guard expanded || menuTrackingDepth > 0 else { return }
        menuTrackingDepth += 1
        hoverWork?.cancel(); hoverWork = nil
    }

    func endMenuTracking(pointerInside: Bool) {
        guard menuTrackingDepth > 0 else { return }
        menuTrackingDepth -= 1
        if menuTrackingDepth == 0 { handleHover(pointerInside) }
    }

    func leaveFileDropTarget() {
        guard fileDragActive, shelfDragExitWork == nil else { return }
        // The drop view can briefly exit while the notch changes size.
        let work = DispatchWorkItem { [weak self] in
            self?.setFileDragActive(false)
        }
        shelfDragExitWork = work
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.1, execute: work)
    }

    func setFileDragActive(_ active: Bool) {
        shelfDragExitWork?.cancel()
        shelfDragExitWork = nil
        guard fileDragActive != active, !active || !shelfOutgoingDragActive else { return }
        reportDropDiagnostic("targeted=\(active)")
        if active {
            shelfDragWidth = expanded || floatingIslandPlacement != nil ? 0 : collapsedNotchSize.width
        }
        fileDragActive = active; hoverWork?.cancel(); hoverWork = nil
        if active {
            shelfDropGeneration += 1; shelfDropPending = false
            shelfConfirmationGeneration += 1; shelfConfirmedFiles.removeAll(); shelfConfirmationMessage = nil; shelfConfirmationKind = .shelf
            if expanded || floatingIslandPlacement != nil { select(.shelf); expanded = true }
        } else {
            shelfDropZone = nil
            if expanded {
                let inside = (NSApp.delegate as? AppDelegate)?.pointIsInsideNotch(NSEvent.mouseLocation) ?? false
                handleHover(inside)
            }
            presentDeferredScreenshotIfPossible()
        }
    }

    func monitorMemoryPressure() {
        let source = DispatchSource.makeMemoryPressureSource(eventMask: [.normal, .warning, .critical], queue: .main)
        source.setEventHandler { [weak self, weak source] in
            guard let self = self, let data = source?.data else { return }
            if data.contains(.critical) { self.pressureEvent = "위험" }
            else if data.contains(.warning) { self.pressureEvent = "주의" }
            else if data.contains(.normal) { self.pressureEvent = "정상" }
            self.pressure = currentMemoryPressure() ?? self.pressureEvent ?? "조회 불가"
        }
        pressureSource = source; source.resume()
    }

    func advanceMedia() {
        sampleMediaOutput()
        guard mediaPlaying, mediaPositionKnown, mediaDuration.isFinite, mediaDuration >= 0, mediaObservedUptime > 0 else { return }
        mediaElapsed = currentMediaElapsed(at: ProcessInfo.processInfo.systemUptime)
    }
    func refreshWallClock(forceRefresh: Bool = false) {
        let current = Date(), uptime = ProcessInfo.processInfo.systemUptime
        let dayStart = Calendar.current.startOfDay(for: current), zone = TimeZone.current.identifier
        let dayChanged = dayStart != observedDayStart || zone != observedTimeZone
        let wallDelta = current.timeIntervalSince(clockWallSample), uptimeDelta = uptime - clockUptimeSample
        let clockChanged = !wallDelta.isFinite || !uptimeDelta.isFinite || uptimeDelta < 0 || abs(wallDelta - uptimeDelta) > 3
        observedDayStart = dayStart; observedTimeZone = zone
        clockWallSample = current; clockUptimeSample = uptime
        if forceRefresh || dayChanged || clockChanged || mediaTick % 60 == 0 {
            now = current
            refreshWeatherConditions()
        }
        if dayChanged { agenda.invalidateToday() }
        if forceRefresh || dayChanged || clockChanged { agenda.refreshAuthorized() }
        if clockChanged && timerState == 1 {
            // The active timer uses a monotonic clock; its persisted deadline
            // uses wall time so it can survive app restarts. Re-anchor that
            // checkpoint after a clock change or sleep without moving the timer.
            updateTimer()
            if timerState == 1 { saveTimer(at: current) }
        }
    }
    func currentMediaElapsed(at uptime: TimeInterval) -> Double {
        return projectedMediaElapsed(base: mediaBaseElapsed, observed: mediaObservedUptime, current: mediaElapsed,
                                     duration: mediaDuration, playing: mediaPlaying, rate: mediaPlaybackRate, uptime: uptime)
    }

    func musicWaveContext(at uptime: TimeInterval) -> MusicWaveContext {
        let seed = musicWaveSeed(mediaObservation?.identity.source ?? "", mediaObservation?.identity.title ?? "")
        let renderTime = Date().timeIntervalSinceReferenceDate + (uptime - ProcessInfo.processInfo.systemUptime)
        let playbackTime: TimeInterval
        if mediaPositionKnown && mediaObservedUptime > 0 && uptime.isFinite {
            playbackTime = currentMediaElapsed(at: uptime)
        } else {
            playbackTime = renderTime
        }
        return MusicWaveContext(seed: seed, playbackTime: playbackTime, renderTime: renderTime)
    }

    func scheduleSampling() {
        timer?.invalidate()
        timer = Timer.scheduledTimer(withTimeInterval: TimeInterval(sampleInterval), repeats: true) { [weak self] _ in self?.sample() }
    }
    func setUsageTrackingEnabled(_ enabled: Bool) {
        guard usageTrackingEnabled != enabled else { return }
        usageTrackingEnabled = enabled
        guard servicesEnabled else { return }
        UserDefaults.standard.set(enabled, forKey: "rium.monitor.enabled")
        if enabled {
            sample()
            monitorMemoryPressure()
            scheduleSampling()
            listAccounts()
            accountTimer = Timer.scheduledTimer(withTimeInterval: 300, repeats: true) { [weak self] _ in
                guard let self, let id = self.monitorAccountID,
                      self.accounts.contains(where: { $0.id == id }) else { return }
                self.refresh(id)
            }
        } else {
            timer?.invalidate(); timer = nil
            accountTimer?.invalidate(); accountTimer = nil
            pressureSource?.cancel(); pressureSource = nil; pressureEvent = nil
        }
    }
    func setMonitorAccount(_ id: String?) {
        monitorAccountID = id
        guard servicesEnabled else { return }
        UserDefaults.standard.set(id, forKey: "rium.monitor.account")
        if usageTrackingEnabled, let id { refresh(id) }
    }
    func setSampleInterval(_ seconds: Int) {
        guard [2, 5, 10].contains(seconds) else { return }
        sampleInterval = seconds; UserDefaults.standard.set(seconds, forKey: "rium.monitor.interval"); scheduleSampling()
    }
    func setLaunchAtLogin(_ enabled: Bool) {
        do {
            if enabled { try SMAppService.mainApp.register() } else { try SMAppService.mainApp.unregister() }
            launchAtLogin = SMAppService.mainApp.status == .enabled
            settingsMessage = SMAppService.mainApp.status == .requiresApproval ? "시스템 설정에서 로그인 항목을 허용해 주세요" : ""
        } catch { launchAtLogin = SMAppService.mainApp.status == .enabled; settingsMessage = "로그인 항목을 변경할 수 없습니다" }
    }

    func restoreHomeLayout() {
        tabOrder = NotchTab.normalized(layoutPreferences?.stringArray(forKey: "rium.home.tabOrder"),
                                       preservesHidden: (layoutPreferences?.integer(forKey: "rium.home.tabOrderVersion") ?? 0) >= 2)
        homeNote = layoutPreferences?.string(forKey: "rium.home.note") ?? ""
        for slot in HomeSlot.allCases {
            let value = layoutPreferences?.string(forKey: "rium.home.variant.\(slot.rawValue)") ?? slot.defaultVariant
            homeVariantValues[slot.rawValue] = slot.variants.contains(where: { $0.id == value }) ? value : slot.defaultVariant
        }
        homeBackground = layoutPreferences?.string(forKey: "rium.home.background").flatMap(HomeBackground.init(rawValue:)) ?? .dynamic
    }
    func homeVariant(_ slot: HomeSlot) -> String { homeVariantValues[slot.rawValue] ?? slot.defaultVariant }
    func setHomeVariant(_ value: String, for slot: HomeSlot) {
        guard slot.variants.contains(where: { $0.id == value }) else { return }
        homeVariantValues[slot.rawValue] = value
        layoutPreferences?.set(value, forKey: "rium.home.variant.\(slot.rawValue)")
    }
    func setHomeBackground(_ value: HomeBackground) {
        homeBackground = value; layoutPreferences?.set(value.rawValue, forKey: "rium.home.background")
    }
    func editHomeNote() {
        guard !homeEditing else { return }
        let alert = NSAlert()
        alert.messageText = "홈 메모"
        alert.addButton(withTitle: "저장")
        alert.addButton(withTitle: "취소").keyEquivalent = "\u{1b}"
        let scroll = NSScrollView(frame: NSRect(x: 0, y: 0, width: 360, height: 110))
        let editor = NSTextView(frame: scroll.bounds)
        editor.string = homeNote; editor.isRichText = false; editor.isVerticallyResizable = true
        editor.textContainer?.widthTracksTextView = true
        scroll.hasVerticalScroller = true; scroll.documentView = editor
        alert.accessoryView = scroll
        alert.window.initialFirstResponder = editor
        NSApp.activate(ignoringOtherApps: true)
        guard alert.runModal() == .alertFirstButtonReturn else { return }
        homeNote = editor.string
        layoutPreferences?.set(homeNote, forKey: "rium.home.note")
    }
    func beginHomeEdit(slot: HomeSlot? = nil) {
        setNotesEditing(false); setPromptEditing(false); setAssistantEditing(false)
        if let slot { homeSelectedSlot = slot }
        hoverWork?.cancel(); draggingTab = nil; tabEditing = false; section = .home; expanded = true; homeEditing = true
    }
    func beginTabEdit() {
        setNotesEditing(false); setPromptEditing(false); setAssistantEditing(false)
        hoverWork?.cancel(); draggingTab = nil; homeEditing = false; section = .home; expanded = true; tabEditing = true
        if selectedTab == .home || !tabOrder.contains(selectedTab) { selectedTab = tabOrder.first(where: { $0 != .home }) ?? .home }
    }
    func finishEditing(pointerInside: Bool? = nil) {
        let wasEditing = homeEditing || tabEditing
        homeEditing = false; tabEditing = false; draggingTab = nil
        guard wasEditing else { return }
        hoverWork?.cancel(); hoverWork = nil
        // Reconcile with the regular close delay as soon as editing finishes.
        let inside = pointerInside ?? ((NSApp.delegate as? AppDelegate)?.pointIsInsideNotch(NSEvent.mouseLocation) ?? true)
        handleHover(inside)
    }
    private func saveTabOrder() {
        layoutPreferences?.set(tabOrder.map(\.rawValue), forKey: "rium.home.tabOrder")
        layoutPreferences?.set(2, forKey: "rium.home.tabOrderVersion")
    }
    func addTab(_ tab: NotchTab) {
        guard tab != .home, !tabOrder.contains(tab) else { return }
        tabOrder.append(tab); selectedTab = tab; saveTabOrder()
    }
    func removeTab(_ tab: NotchTab) {
        guard tab != .home, let index = tabOrder.firstIndex(of: tab) else { return }
        tabOrder.remove(at: index)
        if selectedTab == tab { selectedTab = tabOrder.first(where: { $0 != .home }) ?? .home }
        saveTabOrder()
    }
    func moveTab(_ tab: NotchTab, by delta: Int) {
        guard tab != .home, let from = tabOrder.firstIndex(of: tab) else { return }
        let to = from + delta
        guard to >= 1, to < tabOrder.count else { return }
        tabOrder.swapAt(from, to); saveTabOrder()
    }
    func moveTab(_ tab: NotchTab, to target: NotchTab) {
        guard tab != .home, target != .home, let from = tabOrder.firstIndex(of: tab), let to = tabOrder.firstIndex(of: target), from != to else { return }
        tabOrder.remove(at: from); tabOrder.insert(tab, at: to)
        selectedTab = tab; saveTabOrder()
    }

    func select(_ next: PanelSection) {
        if next != .home && (homeEditing || tabEditing) { finishEditing() }
        if next != .notes { setNotesEditing(false) }
        if next != .teleprompter { setPromptEditing(false) }
        if next != .assistant { setAssistantEditing(false) }
        if next == .clipboard && section != .clipboard && expanded { rememberClipboardDestination() }
        if next != .clipboard {
            setClipboardSearchEditing(false)
            clipboardHistoryDestination = nil
        }
        section = next
        if next == .agenda || next == .home { agenda.refreshAuthorized() }
        if next == .shelf { reloadShelf() }
        if next == .music || next == .home { refreshMedia() }
        if next == .agents { refreshAgents() }
    }

    func setNotesEditing(_ editing: Bool) {
        guard notesEditing != editing else { return }
        notesEditing = editing
        hoverWork?.cancel(); hoverWork = nil
        if !editing {
            notes.finishEditing()
            if expanded {
                let inside = (NSApp?.delegate as? AppDelegate)?.pointIsInsideNotch(NSEvent.mouseLocation) ?? true
                handleHover(inside)
            }
        }
    }

    func setClipboardSearchEditing(_ editing: Bool) {
        guard !editing || (expanded && section == .clipboard && !hoverSuspended && notchScreenAvailable),
              editing != clipboardSearchEditing else { return }
        clipboardSearchEditing = editing
        hoverWork?.cancel(); hoverWork = nil
        onClipboardSearchKeyChange?(editing)
        if !editing && expanded {
            let inside = (NSApp?.delegate as? AppDelegate)?.pointIsInsideNotch(NSEvent.mouseLocation) ?? true
            handleHover(inside)
        }
    }

    func setAssistantEditing(_ editing: Bool) {
        let active = editing && section == .assistant
        guard assistantEditing != active else { return }
        assistantEditing = active
        hoverWork?.cancel(); hoverWork = nil
        if !active {
            let inside = (NSApp.delegate as? AppDelegate)?.pointIsInsideNotch(NSEvent.mouseLocation) ?? true
            handleHover(inside)
        }
    }

    func setPromptEditing(_ editing: Bool) {
        let active = editing && section == .teleprompter && !teleprompter.isDetached
        guard promptEditing != active else { return }
        promptEditing = active
        hoverWork?.cancel(); hoverWork = nil
        if !active {
            let inside = (NSApp.delegate as? AppDelegate)?.pointIsInsideNotch(NSEvent.mouseLocation) ?? true
            handleHover(inside)
        }
    }

    func stopAssistantSpeech() {
        assistantSpeechSuppressed.formUnion(assistantSpeechChunks.keys)
        assistantSpeechChunks.removeAll()
        assistantSpeech.stop()
    }

    private func speakAssistantUpdate(id: String, text: String, complete: Bool) {
        guard servicesEnabled else { return }
        if assistantSpeechSuppressed.contains(id) {
            if complete { assistantSpeechSuppressed.remove(id) }
            return
        }
        guard UserDefaults.standard.bool(forKey: "rium.assistant.speakResponses"),
              !systemNotificationScreenLocked, !systemNotificationSleeping, !FeedbackSound.quietForPrivacy,
              !dictationRecording, !interview.active, !voiceApproval.active else {
            stopAssistantSpeech()
            if complete { assistantSpeechSuppressed.remove(id) } else { assistantSpeechSuppressed.insert(id) }
            return
        }
        let chunker = assistantSpeechChunks[id] ?? AssistantSpeechChunks()
        assistantSpeechChunks[id] = chunker
        guard let result = chunker.consume(text, complete: complete), !result.invalidated else {
            stopAssistantSpeech()
            if complete { assistantSpeechSuppressed.remove(id) } else { assistantSpeechSuppressed.insert(id) }
            return
        }
        if complete { assistantSpeechChunks.removeValue(forKey: id) }
        for chunk in result.chunks {
            let utterance = AVSpeechUtterance(string: chunk)
            if let language = NLLanguageRecognizer.dominantLanguage(for: chunk) {
                utterance.voice = AVSpeechSynthesisVoice(language: language.rawValue)
            }
            assistantSpeech.speak(utterance)
        }
    }

    func startAssistantVoiceCapture() {
        guard servicesEnabled, assistant.phase == .ready else { return }
        if !deferredServicesStarted { startDeferredServices() }
        let conversation = assistant.activeConversationID
        dictation.beginAssistantCapture { [weak self] text in
            guard let self, let text, !text.isEmpty, self.assistant.phase == .ready,
                  self.assistant.activeConversationID == conversation else { return }
            let draft = self.assistant.draft
            let separator = draft.isEmpty || draft.last?.isWhitespace == true ? "" : " "
            self.assistant.draft = draft + separator + text
        }
        if dictation.assistantCaptureActive {
            assistantFinishGeneration += 1; assistantFinishing = false; assistantFinishStarted = nil
        }
    }

    func startInterview(includeSystemAudio: Bool) {
        guard !dictationRecording else { return }
        dictation.cancelAssistantCapture()
        stopAssistantSpeech()
        voiceApproval.cancel()
        interview.start(language: dictation.languageID, includeSystemAudio: includeSystemAudio)
    }

    func sampleVolume(limitDirection: Int32 = 0) {
        guard !systemNotificationSleeping, !systemNotificationScreenLocked else { return }
        var value = -1.0; var muted: Int32 = 0; var device: UInt32 = 0
        let flags = outputVolume(&value, &muted, &device)
        volumeObserver?.observeDevice(device)
        recordVolume(percent: flags & 1 != 0 ? value : nil, muted: flags & 2 != 0 ? muted != 0 : nil,
                     device: device == 0 ? nil : device, limitDirection: limitDirection)
        expireControlOverlay(at: ProcessInfo.processInfo.systemUptime)
    }
    func expireControlOverlay(at uptime: TimeInterval) {
        if !volumeOverlay.isEmpty && uptime >= volumeHideAt { volumeOverlay = "" }
    }
    func clearControlOverlay() {
        volumeOverlay = ""; volumeHideAt = 0
        activeLightCues.removeAll { $0.isSystemHUD }
        if lightCue?.isSystemHUD == true { lightCue = activeLightCues.last }
    }
    fileprivate func clearTransientLights() {
        clearShortcutPeeks()
        clearControlOverlay()
        batteryPeekGeneration += 1; batteryPeek = nil
        lastVolumeLevel = nil; lastMuted = nil; brightnessBaseline = nil
        activeLightCues.removeAll(); lightCue = nil
        let hadScreenWaves = !edgeWaves.isEmpty || !notchScreenWaves.isEmpty
        edgeWaves.removeAll(); notchScreenWaves.removeAll()
        if hadScreenWaves { onEdgeWaveChange?() }
    }
    func recordVolume(percent: Double?, muted: Bool?, device: UInt32? = nil, limitDirection: Int32 = 0) {
        guard !systemNotificationSleeping, !systemNotificationScreenLocked else { return }
        if let device = device {
            if let previous = volumeDeviceID, previous != device {
                lastVolumeLevel = nil; lastMuted = nil
                if overlaySymbol.hasPrefix("speaker.") { clearControlOverlay() }
            }
            volumeDeviceID = device
        }
        let level = percent.flatMap { $0.isFinite && (0...100).contains($0) ? Int($0.rounded()) : nil }
        let label: String
        if muted == true { label = "음소거" }
        else if let level = level { label = "음량 \(level)%" }
        else if muted == false { label = "음소거 해제" }
        else { label = "음량 조회 불가" }
        let muteChanged = lastMuted != nil && muted != nil && lastMuted != muted
        let levelChanged = lastVolumeLevel != nil && level != nil && lastVolumeLevel != level && muted != true
        let pressedAtLimit = device != nil && lastVolumeLevel == level && muted != true &&
            systemControlAtLimit(percent ?? .nan, limitDirection) == 1
        if muteChanged || levelChanged || pressedAtLimit {
            let cue: NotchLightCue.Kind
            if muteChanged && muted == true { cue = .mute(true) }
            else if let level = level { cue = .systemLevel(level) }
            else if muteChanged { cue = .mute(false) }
            else { cue = .systemControl }
            showControlOverlay(label, symbol: muted == true ? "speaker.slash.fill" : "speaker.wave.2.fill", cue: cue,
                               previousSystemLevel: muteChanged ? nil : lastVolumeLevel,
                               restoringSound: muteChanged && muted == false && level != nil)
        }
        if volume != label { volume = label }
        lastVolumeLevel = level; lastMuted = muted
    }
    private func showControlOverlay(_ label: String, symbol: String, cue: NotchLightCue.Kind = .systemControl, previousSystemLevel: Int? = nil, restoringSound: Bool = false) {
        if clipboardPeek != nil { clearClipboardPeek() }
        let duration = systemHUDSeconds()
        let deadline = ProcessInfo.processInfo.systemUptime + duration
        volumeOverlay = label; overlaySymbol = symbol; volumeHideAt = deadline
        DispatchQueue.main.asyncAfter(deadline: .now() + duration) { [weak self] in
            guard let self, self.volumeHideAt == deadline else { return }
            self.expireControlOverlay(at: ProcessInfo.processInfo.systemUptime)
        }
        showLight(cue, previousSystemLevel: previousSystemLevel, restoringSound: restoringSound)
    }
    func selectDisplay(_ id: UInt32?) {
        guard id != selectedDisplayID else { return }
        invalidateRenderedNotchOutline()
        selectedDisplayID = id; brightnessBaseline = nil; brightnessDisplayID = nil
        if deferredServicesStarted { observeBrightness(on: id) }
        sampleBrightness()
    }
    func observeBrightness(on display: UInt32?) {
        guard observedBrightnessDisplay != display else { return }
        if let previous = observedBrightnessDisplay { _ = rustObserveDisplayBrightness(previous, nil) }
        observedBrightnessDisplay = nil
        if let display = display, rustObserveDisplayBrightness(display, displayBrightnessChanged) == 1 {
            observedBrightnessDisplay = display
        }
    }
    func handleBrightnessChange(on display: UInt32) {
        guard display == observedBrightnessDisplay, display == selectedDisplayID else { return }
        sampleBrightness()
    }
    func refreshDisplayChoices() {
        let screens = NSScreen.screens.filter { notchScreenFrameUsable($0.frame) }
        let connected = screens.enumerated().compactMap { index, screen -> NotchDisplayChoice? in
            guard let id = displayIdentifier(screen), id != 0 else { return nil }
            let name = screen.localizedName
            let title = screens.filter { $0.localizedName == name }.count > 1 ? "\(name) (\(index + 1))" : name
            return NotchDisplayChoice(id: id, name: title, key: notchDisplayKey(id))
        }
        let byKey = Dictionary(grouping: connected, by: \.key)
        let choices = connected.map { choice in
            // A duplicate UUID is ambiguous. Keep both screens selectable for this session.
            byKey[choice.key]?.count == 1 ? choice : NotchDisplayChoice(id: choice.id, name: choice.name, key: String(choice.id))
        }
        if availableDisplays != choices { availableDisplays = choices }
        if let layoutPreferences {
            let restored = NotchDisplayPreference(defaults: layoutPreferences).load(available: choices)
            if preferredDisplayKey != restored { preferredDisplayKey = restored }
        }
    }
    func setPreferredDisplay(_ key: String?) {
        guard key != preferredDisplayKey else { return }
        let choice = availableDisplays.first { $0.key == key }
        guard key == nil || choice != nil else { return }
        if let layoutPreferences { NotchDisplayPreference(defaults: layoutPreferences).save(choice) }
        preferredDisplayKey = key
        NotificationCenter.default.post(name: .notchDisplayChanged, object: nil)
    }
    func recordBrightness(display: UInt32, percent: Double?, limitDirection: Int32 = 0) {
        guard !systemNotificationSleeping, !systemNotificationScreenLocked else { return }
        guard let percent = percent, percent.isFinite, (0...100).contains(percent) else {
            if brightness != "밝기 조회 불가" { brightness = "밝기 조회 불가" }
            brightnessBaseline = nil; brightnessDisplayID = display
            return
        }
        let value = Int(percent.rounded())
        let label = "밝기 \(value)%"
        if brightnessDisplayID == display, let previous = brightnessBaseline,
           previous != value || systemControlAtLimit(percent, limitDirection) == 1 {
            showControlOverlay(label, symbol: "sun.max.fill", cue: .brightness(value), previousSystemLevel: previous)
        }
        if brightness != label { brightness = label }
        brightnessBaseline = value; brightnessDisplayID = display
    }
    func sampleBrightness(limitDirection: Int32 = 0) {
        guard !systemNotificationSleeping, !systemNotificationScreenLocked else { return }
        guard let display = selectedDisplayID else {
            if brightness != "밝기 조회 불가" { brightness = "밝기 조회 불가" }
            return
        }
        var value = -1.0
        let available = displayBrightness(display, &value) == 1
        recordBrightness(display: display, percent: available ? value : nil, limitDirection: limitDirection)
    }

    func toggleClipboard() {
        guard clipboardReady else { return }
        clipboardCaptureGeneration &+= 1
        clipboardChangeCount = pasteboard.changeCount
        clipboardEnabled.toggle()
        if !clipboardEnabled { clearClipboardPeek() }
        if clipboardRoot != nil { UserDefaults.standard.set(clipboardEnabled, forKey: "rium.clipboard.enabled") }
        (NSApp.delegate as? AppDelegate)?.configureShortcutMonitor()
    }

    private var systemHUDCoversClipboard: Bool { !volumeOverlay.isEmpty || caseKeyPeek != nil }

    private func clearClipboardPeek() {
        let previousState = currentNotchShellState
        clipboardPeekDismissal?.cancel()
        clipboardPeekDismissal = nil
        clipboardPeek = nil
        recordDetailFold(from: previousState)
    }

    @discardableResult func showClipboardPeek(_ kind: ClipboardPeekKind, content: ClipboardRecord.Content) -> Bool {
        guard clipboardReady, clipboardEnabled, let preview = clipboardPeekContent(content) else { return false }
        return presentClipboardPeek(kind, preview: preview)
    }
    @discardableResult private func showClipboardActivity(_ kind: ClipboardPeekKind) -> Bool {
        presentClipboardPeek(kind, preview: ClipboardPeekContent(text: "", symbol: "doc.on.clipboard"))
    }
    private func presentClipboardPeek(_ kind: ClipboardPeekKind, preview: ClipboardPeekContent) -> Bool {
        guard !expanded, notchScreenAvailable, !systemHUDCoversClipboard else { return false }
        clipboardPeekDismissal?.cancel()
        let peek = ClipboardPeek(kind: kind, content: preview)
        clipboardPeek = peek
        let work = DispatchWorkItem { [weak self] in
            guard let self, self.clipboardPeek?.id == peek.id else { return }
            self.clearClipboardPeek()
        }
        clipboardPeekDismissal = work
        DispatchQueue.main.asyncAfter(deadline: .now() + rustClipboardPreviewDuration(), execute: work)
        return true
    }

    @discardableResult func showClipboardPastePeek() -> Bool {
        guard shortcutPeeksEnabled, !systemNotificationScreenLocked, !systemNotificationSleeping else { return false }
        sampleClipboard()
        let count = pasteboard.changeCount
        guard clipboardAllowsPreview(pasteboard), pasteboard.changeCount == count else {
            clearClipboardPeek()
            return false
        }
        guard !expanded, !systemHUDCoversClipboard else { return false }
        guard clipboardReady, clipboardEnabled else { return showClipboardActivity(.pasted) }
        guard let captured = readClipboardContent(), pasteboard.changeCount == count,
              clipboardPeekContent(captured.content) != nil else {
            guard pasteboard.changeCount == count, clipboardAllowsPreview(pasteboard) else {
                clearClipboardPeek()
                return false
            }
            return showClipboardActivity(.pasted)
        }
        return showClipboardPeek(.pasted, content: captured.content)
    }

    func handleClipboardPasteShortcut(_ feedback: ShortcutFeedback) {
        guard feedback != .none, !systemNotificationScreenLocked, !systemNotificationSleeping else { return }
        sampleClipboard()
        let count = pasteboard.changeCount
        guard clipboardAllowsPreview(pasteboard), pasteboard.changeCount == count else {
            clearClipboardPeek()
            return
        }
        if feedback == .pasteLight {
            showLight(.clipboardPaste)
            return
        }
        guard !systemHUDCoversClipboard else { return }
        let presented = showClipboardPastePeek()
        // A provider may change the metadata during the preview read.
        guard clipboardAllowsPreview(pasteboard), pasteboard.changeCount == count else {
            clearClipboardPeek()
            return
        }
        if presented { showLight(.shortcut(.paste)) }
        else { showShortcutPeek(.paste) }
    }

    private func restoreClipboard() {
        let support = FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask).first ?? FileManager.default.homeDirectoryForCurrentUser.appendingPathComponent("Library/Application Support", isDirectory: true)
        let root = support.appendingPathComponent("Rium Notch", isDirectory: true)
        clipboardChangeCount = pasteboard.changeCount
        let initialChangeCount = clipboardChangeCount
        clipboardRoot = root; clipboardReady = false
        clipboardQueue.async { [weak self] in
            let result = root.path.withCString { clipboardLoad($0) }
            DispatchQueue.main.async { [weak self] in
                guard let self = self else { return }
                self.clipboardCanSave = result == 0
                self.clipboardStorageStatus = result == 0 ? "" : "저장된 기록을 읽지 못해 이번 실행의 기록은 저장하지 않습니다."
                if result == 0 { self.reloadClipboard(replacingHistory: true) }
                self.finishClipboardRestore(initialChangeCount: initialChangeCount,
                                            historyEnabled: UserDefaults.standard.bool(forKey: "rium.clipboard.enabled"))
                (NSApp.delegate as? AppDelegate)?.configureShortcutMonitor()
            }
        }
    }
    func finishClipboardRestore(initialChangeCount: Int, historyEnabled: Bool) {
        clipboardEnabled = historyEnabled; clipboardReady = true
        let current = pasteboard.changeCount
        let interrupted = clipboardRestoreInterrupted
        if interrupted { clipboardChangeCount = current }
        clipboardRestoreInterrupted = false
        // shortcut: only the latest clipboard item can be recovered after restoration.
        if !interrupted && historyEnabled && current != initialChangeCount && current == clipboardChangeCount {
            captureClipboard(count: current)
        } else {
            sampleClipboard()
        }
    }
    private func scheduleClipboardSave(afterClear: Bool = false) {
        guard clipboardCanSave, let root = clipboardRoot else { return }
        clipboardQueue.async { [weak self] in
            let result = root.path.withCString { afterClear ? clipboardSaveAfterClear($0) : clipboardSave($0) }
            DispatchQueue.main.async { [weak self] in self?.clipboardStorageStatus = result == 0 ? "" : "클립보드 기록을 저장하지 못했습니다." }
        }
    }
    func flushClipboard() { if clipboardRoot != nil { clipboardQueue.sync {} } }

    private func readClipboardContent() -> (kind: String, data: Data, content: ClipboardRecord.Content)? {
        let board = pasteboard
        // Password managers can mark pasteboard entries as confidential or transient.
        guard clipboardAllowsPreview(board) else { return nil }
        let types = Set(board.types?.map(\.rawValue) ?? [])
        if types.contains(NSPasteboard.PasteboardType.fileURL.rawValue) {
            guard let urls = board.readObjects(forClasses: [NSURL.self], options: [.urlReadingFileURLsOnly: true]) as? [URL],
                  !urls.isEmpty, urls.count <= 100,
                  let encoded = try? JSONEncoder().encode(urls.map(\.absoluteString)) else { return nil }
            return ("files", encoded, .files(urls))
        } else if types.contains(NSPasteboard.PasteboardType.png.rawValue), let png = board.data(forType: .png) {
            return ("image/png", png, .image(png, .png))
        } else if types.contains(NSPasteboard.PasteboardType.tiff.rawValue), let tiff = board.data(forType: .tiff) {
            return ("image/tiff", tiff, .image(tiff, .tiff))
        } else if let text = board.string(forType: .string) ?? board.string(forType: .URL), let encoded = text.data(using: .utf8) {
            return ("text", encoded, .text(text))
        }
        return nil
    }

    func sampleClipboard() {
        let board = pasteboard
        let count = board.changeCount
        guard count != clipboardChangeCount else { return }
        clipboardCaptureGeneration &+= 1
        clipboardChangeCount = count
        guard !systemNotificationScreenLocked, !systemNotificationSleeping else { return }
        clipboardRestoreInterrupted = false
        // Check the privacy markers without fetching the copied payload.
        guard clipboardAllowsPreview(board), board.changeCount == count else {
            clearClipboardPeek()
            return
        }
        showLight(.clipboard)
        guard clipboardReady, clipboardEnabled else { showClipboardActivity(.copied); return }
        captureClipboard(count: count)
    }

    private func captureClipboard(count: Int, retriesRemaining: Int = 4, previewID: UUID? = nil) {
        let board = pasteboard
        guard clipboardReady, clipboardEnabled, !systemNotificationScreenLocked, !systemNotificationSleeping,
              board.changeCount == count, clipboardChangeCount == count else {
            clipboardPendingRetry = nil
            return
        }
        let pending = clipboardPendingRetry
        let ownsPreview = previewID != nil && clipboardPeek?.id == previewID
        guard let captured = readClipboardContent(), board.changeCount == count, clipboardAllowsPreview(board) else {
            guard board.changeCount == count, clipboardAllowsPreview(board) else {
                if pending == nil || ownsPreview { clearClipboardPeek() }
                clipboardPendingRetry = nil
                return
            }
            guard retriesRemaining > 0 else { clipboardPendingRetry = nil; return }
            let generation = clipboardCaptureGeneration
            let shownID: UUID?
            if pending == nil {
                shownID = showClipboardActivity(.copied) ? clipboardPeek?.id : nil
                clipboardPendingRetry = PendingClipboardRetry(generation: generation)
            } else {
                shownID = previewID
            }
            // shortcut: retry for about 0.8 seconds; extend only if a real writer needs longer.
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.2) { [weak self] in
                guard let self, self.clipboardPendingRetry?.generation == generation else { return }
                self.captureClipboard(count: count, retriesRemaining: retriesRemaining - 1, previewID: shownID)
            }
            return
        }
        clipboardPendingRetry = nil
        guard pending?.allows(captured.content) ?? true else { return }
        if pending == nil || ownsPreview {
            if clipboardPeekContent(captured.content) == nil { showClipboardActivity(.copied) }
            else { showClipboardPeek(.copied, content: captured.content) }
        }
        let added = captured.kind.withCString { name in captured.data.withUnsafeBytes { bytes in clipboardAddRecord(name, bytes.baseAddress, bytes.count) } }
        if added { reloadClipboard(); scheduleClipboardSave() }
    }

    func reloadClipboard(replacingHistory: Bool = false) {
        guard let raw = clipboardJSON() else { return }
        defer { clipboardFree(raw) }
        let data = Data(bytes: raw, count: strlen(raw))
        let metadata = (try? JSONDecoder().decode([ClipboardMetadata].self, from: data)) ?? []
        // Rust preserves IDs for unchanged payloads, but allocates them again when loading an archive.
        let current = replacingHistory ? [:] : Dictionary(uniqueKeysWithValues: clipboardItems.map { ($0.id, $0.content) })
        clipboardItems = metadata.compactMap { item in
            guard item.size > 0, item.size <= 8 * 1024 * 1024 else { return nil }
            let copiedAt = item.copiedAtMs.map { Date(timeIntervalSince1970: Double($0) / 1000) }
            if let content = current[item.id] {
                return ClipboardRecord(id: item.id, content: content, pinned: item.pinned ?? false, copiedAt: copiedAt)
            }
            var length = 0
            guard let bytes = clipboardCopyData(item.id, &length) else { return nil }
            defer { clipboardFreeData(bytes, length) }
            guard length == item.size else { return nil }
            let data = Data(bytes: bytes, count: length)
            switch item.kind {
            case "text":
                guard let text = String(data: data, encoding: .utf8) else { return nil }
                return ClipboardRecord(id: item.id, content: .text(text), pinned: item.pinned ?? false, copiedAt: copiedAt)
            case "files":
                guard let values = try? JSONDecoder().decode([String].self, from: data) else { return nil }
                let urls = values.compactMap(URL.init(string:)).filter(\.isFileURL)
                guard !urls.isEmpty, urls.count == values.count else { return nil }
                return ClipboardRecord(id: item.id, content: .files(urls), pinned: item.pinned ?? false, copiedAt: copiedAt)
            case "image/png", "image/tiff":
                guard NSImage(data: data) != nil else { return nil }
                return ClipboardRecord(id: item.id, content: .image(data, item.kind == "image/png" ? .png : .tiff), pinned: item.pinned ?? false, copiedAt: copiedAt)
            default: return nil
            }
        }
    }

    @discardableResult func copyClipboard(_ record: ClipboardRecord, showCue: Bool = true) -> Bool {
        clipboardCaptureGeneration &+= 1
        let board = pasteboard; board.clearContents()
        let written: Bool
        switch record.content {
        case .text(let value): written = board.setString(value, forType: .string)
        case .files(let urls): written = board.writeObjects(urls as [NSURL])
        case .image(let data, let type): written = board.setData(data, forType: type)
        }
        clipboardChangeCount = board.changeCount
        guard written else { clipboardActionStatus = "클립보드에 복사하지 못했습니다."; return false }
        clipboardActionStatus = ""
        if showCue { showLight(.clipboard); showClipboardPeek(.copied, content: record.content) }
        return true
    }
    fileprivate func rememberClipboardDestination() {
        let frontmost = NSWorkspace.shared.frontmostApplication?.processIdentifier
        let own = ProcessInfo.processInfo.processIdentifier
        clipboardHistoryDestination = nil
        guard notchScreenAvailable, !hoverSuspended, frontmost != own, AXIsProcessTrusted(), let current = ClipboardPasteDestination.focused(),
              clipboardPasteTargetMatches(frontmost: frontmost, focused: current.pid, own: own, secure: current.secure) else { return }
        clipboardHistoryDestination = current
    }

    func pasteClipboard(_ record: ClipboardRecord) {
        clipboardPasteGeneration &+= 1
        guard notchScreenAvailable, !hoverSuspended else { return }
        guard AXIsProcessTrusted(), CGPreflightPostEventAccess() else {
            clipboardActionStatus = "붙여넣으려면 손쉬운 사용 권한이 필요합니다."
            return
        }
        let frontmost = NSWorkspace.shared.frontmostApplication?.processIdentifier
        let own = ProcessInfo.processInfo.processIdentifier
        let focused = ClipboardPasteDestination.focused()
        let destination: ClipboardPasteDestination?
        if let focused, clipboardPasteTargetMatches(frontmost: frontmost, focused: focused.pid, own: own, secure: focused.secure) {
            destination = focused
        } else if let saved = clipboardHistoryDestination, focused?.secure != true,
                  rustClipboardCanReturnFocus(saved.pid, frontmost ?? 0, focused?.pid ?? 0, own) == 1 {
            destination = saved
        } else {
            destination = nil
        }
        guard let destination,
              let down = CGEvent(keyboardEventSource: nil, virtualKey: 9, keyDown: true),
              let up = CGEvent(keyboardEventSource: nil, virtualKey: 9, keyDown: false) else {
            clipboardActionStatus = "이전 앱의 입력 위치를 확인할 수 없습니다."; return
        }
        down.flags = .maskCommand; up.flags = .maskCommand
        down.setIntegerValueField(.eventSourceUserData, value: riumPasteEventMarker)
        up.setIntegerValueField(.eventSourceUserData, value: riumPasteEventMarker)
        let notch = (NSApp?.delegate as? AppDelegate)?.panel
        if focused?.pid == own, notch?.isKeyWindow == true { notch?.resignKey() }
        if frontmost == own { NSApp?.deactivate() }
        scheduleClipboardPaste(record, destinationIsCurrent: {
            guard NSWorkspace.shared.frontmostApplication?.processIdentifier == destination.pid,
                  let current = ClipboardPasteDestination.focused(), current.pid == destination.pid, !current.secure else { return false }
            return CFEqual(current.element, destination.element)
                && (destination.selection.map { current.selection == $0 } ?? true)
        }, send: {
            down.postToPid(destination.pid); up.postToPid(destination.pid)
        })
    }

    fileprivate func scheduleClipboardPaste(_ record: ClipboardRecord, destinationIsCurrent: @escaping () -> Bool,
                                            send: @escaping () -> Void) {
        clipboardPasteGeneration &+= 1
        let generation = clipboardPasteGeneration
        let boardCount = pasteboard.changeCount
        clipboardActionStatus = "붙여넣을 위치를 확인하는 중…"
        DispatchQueue.main.asyncAfter(deadline: .now() + rustClipboardPasteHandoffDelay()) { [weak self] in
            guard let self, self.notchScreenAvailable, !self.hoverSuspended,
                  self.clipboardPasteGeneration == generation else { return }
            guard destinationIsCurrent() else {
                self.clipboardActionStatus = "입력 위치가 바뀌어 붙여넣기를 취소했습니다."
                return
            }
            guard self.pasteboard.changeCount == boardCount else {
                self.clipboardActionStatus = "클립보드 내용이 바뀌어 붙여넣기를 취소했습니다."
                return
            }
            guard self.copyClipboard(record, showCue: false) else { return }
            let samePosition = destinationIsCurrent()
            guard self.pasteboard.changeCount == self.clipboardChangeCount else {
                self.clipboardActionStatus = "클립보드 내용이 바뀌어 붙여넣기를 취소했습니다."
                return
            }
            guard samePosition else {
                self.showLight(.clipboard)
                self.showClipboardPeek(.copied, content: record.content)
                self.clipboardActionStatus = "입력 위치가 바뀌었습니다. 복사된 항목을 직접 붙여넣으세요."
                return
            }
            send()
            self.expanded = false
            self.showLight(.clipboardPaste)
            self.showClipboardPeek(.pasted, content: record.content)
            self.clipboardActionStatus = "이전 앱에 붙여넣기를 요청했습니다."
        }
    }
    func clearClipboardHistory() { guard clipboardReady else { return }; clipboardCaptureGeneration &+= 1; clipboardClear(); reloadClipboard(); scheduleClipboardSave(afterClear: true) }
    func toggleClipboardPin(_ record: ClipboardRecord) {
        guard clipboardReady, clipboardSetPinned(record.id, !record.pinned) else { return }
        reloadClipboard(); scheduleClipboardSave()
    }
    func removeClipboardRecord(_ record: ClipboardRecord) {
        guard clipboardReady, clipboardRemove(record.id) else { return }
        if clipboardPendingRetry?.generation == clipboardCaptureGeneration {
            clipboardPendingRetry?.removed.append(record.content)
        }
        reloadClipboard(); scheduleClipboardSave(afterClear: true)
    }

    func pomodoroValue(_ setting: PomodoroSetting) -> Int {
        switch setting { case .focus: return pomodoroFocus; case .shortBreak: return pomodoroShortBreak; case .longBreak: return pomodoroLongBreak; case .sessions: return pomodoroSessions }
    }
    private func assignPomodoroValue(_ setting: PomodoroSetting, _ value: Int) {
        switch setting { case .focus: pomodoroFocus = value; case .shortBreak: pomodoroShortBreak = value; case .longBreak: pomodoroLongBreak = value; case .sessions: pomodoroSessions = value }
    }
    private func restorePomodoroSettings() {
        for setting in PomodoroSetting.allCases {
            let value = timerPreferences?.object(forKey: setting.key) as? Int ?? setting.defaultValue
            assignPomodoroValue(setting, setting.range.contains(value) ? value : setting.defaultValue)
        }
    }
    func setPomodoroValue(_ setting: PomodoroSetting, _ value: Int) {
        guard setting.range.contains(value) else { return }
        assignPomodoroValue(setting, value)
        timerPreferences?.set(value, forKey: setting.key)
    }
    func updateTimer() {
        var seconds: UInt64 = 0
        let previous = timerState
        timerState = timerStatus(&seconds); timerRemaining = seconds
        if previous == 1 && timerState == 3 {
            timerAlarmGeneration &+= 1
            let generation = timerAlarmGeneration
            timerAlarmStartedAt = ProcessInfo.processInfo.systemUptime
            timerAlarmPhase = timerPhase
            timerAlarmTitle = timerPomodoro ? timerPhase.completionTitle : "타이머 완료"
            timerAlarmStatus = ""
            DispatchQueue.main.asyncAfter(deadline: .now() + timerAlarmPreviewSeconds()) { [weak self] in self?.expireTimerAlarm(generation) }
            showLight(.timerTransition(timerPhase))
            if servicesEnabled && !systemNotificationSleeping { FeedbackSound.startTimerAlarm() }
            if timerPomodoro && advancePomodoro(elapsed: timerOverdueSeconds()) {
                saveTimer()
                // Let the just-completed phase's scheduled alert arrive before
                // replacing it with the next phase's pending alert.
                syncTimerNotification(afterTransition: true)
                return
            }
            saveTimer()
        }
        if FeedbackSound.timerAlarmIsPlaying && (!FeedbackSound.timerEnabled || FeedbackSound.quietForPrivacy) { FeedbackSound.stopTimerAlarm() }
    }

    func stopTimerAlarm() {
        let previous = currentNotchShellState
        timerAlarmGeneration &+= 1
        FeedbackSound.stopTimerAlarm()
        timerAlarmStartedAt = nil
        timerAlarmPhase = nil
        timerAlarmTitle = nil; timerAlarmStatus = ""
        recordDetailFold(from: previous)
    }
    fileprivate func expireTimerAlarm(_ generation: UInt64) {
        guard timerAlarmGeneration == generation, timerAlarmTitle != nil else { return }
        stopTimerAlarm()
    }
    func timerAlarmProgress(at time: TimeInterval) -> Double {
        guard let started = timerAlarmStartedAt else { return 0 }
        return timerAlarmFraction(time - started)
    }
    func extendTimerAlarm(by seconds: UInt32) {
        guard timerAlarmTitle != nil, seconds == 60 || seconds == 300 else { return }
        let previousDuration = timerDuration
        let result = timerExtend(seconds)
        guard result >= 0 else { timerAlarmStatus = "타이머는 최대 24시간까지 설정할 수 있습니다."; return }
        var remaining: UInt64 = 0
        timerState = timerStatus(&remaining); timerRemaining = remaining
        timerDuration = result == 1 ? min(86_400, max((previousDuration ?? 0) + UInt64(seconds), remaining)) : UInt64(seconds)
        stopTimerAlarm(); showLight(.timerActivation(timerPhase)); saveTimer(); syncTimerNotification()
    }

    private func advancePomodoro(elapsed: Double) -> Bool {
        var next: Int32 = 0, completed: UInt64 = 0, remaining: UInt64 = 0
        guard let wholeSeconds = UInt64(exactly: elapsed.rounded(.down)),
              pomodoroAdvance(timerPhase.rawValue, timerSessions, wholeSeconds, UInt32(pomodoroFocus), UInt32(pomodoroShortBreak), UInt32(pomodoroLongBreak), UInt32(pomodoroSessions), &next, &completed, &remaining) == 0,
              let phase = FocusPhase(rawValue: next), remaining > 0,
              timerRestore(1, Double(remaining) - (elapsed - Double(wholeSeconds))) == 0 else { return false }
        let minutes: Int
        switch phase { case .focus: minutes = pomodoroFocus; case .shortBreak: minutes = pomodoroShortBreak; case .longBreak: minutes = pomodoroLongBreak }
        timerPhase = phase; timerSessions = completed; timerDuration = UInt64(minutes * 60)
        timerState = timerStatus(&remaining); timerRemaining = remaining
        return timerState == 1
    }

    func saveTimer(at now: Date = Date()) {
        guard let defaults = timerPreferences else { return }
        var checkpoint: [String: Any] = ["state": timerState, "mode": timerPomodoro ? "pomodoro" : "timer", "phase": timerPhase.rawValue, "sessions": timerSessions]
        if let duration = timerDuration, duration > 0, duration <= 86_400 { checkpoint["duration"] = duration }
        switch timerState {
        case 1: checkpoint["deadline"] = now.timeIntervalSince1970 + timerRemainingSeconds()
        case 2: checkpoint["remaining"] = timerRemainingSeconds()
        case 3: break
        default: defaults.removeObject(forKey: "rium.timer.checkpoint"); return
        }
        defaults.set(checkpoint, forKey: "rium.timer.checkpoint")
    }
    func restoreTimer(at now: Date = Date()) {
        guard let defaults = timerPreferences, let checkpoint = defaults.dictionary(forKey: "rium.timer.checkpoint"), let state = checkpoint["state"] as? Int else { return }
        timerDuration = (checkpoint["duration"] as? NSNumber).flatMap { number in
            let value = number.uint64Value
            return number.int64Value > 0 && value <= 86_400 ? value : nil
        }
        timerPomodoro = (checkpoint["mode"] as? String) == "pomodoro"
        if timerPomodoro {
            guard let rawPhase = checkpoint["phase"] as? Int, let phaseValue = Int32(exactly: rawPhase), let phase = FocusPhase(rawValue: phaseValue),
                  let count = checkpoint["sessions"] as? NSNumber, count.int64Value >= 0, count.uint64Value <= 1_000_000 else {
                timerPomodoro = false; defaults.removeObject(forKey: "rium.timer.checkpoint"); return
            }
            timerPhase = phase; timerSessions = count.uint64Value
        } else { timerPhase = .focus; timerSessions = 0 }
        var restoredState = state
        var remaining = 0.0
        if state == 1, let deadline = checkpoint["deadline"] as? Double, deadline.isFinite {
            remaining = deadline - now.timeIntervalSince1970
            if remaining <= 0 {
                let overdue = -remaining
                guard overdue.isFinite, overdue >= 0, overdue < Double(UInt64.max) else {
                    defaults.removeObject(forKey: "rium.timer.checkpoint"); return
                }
                if timerPomodoro && advancePomodoro(elapsed: overdue) { saveTimer(at: now); return }
                restoredState = 3; remaining = 0
            }
        } else if state == 2, let value = checkpoint["remaining"] as? NSNumber { remaining = value.doubleValue }
        else if state != 3 { defaults.removeObject(forKey: "rium.timer.checkpoint"); return }
        guard remaining.isFinite, remaining >= 0, remaining <= 86_400, [1, 2, 3].contains(restoredState),
              timerRestore(Int32(restoredState), remaining) == 0 else { defaults.removeObject(forKey: "rium.timer.checkpoint"); return }
        updateTimer(); if restoredState == 3 { saveTimer(at: now) }
    }
    private func notificationService() -> TimerNotificationService {
        if let service = timerNotificationService { return service }
        let service = TimerNotificationService()
        service.coordinator.onError = { [weak self] message in
            self?.timerNotificationsAuthorized = false
            self?.timerNotificationStatus = message
        }
        timerNotificationService = service
        return service
    }
    private func syncTimerNotification(afterTransition: Bool = false) {
        timerScheduleRevision += 1; let revision = timerScheduleRevision
        guard timerNotificationsEnabled, timerNotificationsAuthorized else { return }
        if timerState == 1 {
            let schedule = { [weak self] in
                guard let self = self, self.timerScheduleRevision == revision, self.timerNotificationsEnabled,
                      self.timerNotificationsAuthorized, self.timerState == 1 else { return }
                let title = self.timerPomodoro ? self.timerPhase.completionTitle : "타이머 완료"
                self.notificationService().coordinator.replace(remaining: { [weak self] in
                    guard self?.timerScheduleRevision == revision else { return 0 }
                    return timerRunningSeconds()
                }, title: title)
            }
            if afterTransition { DispatchQueue.main.asyncAfter(deadline: .now() + 1, execute: schedule) } else { schedule() }
        }
        else if timerState == 0 || timerState == 2 { notificationService().coordinator.replace(remaining: nil) }
    }
    func refreshTimerNotificationSound() { syncTimerNotification() }
    func refreshAgentNotificationPermission() {
        guard agentNotificationsEnabled else { return }
        agentNotificationPermissionRevision += 1; let revision = agentNotificationPermissionRevision
        notificationService().authorization { [weak self] granted in
            guard let self = self, self.agentNotificationsEnabled, self.agentNotificationPermissionRevision == revision else { return }
            self.agentNotificationsAuthorized = granted
            self.agentNotificationStatus = granted ? "" : "시스템 설정에서 Rium Notch 알림을 허용해 주세요."
        }
    }
