    func setTimerNotificationsEnabled(_ enabled: Bool) {
        timerPermissionRevision += 1; let revision = timerPermissionRevision
        timerScheduleRevision += 1
        timerNotificationsEnabled = enabled; UserDefaults.standard.set(enabled, forKey: "rium.timer.notifications")
        if !enabled {
            timerNotificationsAuthorized = false; timerNotificationStatus = ""
            timerNotificationService?.coordinator.replace(remaining: nil)
            return
        }
        timerNotificationStatus = "알림 권한 확인 중…"
        notificationService().requestAuthorization { [weak self] granted in
            guard let self = self, self.timerNotificationsEnabled, self.timerPermissionRevision == revision else { return }
            self.timerNotificationsAuthorized = granted
            self.timerNotificationStatus = granted ? "" : "시스템 설정에서 Rium Notch 알림을 허용해 주세요."
            if granted { self.syncTimerNotification() } else { self.timerNotificationService?.coordinator.replace(remaining: nil) }
        }
    }
    func startTimer(_ seconds: UInt32) { stopTimerAlarm(); timerPomodoro = false; timerPhase = .focus; timerSessions = 0; timerDuration = seconds > 0 ? UInt64(seconds) : nil; timerStart(seconds); updateTimer(); if timerState == 1 { showLight(.timerActivation(timerPhase)) }; saveTimer(); syncTimerNotification() }
    func startPomodoro() { stopTimerAlarm(); timerPomodoro = true; timerPhase = .focus; timerSessions = 0; timerDuration = UInt64(pomodoroFocus * 60); timerStart(UInt32(pomodoroFocus * 60)); updateTimer(); if timerState == 1 { showLight(.timerActivation(timerPhase)) }; saveTimer(); syncTimerNotification() }
    func pauseTimer() { updateTimer(); timerPause(); updateTimer(); saveTimer(); syncTimerNotification() }
    func resumeTimer() { timerResume(); updateTimer(); saveTimer(); syncTimerNotification() }
    func resetTimer() { stopTimerAlarm(); timerReset(); timerPomodoro = false; timerPhase = .focus; timerSessions = 0; timerDuration = nil; updateTimer(); saveTimer(); syncTimerNotification() }

    func customTimer() {
        let alert = NSAlert(); alert.messageText = "타이머 시간"
        alert.informativeText = "1분부터 1,440분까지 입력할 수 있습니다."
        let field = NSTextField(frame: NSRect(x: 0, y: 0, width: 120, height: 24)); field.stringValue = "25"; alert.accessoryView = field
        alert.addButton(withTitle: "시작"); alert.addButton(withTitle: "취소"); NSApp.activate(ignoringOtherApps: true)
        guard alert.runModal() == .alertFirstButtonReturn, let minutes = UInt32(field.stringValue), (1...1440).contains(minutes) else { return }
        startTimer(minutes * 60)
    }

    private static func shelfSnapshot() -> (items: [String]?, error: String?) {
        guard let raw = shelfJSON() else { return (nil, "보관함을 읽을 수 없습니다") }
        defer { shelfFree(raw) }
        let data = Data(bytes: raw, count: strlen(raw))
        if let result = (try? JSONSerialization.jsonObject(with: data)) as? [String: Any] {
            if let items = result["items"] as? [String] { return (items, nil) }
            return (nil, result["error"] as? String ?? "보관함을 읽을 수 없습니다")
        }
        return (nil, "보관함을 읽을 수 없습니다")
    }
    private func applyShelfSnapshot(_ snapshot: (items: [String]?, error: String?)) {
        if let items = snapshot.items {
            shelfItems = items; shelfStatus = items.isEmpty ? "파일을 끌어 놓거나 추가하세요" : "파일 \(items.count)개"
        } else { shelfStatus = snapshot.error ?? "보관함을 읽을 수 없습니다" }
    }
    func reloadShelf() {
        shelfQueue.async { [weak self] in
            let snapshot = Self.shelfSnapshot()
            DispatchQueue.main.async { self?.applyShelfSnapshot(snapshot) }
        }
    }
    func flushShelf() { shelfQueue.sync {} }
    func addShelf(_ url: URL, completion: ((Bool) -> Void)? = nil) {
        guard url.isFileURL else { completion?(false); return }
        let path = url.standardizedFileURL.path
        shelfQueue.async { [weak self] in
            let result = path.withCString { shelfAdd($0) }
            let snapshot = result >= 0 ? Self.shelfSnapshot() : nil
            DispatchQueue.main.async {
                guard let self = self else { return }
                if let snapshot = snapshot { self.applyShelfSnapshot(snapshot) }
                else { self.shelfStatus = "보관함에 추가할 수 없습니다" }
                completion?(result >= 0)
            }
        }
    }

    func setCordEnabled(_ enabled: Bool) {
        cordEnabled = enabled
        UserDefaults.standard.set(enabled, forKey: "rium.cord.enabled")
        if !enabled { cordItems.removeAll(); cordExpanded = false }
        onCordChange?()
    }

    func addCordFile(_ url: URL) {
        guard cordEnabled, url.isFileURL else { return }
        cordItems.removeAll { $0 == url }
        cordItems.insert(url, at: 0)
        cordItems = Array(cordItems.prefix(cordCapacity))
        onCordChange?()
    }

    func removeCordFile(_ url: URL) {
        cordItems.removeAll { $0 == url }
        onCordChange?()
    }

    func receiveFileDrop(_ providers: [NSItemProvider]) -> Bool {
        let identifier = UTType.fileURL.identifier
        let files = providers.filter { $0.hasItemConformingToTypeIdentifier(identifier) }
        reportDropDiagnostic("providers=\(providers.count) files=\(files.count)")
        guard !files.isEmpty, !shelfOutgoingDragActive else { return false }
        let compact = !expanded && floatingIslandPlacement == nil
        shelfDropGeneration += 1
        let generation = shelfDropGeneration
        shelfDropPending = compact
        let count = files.count
        var resolved = [URL?](repeating: nil, count: count)
        var completed = Set<Int>()
        var finished = false
        let finish = DispatchWorkItem { [weak self] in
            guard let self, !finished else { return }
            finished = true
            let paths = resolved.compactMap { $0?.path }
            resolved.removeAll()
            self.commitShelfDrop(paths, partial: paths.count != count, compact: compact, generation: generation)
        }
        for (index, provider) in files.enumerated() {
            provider.loadItem(forTypeIdentifier: identifier, options: nil) { item, _ in
                let url = droppedFileURL(item)
                DispatchQueue.main.async {
                    guard !finished, completed.insert(index).inserted else { return }
                    resolved[index] = url
                    if completed.count == count { finish.perform() }
                }
            }
        }
        // shortcut: give unresponsive providers ten seconds, then commit the files already available.
        DispatchQueue.main.asyncAfter(deadline: .now() + 10, execute: finish)
        return true
    }

    private static func storeShelfDrop(_ paths: [String]) -> (items: [String], accepted: [String])? {
        guard !paths.isEmpty, let data = try? JSONEncoder().encode(paths),
              let raw = String(decoding: data, as: UTF8.self).withCString({ shelfAddOrdered($0) }) else { return nil }
        defer { shelfFree(raw) }
        let dataResult = Data(bytes: raw, count: strlen(raw))
        guard let record = (try? JSONSerialization.jsonObject(with: dataResult)) as? [String: Any],
              let items = record["items"] as? [String], let accepted = record["accepted"] as? [String] else { return nil }
        return (items, accepted)
    }

    private func commitShelfDrop(_ paths: [String], partial: Bool, compact: Bool, generation: Int) {
        shelfQueue.async { [weak self] in
            let result = Self.storeShelfDrop(paths)
            DispatchQueue.main.async {
                guard let self else { return }
                guard generation == self.shelfDropGeneration else {
                    if let result { self.shelfItems = result.items }
                    return
                }
                self.shelfDropPending = false
                guard let result, !result.accepted.isEmpty else {
                    self.showShelfDropFailure(paths.isEmpty ? "끌어온 파일을 읽을 수 없습니다" : "보관함에 추가할 수 없습니다", compact: compact)
                    return
                }
                self.applyShelfSnapshot((result.items, nil))
                let partiallyAdded = partial || result.accepted.count < Set(paths).count
                if partiallyAdded {
                    self.shelfStatus = "\(result.accepted.count)개 추가 · 일부 파일을 추가할 수 없습니다"
                }
                reportDropDiagnostic("added=true")
                if compact {
                    self.shelfConfirmationKind = .shelf
                    self.shelfConfirmedFiles = result.accepted.map { URL(fileURLWithPath: $0) }
                    self.shelfConfirmationMessage = partiallyAdded ? self.shelfStatus : nil
                    self.showShelfCatch(.shelf)
                    self.scheduleShelfConfirmationDismissal()
                } else { self.showLight(.shelf) }
            }
        }
    }

    private func showShelfDropFailure(_ message: String, compact: Bool) {
        shelfStatus = message
        guard compact else { presentDeferredScreenshotIfPossible(); return }
        shelfConfirmedFiles.removeAll()
        shelfConfirmationKind = .shelf
        shelfConfirmationMessage = message
        scheduleShelfConfirmationDismissal()
    }

    func receiveAirDropFiles(_ providers: [NSItemProvider]) -> Bool {
        let identifier = UTType.fileURL.identifier
        let files = providers.filter { $0.hasItemConformingToTypeIdentifier(identifier) }
        guard !files.isEmpty, !shelfOutgoingDragActive else { return false }
        shelfDropGeneration += 1
        let generation = shelfDropGeneration
        let compact = !expanded && floatingIslandPlacement == nil
        shelfDropPending = compact
        var resolved = [URL?](repeating: nil, count: files.count)
        var remaining = files.count
        var finished = false
        for (index, provider) in files.enumerated() {
            provider.loadItem(forTypeIdentifier: identifier, options: nil) { [weak self] item, _ in
                let url = droppedFileURL(item)
                DispatchQueue.main.async {
                    guard let self = self, shelfDropResolutionCurrent(generation: generation, current: self.shelfDropGeneration, finished: finished) else {
                        finished = true; return
                    }
                    resolved[index] = url
                    remaining -= 1
                    guard remaining == 0 else { return }
                    finished = true
                    if compact && self.shelfDropGeneration == generation { self.shelfDropPending = false }
                    let urls = resolved.compactMap { $0 }
                    guard urls.count == files.count else {
                        self.showShelfDropFailure("끌어온 파일을 읽을 수 없습니다", compact: compact); return
                    }
                    guard self.sendAirDrop(urls) else {
                        self.showShelfDropFailure(self.shelfStatus, compact: compact); return
                    }
                    if compact && self.shelfDropGeneration == generation {
                        self.shelfConfirmationKind = .airDrop
                        self.shelfConfirmedFiles = urls
                        self.shelfConfirmationMessage = nil
                        self.showShelfCatch(.airDrop)
                        self.scheduleShelfConfirmationDismissal()
                    }
                }
            }
        }
        // shortcut: a provider that never responds times out; tune after real drag testing.
        DispatchQueue.main.asyncAfter(deadline: .now() + 10) { [weak self] in
            guard let self = self, shelfDropResolutionCurrent(generation: generation, current: self.shelfDropGeneration, finished: finished) else {
                finished = true; return
            }
            finished = true
            if compact { self.shelfDropPending = false }
            self.showShelfDropFailure("끌어온 파일을 읽을 수 없습니다", compact: compact)
        }
        return true
    }

    func showScreenshotConfirmation(_ url: URL) {
        guard url.isFileURL else { return }
        if fileDragActive || shelfDropPending || shelfOutgoingDragActive || shelfConfirmationMessage != nil ||
           (!shelfConfirmedFiles.isEmpty && shelfConfirmationKind != .screenshot) {
            deferredScreenshotPreview = url; return
        }
        deferredScreenshotPreview = nil
        shelfConfirmationKind = .screenshot
        shelfConfirmedFiles = [url]
        showShelfCatch(.shelf)
        scheduleShelfConfirmationDismissal()
    }
    private func presentDeferredScreenshotIfPossible() {
        guard let url = deferredScreenshotPreview, !fileDragActive, !shelfDropPending,
              !shelfOutgoingDragActive, shelfConfirmedFiles.isEmpty, shelfConfirmationMessage == nil else { return }
        showScreenshotConfirmation(url)
    }

    private func showShelfCatch(_ zone: ShelfDropZone) {
        let cue = ShelfCatchCue(zone: zone, started: ProcessInfo.processInfo.systemUptime)
        shelfCatchCue = cue
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.62) { [weak self] in
            if self?.shelfCatchCue?.id == cue.id { self?.shelfCatchCue = nil }
        }
    }

    private func scheduleShelfConfirmationDismissal() {
        shelfConfirmationGeneration += 1
        let confirmation = shelfConfirmationGeneration
        DispatchQueue.main.asyncAfter(deadline: .now() + shelfConfirmationDuration(shelfConfirmationKind)) { [weak self] in
            guard let self = self, self.shelfConfirmationGeneration == confirmation, !self.shelfOutgoingDragActive else { return }
            self.shelfConfirmedFiles.removeAll(); self.shelfConfirmationMessage = nil
            self.presentDeferredScreenshotIfPossible()
        }
    }
    func beginShelfConfirmationDrag() {
        guard !shelfOutgoingDragActive else { return }
        shelfConfirmationGeneration += 1
        let confirmation = shelfConfirmationGeneration
        shelfOutgoingDragActive = true
        guard shelfConfirmationKind == .screenshot else { return }
        DispatchQueue.main.async { [weak self] in
            guard let self = self, self.shelfOutgoingDragActive, self.shelfConfirmationGeneration == confirmation,
                  self.shelfConfirmationKind == .screenshot else { return }
            self.screenshotDragCloseGeneration += 1
            let closing = self.screenshotDragCloseGeneration
            self.screenshotDragClosing = true
            self.shelfConfirmedFiles.removeAll()
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.2) { [weak self] in
                guard let self = self, self.screenshotDragCloseGeneration == closing else { return }
                self.screenshotDragClosing = false
            }
        }
    }
    func endShelfConfirmationDrag() {
        guard shelfOutgoingDragActive else { return }
        shelfOutgoingDragActive = false
        if shelfConfirmedFiles.isEmpty { presentDeferredScreenshotIfPossible() }
        else { scheduleShelfConfirmationDismissal() }
    }

    func removeShelf(_ path: String) {
        shelfQueue.async { [weak self] in
            let result = path.withCString { shelfRemove($0) }
            let snapshot = result >= 0 ? Self.shelfSnapshot() : nil
            DispatchQueue.main.async {
                guard let self = self else { return }
                if let snapshot = snapshot { self.applyShelfSnapshot(snapshot) }
                else { self.shelfStatus = "보관함에서 제거할 수 없습니다" }
            }
        }
    }

    func chooseShelfFiles() {
        let panel = NSOpenPanel(); panel.canChooseFiles = true; panel.canChooseDirectories = true; panel.allowsMultipleSelection = true
        panel.prompt = "보관함에 추가"; NSApp.activate(ignoringOtherApps: true)
        if panel.runModal() == .OK {
            for url in panel.urls {
