    private func showReceivedFilePeek(_ url: URL) {
        guard url.isFileURL else { return }
        let duration = airDropLandedPreviewSeconds(receivedFilePeek == nil ? 0 : 1)
        let id = UUID()
        receivedFilePeek = ReceivedFilePeek(id: id, url: url, thumbnail: nil)
        receivedFileHideWork?.cancel()
        let work = DispatchWorkItem { [weak self] in
            guard let self, self.receivedFilePeek?.id == id else { return }
            self.receivedFilePeek = nil
            self.receivedFileHideWork = nil
        }
        receivedFileHideWork = work
        DispatchQueue.main.asyncAfter(deadline: .now() + duration, execute: work)
        DispatchQueue.global(qos: .utility).async { [weak self] in
            guard let image = fileImageThumbnail(url, maxPixelSize: 160) else { return }
            DispatchQueue.main.async {
                guard let self = self, self.receivedFilePeek?.id == id else { return }
                self.receivedFilePeek?.thumbnail = NSImage(cgImage: image, size: .zero)
            }
        }
    }

