    func sendAirDrop(_ path: String) { _ = sendAirDrop([URL(fileURLWithPath: path)]) }
    @discardableResult func sendAirDrop(_ urls: [URL]) -> Bool {
        shelfStatus = "AirDrop 공유 중"
        guard airDropSender.send(urls) else { shelfStatus = "AirDrop을 사용할 수 없거나 파일이 없습니다"; return false }
        return true
    }

    fileprivate func handleAirDropShareEvent(_ event: AirDropShareEvent) {
        switch event {
        case .prepared(let id, _):
            latestAirDropSendID = id
            airDropSendHideWork?.cancel(); airDropSendHideWork = nil
            airDropSendPeek = nil
        case .started(let id, let url):
            guard latestAirDropSendID == id else { return }
            setAirDropSendPeek(AirDropSendPeek(id: id, url: url, phase: .sending))
            DispatchQueue.global(qos: .utility).async { [weak self] in
                guard let image = fileImageThumbnail(url, maxPixelSize: 160) else { return }
                DispatchQueue.main.async {
                    guard let self = self, self.airDropSendPeek?.id == id else { return }
                    self.airDropSendPeek?.thumbnail = NSImage(cgImage: image, size: .zero)
                }
            }
        case .finished(let id, let url, let success, let cancelled):
            guard latestAirDropSendID == id else { return }
            if success { shelfStatus = "AirDrop 공유 완료"; showLight(.airDropSent) }
            else { shelfStatus = cancelled ? "AirDrop 공유 취소됨" : "AirDrop 공유를 완료할 수 없습니다" }
            guard success || airDropSendPeek?.id == id else { return }
            setAirDropSendPeek(AirDropSendPeek(id: id, url: url, phase: success ? .shared : .interrupted))
        }
    }

    fileprivate func handleObservedAirDropSend(_ result: AirDropObservedSend) {
        if let source = result.bundleID, let own = Bundle.main.bundleIdentifier, source == own { return }
        if result.bundleID == nil, airDropSendPeek?.id == latestAirDropSendID,
           airDropSendPeek?.phase == .sending { return }
        if result.success { showLight(.airDropSent) }
        setAirDropSendPeek(AirDropSendPeek(id: UUID(), url: nil, phase: result.success ? .shared : .interrupted))
    }

    private func setAirDropSendPeek(_ peek: AirDropSendPeek) {
        airDropSendHideWork?.cancel()
        var next = peek
        if airDropSendPeek?.id == peek.id { next.thumbnail = airDropSendPeek?.thumbnail }
        airDropSendPeek = next
        if peek.phase == .sending {
            let work = DispatchWorkItem { [weak self] in
                guard let self = self, self.airDropSendPeek?.id == peek.id, self.airDropSendPeek?.phase == .sending else { return }
                self.shelfStatus = "AirDrop 공유 결과 확인 필요"
                self.setAirDropSendPeek(AirDropSendPeek(id: peek.id, url: peek.url, phase: .unknown))
            }
            airDropSendHideWork = work
            DispatchQueue.main.asyncAfter(deadline: .now() + 120, execute: work)
        } else {
            scheduleAirDropSendHide(peek.id, remaining: peek.phase == .shared ? 2.9 : 2)
        }
    }

    private func scheduleAirDropSendHide(_ id: UUID, remaining: TimeInterval, startedAt: TimeInterval? = nil, lastCheckedAt: TimeInterval? = nil) {
        airDropSendHideWork?.cancel()
        let started = startedAt ?? ProcessInfo.processInfo.systemUptime
        let lastChecked = lastCheckedAt ?? started
        let work = DispatchWorkItem { [weak self] in
            guard let self = self, self.airDropSendPeek?.id == id, self.airDropSendPeek?.phase != .sending else { return }
            let now = ProcessInfo.processInfo.systemUptime
            let visible = self.visibleAirDropPeek && !self.receivingFile && self.receivedFilePeek == nil
            let next = visiblePeekRemaining(remaining, elapsed: now - lastChecked, visible: visible)
            if next <= 0 || now - started >= 30 { self.airDropSendPeek = nil; self.airDropSendHideWork = nil }
            else { self.scheduleAirDropSendHide(id, remaining: next, startedAt: started, lastCheckedAt: now) }
        }
        airDropSendHideWork = work
        // shortcut: the freshness cap and uncertain-result timeout need reference comparison.
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.5, execute: work)
    }

    private func requestMedia(_ action: String, position: String? = nil, player: String? = nil,
                              completion: @escaping ([String: Any]) -> Void) {
        if let requester = mediaRequester { requester(action, position, completion); return }
        var args = ["media", action]
        if let position = position { args.append(position) }
        if let player { args.append("--player=" + player) }
        run(args, timeout: 12, event: completion)
    }
    private func updateMediaSource(_ data: [String: Any]?) {
        let candidates = [data?["parentApplicationBundleIdentifier"] as? String, data?["bundleIdentifier"] as? String].compactMap { $0 }
        let url = candidates.lazy.compactMap { NSWorkspace.shared.urlForApplication(withBundleIdentifier: $0) }.first
        guard url != mediaSourceURL else { return }
        mediaSourceURL = url
        if let url = url {
            mediaSourceName = FileManager.default.displayName(atPath: url.path)
            mediaSourceIcon = NSWorkspace.shared.icon(forFile: url.path)
        } else {
            mediaSourceName = "재생 앱"
            mediaSourceIcon = nil
        }
    }
    func openMediaSource() {
        guard let url = mediaSourceURL else { return }
        NSWorkspace.shared.openApplication(at: url, configuration: NSWorkspace.OpenConfiguration()) { _, _ in }
    }
    func stopMediaWatching() { mediaWatcher?.stop(); mediaWatcher = nil }
    func setMediaArtwork(_ encoded: String?) {
        let encoded = encoded.flatMap { !$0.isEmpty && $0.utf8.count <= mediaArtworkEncodedLimit ? $0 : nil }
        if encoded == requestedMediaArtwork && (encoded != nil || (mediaArtwork == nil && mediaAtmosphere == nil)) { return }
        mediaArtworkGeneration &+= 1
        let generation = mediaArtworkGeneration
        mediaArtworkWork?.cancel()
        mediaArtworkWork = nil
        requestedMediaArtwork = encoded
        let cached = encoded.flatMap { mediaArtworkCache.object(forKey: $0 as NSString) }
        applyMediaArtwork(cached)
        if cached != nil { return }
        guard let encoded = encoded else { return }
        let work = DispatchWorkItem { [weak self] in
            let cover = mediaArtworkThumbnail(encoded)
            let atmosphere = cover.flatMap(blurredArtworkImage)
            let tint = cover.flatMap { artworkLightColor(NSBitmapImageRep(cgImage: $0)) }
            DispatchQueue.main.async { [weak self] in
                guard let self = self, self.mediaArtworkGeneration == generation else { return }
                self.mediaArtworkWork = nil
                guard let cover else { return }
                let presentation = MediaArtworkPresentation(cover: cover, atmosphere: atmosphere,
                                                            tint: tint ?? defaultMusicLightColor)
                let atmosphereCost = atmosphere.map { $0.bytesPerRow * $0.height } ?? 0
                let cost = cover.bytesPerRow * cover.height + atmosphereCost + encoded.utf8.count * 2
                self.mediaArtworkCache.setObject(presentation, forKey: encoded as NSString, cost: cost)
                self.applyMediaArtwork(presentation)
            }
        }
        mediaArtworkWork = work
        mediaArtworkQueue.async(execute: work)
    }
    private func applyMediaArtwork(_ presentation: MediaArtworkPresentation?) {
        mediaArtwork = presentation?.cover
        mediaAtmosphere = presentation?.atmosphere
        mediaLightColor = presentation?.tint ?? defaultMusicLightColor
    }
    private func clearPendingMediaSkip(keepPeek: Bool = false) {
        let previousState = currentNotchShellState
        trackSkipHideGeneration += 1
        pendingMediaSkip = nil
        if !keepPeek { trackSkipPeek = nil }
        activeLightCues.removeAll { if case .musicSkipHunt = $0.kind { return true }; return false }
        if let cue = lightCue, case .musicSkipHunt = cue.kind { lightCue = activeLightCues.last }
        if !keepPeek { recordDetailFold(from: previousState) }
    }
    fileprivate func setMediaOutputSource(_ pid: UInt32?, changedTrack: Bool = false) {
        guard pid != mediaOutputPID || changedTrack else { return }
        mediaOutputPID = pid
        mediaOutputGeneration &+= 1
        mediaLastOutputUptime = nil
        if mediaOutputHidden { mediaOutputHidden = false }
        sampleMediaOutput()
    }

    private func sampleMediaOutput() {
        guard deferredServicesStarted, !mediaSuspended, !mediaOutputChecking, let pid = mediaOutputPID else { return }
        mediaOutputChecking = true
        let generation = mediaOutputGeneration
        DispatchQueue.global(qos: .utility).async { [weak self] in
            let activity = rustMediaOutputActivity(pid)
            DispatchQueue.main.async { [weak self] in
                self?.completeMediaOutputSample(activity, generation: generation, at: ProcessInfo.processInfo.systemUptime)
            }
        }
    }

    fileprivate func refreshMediaOutputActivity() {
        guard !mediaSuspended, mediaOutputPID != nil else { return }
        mediaOutputGeneration &+= 1
        sampleMediaOutput()
    }

    fileprivate func completeMediaOutputSample(_ activity: Int32, generation: UInt64, at uptime: TimeInterval) {
        mediaOutputChecking = false
        guard mediaOutputGeneration == generation else {
            sampleMediaOutput()
            return
        }
        applyMediaOutputActivity(activity, at: uptime)
    }

    fileprivate func applyMediaOutputActivity(_ activity: Int32, at uptime: TimeInterval) {
        if activity == 1 { mediaLastOutputUptime = uptime }
        let age = mediaLastOutputUptime.map { uptime - $0 } ?? -1
        // shortcut: silent videos with no previous output rely on the player until source-level mute metadata is available.
        let hidden = rustMediaOutputHidesLight(activity, age, mediaOutputHidden ? 1 : 0) == 1
        if hidden != mediaOutputHidden { mediaOutputHidden = hidden }
    }

    func suspendMediaObservation() {
        mediaSuspended = true; mediaRevision += 1
        mediaSuspensionGeneration += 1
        mediaCommands.removeAll()
        mediaControlPending = mediaCommandBusy
        mediaEditingPosition = false
        mediaError = ""
        systemMediaInteractionGeneration += 1; systemMediaSeekKey = nil
        clearPendingMediaSkip()
        pendingMediaSeek = nil
        mediaPositionKnown = false; mediaPlaying = false
        setMediaOutputSource(nil)
    }
    func resumeMediaObservation() {
        mediaSuspended = false
        if deferredServicesStarted { refreshMedia() }
    }
    func refreshMedia() {
        guard !mediaSuspended else { mediaRefreshPending = true; return }
        guard !mediaBusy, !mediaSeekPending, !mediaControlPending, systemMediaSeekKey == nil else { mediaRefreshPending = true; return }
        mediaRefreshPending = false; mediaBusy = true
        let revision = mediaRevision
        requestMedia("get") { [weak self] event in
            guard let self = self else { return }
            guard let kind = event["event"] as? String, kind == "result" || kind == "error" else { return }
            self.mediaBusy = false
            guard revision == self.mediaRevision, !self.mediaSeekPending, !self.mediaControlPending else {
                self.mediaRefreshPending = true
                if !self.mediaSeekPending && !self.mediaControlPending { self.refreshMedia() }
                return
            }
            let data = event["data"] as? [String: Any]
            let emptySnapshot = kind == "result" && data?["snapshotEmpty"] as? Bool == true
            if kind == "result", let data, !emptySnapshot {
                let title = (data["title"] as? String).flatMap { $0.isEmpty ? nil : $0 }
                let artist = data["artist"] as? String ?? ""
                let playing = data["playing"] as? Bool
                let previous = self.mediaObservation
                let identity = MediaTrackIdentity(identifier: (data["trackIdentifier"] as? String).flatMap { $0.isEmpty ? nil : $0 },
                                                  source: data["bundleIdentifier"] as? String, title: title, artist: artist,
                                                  identifierKind: data["trackIdentifierKind"] as? String,
                                                  parentSource: data["parentApplicationBundleIdentifier"] as? String)
                let receivedUptime = ProcessInfo.processInfo.systemUptime
                let skip = self.pendingMediaSkip
                let changedTrack = (skip?.identity ?? previous?.identity).map { mediaTrackChanged($0, identity) } ?? false
                let elapsed = (data["elapsedTime"] as? Double).flatMap { $0.isFinite && $0 >= 0 ? $0 : nil }
                let expired = skip.map { receivedUptime - $0.started >= trackSkipWaitDuration } ?? false
                let restarted = skip.map {
                    !expired && !changedTrack && sameMediaApplication($0.identity, identity) == true &&
                    ($0.identity.hasComparableIdentifier(to: identity) || ($0.identity.title != nil && $0.identity.title == title)) &&
                    rustMediaPlayheadRestarted($0.position ?? -1, elapsed ?? -1) == 1
                } ?? false
                let waitingForSkip = skip != nil && !changedTrack && !restarted && !expired
                self.mediaPlaying = playing ?? (waitingForSkip && self.mediaPlaying)
                if !waitingForSkip {
                    self.updateMediaSource(data)
                    self.mediaTitle = title ?? (self.mediaPlaying ? self.mediaSourceName : "재생 중인 미디어 없음")
                    self.mediaArtist = artist
                    self.mediaAlbum = data["album"] as? String ?? ""
                    let duration = data["duration"] as? Double ?? 0
                    self.mediaDuration = duration.isFinite ? max(0, duration) : 0
                    self.mediaAvailable = title != nil || !artist.isEmpty || self.mediaPlaying || self.mediaDuration > 0 || ((data["artworkData"] as? String).map { !$0.isEmpty } ?? false)
                    self.setMediaArtwork(data["artworkData"] as? String)
                }
                let outputPID = (data["processIdentifier"] as? Int).flatMap(UInt32.init(exactly:))
                if !waitingForSkip || outputPID != nil || !self.mediaPlaying {
                    self.setMediaOutputSource(self.mediaPlaying ? outputPID : nil, changedTrack: changedTrack)
                }
                self.mediaPlaybackRate = normalizedMediaRate(data["playbackRate"] as? Double)
                let observedUptime = mediaPositionObservedUptime(data["positionObservedUptime"] as? Double, received: receivedUptime)
                if let seek = self.pendingMediaSeek {
                    let trackReplaced = seek.identity.map { mediaTrackChanged($0, identity) } ?? changedTrack
                    let rate = self.mediaPlaying ? self.mediaPlaybackRate : 0
                    let matches = elapsed.map {
                        rustMediaSeekPositionMatches(seek.position, $0, observedUptime - seek.requestedAt, rate, self.mediaDuration) == 1
                    } ?? false
                    if trackReplaced || matches || receivedUptime >= seek.deadline { self.pendingMediaSeek = nil }
                }
                self.mediaPositionKnown = !waitingForSkip && self.pendingMediaSeek == nil && elapsed != nil
                let normalizedElapsed = self.mediaPositionKnown ? (elapsed ?? 0) : 0
                self.mediaElapsed = self.mediaDuration > 0 ? min(self.mediaDuration, normalizedElapsed) : normalizedElapsed
                if self.mediaEditingPosition {
                    if changedTrack || (!waitingForSkip && (previous.map({ !$0.identity.hasComparableIdentifier(to: identity) && $0.identity.title != title }) ?? false)) || self.mediaDuration == 0 {
                        self.mediaEditingPosition = false
                    } else {
                        self.mediaEditedPosition = self.mediaEditedPosition.isFinite ? min(max(self.mediaEditedPosition, 0), self.mediaDuration) : 0
                    }
                }
                self.mediaBaseElapsed = self.mediaElapsed
                self.mediaObservedUptime = observedUptime
                if self.mediaPlaying && self.mediaPositionKnown {
                    self.mediaElapsed = self.currentMediaElapsed(at: receivedUptime)
                }
                if let previous = previous {
                    if changedTrack || restarted {
                        let landed = restarted || (skip.map { mediaSkipLanded(from: $0.identity, to: identity, age: receivedUptime - $0.started) } ?? false)
                        let skipPeek = self.trackSkipPeek
                        self.clearPendingMediaSkip(keepPeek: landed && skipPeek != nil)
                        if landed, let old = skipPeek {
                            let now = ProcessInfo.processInfo.systemUptime
                            let generation = self.trackSkipHideGeneration
                            self.trackSkipPeek = TrackSkipPeek(id: old.id, forward: old.forward, started: old.started, title: title ?? self.mediaSourceName,
                                                              artist: artist.isEmpty ? nil : artist, systemKey: nil)
                            DispatchQueue.main.asyncAfter(deadline: .now() + trackSkipLandingDuration(shownFor: now - old.started)) { [weak self] in
                                guard let self = self, self.trackSkipHideGeneration == generation, self.trackSkipPeek?.id == old.id else { return }
                                self.clearPendingMediaSkip()
                            }
                        }
                        self.showLight(landed ? .musicSkipArrival : .musicTrack)
                    } else if expired {
                        self.clearPendingMediaSkip()
                    }
                    if previous.playing != self.mediaPlaying { self.showLight(.musicPlayback(self.mediaPlaying)) }
                }
                if waitingForSkip {
                    self.mediaObservation?.playing = self.mediaPlaying
                } else {
                    self.mediaObservation = (identity, self.mediaPlaying, self.mediaPositionKnown ? self.mediaElapsed : nil)
                    self.refreshLyrics()
                }
            } else {
                let message = emptySnapshot ? "재생 중인 미디어 없음" : event["message"] as? String ?? "재생 정보를 읽을 수 없습니다"
                self.updateMediaSource(nil)
                self.mediaObservation = nil
                self.clearPendingMediaSkip()
                self.pendingMediaSeek = nil
                self.mediaTitle = message; self.mediaArtist = ""; self.mediaAlbum = ""; self.mediaAvailable = false; self.mediaPlaying = false
                self.setMediaOutputSource(nil)
                self.mediaDuration = 0; self.mediaElapsed = 0; self.mediaPositionKnown = false
                self.mediaPlaybackRate = 1
                self.setMediaArtwork(nil)
                self.mediaEditingPosition = false
                self.refreshLyrics()
            }
            if self.mediaRefreshPending { self.refreshMedia() }
        }
    }

    func refreshAgents() {
        guard !agentWatchingStopped else { return }
        guard !agentBusy else { agentRefreshPending = true; return }
        agentBusy = true
        let observedPaths = agentWatcher?.observedSessionPaths() ?? []
        let input = try? JSONSerialization.data(withJSONObject: ["paths": observedPaths, "anchors": recentAgentTools.anchors(),
                                                                 "watchSessionFiles": true])
        run(input == nil ? ["agents"] : ["agents-observed"], input: input, timeout: 8) { [weak self] event in
            guard let self = self else { return }
            guard let kind = event["event"] as? String, kind == "result" || kind == "error" else { return }
            defer {
                self.agentBusy = false
                if self.agentRefreshPending && !self.agentWatchingStopped {
                    self.agentRefreshPending = false
                    DispatchQueue.main.async { [weak self] in self?.refreshAgents() }
                }
            }
            guard !self.agentWatchingStopped else { return }
            if let rows = agentSnapshotRows(event) {
                self.agentLastSuccess = ProcessInfo.processInfo.systemUptime
                self.agentWatcher?.watchSessionFiles(rows.compactMap { row in
                    guard let provider = row["source"] as? String, let relativePath = row["watchFile"] as? String else { return nil }
                    return (provider: provider, relativePath: relativePath)
                })
                var updated: [AgentActivity] = rows.compactMap { row in
                    guard let id = row["id"] as? String, let project = row["project"] as? String, let state = row["state"] as? String else { return nil }
                    let knownActions: Set<String> = ["작업 실행", "웹 확인", "웹 검색", "검색", "파일 수정", "파일 확인", "도구 사용"]
                    let actions = (row["activities"] as? [String] ?? []).filter { knownActions.contains($0) }
                    let toolEvents = (row["toolEvents"] as? [[String: Any]] ?? []).suffix(16).compactMap { event -> AgentToolEvent? in
                        guard let marker = event["marker"] as? UInt64, let action = event["activity"] as? String,
                              knownActions.contains(action) else { return nil }
                        let kind = (event["kind"] as? Int).flatMap { Int32(exactly: $0) }.flatMap { (0...4).contains($0) ? $0 : nil }
                        let offset = event["offset"] as? UInt64
                        let identity = (row["transcriptIdentity"] as? String).flatMap { $0.isEmpty || $0.utf8.count > 128 ? nil : $0 }
                        return AgentToolEvent(marker: marker, activity: action, kind: kind, offset: offset,
                                              transcriptIdentity: identity, transcriptLength: row["transcriptLength"] as? UInt64,
                                              verifiedAnchorMarker: row["toolAnchorMarker"] as? UInt64,
                                              verifiedAnchorOffset: row["toolAnchorOffset"] as? UInt64)
                    }
                    let questions = (row["pendingQuestions"] as? [[String: Any]] ?? []).prefix(6).compactMap { question -> PendingAgentQuestion? in
                        guard let questionID = question["id"] as? String, !questionID.isEmpty,
                              let title = question["title"] as? String, !title.isEmpty else { return nil }
                        let options = (question["options"] as? [String] ?? []).prefix(20).map { String($0.prefix(200)) }
                        return PendingAgentQuestion(id: String(questionID.prefix(240)), title: String(title.prefix(1000)), options: Array(options))
                    }
                    return AgentActivity(id: id, project: project, state: state, activity: row["activity"] as? String ?? "", source: row["source"] as? String == "claude" ? "claude" : "codex", recentActivities: Array(actions.suffix(3)), ageSeconds: row["ageSeconds"] as? UInt64, messageMarker: row["messageMarker"] as? UInt64, messageAliases: Array((row["messageAliases"] as? [UInt64] ?? []).prefix(1)), pendingQuestions: questions, toolEvents: toolEvents, toolRunning: row["toolRunning"] as? Bool ?? false)
                }
                let observationTime = ProcessInfo.processInfo.systemUptime
                for index in updated.indices {
                    let item = updated[index]
                    updated[index].toolObservedAt = self.recentAgentTools.observe(item, now: observationTime)
                }
                let recovering = self.agentSnapshotBeforeExpiry != nil
                let rawPrevious = self.agentSnapshotBeforeExpiry ?? self.agentItems
                self.agentSnapshotBeforeExpiry = nil
                let previous = self.recentAgentSnapshots.previous(rawPrevious, current: updated, at: observationTime)
                let newQuestions = self.recentAgentQuestions.observe(updated, at: observationTime)
                let initialized = self.agentObservationReady || recovering
                let transitions = agentLightTransitions(previous: previous, current: updated, initialized: initialized, newQuestionSessions: newQuestions)
                    .filter { !self.isPersonalAssistantSession($0.session) && (!recovering || agentRecoveryAllows($0, previous: previous)) }
                let arrivals = agentArrivalKinds(transitions)
                let previousSessions = Set(previous.map(\.sessionKey))
                let notifications = agentNotificationTransitions(previous: previous, current: updated, initialized: initialized, newQuestionSessions: newQuestions)
                    .filter { !self.isPersonalAssistantSession($0.0.sessionKey) && (!recovering || $0.1 == .attention || previousSessions.contains($0.0.sessionKey)) }
                let stalled = updated.first { item in
                    !self.isPersonalAssistantSession(item.sessionKey) && agentEnteredStall(item, previous: previous, initialized: initialized)
                }
                let moodNow = ProcessInfo.processInfo.systemUptime
                for item in updated {
                    _ = lumiMoodMemory.observe(item.sessionKey, mood: lumiMood(waiting: agentNeedsAttention(item.state), state: item.state), now: moodNow)
                }
                self.agentItems = updated; self.agentObservationReady = true
                if let peek = self.permissionPeek, livePermissionAgent(peek, in: updated) == nil {
                    self.clearPermissionPeek(discardPending: false)
                }
                if let peek = self.agentTransientPeek,
                   !updated.contains(where: { transientPeekMatches(peek, activity: $0) }) {
                    self.clearAgentTransientPeek()
                }
                let approvals = transitions.filter { $0.kind == .agentApproval }
                if !approvals.isEmpty {
                    for transition in approvals {
                        if let item = updated.first(where: { AgentSessionKey($0) == transition.session }) { self.showPermissionPeek(item) }
                    }
                } else if (!initialized || recovering), updated.contains(where: { $0.state.hasPrefix("승인 대기") && !self.isPersonalAssistantSession($0.sessionKey) }) {
                    for item in updated where item.state.hasPrefix("승인 대기") && !self.isPersonalAssistantSession(item.sessionKey) { self.showPermissionPeek(item) }
                } else if transitions.contains(where: { $0.kind == .agentQuestion }) {
                    self.clearAgentTransientPeek()
                } else if let transition = transitions.first(where: { $0.kind == .agentFailed })
                            ?? transitions.first(where: { $0.kind == .agentInterrupted }),
                          let item = updated.first(where: { AgentSessionKey($0) == transition.session }) {
                    self.showAgentTransientPeek(item, kind: transition.kind == .agentFailed ? .failed : .interrupted)
                } else if let item = stalled {
                    self.showAgentTransientPeek(item, kind: .stalled)
                } else if let transition = transitions.first(where: { $0.kind == .agentDone })
                            ?? transitions.first(where: { $0.kind == .agentRunning }),
                          let item = updated.first(where: { AgentSessionKey($0) == transition.session }) {
                    self.showAgentTransientPeek(item, kind: transition.kind == .agentDone ? .completed : .running)
                }
                if self.agentNotificationsEnabled && self.agentNotificationsAuthorized {
                    let preferences = UserDefaults.standard
                    for (item, kind) in notifications {
                        let key = kind == .attention ? "rium.agent.notifyAttention" : "rium.agent.notifyFailure"
                        guard preferences.object(forKey: key) as? Bool ?? true else { continue }
                        let showProject = preferences.bool(forKey: "rium.agent.notificationDetails") && !FeedbackSound.quietForPrivacy
                        self.notificationService().notifyAgent(item, kind: kind, showProject: showProject) { [weak self] error in
                            guard error != nil else { return }
                            DispatchQueue.main.async {
                                guard let self = self, self.agentNotificationsEnabled else { return }
                                self.agentNotificationStatus = "에이전트 알림을 전달하지 못했습니다."
                            }
                        }
                    }
                }
                // Draw the most urgent cue last and keep it if the queue fills.
                for cue in arrivals.reversed() {
                    self.showLight(cue)
                    self.playAgentFeedback(cue)
                }
                self.showAgentScreenWaves(prioritizedAgentWaveTransitions(transitions).map(\.kind))
                self.agentStatus = self.agentItems.isEmpty ? "최근 에이전트 활동 없음" : "최근 에이전트 활동"
            } else {
                self.agentStatus = kind == "result" ? "에이전트 상태 응답 형식이 올바르지 않습니다" : (event["message"] as? String ?? "에이전트 상태를 읽을 수 없습니다")
            }
        }
    }

    private func expireAgentSnapshotIfNeeded() {
        guard !agentWatchingStopped, let last = agentLastSuccess,
              rustAgentSnapshotExpired(last, ProcessInfo.processInfo.systemUptime) == 1 else { return }
        agentLastSuccess = nil
        agentObservationReady = false
        recentAgentSnapshots.clear()
        recentAgentTools.clear()
        // Preserve only identity, state, and message markers while waiting for recovery.
        agentSnapshotBeforeExpiry = agentItems.map { AgentActivity(id: $0.id, project: "", state: $0.state, activity: "", source: $0.source,
                                                                  messageMarker: $0.messageMarker, messageAliases: $0.messageAliases) }
        clearPermissionPeek(); clearAgentTransientPeek()
        agentItems.removeAll()
        agentStatus = "에이전트 상태 확인 지연"
    }

    func stopAgentWatching() {
        agentWatchingStopped = true
        deferredRunningPeek = nil
        agentLastSuccess = nil
        agentSnapshotBeforeExpiry = nil
        recentAgentSnapshots.clear()
        recentAgentTools.clear()
        agentRefreshPending = false
        agentWatcher?.stop(); agentWatcher = nil
    }

