        guard !agentIntegrationBusy else { return }
        agentIntegrationBusy = true; agentIntegrationStatus = "Codex 연동 설정 중…"
        run([activePermission ? "codex-permission-install" : "agent-hook-install"]) { [weak self] event in
            guard let self = self, let kind = event["event"] as? String, kind == "result" || kind == "error" else { return }
            self.agentIntegrationBusy = false
            if kind == "result" {
                self.agentIntegrationStatus = activePermission ? "노치 승인 훅을 등록했습니다. Codex에서 훅 기능을 켠 뒤 새 세션에 적용됩니다." : "상태 감지 훅을 등록했습니다. Codex에서 훅 기능을 켠 뒤 새 세션에 적용됩니다."
            } else {
                self.agentIntegrationStatus = event["message"] as? String ?? "Codex 연동을 설정하지 못했습니다."
            }
        }
    }

    func removeAgentIntegration() {
        guard !agentIntegrationBusy else { return }
        agentIntegrationBusy = true; agentIntegrationStatus = "Codex 연동 해제 중…"
        run(["agent-hook-uninstall"]) { [weak self] event in
            guard let self = self, let kind = event["event"] as? String, kind == "result" || kind == "error" else { return }
            self.agentIntegrationBusy = false
            self.agentIntegrationStatus = kind == "result" ? "Rium 훅을 해제했습니다. 새 Codex 세션부터 적용됩니다." : (event["message"] as? String ?? "Codex 연동을 해제하지 못했습니다.")
        }
    }

    private func desktopIntegrationMessage(_ code: String) -> String {
        switch code {
        case "disabled": return "Codex Desktop 연동이 꺼져 있습니다."
        case "configured": return "Codex Desktop 연동이 설정되어 있습니다. 새로 실행한 Codex부터 적용됩니다."
        case "restart_required": return "연동을 설정했습니다. 현재 작업을 마친 뒤 Codex를 다시 실행하면 적용됩니다."
        case "restore_required": return "연동을 다시 설정해야 합니다."
        case "update_required", "update_in_progress": return "Codex가 변경되어 연동을 다시 설정해야 합니다."
        case "conflict", "file_conflict", "override_conflict", "directory_conflict": return "다른 설정과 충돌했습니다. 연동 상태와 설정 파일을 확인해 주세요."
        case "unknown", "launchctl_unknown": return "설정 결과를 확인할 수 없습니다. 연동 상태를 다시 확인해 주세요."
        case "override_unsupported", "protocol_unverified": return "이 Codex 버전의 연동 호환성을 확인하지 못했습니다."
        case "signature_invalid", "app_invalid", "binary_mismatch", "binary_invalid": return "Codex 앱의 무결성을 확인하지 못했습니다."
        case "app_missing", "binary_missing": return "Codex 앱 또는 실행 파일을 찾을 수 없습니다."
        case "setup_busy": return "다른 연동 설정이 진행 중입니다. 잠시 후 다시 시도해 주세요."
        case "file_changed", "recovery_required", "rollback_incomplete": return "설정 파일이 변경되어 연동 상태를 확인해야 합니다."
        default: return "Codex Desktop 연동을 확인하지 못했습니다."
        }
    }

    private func desktopIntegrationCommand(_ args: [String], progress: String) {
        guard !desktopIntegrationBusy else { return }
        desktopIntegrationBusy = true
        desktopIntegrationStatus = progress
        run(args) { [weak self] event in
            guard let self = self, let kind = event["event"] as? String, kind == "result" || kind == "error" else { return }
            self.desktopIntegrationBusy = false
            let data = event["data"] as? [String: Any]
            let code = kind == "result" ? (data?["status"] as? String ?? "unknown") : (event["message"] as? String ?? "unknown")
            self.desktopIntegrationStatus = self.desktopIntegrationMessage(code)
        }
    }

