    func controlMedia(_ action: String) {
        guard !mediaSuspended, ["previous", "toggle", "next"].contains(action) else { return }
        if action != "toggle" { pendingMediaSeek = nil }
        mediaRevision += 1; mediaPositionKnown = false
        mediaError = ""
        mediaCommands.append((action, mediaObservation?.identity.applicationIdentifier, systemMediaInteractionGeneration))
        mediaControlPending = true
        sendNextMediaCommand()
    }
    private func beginMediaSkip(forward: Bool, systemKey: UInt32? = nil) {
        guard !mediaSuspended else { return }
        pendingMediaSeek = nil
        clearPendingMediaSkip()
        let id = UUID()
        let generation = trackSkipHideGeneration
        let now = ProcessInfo.processInfo.systemUptime
        pendingMediaSkip = mediaObservation.flatMap {
            guard $0.identity.identifier != nil || $0.identity.title != nil else { return nil }
            return (id, $0.identity, now, $0.position)
        }
        trackSkipPeek = TrackSkipPeek(id: id, forward: forward, started: now, title: nil, artist: nil, systemKey: systemKey)
        showLight(.musicSkip(forward))
        if pendingMediaSkip != nil {
            DispatchQueue.main.asyncAfter(deadline: .now() + trackSkipPassDuration) { [weak self] in
                guard let self = self, !self.mediaSuspended, self.pendingMediaSkip?.id == id else { return }
                self.showLight(.musicSkipHunt(forward))
            }
        }
        DispatchQueue.main.asyncAfter(deadline: .now() + trackSkipWaitDuration) { [weak self] in
            guard let self = self, self.trackSkipHideGeneration == generation, self.trackSkipPeek?.id == id else { return }
            let refreshPosition = self.pendingMediaSkip != nil && !self.mediaPositionKnown
            self.clearPendingMediaSkip()
            if refreshPosition { self.refreshMedia() }
        }
    }
    func observeSystemMediaKey(_ event: SystemMediaKeyEvent) {
        guard !mediaSuspended else { return }
        switch event {
        case let .volumeNudge(direction):
            if servicesEnabled { sampleVolume(limitDirection: direction) }
        case let .brightnessNudge(direction):
            if servicesEnabled && selectedDisplayID == CGMainDisplayID() { sampleBrightness(limitDirection: direction) }
        case let .skip(forward, key):
            systemMediaInteractionGeneration += 1; systemMediaSeekKey = nil
            mediaRevision += 1; mediaPositionKnown = false
            beginMediaSkip(forward: forward, systemKey: key)
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.4) { [weak self] in self?.refreshMedia() }
        case let .seekHeld(key):
            guard systemMediaSeekKey == key || (trackSkipPeek?.systemKey == key && trackSkipPeek?.title == nil) else { return }
            if systemMediaSeekKey == nil { clearPendingMediaSkip() }
            systemMediaSeekKey = key; systemMediaInteractionGeneration += 1
            let generation = systemMediaInteractionGeneration
            mediaRevision += 1; mediaPositionKnown = false
            // shortcut: key-up is not exposed by all media keys; settle after repeat events stop.
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.4) { [weak self] in
                guard let self = self, !self.mediaSuspended, self.systemMediaInteractionGeneration == generation else { return }
                self.systemMediaSeekKey = nil
                self.refreshMedia()
            }
        }
    }
    private func sendNextMediaCommand() {
        guard !mediaSuspended, !mediaCommandBusy, !mediaSeekPending, !mediaCommands.isEmpty else { return }
        mediaCommandBusy = true
        let (action, player, systemInteraction) = mediaCommands.removeFirst()
        let generation = mediaSuspensionGeneration
        requestMedia(action, player: player) { [weak self] event in
            guard let self = self, let kind = event["event"] as? String, kind == "result" || kind == "error" else { return }
            self.mediaCommandBusy = false
            if generation == self.mediaSuspensionGeneration {
                if !mediaCommandWasSent(event) {
                    self.mediaError = kind == "error" ? (event["message"] as? String ?? "재생 명령을 전달하지 못했습니다") : "재생 명령 전달 여부를 확인할 수 없습니다"
                } else if systemInteraction == self.systemMediaInteractionGeneration,
                          action == "next" || action == "previous" {
                    self.beginMediaSkip(forward: action == "next")
                }
            }
            if !self.mediaCommands.isEmpty { self.sendNextMediaCommand(); return }
            self.mediaControlPending = false
            self.refreshMediaAfterCommand(generation)
        }
    }

    private func refreshMediaAfterCommand(_ generation: Int) {
        guard generation == mediaSuspensionGeneration else { refreshMedia(); return }
        // The player can accept a command before updating its metadata.
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.4) { [weak self] in
            guard let self, self.mediaSuspensionGeneration == generation else { return }
            self.refreshMedia()
        }
    }

    func setLyricsEnabled(_ enabled: Bool) {
        lyricsEnabled = enabled; UserDefaults.standard.set(enabled, forKey: "rium.lyrics.enabled")
        lyricsGeneration += 1; lyricsKey = ""; lyricsRetryAfter = nil; lyricLines = []
        lyricsStatus = enabled ? "가사를 확인하는 중…" : "가사를 켜면 현재 곡을 조회합니다."
        if enabled { refreshLyrics() }
    }
    func refreshLyrics() {
        guard lyricsEnabled else { return }
        let title = mediaTitle.trimmingCharacters(in: .whitespacesAndNewlines), artist = mediaArtist.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !artist.isEmpty, !title.isEmpty, title != "재생 중인 미디어 없음" else { lyricsGeneration += 1; lyricsKey = ""; lyricsRetryAfter = nil; lyricLines = []; lyricsStatus = "곡 제목과 아티스트를 기다리는 중"; return }
        let duration = mediaDuration.isFinite ? min(max(mediaDuration, 0), 604_800) : 0
        let key = "\(title)\u{0}\(artist)\u{0}\(Int(duration))"
        if lyricsBusy { if key != lyricsKey { lyricsGeneration += 1; lyricsKey = ""; lyricsRetryAfter = nil; lyricLines = []; lyricsStatus = "새 곡의 가사를 기다리는 중" }; return }
        guard lyricsShouldRefresh(sameTrack: key == lyricsKey, retryAfter: lyricsRetryAfter, now: ProcessInfo.processInfo.systemUptime) else { return }
        lyricsRetryAfter = nil
        lyricsKey = key; lyricsGeneration += 1; let generation = lyricsGeneration
        lyricLines = []; lyricsStatus = "가사를 확인하는 중…"; lyricsBusy = true
        guard let input = try? JSONSerialization.data(withJSONObject: ["title":title, "artist":artist, "duration":duration]) else { lyricsBusy = false; lyricsRetryAfter = ProcessInfo.processInfo.systemUptime + 60; lyricsStatus = "가사 요청을 만들 수 없습니다"; return }
        run(["lyrics"], input: input) { [weak self] event in
            guard let self = self else { return }
            guard let kind = event["event"] as? String, kind == "result" || kind == "error" else { return }
            self.lyricsBusy = false
            guard self.lyricsEnabled, generation == self.lyricsGeneration else { self.refreshLyrics(); return }
            if kind == "result", let data = event["data"] as? [String: Any] {
                self.lyricLines = parseLyrics(synced: data["synced"] as? String, plain: data["plain"] as? String)
                self.lyricsStatus = data["instrumental"] as? Bool == true ? "연주곡" : (self.lyricLines.isEmpty ? "이 곡의 가사를 찾지 못했습니다" : "가사 제공: LRCLIB")
            } else {
                self.lyricsRetryAfter = ProcessInfo.processInfo.systemUptime + 60
                self.lyricsStatus = event["message"] as? String ?? "가사를 불러올 수 없습니다"
            }
            self.refreshLyrics()
        }
    }

    func seekMedia(_ requested: Double) {
        guard !mediaSuspended, requested.isFinite, mediaDuration.isFinite, mediaDuration > 0,
              !mediaSeekPending, !mediaControlPending else { return }
        let position = min(max(0, requested), min(mediaDuration, 604_800))
        if pendingMediaSkip != nil { clearPendingMediaSkip() }
        mediaRevision += 1; mediaSeekPending = true; mediaError = ""
        let generation = mediaSuspensionGeneration
        let id = UUID()
        let identity = mediaObservation?.identity
        pendingMediaSeek = (id, identity, position, ProcessInfo.processInfo.systemUptime, .infinity)
        mediaPositionKnown = false
        requestMedia("seek", position: String(position), player: identity?.applicationIdentifier) { [weak self] event in
            guard let self = self else { return }
            guard let kind = event["event"] as? String, kind == "result" || kind == "error" else { return }
            self.mediaSeekPending = false
            if generation == self.mediaSuspensionGeneration {
                if !mediaCommandWasSent(event) {
                    self.pendingMediaSeek = nil
                    self.mediaError = kind == "error" ? (event["message"] as? String ?? "재생 위치를 변경하지 못했습니다") : "재생 위치 변경 여부를 확인할 수 없습니다"
                } else if self.pendingMediaSeek?.id == id {
                    self.pendingMediaSeek?.deadline = ProcessInfo.processInfo.systemUptime + mediaSeekConfirmationWindow
                    DispatchQueue.main.asyncAfter(deadline: .now() + mediaSeekConfirmationWindow) { [weak self] in
                        guard let self, self.pendingMediaSeek?.id == id else { return }
                        self.refreshMedia()
                    }
                }
            }
            self.sendNextMediaCommand()
            self.refreshMediaAfterCommand(generation)
        }
    }

    private func cancelWeatherGeocode() {
        weatherGeocodeTimeout?.cancel(); weatherGeocodeTimeout = nil
        geocoder.cancelGeocode()
    }

    private func scheduleWeatherGeocodeTimeout(generation: Int, action: @escaping () -> Void) {
        weatherGeocodeTimeout?.cancel()
        let work = DispatchWorkItem { [weak self] in
            guard let self = self, weatherGeocodeTimeoutApplies(expected: generation, current: self.weatherGeneration,
                                                                 inProgress: self.weatherSelectionInProgress) else { return }
            self.weatherGeneration += 1
            self.weatherGeocodeTimeout = nil
            self.geocoder.cancelGeocode()
            action()
        }
        weatherGeocodeTimeout = work
        DispatchQueue.main.asyncAfter(deadline: .now() + 20, execute: work)
    }

    func chooseWeatherCity() {
        let alert = NSAlert(); alert.messageText = "날씨 도시 선택"
        alert.informativeText = "도시 이름으로 날씨를 조회합니다. 선택한 도시의 좌표가 MET Norway에 전송됩니다."
        let field = NSTextField(frame: NSRect(x: 0, y: 0, width: 220, height: 24)); field.placeholderString = "예: 서울"
        alert.accessoryView = field; alert.addButton(withTitle: "조회"); alert.addButton(withTitle: "취소")
        NSApp.activate(ignoringOtherApps: true)
        guard alert.runModal() == .alertFirstButtonReturn else { return }
        let city = field.stringValue.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !city.isEmpty else { return }
        clearWeatherPeek()
        weatherGeneration += 1; let geocodeGeneration = weatherGeneration
        weatherLocator.cancel(); cancelWeatherGeocode()
        weatherSelectionInProgress = true
        weatherShowingStatus = true
        weatherText = "도시 확인 중…"
        scheduleWeatherGeocodeTimeout(generation: geocodeGeneration) { [weak self] in
            self?.weatherSelectionInProgress = false
            self?.weatherText = "도시 검색 시간이 초과됐습니다"
        }
        geocoder.geocodeAddressString(city) { [weak self] places, error in
            guard let self = self, self.weatherGeneration == geocodeGeneration else { return }
            self.weatherGeocodeTimeout?.cancel(); self.weatherGeocodeTimeout = nil
            guard error == nil, let place = places?.first, let coordinate = place.location?.coordinate else {
                self.weatherSelectionInProgress = false; self.weatherText = "도시를 찾을 수 없습니다"; return
            }
            let roundedLat = (coordinate.latitude * 10000).rounded() / 10000
            let roundedLon = (coordinate.longitude * 10000).rounded() / 10000
            self.fetchWeather(city: city, lat: roundedLat, lon: roundedLon, timeZoneID: place.timeZone?.identifier, currentLocation: false)
        }
    }

    func useCurrentWeatherLocation(background: Bool = false) {
        clearWeatherPeek()
        weatherGeneration += 1; let generation = weatherGeneration
        weatherSelectionInProgress = true
        cancelWeatherGeocode(); lastWeatherAttempt = Date()
        if !background {
            weatherShowingStatus = true
            weatherText = "현재 위치 확인 중…"
        }
        weatherLocator.request(allowAuthorizationPrompt: !background) { [weak self] result in
            guard let self = self, self.weatherGeneration == generation else { return }
            switch result {
            case .failure(let error): self.weatherSelectionInProgress = false; self.showWeatherLocationFailure(error.message)
            case .success(let location):
                let coordinate = location.coordinate
                guard CLLocationCoordinate2DIsValid(coordinate) else {
                    self.weatherSelectionInProgress = false; self.showWeatherLocationFailure("현재 위치를 확인하지 못했습니다"); return
                }
                let lat = (coordinate.latitude * 10_000).rounded() / 10_000
                let lon = (coordinate.longitude * 10_000).rounded() / 10_000
                if !background { self.weatherText = "현재 위치의 날씨 확인 중…" }
                self.scheduleWeatherGeocodeTimeout(generation: generation) { [weak self] in
                    self?.fetchWeather(city: "현재 위치", lat: lat, lon: lon, currentLocation: true, background: background)
                }
                self.geocoder.reverseGeocodeLocation(location) { [weak self] places, _ in
                    guard let self = self, self.weatherGeneration == generation else { return }
                    self.weatherGeocodeTimeout?.cancel(); self.weatherGeocodeTimeout = nil
                    let place = places?.first
                    let city = place?.locality ?? place?.administrativeArea ?? "현재 위치"
                    self.fetchWeather(city: city, lat: lat, lon: lon, timeZoneID: place?.timeZone?.identifier, currentLocation: true, background: background)
                }
            }
        }
    }

    private func showWeatherLocationFailure(_ message: String) {
        let defaults = UserDefaults.standard
        guard let previous = previousCurrentLocationWeather(cache: defaults.dictionary(forKey: "rium.weather.cache"),
                                                             wasCurrent: defaults.bool(forKey: "rium.weather.currentLocation")) else {
            weatherText = message
            return
        }
        showWeather(city: "\(previous.city) (마지막 위치)", data: previous.data, updated: previous.updated,
                    timeZoneID: previous.timeZoneID, locationUncertain: true)
        weatherDetail += " · \(message)"
    }

    func refreshStaleWeather() {
        let now = Date()
        // A failed manual selection must not be replaced by the previous city.
        guard !weatherShowingStatus, let cache = UserDefaults.standard.dictionary(forKey: "rium.weather.cache"),
              let updated = cache["updated"] as? Double,
              weatherMayAutoRefresh(inProgress: weatherSelectionInProgress, sinceAttempt: now.timeIntervalSince(lastWeatherAttempt), cacheAge: now.timeIntervalSince1970 - updated),
              let lat = cache["lat"] as? Double, let lon = cache["lon"] as? Double,
              let city = cache["city"] as? String else { return }
        if UserDefaults.standard.bool(forKey: "rium.weather.currentLocation") { useCurrentWeatherLocation(background: true); return }
        fetchWeather(city: city, lat: lat, lon: lon, timeZoneID: cache["timezone"] as? String, background: true)
    }

    func fetchWeather(city: String, lat: Double, lon: Double, timeZoneID: String? = nil, currentLocation: Bool? = nil, background: Bool = false) {
        clearWeatherPeek()
        weatherGeneration += 1; let generation = weatherGeneration
        cancelWeatherGeocode()
        weatherSelectionInProgress = true
        let defaults = UserDefaults.standard
        if let cache = defaults.dictionary(forKey: "rium.weather.cache"), let oldLat = cache["lat"] as? Double,
           let oldLon = cache["lon"] as? Double, oldLat == lat, oldLon == lon,
           let updated = cache["updated"] as? Double, (0..<10_800).contains(Date().timeIntervalSince1970 - updated),
           let data = cache["data"] as? [String: Any] {
            var updatedCache = cache
            updatedCache["city"] = city
            if let id = timeZoneID, TimeZone(identifier: id) != nil { updatedCache["timezone"] = id }
            defaults.set(updatedCache, forKey: "rium.weather.cache")
            if let currentLocation = currentLocation { defaults.set(currentLocation, forKey: "rium.weather.currentLocation") }
            weatherSelectionInProgress = false
            showWeather(city: city, data: data, updated: Date(timeIntervalSince1970: updated), timeZoneID: timeZoneID ?? (cache["timezone"] as? String)); return
        }
        lastWeatherAttempt = Date()
        if !background {
            weatherShowingStatus = true
            weatherText = "날씨 조회 중…"
        }
        run(["weather", String(lat), String(lon)], timeout: 20) { [weak self] event in
            guard let self = self, self.weatherGeneration == generation else { return }
            guard let kind = event["event"] as? String, kind == "result" || kind == "error" else { return }
            defer { self.weatherSelectionInProgress = false }
            if kind == "result", let data = event["data"] as? [String: Any],
               let temperature = data["temperature"] as? Double, temperature.isFinite {
                let hours = weatherHours(data["hourly"] as? [[String: Any]] ?? [])
                let safeHours: [[String: Any]] = hours.map { hour in
                    var row: [String: Any] = ["time": hour.id, "temperature": hour.temperature, "symbol": hour.symbol]
                    if let precipitation = hour.precipitation { row["precipitation"] = precipitation }
                    if let humidity = hour.humidity { row["humidity"] = humidity }
                    if let wind = hour.wind { row["wind"] = wind }
                    return row
                }
                var safeData: [String: Any] = ["temperature": temperature, "symbol": data["symbol"] as? String ?? "", "hourly": safeHours]
                if let humidity = validWeatherHumidity(data["humidity"]) { safeData["humidity"] = humidity }
                if let wind = validWeatherWind(data["wind"]) { safeData["wind"] = wind }
                var entry: [String: Any] = ["lat": lat, "lon": lon, "city": city, "updated": Date().timeIntervalSince1970, "data": safeData]
                if let id = timeZoneID, TimeZone(identifier: id) != nil { entry["timezone"] = id }
                defaults.set(entry, forKey: "rium.weather.cache")
                if let currentLocation = currentLocation { defaults.set(currentLocation, forKey: "rium.weather.currentLocation") }
                self.showWeather(city: city, data: safeData, timeZoneID: timeZoneID)
            } else {
                let error = event["message"] as? String ?? "날씨를 읽을 수 없습니다"
                if let cache = defaults.dictionary(forKey: "rium.weather.cache"), let oldLat = cache["lat"] as? Double,
                   let oldLon = cache["lon"] as? Double, oldLat == lat, oldLon == lon,
                   let updated = cache["updated"] as? Double, let data = cache["data"] as? [String: Any] {
                    self.showWeather(city: city, data: data, updated: Date(timeIntervalSince1970: updated), timeZoneID: cache["timezone"] as? String)
                    self.weatherDetail += " · 연결 실패"
                } else if background && currentLocation == true {
                    self.showWeatherLocationFailure(error)
                } else { self.weatherText = error }
            }
        }
    }

    func showWeather(city: String, data: [String: Any], updated: Date = Date(), timeZoneID: String? = nil, locationUncertain: Bool = false) {
        guard let temp = data["temperature"] as? Double, temp.isFinite else {
            weatherShowingStatus = true; weatherText = "날씨를 읽을 수 없습니다"; return
        }
        weatherShowingStatus = false
        weatherLocationUncertain = locationUncertain
        weatherCity = city
        let humidity = validWeatherHumidity(data["humidity"]), wind = validWeatherWind(data["wind"])
        var hours = weatherHours(data["hourly"] as? [[String: Any]] ?? [])
        // Older caches kept wind and humidity only on the first forecast sample.
        if !hours.isEmpty {
            hours[0].humidity = hours[0].humidity ?? humidity
            hours[0].wind = hours[0].wind ?? wind
        }
        weatherForecast = hours
        weatherDisplayedHour = hours.first?.date
        applyWeatherConditions(temperature: temp, symbol: data["symbol"] as? String ?? "", humidity: humidity, wind: wind)
        refreshWeatherConditions()
        weatherUpdatedAt = updated
        weatherTimeZoneID = timeZoneID.flatMap { TimeZone(identifier: $0) != nil ? $0 : nil }
        let formatter = DateFormatter(); formatter.locale = Locale(identifier: "ko_KR"); formatter.dateFormat = "M/d HH:mm"
        let stale = Date().timeIntervalSince(updated) >= 10_800 ? " · 업데이트 필요" : ""
        weatherDetail = "MET Norway · \(formatter.string(from: updated))\(stale)"
        if let displayed = weatherPeek, displayed != weatherPrecipitationWindow { clearWeatherPeek() }
        refreshWeatherAlert()
    }
    private func applyWeatherConditions(temperature: Double, symbol: String, humidity: Double?, wind: Double?) {
        let condition = weatherDescription(symbol)
        weatherText = String(format: "%@  %.0f°  %@", weatherCity, temperature, condition)
        weatherCondition = condition
        weatherSymbol = symbol
        weatherTemperature = temperature
        weatherHumidity = humidity
        weatherWind = wind
    }
    fileprivate func refreshWeatherConditions() {
        guard !weatherShowingStatus, let hour = currentWeatherHour(weatherForecast, at: now),
              hour.date != weatherDisplayedHour else { return }
        weatherDisplayedHour = hour.date
        applyWeatherConditions(temperature: hour.temperature, symbol: hour.symbol, humidity: hour.humidity, wind: hour.wind)
    }

    var weatherPrecipitationWindow: Date? {
        guard !weatherShowingStatus, !weatherLocationUncertain, let updated = weatherUpdatedAt, !weatherForecast.isEmpty else { return nil }
        let times = weatherForecast.map { $0.date.timeIntervalSince1970 }
        let amounts = weatherForecast.map { $0.precipitation ?? .nan }
        var result = 0.0
        let status = times.withUnsafeBufferPointer { times in
            amounts.withUnsafeBufferPointer { amounts in
                rustWeatherPrecipitationWindow(now.timeIntervalSince1970, updated.timeIntervalSince1970, times.baseAddress, amounts.baseAddress, times.count, &result)
            }
        }
        return status == 1 ? Date(timeIntervalSince1970: result) : nil
    }

    func setWeatherAlertsEnabled(_ enabled: Bool) {
        weatherAlertsEnabled = enabled
        UserDefaults.standard.set(enabled, forKey: "rium.weather.alerts")
        if enabled { refreshWeatherAlert() } else { clearWeatherPeek() }
    }

    private func clearWeatherPeek() {
        weatherPeekGeneration += 1
        weatherPeek = nil
    }

    private func refreshWeatherAlert() {
        guard servicesEnabled, weatherAlertsEnabled, !expanded, weatherPeek == nil, !showsCollapsedAgent,
              !dictationDisplayActive, !receivingFile, receivedFilePeek == nil, shortcutPeek == nil,
              caseKeyPeek == nil, batteryPeek == nil, volumeOverlay.isEmpty,
              let date = weatherPrecipitationWindow else { return }
        let signature = "\(weatherCity):\(date.timeIntervalSince1970)"
        guard signature != lastWeatherAlertSignature else { return }
        lastWeatherAlertSignature = signature
        weatherPeekGeneration += 1
        let generation = weatherPeekGeneration
        weatherPeek = date
        DispatchQueue.main.asyncAfter(deadline: .now() + 5) { [weak self] in
            guard let self = self, self.weatherPeekGeneration == generation else { return }
            self.weatherPeek = nil
        }
    }

    func sample() {
        var value = -1.0, used: UInt64 = 0, total: UInt64 = 0, swapped: UInt64 = 0
        let flags = readMetrics(&value, &used, &total, &swapped)
        let cpuValue: Double? = flags & 1 != 0 && value.isFinite && (0...100).contains(value) ? value : nil
        cpu = flags & 1 == 0 ? "조회 불가" : (value == -1 ? "측정 중" : (cpuValue.map { String(format: "%.0f%%", $0) } ?? "조회 불가"))
        let memoryValue = memoryUsagePercent(used: used, total: total, available: flags & 2 != 0)
        memory = memoryValue == nil ? "조회 불가" : String(format: "%.1f / %.1f GB", Double(used) / 1_000_000_000, Double(total) / 1_000_000_000)
        memoryPercent = memoryValue.map { String(format: "%.0f%%", $0) } ?? "조회 불가"
        swap = flags & 4 == 0 ? "조회 불가" : String(format: "%.1f GB", Double(swapped) / 1_000_000_000)
        pressure = currentMemoryPressure() ?? pressureEvent ?? "조회 불가"
        appendMonitorSample(cpuValue, to: &cpuHistory)
        appendMonitorSample(memoryValue, to: &memoryHistory)
    }

    // Each operation is isolated from the UI thread. The Rust helper keeps the
    // existing Rium Dock account profiles and asks the official Codex CLI.
    func run(_ args: [String], input: Data? = nil, timeout: TimeInterval? = nil, event: @escaping ([String: Any]) -> Void) {
        guard let executable = Bundle.main.url(forAuxiliaryExecutable: "rium-notch-core") else { event(["event":"error", "message":"기능 도구를 찾을 수 없습니다"]); return }
        DispatchQueue.global(qos: .utility).async {
            let process = Process(); process.executableURL = executable; process.arguments = args
            let pipe = Pipe(); process.standardOutput = pipe; process.standardError = FileHandle.nullDevice
            let inputPipe = input.map { _ in Pipe() }
            if let inputPipe = inputPipe {
                guard suppressBrokenPipeSignal(inputPipe.fileHandleForWriting) else {
                    DispatchQueue.main.async { event(["event":"error", "message":"기능 도구의 입력을 준비할 수 없습니다"]) }; return
                }
                process.standardInput = inputPipe
            }
            do { try process.run() } catch { DispatchQueue.main.async { event(["event":"error", "message":"기능 도구를 실행할 수 없습니다"]) }; return }
            let gate = HelperEventGate()
            let timeoutWork: DispatchWorkItem? = timeout.flatMap { seconds in
                guard seconds.isFinite, seconds > 0 else { return nil }
                let work = DispatchWorkItem {
                    if gate.accepts("error") {
                        let failure = helperFailureAfterLaunch(args, message: "기능 도구 응답 시간 초과")
                        DispatchQueue.main.async { event(failure) }
                    }
                    if process.isRunning { process.terminate() }
                }
                DispatchQueue.global(qos: .utility).asyncAfter(deadline: .now() + seconds, execute: work)
                return work
            }
            // The child owns these ends; the parent must not keep its output open.
            try? pipe.fileHandleForWriting.close()
            if let inputPipe = inputPipe { try? inputPipe.fileHandleForReading.close() }
            var inputFailed = false
            if let inputPipe = inputPipe, let input = input {
                do { try inputPipe.fileHandleForWriting.write(contentsOf: input) } catch { inputFailed = true }
                try? inputPipe.fileHandleForWriting.close()
            }
            var buffer = Data()
            while true {
                // availableData returns as soon as a line arrives. A fixed-size
                // read can wait for EOF and deadlock the interactive login flow.
                let data = pipe.fileHandleForReading.availableData
                if data.isEmpty { break }
                buffer.append(data)
                if buffer.count > 2_100_000 {
                    if process.isRunning { process.terminate() }
                    if gate.accepts("error") {
                        let failure = helperFailureAfterLaunch(args, message: "기능 응답이 너무 큽니다")
                        DispatchQueue.main.async { event(failure) }
                    }
                    break
                }
                while let newline = buffer.firstIndex(of: 10) {
                    let line = buffer.prefix(upTo: newline); buffer.removeSubrange(...newline)
                    if let item = try? JSONSerialization.jsonObject(with: line) as? [String: Any] {
                        if gate.accepts(item["event"] as? String) { DispatchQueue.main.async { event(item) } }
                    }
                }
            }
            process.waitUntilExit()
            timeoutWork?.cancel()
            if gate.accepts("error") {
                let message = inputFailed ? "기능 도구에 입력을 전달하지 못했습니다" : "기능 도구가 응답 없이 종료되었습니다"
                let failure = helperFailureAfterLaunch(args, message: message)
                DispatchQueue.main.async { event(failure) }
            }
        }
    }

    func listAccounts() {
        run(["list"]) { [weak self] e in
            guard let self = self else { return }
            if let rows = e["data"] as? [[String: Any]] {
                self.accounts = rows.compactMap { row in
                    guard let id = row["id"] as? String, let name = row["name"] as? String else { return nil }
                    var account = self.accounts.first(where: { $0.id == id }) ?? Account(id: id, name: name)
                    account.name = name
                    return account
                }
                if self.usageTrackingEnabled, let id = self.monitorAccountID,
                   self.accounts.contains(where: { $0.id == id }) { self.refresh(id) }
            } else if let error = e["message"] as? String { self.message = error }
        }
    }

    func refresh(_ id: String) {
        guard !busy.contains(id) else { return }
        busy.insert(id)
        run(["refresh", id]) { [weak self] e in
            guard let self = self else { return }
            if e["event"] as? String == "result" {
                let data = e["data"] as? [String: Any] ?? [:]
                self.applyCodexUsage(data, to: id)
                self.busy.remove(id)
            } else if let error = e["message"] as? String {
                if let i = self.accounts.firstIndex(where: { $0.id == id }) {
                    self.accounts[i].usage = error; self.accounts[i].detail = ""; self.accounts[i].additionalUsage = []; self.accounts[i].remaining = nil
                }
                self.busy.remove(id)
            }
        }
    }

    private func applyCodexUsage(_ data: [String: Any], to id: String) {
        let status = data["status"] as? String ?? "unknown"
        let label: String
        switch status {
        case "connected": label = codexWindow(data["primary"]) ?? "사용량 조회 불가"
        case "disconnected": label = "로그인 필요"
        case "unsupported": label = "지원하지 않는 계정"
        default: label = "계정 상태 확인 불가"
        }
        var details: [String] = []
        if status == "connected", let secondary = codexWindow(data["secondary"]) { details.append(secondary) }
        if status == "connected", data["ordinaryUsageAllowed"] as? Bool == false { details.append("기본 사용 제한 중") }
        if status == "connected", data["spendControlReached"] as? Bool == true { details.append("지출 한도 도달") }
        if status == "connected" { details.append(contentsOf: codexRestrictions(data)) }
        if status == "connected", let available = data["resetCreditsAvailable"] as? Int, available > 0 { details.append("한도 초기화 크레딧 \(available)개") }
        if status == "connected", let credits = data["credits"] as? [String: Any] {
            if credits["unlimited"] as? Bool == true { details.append("크레딧 무제한") }
            else if let balance = credits["balance"] as? String, let number = Double(balance) { details.append(String(format: "크레딧 %.2f", number)) }
            else if let balance = credits["balance"] as? NSNumber { details.append(String(format: "크레딧 %.2f", balance.doubleValue)) }
        }
        if let i = accounts.firstIndex(where: { $0.id == id }) {
            accounts[i].usage = label
            accounts[i].detail = details.joined(separator: " · ")
            accounts[i].additionalUsage = status == "connected" ? codexAdditionalUsage(data) : []
            accounts[i].connected = status == "connected"
            accounts[i].remaining = status == "connected" ? CodexRemainingWindow(data["primary"]) : nil
        }
    }

    func login(_ id: String) {
        guard !busy.contains(id) else { return }; busy.insert(id); message = "로그인 창을 기다리는 중"
        run(["login", id]) { [weak self] e in
            guard let self = self else { return }
            if e["event"] as? String == "login_url", let str = e["url"] as? String, let url = URL(string: str), url.host == "auth.openai.com" { NSWorkspace.shared.open(url) }
            if e["event"] as? String == "result" {
                self.busy.remove(id)
                let data = e["data"] as? [String: Any] ?? [:]
                self.applyCodexUsage(data, to: id)
                self.message = data["status"] as? String == "connected" ? "로그인 완료" : "Codex 사용량을 확인할 수 없습니다"
            }
            if let error = e["message"] as? String { self.busy.remove(id); self.message = error }
        }
    }

    func addAccount() {
        let alert = NSAlert(); alert.messageText = "Codex 계정 추가"; alert.informativeText = "이 Mac에서 구분할 이름을 입력하세요."
        let field = NSTextField(frame: NSRect(x: 0, y: 0, width: 220, height: 24)); alert.accessoryView = field
        alert.addButton(withTitle: "추가"); alert.addButton(withTitle: "취소")
        NSApp.activate(ignoringOtherApps: true)
        guard alert.runModal() == .alertFirstButtonReturn else { return }
        let name = field.stringValue.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !name.isEmpty else { return }
        run(["create", name]) { [weak self] e in
            guard let self = self else { return }
            if let row = e["data"] as? [String: Any], let id = row["id"] as? String {
                if !self.accounts.contains(where: { $0.id == id }) {
                    self.accounts.append(Account(id: id, name: row["name"] as? String ?? name))
                }
                self.login(id)
            } else if let error = e["message"] as? String {
                self.message = error
            }
        }
    }
    func renameAccount(_ account: Account) {
        guard !busy.contains(account.id) else { message = "계정 작업이 진행 중입니다"; return }
        let alert = NSAlert(); alert.messageText = "계정 이름 변경"
        alert.informativeText = "이 이름은 Rium Dock에도 함께 반영됩니다."
        let field = NSTextField(frame: NSRect(x: 0, y: 0, width: 220, height: 24)); field.stringValue = account.name
        alert.accessoryView = field; alert.addButton(withTitle: "변경"); alert.addButton(withTitle: "취소")
        NSApp.activate(ignoringOtherApps: true)
        guard alert.runModal() == .alertFirstButtonReturn else { return }
        let name = field.stringValue.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !name.isEmpty else { message = "계정 이름을 입력해 주세요"; return }
        busy.insert(account.id); message = "계정 이름 변경 중"
        run(["rename", account.id, name]) { [weak self] event in
            guard let self = self else { return }
            if event["event"] as? String == "result" {
                if let i = self.accounts.firstIndex(where: { $0.id == account.id }) { self.accounts[i].name = name }
                self.busy.remove(account.id); self.message = "계정 이름을 변경했습니다"
            } else if let error = event["message"] as? String {
                self.busy.remove(account.id); self.message = error
            }
        }
    }
    func removeAccount(_ account: Account) {
        guard !busy.contains(account.id) else { message = "계정 작업이 진행 중입니다"; return }
        let alert = NSAlert(); alert.alertStyle = .warning; alert.messageText = "계정 연결 해제"
        alert.informativeText = "이 Mac의 공용 계정 정보가 삭제되고 Rium Dock에서도 로그아웃됩니다. OpenAI 계정 자체는 삭제되지 않습니다."
        alert.addButton(withTitle: "연결 해제"); alert.addButton(withTitle: "취소")
        NSApp.activate(ignoringOtherApps: true)
        guard alert.runModal() == .alertFirstButtonReturn else { return }
        busy.insert(account.id); message = "계정 연결 해제 중"
        run(["remove", account.id]) { [weak self] event in
            guard let self = self else { return }
            if event["event"] as? String == "result" {
                self.accounts.removeAll { $0.id == account.id }
                if self.monitorAccountID == account.id { self.setMonitorAccount(nil) }
                self.busy.remove(account.id); self.message = "계정 연결을 해제했습니다"
            } else if let error = event["message"] as? String {
                self.busy.remove(account.id); self.message = error
            }
        }
    }
}

private extension View {
    @ViewBuilder func clipboardDrag(_ record: ClipboardRecord, onClick: (() -> Void)? = nil) -> some View {
        if case .files(let urls) = record.content, urls.count > 1 {
            overlay { ClipboardFileDragSurface(urls: urls, onClick: onClick) }
        } else {
            onDrag { record.dragProvider() }
        }
    }
}

private struct ClipboardFileDragSurface: NSViewRepresentable {
    let urls: [URL]
    let onClick: (() -> Void)?

    func makeNSView(context: Context) -> ClipboardFileDragView { ClipboardFileDragView() }
    func updateNSView(_ view: ClipboardFileDragView, context: Context) {
        view.urls = urls
        view.onClick = onClick
    }
}

private class ClipboardFileDragView: NSView, NSDraggingSource {
    var urls: [URL] = [] {
        didSet { if oldValue != urls { pressedAt = nil } }
    }
    var onClick: (() -> Void)?
    private var pressedAt: NSPoint?

    override func acceptsFirstMouse(for event: NSEvent?) -> Bool { true }

    override func hitTest(_ point: NSPoint) -> NSView? {
        if let event = NSApp?.currentEvent,
           event.type == .rightMouseDown || (event.type == .leftMouseDown && event.modifierFlags.contains(.control)) {
            return nil
        }
        return super.hitTest(point)
    }

    override func mouseDown(with event: NSEvent) {
        pressedAt = event.locationInWindow
    }

    override func mouseUp(with event: NSEvent) {
        guard pressedAt != nil else { return }
        pressedAt = nil
        if bounds.contains(convert(event.locationInWindow, from: nil)) { onClick?() }
    }

    override func mouseDragged(with event: NSEvent) {
        guard let pressedAt, window != nil else { return }
        let point = event.locationInWindow
        guard hypot(point.x - pressedAt.x, point.y - pressedAt.y) >= 4 else { return }
        self.pressedAt = nil
        let local = convert(point, from: nil)
        let frame = NSRect(x: local.x - 16, y: local.y - 16, width: 32, height: 32)
        let icon = NSWorkspace.shared.icon(for: .item)
        let items = urls.map { url in
            let item = NSDraggingItem(pasteboardWriter: url as NSURL)
            item.setDraggingFrame(frame, contents: icon)
            return item
        }
        startDrag(items, event: event)
    }

    func startDrag(_ items: [NSDraggingItem], event: NSEvent) {
        beginDraggingSession(with: items, event: event, source: self).draggingFormation = .stack
    }

    func draggingSession(_ session: NSDraggingSession, sourceOperationMaskFor context: NSDraggingContext) -> NSDragOperation {
        .copy
    }
}

struct ClipboardRecordButton: View {
    let record: ClipboardRecord
    var compact = false
    var selected = false
    var onPin: (() -> Void)? = nil
    var onDelete: (() -> Void)? = nil
    var onPaste: (() -> Void)? = nil
    var onCopy: (() -> Void)? = nil
    let action: () -> Void

    private var recordButton: some View {
        Button(action: action) {
            HStack(spacing: compact ? 6 : 10) {
                switch record.content {
                case .text(let value):
                    Group {
                        if let color = clipboardColor(value) {
                            RoundedRectangle(cornerRadius: 5).fill(Color(nsColor: color))
                                .overlay(RoundedRectangle(cornerRadius: 5).stroke(.white.opacity(0.25)))
                        } else {
                            Image(systemName: clipboardKind(record) == .link ? "link" : "doc.text")
                        }
                    }.frame(width: compact ? 22 : 34, height: compact ? 18 : 34)
                    Text(value).lineLimit(compact ? 1 : 2)
                case .files(let urls):
                    Image(systemName: "doc").frame(width: compact ? 22 : 34, height: compact ? 18 : 34)
                    if let first = urls.first {
                        Text(urls.count == 1 ? first.lastPathComponent : "\(first.lastPathComponent) 외 \(urls.count - 1)개").lineLimit(1)
                    }
                case .image(let data, _):
                    if let image = NSImage(data: data) {
                        Image(nsImage: image).resizable().scaledToFit().frame(width: compact ? 22 : 34, height: compact ? 18 : 34).clipShape(RoundedRectangle(cornerRadius: 4))
                    }
                    Text("이미지 · \(clipboardImageSize(data.count))").lineLimit(1)
                }
                Spacer(minLength: 0)
            }
            .frame(maxWidth: .infinity, alignment: .leading)
            .padding(compact ? 0 : 8)
            .background(.white.opacity(compact ? 0 : (selected ? 0.18 : 0.06)), in: RoundedRectangle(cornerRadius: 9))
            .contentShape(Rectangle())
        }.buttonStyle(.plain).help(compact ? "다시 복사" : "미리보기")
            .accessibilityAddTraits(selected ? .isSelected : [])
    }

    var body: some View {
        HStack(spacing: 4) {
            if compact { recordButton }
            else { recordButton.clipboardDrag(record, onClick: action) }
            if let onPin = onPin {
                Button(action: onPin) { Image(systemName: record.pinned ? "pin.fill" : "pin") }
                    .buttonStyle(.plain).foregroundStyle(record.pinned ? Color.white : Color.secondary)
                    .help(record.pinned ? "고정 해제" : "고정")
                    .accessibilityLabel(record.pinned ? "클립보드 항목 고정 해제" : "클립보드 항목 고정")
            }
        }.contextMenu {
            if let onCopy = onCopy { Button("복사", action: onCopy) }
            if let onPaste = onPaste { Button("이전 앱에 붙여넣기", action: onPaste) }
            if let onPin = onPin { Button(record.pinned ? "고정 해제" : "고정", action: onPin) }
            if let onDelete = onDelete { Button("기록에서 삭제", role: .destructive, action: onDelete) }
        }
    }
}

struct ClipboardView: View {
    @ObservedObject var model: Model
    @State private var query = ""
    @State private var filter: ClipboardFilter = .all
    @State private var selectedID: UInt64 = 0
    @State private var searchExpanded = false
    @FocusState private var searchFocused: Bool

    private func closeSearch() {
        query = ""
        selectedID = 0
        searchFocused = false
        searchExpanded = false
        model.setClipboardSearchEditing(false)
    }

    private var searchField: some View {
        HStack(spacing: 6) {
            Image(systemName: "magnifyingglass").foregroundStyle(.secondary)
            TextField("검색", text: $query).textFieldStyle(.plain).focused($searchFocused)
            if !query.isEmpty {
                Button { query = "" } label: { Image(systemName: "xmark.circle.fill") }
                    .buttonStyle(.plain).accessibilityLabel("검색 지우기")
            }
        }.padding(7).background(.white.opacity(0.06), in: RoundedRectangle(cornerRadius: 8))
            .task {
                if model.clipboardSearchEditing { searchFocused = true }
            }
    }

    private func records(_ groups: [ClipboardGroup], selected: UInt64) -> some View {
        ScrollView {
            LazyVStack(alignment: .leading, spacing: 5) {
                ForEach(groups) { group in
                    Text(group.id).font(.caption.weight(.semibold)).foregroundStyle(.secondary).padding(.top, 6)
                    ForEach(group.items) { record in
                        ClipboardRecordButton(record: record, selected: record.id == selected,
                            onPin: { model.toggleClipboardPin(record) }, onDelete: { model.removeClipboardRecord(record) },
                            onPaste: { model.pasteClipboard(record) }, onCopy: { model.copyClipboard(record) }) { selectedID = record.id }
                    }
                }
            }
        }
    }

    private func preview(_ record: ClipboardRecord) -> some View {
        VStack(alignment: .leading, spacing: 7) {
            Text("미리보기").font(.caption.weight(.semibold)).foregroundStyle(.secondary)
            ScrollView {
                VStack(alignment: .leading, spacing: 4) {
                    switch record.content {
                    case .text(let value):
                        Text(value)
                    case .files(let urls):
                        ForEach(Array(urls.enumerated()), id: \.offset) { item in
                            Label(item.element.lastPathComponent, systemImage: "doc")
                        }
                    case .image(let data, _):
                        if let image = NSImage(data: data) {
                            Image(nsImage: image).resizable().scaledToFit().frame(maxHeight: 145)
                                .accessibilityLabel("기록된 이미지")
                        }
                    }
                }
                .frame(maxWidth: .infinity, alignment: .topLeading)
                .contentShape(Rectangle())
                .clipboardDrag(record)
            }
            .id(record.id)
            HStack {
                Button("복사") { model.copyClipboard(record) }
                Button("이전 앱에 붙여넣기") { model.pasteClipboard(record) }
            }.buttonStyle(.bordered)
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
        .padding(10)
        .background(.white.opacity(0.07), in: RoundedRectangle(cornerRadius: 10))
    }

    var body: some View {
        let showsSearch = searchExpanded || model.clipboardSearchEditing
        let visible = model.clipboardItems.filter { clipboardMatches($0, filter: filter, query: query) }
        let groups = clipboardGroups(visible)
        let displayedIDs = groups.flatMap { $0.items.map(\.id) }
        let selected = clipboardPreviewID(displayedIDs, selected: selectedID)
        VStack(alignment: .leading, spacing: 10) {
            HStack {
                Text("클립보드").font(.system(size: 14, weight: .semibold))
                Spacer()
                if !model.clipboardItems.isEmpty {
                    Button(showsSearch ? "검색 닫기" : "검색") {
                        if showsSearch { closeSearch() }
                        else { model.setClipboardSearchEditing(true) }
                    }
                }
                Button(model.clipboardEnabled ? "기록 끄기" : "기록 켜기") { model.toggleClipboard() }.disabled(!model.clipboardReady)
                if !model.clipboardItems.isEmpty { Button("기록 지우기") { model.clearClipboardHistory() }.help("고정된 항목은 유지합니다") }
            }.buttonStyle(.plain)
            if model.clipboardItems.isEmpty {
                Spacer()
                Text(!model.clipboardReady ? "기록을 불러오는 중입니다." : (model.clipboardEnabled ? "복사한 텍스트, 이미지, 파일이 여기에 표시됩니다." : "기록을 켜면 복사한 항목을 이 Mac에 저장합니다."))
                    .font(.system(size: 12)).foregroundStyle(.secondary).frame(maxWidth: .infinity)
                Spacer()
            } else {
                if showsSearch { searchField }
                HStack(spacing: 4) {
                    ForEach(ClipboardFilter.allCases.filter { candidate in candidate == .all || model.clipboardItems.contains { clipboardKind($0) == candidate } }) { candidate in
                        Button(candidate.title) { filter = candidate }
                            .buttonStyle(.plain).padding(.horizontal, 8).padding(.vertical, 4)
                            .background(filter == candidate ? Color.white.opacity(0.18) : .clear, in: Capsule())
                    }
                    Spacer(minLength: 0)
                }
                if let record = visible.first(where: { $0.id == selected }) {
                    ViewThatFits(in: .horizontal) {
                        HStack(alignment: .top, spacing: 12) {
                            records(groups, selected: selected).frame(minWidth: 230)
                            preview(record).frame(width: 226)
                        }
                        VStack(spacing: 8) {
                            preview(record).frame(height: 106)
                            records(groups, selected: selected)
                        }
                    }
                } else {
                    Text("결과가 없습니다").foregroundStyle(.secondary).frame(maxWidth: .infinity, maxHeight: .infinity)
                }
            }
            Text(!model.clipboardStorageStatus.isEmpty ? model.clipboardStorageStatus : (model.clipboardActionStatus.isEmpty ? "기록은 이 Mac에 저장되며 직접 지울 수 있습니다." : model.clipboardActionStatus)).font(.caption).foregroundStyle(.secondary)
        }.frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading).font(.system(size: 12))
            .onChange(of: displayedIDs, initial: true) { _, ids in
                selectedID = clipboardPreviewID(ids, selected: selectedID)
            }
            .onChange(of: query) { _, _ in
                selectedID = clipboardPreviewID(displayedIDs, selected: 0)
            }
            .onChange(of: searchFocused) { _, focused in
                model.setClipboardSearchEditing(focused)
            }
            .onChange(of: model.clipboardSearchEditing, initial: true) { _, editing in
                if editing { searchExpanded = true }
                else {
                    searchFocused = false
                    if query.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty { searchExpanded = false }
                }
            }
            .onChange(of: model.clipboardItems.map(\.id)) { _, ids in
                if ids.isEmpty { closeSearch() }
                if filter != .all && !model.clipboardItems.contains(where: { clipboardKind($0) == filter }) { filter = .all }
            }
            .onDisappear { model.setClipboardSearchEditing(false) }
    }
}

// Compact activity shown beside the physical camera cutout. Its two eyes and
// activity capsules follow the observed Glance running state; no project or
// prompt text is exposed in the collapsed notch.
// shortcut: other moods and the original transition curve need visual comparison.
private func lumiEyeScale(previous: Double, mood: Int32, age: TimeInterval, reduceMotion: Bool) -> Double {
    let target = mood == 2 ? 1.18 : 1.0
    guard !reduceMotion else { return target }
    let t = min(1, max(0, age / 0.3)), blend = t * t * (3 - 2 * t)
    return previous + (target - previous) * blend
}
private func riumBlendPose(previous: [Double], target: [Double], idleGaze: Double?, age: TimeInterval, animate: Bool) -> [Double] {
    var destination = target
    if destination.count > 1, let gaze = idleGaze, gaze.isFinite { destination[1] = gaze }
    guard animate, previous.count == destination.count else { return destination }
    let t = min(1, max(0, age / 0.3)), blend = t * t * (3 - 2 * t)
    return zip(previous, destination).map { old, new in old + (new - old) * blend }
}
private func lumiTracksPointer(usesLumi: Bool, reduceMotion: Bool) -> Bool {
    usesLumi && !reduceMotion
}
private func riumGazeTransition(from: [Double], to: [Double], elapsed: TimeInterval) -> [Double] {
    guard from.count == 2, to.count == 2, elapsed.isFinite else { return to }
    let t = min(1, max(0, elapsed / 0.12)), blend = t * t * (3 - 2 * t)
    return zip(from, to).map { old, new in old + (new - old) * blend }
}
private func lumiViewportScale(width: CGFloat, height: CGFloat) -> CGFloat {
    guard width.isFinite, height.isFinite, width > 0, height > 0 else { return 0 }
    let side = min(width, height)
    return side / (side < 44 ? 140 : 200)
}
private struct LumiMoodMemory {
    private struct Record { let mood: Int32; let since: TimeInterval; let previous: Int32?; let previousResumeWeight: Double; var seen: TimeInterval }
    private var records: [AgentSessionKey: Record] = [:]
    var count: Int { records.count }
    mutating func observe(_ key: AgentSessionKey, mood: Int32, now: TimeInterval) -> TimeInterval {
        guard !key.id.isEmpty, now.isFinite, now >= 0 else { return now }
        if var record = records[key], record.mood == mood, now >= record.seen {
            record.seen = now; records[key] = record
            return record.since
        }
        if records[key] == nil && records.count >= 49 {
            records = records.filter { now >= $0.value.seen && now - $0.value.seen < 3600 }
            // shortcut: older live sessions may lose their animation age above 128, revisit if that many are displayed.
            if records.count >= 128, let oldest = records.min(by: { $0.value.seen < $1.value.seen })?.key {
                records.removeValue(forKey: oldest)
            }
        }
        let previous = records[key].flatMap { now >= $0.seen ? $0.mood : nil }
        let priorWeight = previous.map { resumeWeight(key, mood: $0, now: now) } ?? 0
        records[key] = Record(mood: mood, since: now, previous: previous, previousResumeWeight: priorWeight, seen: now)
        return now
    }
    func isResuming(_ key: AgentSessionKey, mood: Int32, now: TimeInterval) -> Bool {
        guard mood == 1, let record = records[key], record.mood == mood,
              let previous = record.previous, previous == 2 || previous == 3 else { return false }
        return now >= record.since && now - record.since < 1.4
    }
    func resumeWeight(_ key: AgentSessionKey, mood: Int32, now: TimeInterval) -> Double {
        guard isResuming(key, mood: mood, now: now), let record = records[key] else { return 0 }
        // shortcut: the reference's transition out of the return pose needs frame comparison.
        let t = min(1, max(0, (now - record.since - 1.1) / 0.3))
        return 1 - t * t * (3 - 2 * t)
    }
    func previousResumeWeight(_ key: AgentSessionKey, old: Int32, new: Int32) -> Double {
        guard let record = records[key], record.mood == new, record.previous == old else { return 0 }
        return record.previousResumeWeight
    }
}
private var lumiMoodMemory = LumiMoodMemory()

private struct AgentFaceIdentity: Equatable {
    let session: AgentSessionKey
    let mood: Int32
    enum Change { case session, mood, unchanged }
    func change(from old: Self) -> Change {
        if session != old.session { return .session }
        return mood == old.mood ? .unchanged : .mood
    }
}

private let notchStatusCharacterSize: CGFloat = 30
private let agentPeekLabelWidth: CGFloat = 72

struct CollapsedAgentFace: View {
    let waiting: Bool
    let source: String
    var state: String = "작업 중"
    var agentID: String = ""
    var size: CGFloat = 19
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @State private var stateStartedAt: TimeInterval = 0
    @State private var previousPose: [Double] = [1, 0, 0, 0, 0, 0, 1, 0]
    @State private var previousParts: [Double] = [0, 0, 0]
    @State private var previousLamp = 0.62
    @State private var previousEyeScale = 1.0
    @State private var previousSquash: [Double] = [1, 1]
    @State private var pointerGaze: [Double]?
    @State private var pointerGazeOrigin: [Double]?
    @State private var pointerGazeStartedAt: TimeInterval = 0
    @State private var releasedGaze: [Double]?
    @State private var gazeReleasedAt: TimeInterval = 0
    @State private var recentClicks: [TimeInterval] = []
    @State private var reactionKind: Int32 = -1
    @State private var reactionStarted: TimeInterval = 0
    @State private var reactionGeneration = 0
    init(waiting: Bool, source: String = "", state: String = "작업 중", agentID: String = "", size: CGFloat = 19) {
        self.waiting = waiting; self.source = source; self.state = state
        self.agentID = agentID; self.size = size
    }

    private var mood: Int32 { lumiMood(waiting: waiting, state: state) }
    private func pose(for mood: Int32, at time: TimeInterval) -> [Double] {
        let age = stateStartedAt > 0 ? max(0, time - stateStartedAt) : 1
        var target = [Double](repeating: 0, count: 8)
        let status = target.withUnsafeMutableBufferPointer {
            rustNotchCharacterPose(mood, time + agentAnimationPhase(agentID) * 3, age, reduceMotion ? 1 : 0, $0.baseAddress)
        }
        guard status == 0 else { return [1, 0, 0, 0, 0, 0, 1, 0] }
        let gaze = mood == 0 ? rustRiumIdleGaze(time + agentAnimationPhase(agentID) * 3, reduceMotion ? 1 : 0) : nil
        return riumBlendPose(previous: previousPose, target: target, idleGaze: gaze, age: age,
                             animate: !reduceMotion && stateStartedAt > 0)
    }
    private func parts(for mood: Int32, at time: TimeInterval) -> [Double] {
        let age = stateStartedAt > 0 ? max(0, time - stateStartedAt) : 1
        var target = [Double](repeating: 0, count: 3)
        let status = target.withUnsafeMutableBufferPointer {
            rustNotchLumiPartsPose(mood, time + agentAnimationPhase(agentID) * 3, age, reduceMotion ? 1 : 0, $0.baseAddress)
        }
        guard status == 0 else { return [0, 0, 0] }
        guard !reduceMotion, stateStartedAt > 0 else { return target }
        let t = min(1, max(0, age / 0.3)), blend = t * t * (3 - 2 * t)
        return zip(previousParts, target).map { old, new in old + (new - old) * blend }
    }
    private func lamp(for mood: Int32, at time: TimeInterval) -> Double {
        let age = stateStartedAt > 0 ? max(0, time - stateStartedAt) : 1
        let observed = rustNotchLumiStateLamp(mood, time + agentAnimationPhase(agentID) * 3, age, reduceMotion ? 1 : 0)
        // shortcut: retain an inferred fallback for unknown future moods.
        let target = observed.isFinite ? observed : 0.4 + pose(for: mood, at: time)[7] * 0.4
        guard !reduceMotion, stateStartedAt > 0 else { return target }
        let t = min(1, age / 0.3), blend = t * t * (3 - 2 * t)
        return previousLamp + (target - previousLamp) * blend
    }
    private func eyeScale(for mood: Int32, at time: TimeInterval) -> Double {
        let age = stateStartedAt > 0 ? max(0, time - stateStartedAt) : 1
        return lumiEyeScale(previous: previousEyeScale, mood: mood, age: age, reduceMotion: reduceMotion)
    }
    private func squash(for mood: Int32, at time: TimeInterval) -> [Double] {
        var target = [1.0, 1.0]
        if mood == 8 {
            let status = target.withUnsafeMutableBufferPointer {
                rustNotchLumiStalledSquash(time + agentAnimationPhase(agentID) * 3, reduceMotion ? 1 : 0, $0.baseAddress)
            }
            if status != 0 { target = [1, 1] }
        }
        guard !reduceMotion, stateStartedAt > 0 else { return target }
        let t = min(1, max(0, (time - stateStartedAt) / 0.3)), blend = t * t * (3 - 2 * t)
        return zip(previousSquash, target).map { old, new in old + (new - old) * blend }
    }
    private func resumeWeight(for mood: Int32, at time: TimeInterval) -> Double {
        guard !reduceMotion else { return 0 }
        return lumiMoodMemory.resumeWeight(AgentSessionKey(source: source, id: agentID), mood: mood, now: time)
    }
    private func visualPose(for mood: Int32, at time: TimeInterval, weight override: Double? = nil) -> [Double] {
        let normal = pose(for: mood, at: time), weight = override ?? resumeWeight(for: mood, at: time)
        guard weight > 0 else { return normal }
        return zip(normal, pose(for: 4, at: time)).map { base, resumed in base + (resumed - base) * weight }
    }
    private func visualParts(for mood: Int32, at time: TimeInterval, weight override: Double? = nil) -> [Double] {
        let normal = parts(for: mood, at: time), weight = override ?? resumeWeight(for: mood, at: time)
        guard weight > 0 else { return normal }
        return zip(normal, parts(for: 4, at: time)).map { base, resumed in base + (resumed - base) * weight }
    }
    private func visualLamp(for mood: Int32, at time: TimeInterval, weight override: Double? = nil) -> Double {
        let normal = lamp(for: mood, at: time), weight = override ?? resumeWeight(for: mood, at: time)
        return weight > 0 ? normal + (lamp(for: 4, at: time) - normal) * weight : normal
    }
    private func resetInteraction() {
        pointerGaze = nil; pointerGazeOrigin = nil; pointerGazeStartedAt = 0; releasedGaze = nil; gazeReleasedAt = 0
        recentClicks = []; clearReaction()
    }
    private func pointerGaze(at time: TimeInterval) -> [Double]? {
        guard let gaze = pointerGaze else { return nil }
        guard let origin = pointerGazeOrigin else { return gaze }
        return riumGazeTransition(from: origin, to: gaze, elapsed: time - pointerGazeStartedAt)
    }
    private func restingGaze(at time: TimeInterval) -> [Double] {
        let pose = visualPose(for: mood, at: time)
        var gaze = [pose[1], pose[2]]
        if let released = releasedGaze, released.count == 2, gazeReleasedAt > 0 {
            let weight = max(0, rustNotchGazeReturnWeight(max(0, time - gazeReleasedAt), reduceMotion ? 1 : 0))
            gaze = zip(gaze, released).map { current, old in current + (old - current) * weight }
        }
        return gaze
    }
    private func clearReaction() {
        reactionGeneration += 1; reactionKind = -1; reactionStarted = 0
    }
    private func beginState(at time: TimeInterval, mood: Int32) {
        stateStartedAt = lumiMoodMemory.observe(AgentSessionKey(source: source, id: agentID), mood: mood, now: time)
    }
    var body: some View {
        TimelineView(.animation(minimumInterval: 1.0 / 60.0, paused: reduceMotion)) { _ in
            let time = ProcessInfo.processInfo.systemUptime
            let reaction: [Double] = {
                guard reactionKind >= 0, reactionStarted > 0 else { return [1, 0, 0, 0, 0, 0, 1, 0, 1, -1] }
                var frame = [Double](repeating: 0, count: 10)
                let result = frame.withUnsafeMutableBufferPointer {
                    rustNotchLumiReactionFrame(reactionKind, max(0, time - reactionStarted), reduceMotion ? 1 : 0, $0.baseAddress)
                }
                return result == 0 ? frame : [1, 0, 0, 0, 0, 0, 1, 0, 1, -1]
            }()
            let motion: [Double] = {
                var result = visualPose(for: mood, at: time)
                if let gaze = pointerGaze(at: time), gaze.count == 2 {
                    result[1] = gaze[0]; result[2] = gaze[1]
                } else if let gaze = releasedGaze, gaze.count == 2, gazeReleasedAt > 0 {
                    let weight = max(0, rustNotchGazeReturnWeight(max(0, time - gazeReleasedAt), reduceMotion ? 1 : 0))
                    result[1] += (gaze[0] - result[1]) * weight
                    result[2] += (gaze[1] - result[2]) * weight
                }
                result[0] *= reaction[0]
                result[1] = min(1, max(-1, result[1] + reaction[1]))
                result[2] = min(1, max(-1, result[2] + reaction[2]))
                result[3] += reaction[3]; result[4] += reaction[4]; result[5] += reaction[5]; result[6] *= reaction[6]
                return result
            }()
            let breathing = squash(for: mood, at: time)
            Group {
                    let reactionParts: [Double] = {
                        var result = visualParts(for: mood, at: time)
                        result[0] += reaction[7]
                        return result
                    }()
                    let reactionFace = reactionKind >= 0 && reactionStarted > 0
                        ? rustNotchLumiReactionFace(reactionKind, max(0, time - reactionStarted), reduceMotion ? 1 : 0) : -1
                    let face = rustRiumCharacterFace(mood, reactionFace)
                    RiumCharacter(motion: motion, headAngle: reactionParts[0], face: face,
                                  eyeScale: eyeScale(for: mood, at: time),
                                  lamp: reaction[9] >= 0 ? reaction[9] : visualLamp(for: mood, at: time),
                                  scaleX: reaction[8] * breathing[0] * motion[6], scaleY: breathing[1] * motion[6])
                        .frame(width: size, height: size * 18 / 19)
            }
                .frame(width: size, height: size * 18 / 19).clipped()
                .offset(x: CGFloat(motion[4]) * lumiViewportScale(width: size, height: size * 18 / 19),
                        y: CGFloat(motion[5]) * lumiViewportScale(width: size, height: size * 18 / 19))
            }
        .contentShape(Rectangle())
        .onContinuousHover { phase in
            guard lumiTracksPointer(usesLumi: true, reduceMotion: reduceMotion) else {
                pointerGaze = nil; pointerGazeOrigin = nil; pointerGazeStartedAt = 0; releasedGaze = nil; gazeReleasedAt = 0; return
            }
            switch phase {
            case .active(let point):
                let time = ProcessInfo.processInfo.systemUptime
                let origin = pointerGaze(at: time) ?? restingGaze(at: time)
                releasedGaze = nil; gazeReleasedAt = 0
                var gaze = [Double](repeating: 0, count: 2)
                let result = gaze.withUnsafeMutableBufferPointer {
                    rustNotchLumiPointerGaze(Double(point.x), Double(point.y), Double(size), Double(size * 18 / 19), $0.baseAddress)
                }
                pointerGazeOrigin = result == 0 ? origin : nil
                pointerGazeStartedAt = result == 0 ? time : 0
                pointerGaze = result == 0 ? gaze : nil
            case .ended:
                let releasedAt = ProcessInfo.processInfo.systemUptime
                guard let gaze = pointerGaze(at: releasedAt) else { return }
                releasedGaze = gaze; gazeReleasedAt = releasedAt; pointerGaze = nil; pointerGazeOrigin = nil; pointerGazeStartedAt = 0
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.35) {
                    guard gazeReleasedAt == releasedAt, pointerGaze == nil else { return }
                    releasedGaze = nil; gazeReleasedAt = 0
                }
            @unknown default: pointerGaze = nil; pointerGazeOrigin = nil; pointerGazeStartedAt = 0; releasedGaze = nil; gazeReleasedAt = 0
            }
        }
        // A character can be inside an agent or preview Button. Observe its
        // tap without taking priority over the enclosing navigation action.
        .simultaneousGesture(TapGesture().onEnded {
            let time = ProcessInfo.processInfo.systemUptime
            recentClicks = recentClicks.filter { time >= $0 && time - $0 < 2.5 }
            recentClicks.append(time)
            if recentClicks.count > 6 { recentClicks.removeFirst(recentClicks.count - 6) }
            reactionKind = rustNotchLumiReactionKind(mood, UInt32(recentClicks.count))
            reactionStarted = time
            reactionGeneration += 1
            let generation = reactionGeneration, kind = reactionKind
            let duration = rustNotchLumiReactionDuration(kind)
            if duration > 0 {
                DispatchQueue.main.asyncAfter(deadline: .now() + duration + (kind == 5 ? 0.2 : 0)) {
                    guard reactionGeneration == generation else { return }
                    clearReaction()
                }
            } else { clearReaction() }
        }, including: .all)
        .onAppear { beginState(at: ProcessInfo.processInfo.systemUptime, mood: mood) }
        .onDisappear { resetInteraction() }
        .onChange(of: reduceMotion) { _, reduced in
            if reduced { pointerGaze = nil; pointerGazeOrigin = nil; pointerGazeStartedAt = 0; releasedGaze = nil; gazeReleasedAt = 0 }
        }
        .onChange(of: AgentFaceIdentity(session: AgentSessionKey(source: source, id: agentID), mood: mood)) { old, next in
            let time = ProcessInfo.processInfo.systemUptime
            switch next.change(from: old) {
            case .session:
                resetInteraction()
                previousPose = [1, 0, 0, 0, 0, 0, 1, 0]; previousParts = [0, 0, 0]; previousLamp = 0.62; previousEyeScale = 1; previousSquash = [1, 1]
                beginState(at: time, mood: next.mood)
            case .mood:
                let oldWeight = !reduceMotion
                    ? max(resumeWeight(for: old.mood, at: time), lumiMoodMemory.previousResumeWeight(next.session, old: old.mood, new: next.mood)) : 0
                let oldPose = visualPose(for: old.mood, at: time, weight: oldWeight)
                let oldParts = visualParts(for: old.mood, at: time, weight: oldWeight)
                let oldLamp = visualLamp(for: old.mood, at: time, weight: oldWeight)
                let oldEyeScale = eyeScale(for: old.mood, at: time)
                let oldSquash = squash(for: old.mood, at: time)
                previousPose = oldPose; previousParts = oldParts; previousLamp = oldLamp; previousEyeScale = oldEyeScale; previousSquash = oldSquash
                beginState(at: time, mood: next.mood)
                // shortcut: prioritizing a new state over a tap reaction needs reference comparison.
                clearReaction(); recentClicks = []
            case .unchanged: break
            }
        }
        .accessibilityHidden(true)
    }
}

struct CollapsedAgentPulse: View {
    static let badgeWidth: CGFloat = 60
    let active: Bool
    let waiting: Bool
    let completed: Bool
    let activity: String
    let agentID: String
    let toolEvents: [AgentToolEvent]
    let toolObservedAt: TimeInterval?
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    private struct Token: Identifiable { let id: UInt64; let width: CGFloat; let color: Color; let accent: Bool }
    @State private var tokens: [Token] = []
    @State private var sequence: UInt64 = 0
    @State private var sessionSeed = UInt64.random(in: UInt64.min...UInt64.max)
    @State private var lastAction: TimeInterval = 0
    @State private var actionTask: Task<Void, Never>?
    @State private var actionQueue: [(Int, Color, Bool, TimeInterval)] = []
    @State private var recentEventMarkers: [UInt64] = []
    @State private var checkShown = false
    @State private var cursorStarted: TimeInterval = 0
    init(active: Bool, waiting: Bool, completed: Bool, activity: String, agentID: String, toolEvents: [AgentToolEvent], toolObservedAt: TimeInterval? = nil) {
        self.active = active; self.waiting = waiting; self.completed = completed; self.activity = activity; self.agentID = agentID; self.toolEvents = toolEvents
        self.toolObservedAt = toolObservedAt
    }
    private func showRecentAction() {
        guard let observed = toolObservedAt, agentToolBurstIsFresh(queuedAt: observed, now: ProcessInfo.processInfo.systemUptime),
              let last = toolEvents.last else { return }
        showAction(last.activity, kind: last.kind, observedAt: observed)
    }
    private var seed: UInt64 {
        agentID.utf8.reduce(sessionSeed) { ($0 ^ UInt64($1)) &* 1_099_511_628_211 }
    }
    private func sample() -> [Double] {
        var values = [Double](repeating: 0, count: 4)
        let result = values.withUnsafeMutableBufferPointer { rustAgentTokenSample(seed, sequence, $0.baseAddress) }
        return result == 0 ? values : [1.45, 4, 5, 3]
    }
    private func append(width: Double, color: Color, accent: Bool = false) {
        sequence &+= 1
        let token = Token(id: sequence, width: CGFloat(width), color: color, accent: accent)
        let update = {
            self.tokens.append(token)
            if self.tokens.count > 16 { self.tokens.removeFirst(self.tokens.count - 16) }
        }
        if !reduceMotion {
            withAnimation(.spring(response: 0.22, dampingFraction: 0.62), update)
        } else {
            var transaction = Transaction()
            transaction.disablesAnimations = true
            withTransaction(transaction, update)
        }
    }
    private func showAction(_ action: String, kind: Int32? = nil, observedAt: TimeInterval? = nil) {
        guard active, !waiting, !completed else { return }
        let now = ProcessInfo.processInfo.systemUptime
        let queuedAt = observedAt ?? now
        guard agentToolBurstIsFresh(queuedAt: queuedAt, now: now) else { return }
        lastAction = now
        // shortcut: a busy display retains the newest 16 bursts; revisit after event-rate measurement.
        if actionQueue.count == 16 { actionQueue.removeFirst() }
        let count = Int(sample()[3]); sequence &+= 1
        actionQueue.append((count, tint(for: action, kind: kind), reduceMotion, queuedAt))
        guard actionTask == nil else { return }
        actionTask = Task { @MainActor in
            while !actionQueue.isEmpty && !Task.isCancelled {
                let (count, actionTint, immediate, queuedAt) = actionQueue.removeFirst()
                guard agentToolBurstIsFresh(queuedAt: queuedAt, now: ProcessInfo.processInfo.systemUptime) else { continue }
                for index in 0..<count {
                    if index > 0 && !immediate {
                        let remaining = count - index + actionQueue.reduce(0) { $0 + $1.0 }
                        let delay = agentToolBurstDelay(queuedAt: queuedAt, now: ProcessInfo.processInfo.systemUptime, tokensRemaining: remaining)
                        do { try await Task.sleep(nanoseconds: UInt64(delay * 1_000_000_000)) } catch { return }
                    }
                    guard !Task.isCancelled else { return }
                    let now = ProcessInfo.processInfo.systemUptime
                    if !agentToolBurstIsFresh(queuedAt: queuedAt, now: now) { break }
                    lastAction = now
                    append(width: sample()[2], color: index == 0 ? actionTint : .white, accent: index == 0)
                }
            }
            actionTask = nil
        }
    }
    private func tint(for action: String, kind: Int32?) -> Color {
        let bytes = Array(action.utf8)
        var rgb = [Double](repeating: 1, count: 3)
        let status = rgb.withUnsafeMutableBufferPointer { output in
            if let kind = kind { return rustAgentTokenKindColor(kind, output.baseAddress) }
            return bytes.withUnsafeBufferPointer { rustAgentTokenColor($0.baseAddress, $0.count, output.baseAddress) }
        }
        return status == 0 ? Color(red: rgb[0], green: rgb[1], blue: rgb[2]) : .white
    }
    private func setCheckShown(_ shown: Bool) {
        if shown && !reduceMotion {
            withAnimation(.spring(response: 0.42, dampingFraction: 0.55).delay(0.1)) { checkShown = true }
        } else {
            var transaction = Transaction()
            transaction.disablesAnimations = true
            withTransaction(transaction) { checkShown = shown }
        }
    }
    var body: some View {
        let pixelStyle = false
        ZStack {
          TimelineView(.animation(minimumInterval: 1.0 / 30.0, paused: reduceMotion || !active)) { _ in
            let time = reduceMotion || !active ? 0 : ProcessInfo.processInfo.systemUptime
            if pixelStyle {
            Canvas { context, size in
                let lineWidth = min(CGFloat(52), size.width)
                let lineLeft = (size.width - lineWidth) / 2
                let widths = tokens.map { max(2, ($0.width / 2).rounded() * 2) }
                let total = widths.reduce(CGFloat(2)) { $0 + $1 + 2 }
                var x = lineLeft + lineWidth - total
                let baseline = (size.height - 6) / 2 + 6
                context.clip(to: Path(CGRect(x: lineLeft, y: 0, width: lineWidth, height: size.height)))
                for (token, width) in zip(tokens, widths) {
                    let rect = CGRect(x: x, y: baseline - 4, width: width, height: 4)
                    context.fill(Path(rect), with: .color(token.color.opacity(token.accent ? 1 : 0.85)))
                    x += width + 2
                }
                let cursor = reduceMotion || Int(time * 2) % 2 == 0 ? 1.0 : 0.0
                context.fill(Path(CGRect(x: x, y: baseline - 6, width: 2, height: 6)), with: .color(.white.opacity(cursor)))
            }
            } else {
                let elapsed = reduceMotion || !active ? 0 : max(0, time - cursorStarted)
                let cursorOpacity = rustAgentCursorOpacity(elapsed, reduceMotion || !active ? 1 : 0)
                HStack(alignment: .center, spacing: 1.4) {
                    ForEach(tokens) { token in
                        Capsule().fill(token.color)
                            .frame(width: token.width, height: 4.2)
                            .opacity(token.accent ? 1 : 0.85)
                            .shadow(color: token.accent ? token.color.opacity(0.8) : .clear, radius: 1.5)
                            .transition(.scale(scale: 0.1).combined(with: .opacity))
                    }
                    Capsule().fill(.white)
                        .frame(width: 2.2, height: 6.4)
                        .opacity(cursorOpacity)
                }
                .fixedSize()
                .frame(width: 50, alignment: .trailing)
                .clipped()
                .frame(maxWidth: .infinity, maxHeight: .infinity)
            }
          }
          .opacity(completed ? 0.18 : 1)
          // shortcut: the token fade duration is provisional until frame comparison.
          .animation(reduceMotion ? nil : .easeInOut(duration: 0.25), value: completed)
          if completed {
            Canvas { context, size in
                if pixelStyle {
                // The modified reference uses a 12×6 grid of 2pt cells.
                let rows = ["..........w.", ".......#.www", "......#...w.", ".#...#......", "..#.#.......", "...#........"]
                let origin = CGPoint(x: (size.width - 24) / 2, y: (size.height - 12) / 2 - 1)
                for (row, line) in rows.enumerated() {
                    for (column, cell) in line.enumerated() where cell != "." {
                        let color = cell == "#" ? Color(red: 0.28, green: 0.88, blue: 0.55) : .white
                        context.fill(Path(CGRect(x: origin.x + CGFloat(column * 2), y: origin.y + CGFloat(row * 2), width: 2, height: 2)), with: .color(color))
                    }
                }
                } else {
                    let center = CGPoint(x: size.width / 2, y: size.height / 2)
                    let origin = CGPoint(x: center.x - 5.5, y: center.y - 4)
                    var check = Path()
                    check.move(to: CGPoint(x: origin.x, y: origin.y + 4.2))
                    check.addLine(to: CGPoint(x: origin.x + 3.8, y: origin.y + 8))
                    check.addLine(to: CGPoint(x: origin.x + 11, y: origin.y))
                    context.stroke(check, with: .color(Color(red: 0.28, green: 0.88, blue: 0.55)), style: StrokeStyle(lineWidth: 2.8, lineCap: .round, lineJoin: .round))
                    let sparkleCenter = CGPoint(x: center.x + 11, y: center.y - 5)
                    let radius: CGFloat = 2.75
                    let inner = radius * 0.2
                    var sparkle = Path()
                    sparkle.move(to: CGPoint(x: sparkleCenter.x, y: sparkleCenter.y - radius))
                    sparkle.addQuadCurve(to: CGPoint(x: sparkleCenter.x + radius, y: sparkleCenter.y), control: CGPoint(x: sparkleCenter.x + inner, y: sparkleCenter.y - inner))
                    sparkle.addQuadCurve(to: CGPoint(x: sparkleCenter.x, y: sparkleCenter.y + radius), control: CGPoint(x: sparkleCenter.x + inner, y: sparkleCenter.y + inner))
                    sparkle.addQuadCurve(to: CGPoint(x: sparkleCenter.x - radius, y: sparkleCenter.y), control: CGPoint(x: sparkleCenter.x - inner, y: sparkleCenter.y + inner))
                    sparkle.addQuadCurve(to: CGPoint(x: sparkleCenter.x, y: sparkleCenter.y - radius), control: CGPoint(x: sparkleCenter.x - inner, y: sparkleCenter.y - inner))
                    sparkle.closeSubpath()
                    context.fill(sparkle, with: .color(.white))
                }
            }
            .opacity(checkShown ? 1 : 0)
            .scaleEffect(pixelStyle ? 1 : (checkShown ? 1 : 0.2))
          }
        }
        .onAppear {
            cursorStarted = ProcessInfo.processInfo.systemUptime
            setCheckShown(completed)
            _ = unseenAgentToolEvents(markers: &recentEventMarkers, current: toolEvents)
            guard tokens.isEmpty else { return }
            showRecentAction()
        }
        .onChange(of: toolEvents) { previous, current in
            if agentToolHistoryChanged(previous: previous.last, current: current.last) { recentEventMarkers.removeAll() }
            let fresh = unseenAgentToolEvents(markers: &recentEventMarkers, current: current)
            if let observed = toolObservedAt {
                for event in actionableAgentToolEvents(previous: previous, current: current, unseen: fresh) {
                    showAction(event.activity, kind: event.kind, observedAt: observed)
                }
            }
        }
        .onChange(of: activity) { _, current in
            if toolEvents.isEmpty && !current.isEmpty { showAction(current) }
        }
        .onChange(of: completed) { _, done in
            setCheckShown(done)
            if done {
                actionTask?.cancel(); actionTask = nil; actionQueue.removeAll()
            }
        }
        .onChange(of: waiting) { _, isWaiting in
            if isWaiting {
                actionTask?.cancel(); actionTask = nil; actionQueue.removeAll()
            }
        }
        .onChange(of: active) { _, isActive in
            if !isActive {
                actionTask?.cancel(); actionTask = nil; actionQueue.removeAll()
            }
        }
        .onDisappear { actionTask?.cancel(); actionTask = nil; actionQueue.removeAll() }
        .task(id: agentPulseCanAnimate(active: active, waiting: waiting, completed: completed, reduceMotion: reduceMotion)) {
            while !Task.isCancelled && agentPulseCanAnimate(active: active, waiting: waiting, completed: completed, reduceMotion: reduceMotion) {
                let delay = sample()[0]
                do { try await Task.sleep(nanoseconds: UInt64(delay * 1_000_000_000)) } catch { return }
                guard !Task.isCancelled else { return }
                if ProcessInfo.processInfo.systemUptime - lastAction > 1 {
                    append(width: sample()[1], color: .white)
                } else {
                    // Advance the next idle delay even while an action is active.
                    sequence &+= 1
                }
            }
        }
        .frame(width: Self.badgeWidth, height: 22)
        .background {
          if pixelStyle {
            Canvas { context, _ in
                let upper = Color(red: 0.11, green: 0.17, blue: 0.49)
                let lower = Color(red: 0.02, green: 0.03, blue: 0.155)
                for row in 0..<11 {
                    for column in 0..<30 {
                        if (row == 0 || row == 10) && (column == 0 || column == 29) { continue }
                        let edge = row == 0 || row == 10 || column == 0 || column == 29
                            || ((row == 1 || row == 9) && (column == 1 || column == 28))
                        let color = edge ? Color.black : (row <= 4 ? upper : lower)
                        context.fill(Path(CGRect(x: CGFloat(column * 2), y: CGFloat(row * 2), width: 2, height: 2)), with: .color(color))
                    }
                }
                context.fill(Path(CGRect(x: 6, y: 4, width: 28, height: 2)), with: .color(.white.opacity(0.16)))
            }
          } else {
            // shortcut: gradient angle and highlight placement need reference-frame comparison.
            RoundedRectangle(cornerRadius: 9)
                .fill(LinearGradient(colors: [Color(red: 0.11, green: 0.17, blue: 0.49), Color(red: 0.02, green: 0.03, blue: 0.155)], startPoint: .top, endPoint: .bottom))
                .overlay(alignment: .top) {
                    Capsule().fill(.white.opacity(0.16)).frame(width: 34, height: 1.4).padding(.top, 3)
                }
                .overlay(RoundedRectangle(cornerRadius: 9).strokeBorder(.black.opacity(0.5), lineWidth: 0.8))
          }
        }
        .accessibilityHidden(true)
    }
}

struct CollapsedMusicWave: View {
    let tint: NSColor
    @ObservedObject var spectrum: SystemAudioSpectrum
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    var body: some View {
        TimelineView(.animation(minimumInterval: 1.0 / 30.0, paused: reduceMotion)) { _ in
            let time = reduceMotion ? 0 : ProcessInfo.processInfo.systemUptime
            HStack(alignment: .center, spacing: 1.72) {
                ForEach(0..<6) { index in
                    let frame = spectrum.waveFrame(index, at: time, reduced: reduceMotion)
                    Capsule().fill(Color(nsColor: tint).opacity(frame.opacity)).frame(width: 1.9, height: frame.height)
                }
            }.frame(width: 20, height: 24)
        }.accessibilityHidden(true)
    }
}

private struct ReceiveFileBadge: View {
    let progress: Double?
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    var body: some View {
        ZStack {
            Circle().stroke(.white.opacity(0.16), lineWidth: 2.4)
            Circle().trim(from: 0, to: CGFloat(rustAirDropPreviewProgress(progress ?? -1)))
                .stroke(Color(red: 0.38, green: 0.7, blue: 1), style: StrokeStyle(lineWidth: 2.4, lineCap: .round))
                .rotationEffect(.degrees(-90))
                .animation(reduceMotion ? nil : .easeInOut(duration: 0.25), value: progress)
        }.frame(width: 19, height: 19).accessibilityHidden(true)
    }
}

