struct NotchView: View {
    @ObservedObject var model: Model
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @Namespace private var characterMotion
    var retainsExpandedContent = false
    var floatingSize: CGSize? = nil
    init(model: Model, retainsExpandedContent: Bool = false, floatingSize: CGSize? = nil) {
        self.model = model; self.retainsExpandedContent = retainsExpandedContent; self.floatingSize = floatingSize
    }
    private var visualExpanded: Bool { model.expanded || retainsExpandedContent }
    private var visualSize: CGSize { floatingSize ?? (visualExpanded ? model.expandedNotchSize : model.currentNotchSize) }
    private var assistantStateLabel: String { model.assistantStateLabel }
    private var musicHeaderVisible: Bool {
        model.mediaLightPlaying && !model.shelfRevealVisible && model.visibleAgentTransientPeek == nil && model.visiblePermissionPeek == nil &&
        !model.visibleAssistantPeek && model.visibleClipboardPeek == nil && !model.visibleAirDropPeek && model.visibleTrackSkipPeek == nil &&
        model.visibleSystemNotificationPeek == nil && model.visibleFocusAlarmPeek == nil &&
        !model.dictationDisplayActive && model.shortcutPeek == nil && model.caseKeyPeek == nil &&
        model.batteryPeek == nil && !model.receivingFile && model.receivedFilePeek == nil && model.visibleTimerAlarmTitle == nil &&
        !model.showsCollapsedAgent && model.assistantIndicator == .off && !model.assistantFinishing &&
        !model.assistantListening && !model.assistantSpeaking && model.weatherPeek == nil && !model.visibleSystemOverlay
    }
    private var headerHorizontalPadding: CGFloat {
        let padding = collapsedHeaderPadding(width: visualSize.width, cameraWidth: model.cameraExclusion)
        if model.dictationDisplayActive && !model.assistantListening { return min(4, padding) }
        if model.showsCompactMonitor { return min(CompactMonitorBadge.sideInset, padding) }
        return musicHeaderVisible ? min(8, padding) : padding
    }

    @ViewBuilder private func collapsedAgentHeader() -> some View {
        if model.dictationDisplayActive && !model.assistantListening {
            Text(model.dictationFinalizing ? "변환 중…" : "듣는 중…")
                .font(.system(size: 12, weight: .medium)).lineLimit(1).minimumScaleFactor(0.7)
                .accessibilityLabel(model.dictationFinalizing ? "받아쓰기 변환 중" : "받아쓰기 듣는 중")
        } else if let action = model.shortcutPeek {
            ShortcutPeekIcon(action: action, started: model.shortcutPeekStarted)
        } else if let action = model.caseKeyPeek {
            Image(systemName: action.symbol).font(.system(size: 11, weight: .semibold))
                .frame(width: 19, height: 19).background(.white.opacity(0.14), in: RoundedRectangle(cornerRadius: 5))
                .accessibilityLabel(action.title)
        } else if let battery = model.batteryPeek {
            Image(systemName: battery.critical != nil ? "battery.25" : (battery.external ? "bolt.fill" : "battery.100"))
                .font(.system(size: 11, weight: .semibold))
                .foregroundStyle(battery.critical.map { $0 ? Color.red : Color.orange } ?? .green)
                .frame(width: 19, height: 19).accessibilityLabel("배터리")
        } else if model.receivingFile {
            Button(action: { model.select(.shelf); model.expanded = true }) {
                ReceiveFileBadge(progress: model.receivingFileProgress)
            }.buttonStyle(.plain).help("파일 수신 상태 열기").accessibilityLabel("파일 수신 감지 중")
        } else if let received = model.receivedFilePeek {
            Button(action: { model.select(.shelf); model.expanded = true }) {
                Image(nsImage: received.thumbnail ?? NSWorkspace.shared.icon(forFile: received.url.path))
                    .resizable().scaledToFill().frame(width: 19, height: 19)
                    .clipShape(RoundedRectangle(cornerRadius: 4))
            }.buttonStyle(.plain).help("수신 파일 보기").accessibilityLabel("수신 파일 \(received.url.lastPathComponent)")
        } else if model.visibleTimerAlarmTitle != nil {
            Button { model.select(.monitor); model.expanded = true } label: {
                Image(systemName: "timer").font(.system(size: 12, weight: .semibold)).frame(width: 19, height: 19)
            }.buttonStyle(.plain).accessibilityLabel("타이머 알람 열기")
        } else if model.showsCollapsedAgent, let agent = model.collapsedExternalAgent {
            Button(action: { model.select(.agents); model.expanded = true }) {
                CollapsedAgentFace(waiting: agentNeedsAttention(agent.state), source: agent.source, state: agent.state, agentID: agent.id, size: notchStatusCharacterSize).id(agent.sessionKey)
                    .modifier(AgentFlightGeometry(namespace: characterMotion, session: agent.sessionKey,
                                                  enabled: true))
            }.buttonStyle(.plain)
            .accessibilityLabel("\(agent.providerName) \(agent.state)")
            .help("에이전트 활동 열기")
        } else if model.assistantIndicator != .off || model.assistantFinishing || model.assistantListening || model.assistantSpeaking {
            Button(action: { model.select(.assistant); model.expanded = true }) {
                CollapsedAgentFace(waiting: model.assistantIndicator == .approval || model.assistantIndicator == .question,
                                   state: assistantStateLabel, agentID: model.assistantAnimationID, size: notchStatusCharacterSize)
                    .modifier(AgentFlightGeometry(namespace: characterMotion,
                                                  session: AgentSessionKey(source: "", id: model.assistantAnimationID), enabled: true))
            }.buttonStyle(.plain).accessibilityLabel("AI 대화 \(assistantStateLabel)").help("AI 대화 열기")
        } else if model.weatherPeek != nil && model.volumeOverlay.isEmpty {
            Button(action: { model.select(.weather); model.expanded = true }) {
                Image(systemName: "cloud.rain.fill").font(.system(size: 12)).foregroundStyle(.cyan).frame(width: 19, height: 19)
            }.buttonStyle(.plain).help("강수 예보 열기").accessibilityLabel("강수 예보 열기")
        } else if model.mediaLightPlaying {
            Button(action: { model.select(.music); model.expanded = true }) {
                HStack(spacing: 2) {
                    Group {
                        if let artwork = model.mediaArtwork { Image(nsImage: artwork).resizable().scaledToFill() }
                        else { Image(systemName: "music.note").font(.system(size: 10)).foregroundStyle(.white).frame(maxWidth: .infinity, maxHeight: .infinity).background(.white.opacity(0.15)) }
                    }.frame(width: 24.92, height: 24.92).clipShape(RoundedRectangle(cornerRadius: 7))
                    if model.timerState != 0 { CollapsedMusicWave(tint: model.mediaLightColor, spectrum: model.musicSpectrum) }
                }
            }.buttonStyle(.plain).help("음악 열기").accessibilityLabel("음악 열기")
        } else if model.timerState != 0 {
            Button(action: { model.select(.monitor); model.expanded = true }) {
                Image(systemName: model.timerState == 3 ? "checkmark.circle.fill" : "timer").font(.system(size: 13, weight: .medium)).frame(width: 19, height: 19)
            }.buttonStyle(.plain).help("타이머 열기").accessibilityLabel("타이머 열기")
        }
    }
    @ViewBuilder private func headerControls(compact: Bool) -> some View {
        if model.dictationDisplayActive && !model.assistantListening {
            DictationLivePreview(dictation: model.dictation, level: model.dictationLevel,
                                 hidden: model.dictationPreviewHidden, finalizing: model.dictationFinalizing,
                                 started: model.dictationStartedAt, writingStarted: model.dictationWritingStartedAt,
                                 finalLevel: model.dictationFinalLevel)
        } else if let action = model.shortcutPeek {
            Text(action.title).font(.system(size: 10, weight: .medium)).lineLimit(1).minimumScaleFactor(0.7)
        } else if let action = model.caseKeyPeek {
            Text(action.title).font(.system(size: 10, weight: .medium)).lineLimit(1).minimumScaleFactor(0.7)
        } else if let battery = model.batteryPeek {
            Text("\(battery.percentage)%").font(.system(size: 10, weight: .semibold)).monospacedDigit()
                .foregroundStyle(battery.critical.map { $0 ? Color.red : Color.orange } ?? .green)
        } else if model.receivingFile {
            Button(action: { model.select(.shelf); model.expanded = true }) {
                Text(model.receivingFileProgress.map { "수신 \(Int(($0 * 100).rounded()))%" } ?? "수신 중")
                    .font(.system(size: 10, weight: .medium)).monospacedDigit().lineLimit(1).minimumScaleFactor(0.7)
            }.buttonStyle(.plain).help("파일 수신 상태 열기").accessibilityLabel("파일 수신 감지 중")
        } else if model.receivedFilePeek != nil {
            Button(action: { model.select(.shelf); model.expanded = true }) {
                Text("수신 완료").font(.system(size: 10, weight: .medium)).lineLimit(1)
            }.buttonStyle(.plain).help("수신 파일 보기").accessibilityLabel("AirDrop 수신 완료")
        } else if let title = model.visibleTimerAlarmTitle {
            Button { model.select(.monitor); model.expanded = true } label: {
                Text(title).font(.system(size: 10, weight: .semibold)).lineLimit(1).minimumScaleFactor(0.7)
            }.buttonStyle(.plain).accessibilityLabel("\(title), 타이머 알람 열기")
        } else if model.visibleSystemOverlay {
            Label(model.volumeOverlay, systemImage: model.overlaySymbol).font(.system(size: compact ? 9 : 11, weight: .medium)).lineLimit(1).minimumScaleFactor(0.7)
        } else if model.showsCollapsedAgent, let agent = model.collapsedExternalAgent {
            Button(action: { model.select(.agents); model.expanded = true }) {
                if model.usageTrackingEnabled && agentIsRunning(agent.state) {
                    CompactMonitorBadge(model: model)
                } else {
                    CollapsedAgentPulse(active: agentIsRunning(agent.state), waiting: agentNeedsAttention(agent.state), completed: agent.state == "완료", activity: agent.activity, agentID: agent.id, toolEvents: agent.toolEvents, toolObservedAt: agent.toolObservedAt).id(agent.sessionKey)
                }
            }.buttonStyle(.plain)
                .accessibilityLabel(model.usageTrackingEnabled && agentIsRunning(agent.state) ? "\(agent.providerName) \(agent.state), \(model.monitorSummary)" : "\(agent.providerName) \(agent.state)")
                .help(model.usageTrackingEnabled && agentIsRunning(agent.state) ? model.monitorSummary : "에이전트 활동 열기")
        } else if model.assistantIndicator != .off || model.assistantFinishing || model.assistantListening || model.assistantSpeaking {
            Button(action: { model.select(.assistant); model.expanded = true }) {
                if model.usageTrackingEnabled && model.assistantIndicator == .working {
                    CompactMonitorBadge(model: model)
                } else {
                    CollapsedAgentPulse(active: model.assistantIndicator == .working,
                                    waiting: model.assistantIndicator == .approval || model.assistantIndicator == .question,
                                    completed: model.assistantFinishing && model.assistant.lastOutcome == "completed", activity: "", agentID: model.assistantAnimationID, toolEvents: []).id(model.assistantAnimationID)
                }
            }.buttonStyle(.plain).accessibilityLabel("AI 대화 \(assistantStateLabel)").help("AI 대화 열기")
        } else if let date = model.weatherPeek {
            Button(action: { model.select(.weather); model.expanded = true }) {
                Text("\(weatherHourLabel(date, timeZoneID: model.weatherTimeZoneID)) 강수 예보")
                    .font(.system(size: 10, weight: .medium)).lineLimit(1).minimumScaleFactor(0.7)
            }.buttonStyle(.plain).help("시간별 강수량 예보 보기")
        } else if let summary = timerSummary(state: model.timerState, remaining: model.timerRemaining, phase: model.timerPomodoro ? model.timerPhase : nil) {
            Button(action: { model.select(.monitor); model.expanded = true }) {
                HStack(spacing: 3) {
                    if model.timerState == 2 { Image(systemName: "pause.fill").font(.system(size: 8)) }
                    Text(model.timerState == 3 ? "완료" : String(format: "%02llu:%02llu", model.timerRemaining / 60, model.timerRemaining % 60))
                        .font(.system(size: compact ? 10 : 11, weight: .medium)).monospacedDigit().lineLimit(1).minimumScaleFactor(0.65)
                }
            }.buttonStyle(.plain).help("타이머 열기").accessibilityLabel(summary)
        } else if model.mediaLightPlaying {
            Button(action: { model.select(.music); model.expanded = true }) {
                CollapsedMusicWave(tint: model.mediaLightColor, spectrum: model.musicSpectrum)
            }.buttonStyle(.plain).help("음악 열기").accessibilityLabel("음악 재생 중")
        } else if model.showsCompactMonitor {
            Button(action: { model.select(.monitor); model.expanded = true }) {
                CompactMonitorBadge(model: model).contentShape(Rectangle())
            }.buttonStyle(.plain)
                .help(model.monitorSummary)
                .accessibilityLabel(model.monitorSummary)
        }
    }
    private var compactMonitorVerticalPadding: CGFloat { max(0, (visualSize.height - CompactMonitorBadge.size) / 2) }
    var body: some View {
        VStack(alignment: .leading, spacing: 12) {
            if visualExpanded && floatingSize == nil {
                // Reserve the physical camera area without inventing an app
                // title or monitoring controls inside the expanded notch.
                Color.clear.frame(height: max(0, (model.cameraHeight > 0 ? model.cameraHeight : 32) - 17))
                    .allowsHitTesting(false).accessibilityHidden(true)
            } else if !visualExpanded && (model.shelfRevealVisible || (model.collapsedIsIdle && !model.showsCompactMonitor) || model.visibleAgentTransientPeek != nil || model.visiblePermissionPeek != nil || model.visibleAssistantPeek || model.visibleClipboardPeek != nil || model.visibleAirDropPeek || model.visibleTrackSkipPeek != nil || model.visibleSystemNotificationPeek != nil || model.visibleFocusAlarmPeek != nil) {
                EmptyView()
            } else if !visualExpanded && model.showsCompactMonitor {
                headerControls(compact: true).frame(maxWidth: .infinity, alignment: .trailing)
            } else if !visualExpanded && model.cameraExclusion > 0 && floatingSize == nil {
                let metrics = collapsedHeaderMetrics(width: model.currentNotchSize.width, cameraWidth: model.cameraExclusion, padding: headerHorizontalPadding)
                let gap = metrics.gap, side = metrics.side
                HStack(spacing: 0) {
                    collapsedAgentHeader()
                        .frame(width: side, alignment: musicHeaderVisible ? .trailing : (model.dictationDisplayActive && !model.assistantListening ? .center : .leading))
                        .clipped()
                    Color.clear.frame(width: gap).allowsHitTesting(false).accessibilityHidden(true)
                    HStack(spacing: 4) { headerControls(compact: !model.expanded) }.frame(width: side, alignment: musicHeaderVisible ? .leading : .trailing).clipped()
                }
            } else if !visualExpanded {
                HStack {
                    collapsedAgentHeader()
                    Spacer(); headerControls(compact: false)
                }
            }
            Group {
                if !visualExpanded && model.shelfRevealVisible {
                    ShelfDropPreview(model: model)
                        .transition(reduceMotion ? .opacity : .notchBandFold)
                } else if !visualExpanded, let peek = model.visiblePermissionPeek {
                    CollapsedPermissionPreview(model: model, voice: model.voiceApproval, item: peek, flightNamespace: characterMotion).id(peek.sessionKey)
                        .transition(reduceMotion ? .opacity : .notchBandFold)
                } else if !visualExpanded, let peek = model.visibleClipboardPeek {
                    ClipboardNotchPreview(model: model, peek: peek).id(peek.id)
                        .transition(reduceMotion ? .opacity : .notchBandFold)
                } else if !visualExpanded && model.visibleAirDropPeek {
                    AirDropNotchPreview(model: model)
                        .transition(reduceMotion ? .opacity : .notchBandFold)
                } else if !visualExpanded, let peek = model.visibleTrackSkipPeek {
                    TrackSkipNotchPreview(model: model, peek: peek).id(peek.id)
                        .transition(reduceMotion ? .opacity : .notchBandFold)
                } else if !visualExpanded, let peek = model.visibleSystemNotificationPeek {
                    SystemNotificationNotchPreview(model: model, peek: peek).id(peek.id)
                        .transition(reduceMotion ? .opacity : .notchBandFold)
                } else if !visualExpanded, let title = model.visibleFocusAlarmPeek {
                    TimerAlarmNotchPreview(model: model, title: title)
                        .transition(reduceMotion ? .opacity : .notchBandFold)
                } else if !visualExpanded, let peek = model.visibleAgentTransientPeek {
                    AgentTransientPreview(model: model, peek: peek, flightNamespace: characterMotion).id(peek.id)
                        .transition(.identity)
                } else if !visualExpanded && model.visibleAssistantPeek {
                    AssistantNotchPreview(model: model, label: assistantStateLabel, flightNamespace: characterMotion)
                        .transition(.opacity)
                }
            }
            // shortcut: insertion timing and interruption need reference-frame comparison.
            .animation(model.screenshotDragClosing && !reduceMotion ? .easeOut(duration: 0.2) : notchGeometryMotion(state: model.currentNotchShellState, reduceMotion: reduceMotion).animation,
                       value: model.shelfRevealVisible)
            .animation(notchGeometryMotion(state: model.currentNotchShellState, reduceMotion: reduceMotion,
                                           foldingDetail: model.foldingDetailToStatus).animation,
                       value: model.visiblePermissionPeek?.sessionKey)
            .animation(notchGeometryMotion(state: model.currentNotchShellState, reduceMotion: reduceMotion,
                                           foldingDetail: model.foldingDetailToStatus).animation,
                       value: model.visibleClipboardPeek?.id)
            .animation(notchGeometryMotion(state: model.currentNotchShellState, reduceMotion: reduceMotion,
                                           foldingDetail: model.foldingDetailToStatus).animation,
                       value: model.visibleAirDropPeek)
            .animation(notchGeometryMotion(state: model.currentNotchShellState, reduceMotion: reduceMotion,
                                           foldingDetail: model.foldingDetailToStatus).animation,
                       value: model.visibleAgentTransientPeek?.id)
            .animation(notchGeometryMotion(state: model.currentNotchShellState, reduceMotion: reduceMotion,
                                           foldingDetail: model.foldingDetailToStatus).animation,
                       value: model.visibleTrackSkipPeek?.id)
            .animation(notchGeometryMotion(state: model.currentNotchShellState, reduceMotion: reduceMotion,
                                           foldingDetail: model.foldingDetailToStatus).animation,
                       value: model.visibleSystemNotificationPeek?.id)
            .animation(notchGeometryMotion(state: model.currentNotchShellState, reduceMotion: reduceMotion,
                                           foldingDetail: model.foldingDetailToStatus).animation,
                       value: model.visibleFocusAlarmPeek)
            .animation(notchGeometryMotion(state: model.currentNotchShellState, reduceMotion: reduceMotion,
                                           foldingDetail: model.foldingDetailToStatus).animation,
                       value: model.visibleAssistantPeek)
            if visualExpanded && model.agentSwitcherVisible {
                AgentKeyboardSwitcherView(model: model)
            } else if visualExpanded {
                if model.tabEditing {
                    HStack(spacing: 7) {
                        if visualSize.width - 52 < 500 {
                            // shortcut: the narrow editor layout needs reference comparison.
                            ScrollView(.horizontal, showsIndicators: false) {
                                tabEditingControls.fixedSize(horizontal: true, vertical: false)
                            }
                        } else { tabEditingControls }
                        Button("완료") { model.finishEditing() }.buttonStyle(.plain).padding(.horizontal, 14).padding(.vertical, 5).background(.white, in: Capsule()).foregroundStyle(.black)
                            .fixedSize(horizontal: true, vertical: false)
                    }.font(.system(size: 11, weight: .semibold)).buttonStyle(.plain)
                }
                HStack(spacing: 12) {
                    ScrollViewReader { proxy in
                        ViewThatFits(in: .horizontal) {
                            notchTabs.fixedSize(horizontal: true, vertical: false)
                            ScrollView(.horizontal, showsIndicators: false) {
                                notchTabs.fixedSize(horizontal: true, vertical: false)
                            }
                            .onAppear {
                                DispatchQueue.main.async {
                                    guard model.expanded else { return }
                                    let selected = model.tabEditing ? model.selectedTab : model.tabOrder.first(where: { $0.section == model.section })
                                    if let selected { proxy.scrollTo(selected.rawValue, anchor: .center) }
                                }
                            }
                        }
                        .background(.white.opacity(0.10), in: Capsule())
                        .onChange(of: model.section) { _, section in
                            if let tab = model.tabOrder.first(where: { $0.section == section }) { proxy.scrollTo(tab.rawValue, anchor: .center) }
                        }
                        .onChange(of: model.selectedTab) { _, tab in
                            if model.tabEditing { proxy.scrollTo(tab.rawValue, anchor: .center) }
                        }
                        .onChange(of: model.tabOrder) { _, _ in
                            if model.tabEditing { proxy.scrollTo(model.selectedTab.rawValue, anchor: .center) }
                        }
                    }
                    Spacer(minLength: 0)
                    Menu {
                        Button("홈 편집") { model.beginHomeEdit() }
                        Button("탭 편집") { model.beginTabEdit() }
                        Button("탭 관리…") { (NSApp.delegate as? AppDelegate)?.presentSettings(page: .tabs) }
                        Menu("다른 기능") {
                            Button("음악") { model.select(.music) }
                            Button("날씨") { model.select(.weather) }
                            Button("알림") { model.select(.notifications) }
                            Button("일정과 미리 알림") { model.select(.agenda) }
                            Button("보관함") { model.select(.shelf) }
                            Button("면접 코파일럿") { model.select(.interview) }
                            Button("집중 타이머") { model.select(.monitor) }
                            Button("메모") { model.select(.notes) }
                            Button("AI 대화") { model.select(.assistant) }
                            if model.usageTrackingEnabled { Button("시스템 모니터링") { model.select(.monitor) } }
                        }
                        Divider()
                        Button("설정…") { (NSApp.delegate as? AppDelegate)?.showSettings() }
                        Divider()
                        Button("Rium Notch 종료") { NSApp.terminate(nil) }
                    } label: { Image(systemName: "ellipsis").frame(width: 30, height: 28).background(.white.opacity(0.09), in: Circle()).contentShape(Rectangle()) }
                        .menuStyle(.borderlessButton).menuIndicator(.hidden)
                        .fixedSize(horizontal: true, vertical: false)
                        .help("더 보기").accessibilityLabel("더 보기")
                }.buttonStyle(.plain).font(.system(size: 12, weight: .medium))
                if let title = model.visibleTimerAlarmTitle, !model.homeEditing, !model.tabEditing {
                    TimerAlarmBanner(model: model, title: title)
                        .transition(reduceMotion ? .opacity : .move(edge: .top).combined(with: .opacity))
                }
                if model.section == .home || model.section == .agents {
                    Group {
                        if model.section == .home {
                            if model.homeEditing {
                                if model.displayHeight < 455 {
                                    ScrollView(.vertical, showsIndicators: false) { homeEditorContent }
                                } else { homeEditorContent }
                            } else {
                                HomeView(model: model, agenda: model.agenda, contentWidth: visualSize.width, flightNamespace: characterMotion)
                                    .transition(.identity)
                            }
                        } else {
                            AgentView(model: model, flightNamespace: characterMotion).transition(.identity)
                        }
                    }.animation(reduceMotion ? nil : .spring(response: 0.55, dampingFraction: 0.8, blendDuration: 0), value: model.section)
                } else if model.section == .dictation {
                    DictationView(model: model.dictation)
                } else if model.section == .notifications {
                    HomeNotificationsPage(model: model)
                } else if model.section == .music {
                    MusicView(model: model)
                } else if model.section == .shelf {
                    ShelfView(model: model)
                } else if model.section == .clipboard {
                    ClipboardView(model: model)
                } else if model.section == .weather {
                    WeatherView(model: model)
                } else if model.section == .agenda {
                    AgendaView(model: model.agenda)
                } else if model.section == .notes {
                    NotesPage(model: model, notes: model.notes)
                } else if model.section == .assistant {
                    AssistantPage(model: model, assistant: model.assistant, dictation: model.dictation)
                } else if model.section == .teleprompter {
                    TeleprompterPage(controller: model.teleprompter)
                } else if model.section == .interview {
                    if model.interviewDetached {
                        VStack(alignment: .leading, spacing: 10) {
                            Text("면접 코파일럿이 별도 창에서 열려 있습니다.")
                            HStack {
                                Button("별도 창 보기") { model.onOpenInterviewWindow?() }
                                Button("노치로 돌아가기") { model.onReturnInterviewToNotch?() }
                            }.buttonStyle(.plain)
                        }.frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
                    } else {
                        InterviewView(model: model, interview: model.interview, suggestions: model.interview.suggestions)
                    }
                } else {
                if model.usageTrackingEnabled {
                HStack(alignment: .top, spacing: 14) {
                    VStack(alignment: .leading, spacing: 7) {
                        HStack(spacing: 9) {
                            CompactMonitorBadge(model: model, diameter: 36)
                            VStack(alignment: .leading, spacing: 2) {
                                Text("시스템 모니터링").font(.system(size: 14, weight: .semibold))
                                Text(model.monitorCodexRemaining.map { "Codex 기본 한도 \($0)% 남음" } ?? "Codex 잔여량 확인 전")
                                    .font(.caption2).foregroundStyle(.secondary)
                            }
                        }
                        HStack { VStack(alignment: .leading) { Text("CPU  \(model.cpu)"); Text("최근 사용률").font(.caption2).foregroundStyle(.secondary) }; Spacer(); Sparkline(samples: model.cpuHistory).stroke(Color.cyan.opacity(0.8), lineWidth: 1.5).frame(width: 100, height: 23).accessibilityHidden(true) }
                        HStack { VStack(alignment: .leading) { Text("RAM  \(model.memoryPercent)"); Text(model.memory).font(.caption2).foregroundStyle(.secondary) }; Spacer(); Sparkline(samples: model.memoryHistory).stroke(Color.purple.opacity(0.9), lineWidth: 1.5).frame(width: 100, height: 23).accessibilityHidden(true) }
                        HStack { Text("메모리 압력  \(model.pressure)"); Spacer(); Text("스왑  \(model.swap)") }.font(.caption)
                        HStack { Text(model.volume); Spacer(); Text(model.brightness) }.font(.caption)
                        PowerSummary(model: model.power).font(.caption)
                    }.frame(maxWidth: .infinity, alignment: .leading).riumTile()
                    VStack(alignment: .leading, spacing: 7) {
                        HStack { Text("Codex 계정").font(.system(size: 14, weight: .semibold)); Spacer(); Button("추가") { model.addAccount() }.buttonStyle(.plain) }
                        if model.accounts.isEmpty { Text("연결된 계정 없음").foregroundStyle(.secondary) }
                        if !model.accounts.isEmpty { ScrollView { VStack(alignment: .leading, spacing: 8) {
                            ForEach(model.accounts) { account in
                                HStack(alignment: .top) { VStack(alignment: .leading) { Text(account.name); Text(account.usage).font(.caption).foregroundStyle(.secondary); if !account.detail.isEmpty { Text(account.detail).font(.caption).foregroundStyle(.secondary) }; ForEach(Array(account.additionalUsage.enumerated()), id: \.offset) { _, line in Text(line).font(.caption).foregroundStyle(.secondary) } }; Spacer(); if !account.connected { Button("로그인") { model.login(account.id) }.buttonStyle(.plain) }; Button("새로고침") { model.refresh(account.id) }.buttonStyle(.plain)
                                    Menu("관리") {
                                        Button("이름 변경…") { model.renameAccount(account) }
                                        Button("연결 해제…", role: .destructive) { model.removeAccount(account) }
                                    }
                                    .menuStyle(.borderlessButton).fixedSize().help("계정 관리").accessibilityLabel("\(account.name) 계정 관리")
                                }
                            }
                        } }.frame(height: 112) }
                        if !model.message.isEmpty { Text(model.message).font(.caption).foregroundStyle(.secondary) }
                    }.frame(maxWidth: .infinity, alignment: .leading).riumTile()
                }.font(.system(size: 12))
                Divider().overlay(.white.opacity(0.12))
                }
                HStack {
                    Text(model.timerPomodoro ? "포모도로 · \(model.timerPhase.title)" : "집중 타이머").font(.system(size: 13, weight: .semibold))
                    Text(String(format: "%02llu:%02llu", model.timerRemaining / 60, model.timerRemaining % 60)).monospacedDigit()
                    if model.timerPomodoro { Text("집중 완료 \(model.timerSessions)회").foregroundStyle(.secondary) }
                    if model.timerState == 3 { Text("완료").foregroundStyle(.secondary) }
                    Spacer()
                    if model.timerState == 1 {
                        Button("일시 정지") { model.pauseTimer() }
                    } else if model.timerState == 2 {
                        Button("계속") { model.resumeTimer() }
                    } else {
                        Menu("시작") {
                            ForEach([5, 10, 25, 50], id: \.self) { minutes in
                                Button("\(minutes)분") { model.startTimer(UInt32(minutes * 60)) }
                            }
                            Button("포모도로 시작 (\(model.pomodoroFocus)분 · \(model.pomodoroShortBreak)분)") { model.startPomodoro() }
                            Button("직접 입력…") { model.customTimer() }
                        }
                    }
                    if model.timerState != 0 { Button("초기화") { model.resetTimer() } }
                }.buttonStyle(.plain).font(.system(size: 12))
                Divider().overlay(.white.opacity(0.12))
                HStack {
                    Text("클립보드").font(.system(size: 13, weight: .semibold)); Spacer()
                    Button(model.clipboardEnabled ? "기록 끄기" : "기록 켜기") { model.toggleClipboard() }.disabled(!model.clipboardReady)
                    Button("모두 보기") { model.select(.clipboard) }
                    if !model.clipboardItems.isEmpty { Button("기록 지우기") { model.clearClipboardHistory() } }
                }.buttonStyle(.plain).font(.system(size: 12))
                if model.clipboardItems.isEmpty {
                    Text(!model.clipboardReady ? "기록을 불러오는 중입니다." : (model.clipboardEnabled ? "복사한 텍스트, 이미지, 파일이 여기에 표시됩니다." : "기록을 켜면 복사한 항목을 이 Mac에 저장합니다.")).font(.caption).foregroundStyle(.secondary)
                } else {
                    ScrollView { VStack(alignment: .leading, spacing: 4) {
                        ForEach(model.clipboardItems) { record in
                            ClipboardRecordButton(record: record, compact: true) { model.copyClipboard(record) }
                        }
                    }}.frame(maxHeight: 65)
                }
                }
                Spacer(minLength: 0)
            }
        }
        // The animated cover reveals the content; a second transition crossfades the two layouts.
        .animation(floatingSize != nil && !reduceMotion ? .spring(response: 0.55, dampingFraction: 0.8, blendDuration: 0) : nil,
                   value: visualExpanded)
        .animation(reduceMotion ? nil : .spring(response: 0.35, dampingFraction: 0.85), value: model.visibleTimerAlarmTitle)
        .padding(.horizontal, model.shelfRevealVisible ? 16 : (floatingSize == nil && !visualExpanded && model.visibleSystemNotificationPeek != nil ? 22 : (floatingSize == nil && !visualExpanded && model.cameraExclusion > 0 && !model.visibleAssistantPeek ? headerHorizontalPadding : notchContentHorizontalPadding(floating: floatingSize != nil, visualExpanded: visualExpanded,
                                                           assistantPeek: model.visibleAssistantPeek, width: visualSize.width,
                                                           cameraWidth: model.cameraExclusion))))
        .padding(.vertical, floatingSize != nil && !visualExpanded ? 2 : (visualExpanded ? 12 : (model.shelfRevealVisible || model.dictationDisplayActive || model.visibleAgentTransientPeek != nil || model.visiblePermissionPeek != nil || model.visibleAssistantPeek || model.visibleClipboardPeek != nil || model.visibleAirDropPeek || model.visibleTrackSkipPeek != nil || model.visibleSystemNotificationPeek != nil || model.visibleFocusAlarmPeek != nil || model.showsCollapsedAgent ? 1 : (model.showsCompactMonitor ? compactMonitorVerticalPadding : (musicHeaderVisible ? max(0, (visualSize.height - 24.92) / 2) : 8)))))
        .frame(width: visualSize.width, height: visualSize.height, alignment: .top)
        // The persistent opaque background is drawn by NotchContainer.
        .foregroundStyle(.white)
        .contentShape(NotchContentHitShape(outline: floatingSize ?? model.currentNotchOutlineSize, corners: model.currentNotchCorners,
                                           floatingRadius: floatingSize == nil ? nil : (model.floatingIslandGeometry?.radius ?? (visualExpanded ? 28 : 12))))
        .onDrop(of: [UTType.fileURL], delegate: ShelfNotchDropDelegate(model: model))
        .onTapGesture { if !model.expanded { model.expanded = true } }
        .onChange(of: model.expanded) { _, value in NotificationCenter.default.post(name: .notchSizeChanged, object: notchHeight(expanded: value, section: model.section)) }
        .onChange(of: model.section) { _, section in if model.expanded { NotificationCenter.default.post(name: .notchSizeChanged, object: notchHeight(expanded: true, section: section)) } }
        .onChange(of: model.shelfRevealVisible) { _, _ in NotificationCenter.default.post(name: .notchSizeChanged, object: model.currentNotchSize.height) }
        .onChange(of: model.homeEditing) { _, _ in NotificationCenter.default.post(name: .notchSizeChanged, object: model.currentNotchSize.height) }
        .onChange(of: model.tabEditing) { _, _ in NotificationCenter.default.post(name: .notchSizeChanged, object: model.currentNotchSize.height) }
        .onChange(of: model.visibleTimerAlarmTitle) { _, _ in NotificationCenter.default.post(name: .notchSizeChanged, object: model.currentNotchSize.height) }
        .onChange(of: model.visiblePermissionPeek?.sessionKey) { _, _ in NotificationCenter.default.post(name: .notchSizeChanged, object: model.currentNotchSize.height) }
        .onChange(of: model.visibleClipboardPeek?.id) { _, _ in NotificationCenter.default.post(name: .notchSizeChanged, object: model.currentNotchSize.height) }
        .onChange(of: model.visibleAirDropPeek) { _, _ in NotificationCenter.default.post(name: .notchSizeChanged, object: model.currentNotchSize.height) }
        .onChange(of: model.visibleAgentTransientPeek?.id) { _, _ in NotificationCenter.default.post(name: .notchSizeChanged, object: model.currentNotchSize.height) }
        .onChange(of: model.visibleTrackSkipPeek?.id) { _, _ in NotificationCenter.default.post(name: .notchSizeChanged, object: model.currentNotchSize.height) }
        .onChange(of: model.visibleSystemNotificationPeek?.id) { _, _ in NotificationCenter.default.post(name: .notchSizeChanged, object: model.currentNotchSize.height) }
        .onChange(of: model.visibleFocusAlarmPeek) { _, _ in NotificationCenter.default.post(name: .notchSizeChanged, object: model.currentNotchSize.height) }
        .onChange(of: model.visibleAssistantPeek) { _, _ in NotificationCenter.default.post(name: .notchSizeChanged, object: model.currentNotchSize.height) }
    }

    private var notchTabs: some View {
        HStack(spacing: 8) {
            ForEach(model.tabOrder) { tab in EditableNotchTab(model: model, tab: tab).id(tab.rawValue) }
        }.padding(.horizontal, 5).padding(.vertical, 2)
    }
    private var homeEditorContent: some View {
        VStack(alignment: .leading, spacing: 12) {
            HStack { Text("홈 편집").font(.system(size: 14, weight: .semibold)); Spacer(); Button("완료") { model.finishEditing() }.buttonStyle(.plain).padding(.horizontal, 14).padding(.vertical, 5).background(.white, in: Capsule()).foregroundStyle(.black) }
            HomeView(model: model, agenda: model.agenda, contentWidth: visualSize.width)
                .frame(height: homeCardRowHeight(editing: true), alignment: .top)
            HomeEditorOptions(model: model)
        }.frame(maxWidth: .infinity, alignment: .leading)
    }
    private var tabEditingControls: some View {
        HStack(spacing: 7) {
            Button { model.moveTab(model.selectedTab, by: -1) } label: { Image(systemName: "chevron.left").frame(width: 25, height: 25).background(.white.opacity(0.10), in: Circle()).contentShape(Rectangle()) }
                .disabled(model.tabOrder.firstIndex(of: model.selectedTab).map { $0 <= 1 } ?? true).accessibilityLabel("선택한 탭을 왼쪽으로 이동")
            Button { model.moveTab(model.selectedTab, by: 1) } label: { Image(systemName: "chevron.right").frame(width: 25, height: 25).background(.white.opacity(0.10), in: Circle()).contentShape(Rectangle()) }
                .disabled(model.tabOrder.firstIndex(of: model.selectedTab).map { $0 >= model.tabOrder.count - 1 } ?? true).accessibilityLabel("선택한 탭을 오른쪽으로 이동")
            Text(model.selectedTab.title).foregroundStyle(.secondary)
            Spacer(minLength: 0)
            Menu("탭 추가") {
                ForEach(NotchTab.allCases.filter { $0 != .home && !model.tabOrder.contains($0) }) { tab in
                    Button(tab.title) { model.addTab(tab) }
                }
            }.menuStyle(.borderlessButton).fixedSize().disabled(model.tabOrder.count == NotchTab.allCases.count)
            Button("제거") { model.removeTab(model.selectedTab) }.disabled(model.selectedTab == .home)
            Text("\(model.tabOrder.count)/\(NotchTab.allCases.count)").foregroundStyle(.secondary)
        }
    }
}

private struct ShelfNotchDropDelegate: DropDelegate {
    let model: Model
    func validateDrop(info: DropInfo) -> Bool {
        !model.shelfOutgoingDragActive && info.hasItemsConforming(to: [UTType.fileURL])
    }
    private func zone(_ info: DropInfo) -> ShelfDropZone {
        shelfDropZone(atX: info.location.x, width: model.currentNotchSize.width,
                      split: !model.expanded && model.floatingIslandPlacement == nil)
    }
    func dropEntered(info: DropInfo) {
        model.setFileDragActive(true)
        let destination = zone(info)
        if model.shelfDropZone != destination { model.shelfDropZone = destination }
    }
    func dropUpdated(info: DropInfo) -> DropProposal? {
        guard validateDrop(info: info) else { return nil }
        dropEntered(info: info)
        return DropProposal(operation: .copy)
    }
    func dropExited(info: DropInfo) {
        model.leaveFileDropTarget()
    }
    func performDrop(info: DropInfo) -> Bool {
        let destination = zone(info)
        let providers = info.itemProviders(for: [UTType.fileURL])
        let accepted = destination == .airDrop ? model.receiveAirDropFiles(providers) : model.receiveFileDrop(providers)
        model.setFileDragActive(false)
        return accepted
    }
}

private struct ShelfDropPreview: View {
    @ObservedObject var model: Model
    @Environment(\.accessibilityReduceMotion) private var reduceMotion

    private var title: String {
        if model.fileDragActive { return "파일을 여기에 놓으세요" }
        if model.shelfDropPending { return "파일을 준비하는 중" }
        if let feedback = model.shelfConfirmationMessage { return feedback }
        switch model.shelfConfirmationKind {
        case .shelf: return "보관함에 추가됨"
        case .airDrop: return "AirDrop 공유 준비됨"
        case .screenshot: return "스크린샷을 끌어 사용하세요"
        }
    }

    private var statusIcon: (symbol: String, tint: Color) {
        if model.shelfConfirmationMessage != nil { return ("exclamationmark.circle", .orange) }
        if model.shelfConfirmedFiles.isEmpty { return ("tray.and.arrow.down", .white) }
        switch model.shelfConfirmationKind {
        case .shelf: return ("checkmark.circle.fill", .green)
        case .airDrop: return ("airdrop", .blue)
        case .screenshot: return ("camera.viewfinder", .green)
        }
    }

    var body: some View {
        let icon = statusIcon
        VStack(alignment: .leading, spacing: 9) {
            Color.clear.frame(height: max(0, (model.cameraHeight > 0 ? model.cameraHeight : 32) - 1))
                .allowsHitTesting(false).accessibilityHidden(true)
            HStack(spacing: 8) {
                Image(systemName: icon.symbol).foregroundStyle(icon.tint)
                Text(title)
                    .font(.system(size: 11.5, weight: .medium))
                Spacer(minLength: 0)
            }
            if model.fileDragActive {
                HStack(spacing: 8) {
                    shelfTile("보관함", symbol: "tray.and.arrow.down.fill", selected: model.shelfDropZone == .shelf)
                    shelfTile("AirDrop", symbol: "airdrop", selected: model.shelfDropZone == .airDrop)
                }
            }
            if !model.shelfConfirmedFiles.isEmpty {
                VStack(spacing: 5) {
                    ForEach(Array(model.shelfConfirmedFiles.prefix(3).enumerated()), id: \.offset) { index, url in
                        ShelfConfirmedRow(model: model, url: url, index: index).id(url)
                    }
                }
            }
            Spacer(minLength: 0)
        }.frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
    }
    private func shelfTile(_ title: String, symbol: String, selected: Bool) -> some View {
        VStack(spacing: 4) {
            Image(systemName: symbol).font(.system(size: title == "AirDrop" ? 15 : 14))
            Text(title).font(.system(size: 10, weight: .medium))
        }.frame(maxWidth: .infinity).frame(height: 48)
            .background(.white.opacity(selected ? 0.16 : 0.06), in: RoundedRectangle(cornerRadius: 12))
            .overlay(RoundedRectangle(cornerRadius: 12).stroke(.white.opacity(selected ? 0.35 : 0.10)))
            .animation(reduceMotion ? nil : .easeOut(duration: 0.15), value: selected)
    }
}

private struct ShelfConfirmedRow: View {
    @ObservedObject var model: Model
    let url: URL
    let index: Int
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @State private var revealed = false
    @State private var hovering = false

    var body: some View {
        let emphasized = model.shelfConfirmationKind == .screenshot
        HStack(spacing: 8) {
            ShelfConfirmedFileIcon(url: url)
            Text(url.lastPathComponent).lineLimit(1).truncationMode(.middle)
            Spacer(minLength: 0)
        }
        .font(.system(size: 11, weight: .medium))
        .padding(.horizontal, emphasized ? 9 : 0)
        .frame(height: emphasized ? 38 : 22)
        .background(emphasized ? Color.white.opacity(hovering ? 0.11 : 0.055) : .clear,
                    in: RoundedRectangle(cornerRadius: 10))
        .overlay {
            if emphasized {
                RoundedRectangle(cornerRadius: 10)
                    .stroke(Color(red: 0.82, green: 0.74, blue: 1).opacity(hovering ? 0.58 : 0.25))
            }
        }
        .scaleEffect(emphasized && hovering ? 1.015 : 1)
        .animation(reduceMotion ? nil : .easeOut(duration: 0.14), value: hovering)
        .opacity(revealed ? 1 : 0)
        .scaleEffect(revealed || reduceMotion ? 1 : 0.82)
        .animation(reduceMotion ? .easeOut(duration: 0.12) : .timingCurve(0.16, 1, 0.3, 1, duration: 0.78).delay(Double(index) * 0.06), value: revealed)
        .onAppear { revealed = true }
        .onHover { hovering = $0 }
        .contentShape(Rectangle())
        .onDrag {
            model.beginShelfConfirmationDrag()
            return NSItemProvider(object: url as NSURL)
        }
        .help(emphasized ? "스크린샷을 끌어 사용" : "파일 끌기")
        .accessibilityLabel(url.lastPathComponent)
    }
}

private struct ShelfConfirmedFileIcon: View {
    let url: URL
    @State private var thumbnail: NSImage?

    var body: some View {
        Image(nsImage: thumbnail ?? NSWorkspace.shared.icon(forFile: url.path))
            .resizable().scaledToFit().frame(width: 22, height: 22)
            .clipShape(RoundedRectangle(cornerRadius: 5))
            .onAppear {
                DispatchQueue.global(qos: .utility).async {
                    guard let image = fileImageThumbnail(url, maxPixelSize: 120) else { return }
                    DispatchQueue.main.async { thumbnail = NSImage(cgImage: image, size: .zero) }
                }
            }
    }
}

private struct TrackSkipNotchPreview: View {
    @ObservedObject var model: Model
    let peek: TrackSkipPeek
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @State private var leftEntered = false
    @State private var rightEntered = false
    @State private var rightEntrance: DispatchWorkItem?
    var body: some View {
        Button { model.select(.music); model.expanded = true } label: {
            GeometryReader { geometry in
                let metrics = agentPeekBandMetrics(width: geometry.size.width, cameraWidth: model.cameraExclusion,
                                                   floating: model.floatingIslandPlacement != nil)
                TimelineView(.animation(minimumInterval: 1.0 / 30.0, paused: reduceMotion)) { _ in
                    // shortcut: placement and color need reference-frame comparison.
                    let phase = reduceMotion ? -1 : max(0, ProcessInfo.processInfo.systemUptime - peek.started).truncatingRemainder(dividingBy: 0.78) / 0.78
                    HStack(spacing: 0) {
                        HStack(spacing: 3) {
                            HStack(spacing: 0) {
                                ForEach(0..<3) { index in
                                    let wave = rustTrackSkipPeekWave(phase, Int32(index), peek.forward ? 1 : 0)
                                    Image(systemName: peek.forward ? "chevron.right" : "chevron.left")
                                        .font(.system(size: 12, weight: .semibold)).opacity(0.22 + 0.78 * wave)
                                }
                            }
                            Text(peek.forward ? "다음 곡" : "이전 곡")
                                .font(.system(size: 14, weight: .semibold)).lineLimit(1).minimumScaleFactor(0.7)
                        }
                        .scaleEffect(CGFloat(rustAgentPeekEntranceScale(leftEntered ? 1 : 0, reduceMotion ? 1 : 0)))
                        .opacity(leftEntered ? 1 : 0)
                        .frame(width: metrics.side, alignment: .leading).clipped()
                        Color.clear.frame(width: metrics.gap).allowsHitTesting(false).accessibilityHidden(true)
                        Group {
                            if let title = peek.title {
                                VStack(alignment: .trailing, spacing: 1) {
                                    Text(title).font(.system(size: 12, weight: .medium)).lineLimit(1).truncationMode(.tail)
                                    if let artist = peek.artist { Text(artist).font(.system(size: 9)).foregroundStyle(.secondary).lineLimit(1).truncationMode(.tail) }
                                }
                            } else {
                                HStack(spacing: 4) {
                                    ForEach(0..<3) { index in
                                        let wave = rustTrackSkipPeekWave(phase, Int32(index), peek.forward ? 1 : 0)
                                        Circle().fill(.white.opacity(0.2 + 0.7 * wave)).frame(width: 5, height: 5)
                                    }
                                }
                            }
                        }
                        .contentTransition(.opacity)
                        .animation(reduceMotion ? nil : .easeOut(duration: 0.2), value: peek.title)
                        .scaleEffect(CGFloat(rustAgentPeekEntranceScale(rightEntered ? 1 : 0, reduceMotion ? 1 : 0)))
                        .opacity(rightEntered ? 1 : 0)
                        .frame(width: metrics.side, alignment: .trailing).clipped()
                    }.frame(height: 33)
                }
            }.frame(height: 33)
        }.buttonStyle(.plain).accessibilityLabel(peek.title.map { "\(peek.forward ? "다음 곡" : "이전 곡"): \($0)" } ?? (peek.forward ? "다음 곡 확인 중" : "이전 곡 확인 중"))
            .onAppear {
                if reduceMotion { withAnimation(.easeOut(duration: 0.12)) { leftEntered = true; rightEntered = true }; return }
                withAnimation(.timingCurve(0.16, 1, 0.3, 1, duration: 0.32)) { leftEntered = true }
                let work = DispatchWorkItem {
                    withAnimation(.timingCurve(0.16, 1, 0.3, 1, duration: 0.32)) { rightEntered = true }
                }
                rightEntrance = work
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.02, execute: work)
            }
            .onDisappear { rightEntrance?.cancel(); rightEntrance = nil }
            .onChange(of: reduceMotion) { _, reduced in
                if reduced { rightEntrance?.cancel(); rightEntrance = nil; leftEntered = true; rightEntered = true }
            }
    }
}

private struct AirDropReceiveShape: Shape {
    let filled: Bool
    var sending = false
    func path(in rect: CGRect) -> Path {
        var path = Path()
        guard [rect.minX, rect.minY, rect.width, rect.height].allSatisfy(\.isFinite), rect.width > 0, rect.height > 0 else { return path }
        var points = [Double](repeating: 0, count: 42)
        guard points.withUnsafeMutableBufferPointer({ sending ? rustAirDropSendGlyph($0.baseAddress, $0.count) : rustAirDropReceiveGlyph($0.baseAddress, $0.count) }) == 42 else { return path }
        let scale = min(rect.width, rect.height) / 24
        func point(_ index: Int) -> CGPoint {
            CGPoint(x: rect.minX + CGFloat(points[index * 2]) * scale, y: rect.minY + CGFloat(points[index * 2 + 1]) * scale)
        }
        path.move(to: point(0))
        path.addCurve(to: point(1), control1: point(2), control2: point(3))
        path.addLine(to: point(4))
        path.addCurve(to: point(5), control1: point(6), control2: point(7))
        if filled {
            path.addCurve(to: point(0), control1: point(8), control2: point(9))
            path.closeSubpath()
        } else {
            path.move(to: point(10)); path.addLine(to: point(11))
            path.move(to: point(12))
            path.addCurve(to: point(13), control1: point(14), control2: point(15))
            path.addQuadCurve(to: point(16), control: point(17))
            path.addCurve(to: point(18), control1: point(19), control2: point(20))
        }
        return path
    }
}

private struct AirDropTransferGlyph: View {
    let size: CGFloat
    let tint: Color
    var sending = false
    var body: some View {
        ZStack {
            AirDropReceiveShape(filled: true, sending: sending).fill(tint.opacity(0.18))
            AirDropReceiveShape(filled: false, sending: sending).stroke(tint, style: StrokeStyle(lineWidth: size * 1.4 / 17, lineCap: .round, lineJoin: .round))
        }.frame(width: size, height: size).accessibilityHidden(true)
    }
}

private struct AirDropNotchPreview: View {
    @ObservedObject var model: Model
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @State private var leftEntered = false
    @State private var rightEntered = false
    private let tint = Color(red: 0.38, green: 0.7, blue: 1)
    private var sending: Bool { !model.receivingFile && model.receivedFilePeek == nil && model.airDropSendPeek != nil }
    private var label: String {
        guard sending, let phase = model.airDropSendPeek?.phase else { return model.receivingFile ? "수신 중" : "수신 완료" }
        switch phase {
        case .sending: return "공유 중"
        case .shared: return "공유 완료"
        case .interrupted: return "공유 중단"
        case .unknown: return "결과 확인 필요"
        }
    }

    var body: some View {
        Button { model.select(.shelf); model.expanded = true } label: {
            GeometryReader { geometry in
                let metrics = agentPeekBandMetrics(width: geometry.size.width, cameraWidth: model.cameraExclusion,
                                                   floating: model.floatingIslandPlacement != nil)
                HStack(spacing: 0) {
                    HStack(spacing: 7) {
                        Group {
                            if let image = sending ? model.airDropSendPeek?.thumbnail : (model.receivingFile ? nil : model.receivedFilePeek?.thumbnail) {
                                Image(nsImage: image).resizable().scaledToFill().frame(width: 20, height: 20)
                                    .clipShape(RoundedRectangle(cornerRadius: 5))
                            } else {
                                AirDropTransferGlyph(size: 20, tint: tint, sending: sending)
                            }
                        }
                        Text(label)
                            .font(.system(size: 14, weight: .semibold)).foregroundStyle(.white.opacity(0.92))
                            .lineLimit(1).minimumScaleFactor(0.7).contentTransition(.opacity)
                    }
                    .scaleEffect(CGFloat(rustAgentPeekEntranceScale(leftEntered ? 1 : 0, reduceMotion ? 1 : 0)))
                    .opacity(leftEntered ? 1 : 0)
                    .frame(width: min(118, metrics.side), alignment: .leading)
                    .frame(width: metrics.side, alignment: .leading).clipped()
                    Color.clear.frame(width: metrics.gap).allowsHitTesting(false).accessibilityHidden(true)
                    Group {
                        if model.receivingFile || (sending && model.airDropSendPeek?.phase == .sending) {
                            ReceiveFileBadge(progress: sending ? nil : model.receivingFileProgress)
                        } else if sending && (model.airDropSendPeek?.phase == .interrupted || model.airDropSendPeek?.phase == .unknown) {
                            Image(systemName: "exclamationmark.circle").font(.system(size: 15, weight: .medium))
                                .foregroundStyle(.white.opacity(0.6)).frame(width: 19, height: 19)
                        } else {
                            AirDropTransferGlyph(size: 19, tint: tint, sending: sending)
                        }
                    }
                    .scaleEffect(CGFloat(rustAgentPeekEntranceScale(rightEntered ? 1 : 0, reduceMotion ? 1 : 0)))
                    .opacity(rightEntered ? 1 : 0)
                    .frame(width: min(72, metrics.side), alignment: .trailing)
                    .frame(width: metrics.side, alignment: .trailing).clipped()
                }.frame(height: 33)
            }.frame(height: 33)
        }
        .buttonStyle(.plain).accessibilityLabel(sending ? "AirDrop \(label)" : (model.receivingFile ? "파일 수신 중" : "AirDrop 수신 완료"))
        .onAppear {
            if reduceMotion { withAnimation(.easeOut(duration: 0.12)) { leftEntered = true; rightEntered = true }; return }
            withAnimation(.timingCurve(0.16, 1, 0.3, 1, duration: 0.32)) { leftEntered = true }
            withAnimation(.timingCurve(0.16, 1, 0.3, 1, duration: 0.32).delay(0.02)) { rightEntered = true }
        }
        .onChange(of: reduceMotion) { _, reduced in if reduced { leftEntered = true; rightEntered = true } }
    }
}

