                    NotificationMarquee(text: detailsVisible ? peek.detail(appName: appName) : "새 알림",
                                        width: sideWidth)
                        .scaleEffect(CGFloat(rustAgentPeekEntranceScale(rightEntered ? 1 : 0, reduceMotion ? 1 : 0)))
                        .opacity(rightEntered ? 1 : 0)
