struct DictationLivePreview: View {
    @ObservedObject var dictation: DictationController
    let level: Double
    let hidden: Bool
    let finalizing: Bool
    @AppStorage("rium.dictation.previewText") private var showText = false
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    let started: TimeInterval
    let writingStarted: TimeInterval
    let finalLevel: Double
    var body: some View {
        Group {
            if showText && !hidden && !dictation.lastText.isEmpty {
                Text(dictation.lastText).font(.system(size: 12, weight: .medium))
                    .lineLimit(1).truncationMode(.tail)
            } else {
                TimelineView(.animation(minimumInterval: 1.0 / 30.0, paused: reduceMotion)) { _ in
                    let now = ProcessInfo.processInfo.systemUptime
                    let time = reduceMotion ? 0.6 : max(0, now - started)
                    Canvas { context, size in
                        let input = level.isFinite ? min(1, max(0, level)) : 0
                        let sample = finalizing ? dictationWritingCloudSample(age: max(0, now - started),
                            writingAge: max(0, now - writingStarted), initialLevel: finalLevel, reduceMotion: reduceMotion) : nil
                        drawLiveCloud(context: &context, size: size, particleTime: time, level: input,
                                      completion: 0, listening: !finalizing, approval: false,
                                      reduceMotion: reduceMotion, appearance: 1,
                                      organicSample: sample)
                    }
                    .opacity(finalizing ? 0.3 : 1)
                    .animation(reduceMotion ? nil : .easeOut(duration: 0.25), value: finalizing)
                }.frame(maxWidth: 116).frame(height: 32).clipped().accessibilityHidden(true)
            }
        }.frame(height: 32).accessibilityLabel(finalizing ? "받아쓰기 변환 중" : "받아쓰기 음성 입력 중")
    }
}

// Shortcut illustrations are local approximations of the reference's
// per-action animated cards; their exact original artwork remains unknown.
struct ShortcutPeekIcon: View {
    let action: ShortcutAction
    let started: TimeInterval
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    var body: some View {
        TimelineView(.animation(minimumInterval: 1.0 / 30.0, paused: reduceMotion)) { _ in
            let frame = iconFrame(elapsed: max(0, ProcessInfo.processInfo.systemUptime - started))
            let phase = frame[5]
            ZStack {
                if action == .selectAll {
                    RoundedRectangle(cornerRadius: 5).fill(.white.opacity(0.30 * sin(phase * .pi)))
                }
                if action == .print && !reduceMotion {
                    ForEach(0..<3) { index in
                        let progress = min(1, max(0, (phase - Double(index) * 0.19) / 0.42))
                        RoundedRectangle(cornerRadius: 0.5).fill(.white)
                            .frame(width: 3, height: 4)
                            .offset(x: CGFloat(index - 1) * 3, y: CGFloat(2 + progress * 5))
                            .opacity(progress > 0 && progress < 1 ? 0.85 : 0)
                    }
                }
                Image(systemName: action == .save && phase < 0.55 ? "square.and.arrow.down" : action.symbol)
                    .font(.system(size: 11, weight: .semibold))
                    .rotationEffect(.degrees(frame[0])).scaleEffect(CGFloat(frame[1]))
                    .offset(x: CGFloat(frame[2]), y: CGFloat(frame[3]))
                    .opacity(frame[4])
            }
            .frame(width: 19, height: 19)
            .background(.white.opacity(0.14), in: RoundedRectangle(cornerRadius: 5))
            .clipShape(RoundedRectangle(cornerRadius: 5))
        }.accessibilityLabel(action.title)
    }
    private func iconFrame(elapsed: TimeInterval) -> [Double] {
        var values: [Double] = [0, 1, 0, 0, 1, 1]
        let status = values.withUnsafeMutableBufferPointer {
            rustNotchShortcutIconFrame(action.rawValue, elapsed, reduceMotion ? 1 : 0, $0.baseAddress)
        }
        return status == 0 ? values : [0, 1, 0, 0, 1, 1]
    }
}

// Append the open left-to-right edge to a path already at rect.minX/minY.
// The silhouette and light stroke must share the same geometry.
struct NotchCorners: Equatable {
    var bottom: CGFloat
    var shoulder: CGFloat
    static let legacy = NotchCorners(bottom: 16, shoulder: 20)
}

func notchCorners(for state: Int32) -> NotchCorners {
    var values = [Double](repeating: 0, count: 2)
    let status = values.withUnsafeMutableBufferPointer { rustNotchShellCornerGeometry(state, $0.baseAddress) }
    return status == 0 ? NotchCorners(bottom: CGFloat(values[0]), shoulder: CGFloat(values[1])) : .legacy
}

func appendNotchContour(to path: inout Path, in rect: CGRect, corners: NotchCorners = .legacy) {
    var metrics = [Double](repeating: 0, count: 4)
    let status = metrics.withUnsafeMutableBufferPointer {
        rustNotchShellContourMetrics(Double(rect.width), Double(rect.height), Double(corners.bottom), Double(corners.shoulder), $0.baseAddress)
    }
    guard status == 0 else { return }
    let shoulder = CGFloat(metrics[0]), corner = CGFloat(metrics[1])
    let upperControl = CGFloat(metrics[2]), lowerControl = CGFloat(metrics[3])
    let left = rect.minX + shoulder, right = rect.maxX - shoulder
    let top = rect.minY, bottom = rect.maxY
    path.addCurve(to: CGPoint(x: left, y: top + shoulder),
                  control1: CGPoint(x: left - upperControl, y: top),
                  control2: CGPoint(x: left, y: top + upperControl))
    path.addLine(to: CGPoint(x: left, y: bottom - corner))
    path.addCurve(to: CGPoint(x: left + corner, y: bottom),
                  control1: CGPoint(x: left, y: bottom - corner + lowerControl),
                  control2: CGPoint(x: left + corner - lowerControl, y: bottom))
    path.addLine(to: CGPoint(x: right - corner, y: bottom))
    path.addCurve(to: CGPoint(x: right, y: bottom - corner),
                  control1: CGPoint(x: right - corner + lowerControl, y: bottom),
                  control2: CGPoint(x: right, y: bottom - corner + lowerControl))
    path.addLine(to: CGPoint(x: right, y: top + shoulder))
    path.addCurve(to: CGPoint(x: right + shoulder, y: top),
                  control1: CGPoint(x: right, y: top + upperControl),
                  control2: CGPoint(x: right + upperControl, y: top))
}

struct NotchSilhouette: Shape {
    var corners: NotchCorners = .legacy
    func path(in rect: CGRect) -> Path {
        var path = Path()
        path.move(to: CGPoint(x: rect.minX, y: rect.minY))
        appendNotchContour(to: &path, in: rect, corners: corners)
        path.closeSubpath(); return path
    }
}

// The content frame is narrower than the outer shell in expanded mode.
// Align the SwiftUI hit path to the shell instead of adding a second inset.
struct NotchContentHitShape: Shape {
    var outline: CGSize
    var corners: NotchCorners
    var floatingRadius: CGFloat? = nil
    func path(in rect: CGRect) -> Path {
        guard outline.width.isFinite, outline.height.isFinite, outline.width > 0, outline.height > 0 else { return Path() }
        let shell = CGRect(x: rect.midX - outline.width / 2, y: rect.minY, width: outline.width, height: outline.height)
        if let radius = floatingRadius { return FloatingIslandShape(radius: radius).path(in: shell) }
        return NotchSilhouette(corners: corners).path(in: shell)
    }
}

