func mainWeatherPreview(_ model: Model) -> [WeatherHour] {
    Array(model.weatherForecast.filter { $0.date > model.now }.prefix(3))
}

func homeWeatherGraphHours(_ model: Model) -> [WeatherHour] {
    Array(model.weatherForecast.filter { $0.date > model.now }.prefix(8))
}

struct HomeWeatherDay: Identifiable {
    let id: Date
    let low: Double
    let high: Double
    let symbol: String
}
func homeWeatherDays(_ model: Model, limit: Int = 3) -> [HomeWeatherDay] {
    var calendar = Calendar(identifier: .gregorian)
    calendar.timeZone = model.weatherTimeZoneID.flatMap(TimeZone.init(identifier:)) ?? .current
    let upcoming = model.weatherForecast.filter { $0.date >= model.now }
    let groups = Dictionary(grouping: upcoming) { calendar.startOfDay(for: $0.date) }
    return groups.keys.sorted().prefix(max(0, min(limit, 10))).compactMap { day in
        guard let hours = groups[day], let low = hours.map(\.temperature).min(), let high = hours.map(\.temperature).max() else { return nil }
        let noon = calendar.date(bySettingHour: 12, minute: 0, second: 0, of: day) ?? day
        let representative = hours.min { abs($0.date.timeIntervalSince(noon)) < abs($1.date.timeIntervalSince(noon)) }
        return HomeWeatherDay(id: day, low: low, high: high, symbol: representative?.symbol ?? "")
    }
}
func homeWeatherWeekday(_ day: Date, timeZoneID: String?) -> String {
    let formatter = DateFormatter(); formatter.locale = Locale(identifier: "ko_KR")
    formatter.timeZone = timeZoneID.flatMap(TimeZone.init(identifier:)) ?? .current
    formatter.dateFormat = "E"
    return formatter.string(from: day)
}

func homeWeatherRange(_ model: Model) -> (label: String, count: Int)? {
    let hours = homeWeatherGraphHours(model)
    guard let low = hours.map(\.temperature).min(), let high = hours.map(\.temperature).max() else { return nil }
    return (String(format: "%.0f° / %.0f°", low, high), hours.count)
}

func homeWeatherMetric(_ model: Model, variant: String) -> (label: String, value: String) {
    switch variant {
    case "feels":
        let value = rustWeatherFeelsLike(model.weatherTemperature ?? .nan, model.weatherWind ?? .nan, model.weatherHumidity ?? .nan)
        return (value.isFinite ? "체감 온도 · 추정" : "체감 온도", value.isFinite ? String(format: "%.0f°", value) : "정보 없음")
    case "humidity": return ("습도", model.weatherHumidity.map { String(format: "%.0f%%", $0) } ?? "정보 없음")
    case "wind": return ("풍속", model.weatherWind.map { String(format: "%.1f m/s", $0) } ?? "정보 없음")
    case "rain":
        let current = currentWeatherHour(model.weatherForecast, at: model.now)
        return ("1시간 예상 강수량", current?.precipitation.map { String(format: "%.1f mm", $0) } ?? "정보 없음")
    default: return ("날씨", "정보 없음")
    }
}

func homeCentreDestination(_ variant: String) -> PanelSection {
    switch variant {
    case "today": return .agenda
    case "focus": return .monitor
    default: return .agents
    }
}

