    return Int(min(3, (availableWidth - 65) / 29))
}

struct HomeView: View {
    @ObservedObject var model: Model
    @ObservedObject var agenda: AgendaModel
    let contentWidth: CGFloat
    var flightNamespace: Namespace.ID? = nil
    @AppStorage("rium.card.style") private var cardStyle = "liquid"
    private var narrow: Bool { contentWidth - 52 < 720 }
    private var cardWidth: CGFloat {
        (max(720, contentWidth - 52) - 3 * 7) / 4
    }
    @ViewBuilder private var content: some View {
        if cardStyle == "dashboard" {
            DashboardHome(model: model, agenda: agenda, flightNamespace: flightNamespace).background { homeBackdrop }
        } else {
            standardHome
        }
    }
    @ViewBuilder private var homeBackdrop: some View {
        if model.homeBackground.isTexture {
            HomeTextureSurface(background: model.homeBackground, priority: true)
                .mask(LinearGradient(stops: [
                    .init(color: .clear, location: 0), .init(color: .clear, location: 0.12),
                    .init(color: .white.opacity(0.4), location: 0.4), .init(color: .white, location: 0.8)
                ], startPoint: .top, endPoint: .bottom))
                .allowsHitTesting(false).accessibilityHidden(true)
        } else if model.homeBackground == .blue {
            model.homeBackground.preview.opacity(0.7).blur(radius: 12)
        } else if model.homeBackground == .graphite {
            model.homeBackground.preview.opacity(0.6).blur(radius: 12)
        } else if (model.homeBackground == .hour || (model.homeBackground == .album && model.mediaAtmosphere == nil)),
                  let photograph = LocalHourBackdrop.wash(at: model.now) {
            GeometryReader { geometry in
                Image(nsImage: photograph).resizable().scaledToFill()
                    .frame(width: geometry.size.width, height: geometry.size.height)
                    .opacity(0.45)
                    .mask(LinearGradient(stops: [
                        .init(color: .clear, location: 0), .init(color: .white, location: 0.18),
                        .init(color: .white, location: 0.82), .init(color: .clear, location: 1)
                    ], startPoint: .top, endPoint: .bottom))
                    .clipped()
            }.allowsHitTesting(false).accessibilityHidden(true)
        } else if model.homeBackground == .hour {
            model.homeBackground.preview.opacity(0.6).blur(radius: 12)
        } else if (cardStyle == "liquid" || model.homeBackground == .album), let artwork = model.mediaAtmosphere {
            GeometryReader { geometry in
                Image(nsImage: artwork).resizable().scaledToFill()
                    .frame(width: geometry.size.width, height: geometry.size.height)
                    .opacity(model.homeBackground == .album ? 0.45 : 0.20)
                    .mask(LinearGradient(stops: [
                        .init(color: .clear, location: 0),
                        .init(color: .white, location: 0.08),
                        .init(color: .white.opacity(0.55), location: 0.48),
                        .init(color: .clear, location: 1)
                    ], startPoint: .leading, endPoint: .trailing))
                    .mask(LinearGradient(stops: [
                        .init(color: .clear, location: 0),
                        .init(color: .white, location: 0.18),
                        .init(color: .white, location: 0.82),
                        .init(color: .clear, location: 1)
                    ], startPoint: .top, endPoint: .bottom))
                    .clipped()
            }.allowsHitTesting(false).accessibilityHidden(true)
        }
    }
    @ViewBuilder var body: some View {
        if narrow {
            let rowHeight = homeCardRowHeight(editing: model.homeEditing)
            ScrollView(.horizontal, showsIndicators: false) {
                content.frame(width: 720, height: rowHeight, alignment: .top)
            }.frame(height: rowHeight)
        } else { content }
    }
    private var standardHome: some View {
        VStack(alignment: .leading, spacing: 12) {
            HStack(alignment: .top, spacing: 7) {
                VStack(alignment: .leading, spacing: 6) {
                    if model.homeVariant(.music) == "artwork" {
                        HStack(spacing: 10) {
                            Group {
                                if let artwork = model.mediaArtwork { Image(nsImage: artwork).resizable().scaledToFill() }
                                else { Image(systemName: "music.note").resizable().scaledToFit().padding(15).foregroundStyle(.white.opacity(0.65)).background(.white.opacity(0.08)) }
                            }.frame(width: 68, height: 68).clipShape(RoundedRectangle(cornerRadius: 12))
                            VStack(alignment: .leading, spacing: 4) {
                                Text(model.mediaTitle).fontWeight(.semibold).lineLimit(2)
                                Text(model.mediaArtist.isEmpty ? "음악" : model.mediaArtist).font(.caption).foregroundStyle(.secondary).lineLimit(1)
                            }
                        }
                    } else if model.homeVariant(.music) == "lyrics" {
                        Text(model.mediaTitle).font(.caption).foregroundStyle(.secondary).lineLimit(1)
                        Spacer(minLength: 0)
