private struct AgentQuestionKey: Hashable {
    let session: AgentSessionKey
    let question: String
}

private struct ClaudeApproval: Identifiable {
    let id: String
    let request: [String: Any]
    let display: String
    var isQuestion: Bool { request["tool_name"] as? String == "AskUserQuestion" }
}

private struct ClaudeQuestionOption {
    let label: String
    let detail: String
}
private struct ClaudeQuestion {
    let title: String
    let header: String
    let options: [ClaudeQuestionOption]
    let multiple: Bool
    let allowsCustom: Bool

    static func parse(_ request: [String: Any]) -> [ClaudeQuestion]? {
        guard let input = request["tool_input"] as? [String: Any],
              let rows = input["questions"] as? [[String: Any]], (1...4).contains(rows.count) else { return nil }
        var questions: [ClaudeQuestion] = []
        for row in rows {
            guard let title = row["question"] as? String, !title.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty,
                  row["isSecret"] as? Bool != true, row["is_secret"] as? Bool != true else { return nil }
            let rawOptions = row["options"] as? [[String: Any]] ?? []
            let options = rawOptions.compactMap { option -> ClaudeQuestionOption? in
                guard let label = option["label"] as? String else { return nil }
                return ClaudeQuestionOption(label: label, detail: option["description"] as? String ?? "")
            }
            guard options.count == rawOptions.count, Set(options.map(\.label)).count == options.count else { return nil }
            let camel = row["multiSelect"] as? Bool, snake = row["multi_select"] as? Bool
            if row["multiSelect"] != nil && camel == nil { return nil }
            if row["multi_select"] != nil && snake == nil { return nil }
            if let camel = camel, let snake = snake, camel != snake { return nil }
            questions.append(ClaudeQuestion(title: title, header: row["header"] as? String ?? "", options: options, multiple: camel ?? snake ?? false, allowsCustom: true))
        }
        return questions
    }
}

private struct ClaudeQuestionForm: View {
    let questions: [ClaudeQuestion]
    let disabled: Bool
    let submit: ([[String]]) -> Void
    @State private var selected: [Int: Set<String>] = [:]
    @State private var custom: [Int: String] = [:]

    private var answers: [[String]] {
        questions.enumerated().map { index, question in
            let selectedLabels = question.options.map(\.label).filter { selected[index, default: []].contains($0) }
            let text = (custom[index] ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
            return text.isEmpty ? selectedLabels : selectedLabels + [text]
        }
    }
    private var complete: Bool {
        zip(questions, answers).allSatisfy { question, values in
            !values.isEmpty && (question.multiple || values.count == 1) && values.allSatisfy { $0.utf8.count <= 2000 }
        }
    }
    var body: some View {
        VStack(alignment: .leading, spacing: 10) {
            ForEach(Array(questions.enumerated()), id: \.offset) { index, question in
                VStack(alignment: .leading, spacing: 6) {
                    if !question.header.isEmpty { Text(question.header).font(.caption.weight(.semibold)).foregroundStyle(.secondary) }
                    Text(question.title).font(.system(size: 12, weight: .medium)).fixedSize(horizontal: false, vertical: true)
                    ForEach(Array(question.options.enumerated()), id: \.offset) { _, option in
                        Button {
                            var values = selected[index] ?? []
                            if question.multiple {
                                if values.contains(option.label) { values.remove(option.label) } else { values.insert(option.label) }
                            } else { values = [option.label]; custom[index] = "" }
                            selected[index] = values
                        } label: {
                            HStack(alignment: .top, spacing: 6) {
                                Image(systemName: (selected[index] ?? []).contains(option.label) ? "checkmark.circle.fill" : "circle").padding(.top, 2)
                                VStack(alignment: .leading, spacing: 2) {
                                    Text(option.label).fixedSize(horizontal: false, vertical: true)
                                    if !option.detail.isEmpty { Text(option.detail).font(.caption).foregroundStyle(.secondary).fixedSize(horizontal: false, vertical: true) }
                                }
                            }.frame(maxWidth: .infinity, alignment: .leading).contentShape(Rectangle())
                        }.buttonStyle(.plain).disabled(disabled)
                    }
                    if question.allowsCustom {
                        TextField("직접 답변 입력", text: Binding(get: { custom[index] ?? "" }, set: { value in
                            custom[index] = value
                            if !question.multiple && !value.isEmpty { selected[index] = [] }
                        }), axis: .vertical).textFieldStyle(.roundedBorder).lineLimit(1...3).disabled(disabled)
                    }
                }
            }
            Button("답변 보내기") { submit(answers) }.buttonStyle(.bordered).disabled(disabled || !complete)
        }
    }
}

struct SuccessCheckmarkShape: Shape {
    func path(in rect: CGRect) -> Path {
        var values = [Double](repeating: 0, count: 6)
        let status = values.withUnsafeMutableBufferPointer {
            rustSuccessCheckmarkPoints(Double(rect.width), Double(rect.height), $0.baseAddress)
        }
        guard status == 0 else { return Path() }
        var path = Path()
        path.move(to: CGPoint(x: rect.minX + CGFloat(values[0]), y: rect.minY + CGFloat(values[1])))
        path.addLine(to: CGPoint(x: rect.minX + CGFloat(values[2]), y: rect.minY + CGFloat(values[3])))
        path.addLine(to: CGPoint(x: rect.minX + CGFloat(values[4]), y: rect.minY + CGFloat(values[5])))
        return path
    }
}

enum AgentOrbStyle: Equatable {
    case thinking, completed, permission, stalled
    var particleCount: Int { self == .thinking ? 180 : 153 }
    var colors: [Color] {
        switch self {
        case .thinking: return [Color(red: 0.05, green: 0.18, blue: 0.66), Color(red: 0.3, green: 0.68, blue: 1), Color(red: 0.72, green: 0.91, blue: 1)]
        case .completed: return [Color(red: 0.03, green: 0.26, blue: 0.14), Color(red: 0.28, green: 0.88, blue: 0.55), Color(red: 0.78, green: 1, blue: 0.87)]
        case .permission: return [Color(red: 0.42, green: 0.12, blue: 0.01), Color(red: 1, green: 0.55, blue: 0.05), Color(red: 1, green: 0.86, blue: 0.52)]
        case .stalled: return [Color(red: 0.1, green: 0.1, blue: 0.11), Color(red: 0.62, green: 0.61, blue: 0.62), Color(red: 0.91, green: 0.91, blue: 0.93)]
        }
    }
}

func agentOrbTime(style: AgentOrbStyle, time: TimeInterval, reduceMotion: Bool) -> TimeInterval {
    let duration: TimeInterval
    switch style {
    case .thinking: duration = 0.6
    case .permission: duration = 5.0
    case .completed, .stalled: duration = 1.05
    }
    return reduceMotion ? duration : min(duration, max(0, time))
}

private struct AgentOrbPreview: View {
    let time: TimeInterval
    let reduceMotion: Bool
    let style: AgentOrbStyle
    var body: some View {
        Canvas { context, size in
            let count = style.particleCount
            let sampleTime = agentOrbTime(style: style, time: time, reduceMotion: reduceMotion)
            var points = [Double](repeating: 0, count: count * 6)
            let status = points.withUnsafeMutableBufferPointer {
                if style != .thinking {
                    return rustSuccessOrbParticles(Double(size.width), Double(size.height), sampleTime, $0.baseAddress)
                }
                return rustThinkingOrbParticles(Double(size.width), Double(size.height), sampleTime, $0.baseAddress)
            }
            guard status == 0 else { return }
            let colors = style.colors
            for index in 0..<count {
                let offset = index * 6, x = CGFloat(points[offset]), y = CGFloat(points[offset + 1])
                let radius = CGFloat(points[offset + 2]), opacity = points[offset + 3], depth = points[offset + 4]
                let color = colors[depth > 0.73 ? 2 : (depth > 0.38 ? 1 : 0)]
                context.fill(Path(ellipseIn: CGRect(x: x - radius, y: y - radius, width: radius * 2, height: radius * 2)),
                             with: .color(color.opacity(opacity)))
                if points[offset + 5] > 0 {
                    let halo = radius * 3.5
                    context.fill(Path(ellipseIn: CGRect(x: x - halo, y: y - halo, width: halo * 2, height: halo * 2)),
                                 with: .color(colors[1].opacity(0.09)))
                }
            }
        }.accessibilityHidden(true)
    }
}

private var agentStatusRevealProbe: [(id: UUID, elapsed: TimeInterval)] = []

private struct AgentTransientPreview: View {
    @ObservedObject var model: Model
    let peek: AgentTransientPeek
    let flightNamespace: Namespace.ID?
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @State private var rightEntranceVisible = false
    init(model: Model, peek: AgentTransientPeek, flightNamespace: Namespace.ID? = nil) {
        self.model = model; self.peek = peek; self.flightNamespace = flightNamespace
    }
    private var label: String {
        switch peek.kind {
        case .running: return "작업 중"
        case .completed: return "완료"
        case .failed: return "실패"
        case .interrupted: return "중단됨"
        case .stalled: return "응답 지연 추정"
        }
    }
    var body: some View {
        let agent = model.liveAgent(for: peek)
        let showMonitor = model.usageTrackingEnabled && peek.kind == .running
        let statusVisible = reduceMotion || rightEntranceVisible || showMonitor
        Button { model.select(.agents); model.expanded = true } label: {
            GeometryReader { geometry in
                let cameraGap = model.cameraExclusion > 0 ? model.cameraExclusion + 8 : 0
                let metrics = agentPeekBandMetrics(width: geometry.size.width, cameraWidth: cameraGap,
                                                   floating: model.floatingIslandPlacement != nil)
                let gap = metrics.gap, side = metrics.side
                HStack(spacing: 0) {
                    CollapsedAgentFace(waiting: agentNeedsAttention(agent.state), source: agent.source,
                                       state: agent.state, agentID: agent.id, size: notchStatusCharacterSize)
                        .modifier(AgentFlightGeometry(namespace: flightNamespace, session: agent.sessionKey, enabled: true))
                        .frame(width: side, height: geometry.size.height, alignment: .leading)
                        .clipped()
                    Color.clear.frame(width: gap).allowsHitTesting(false).accessibilityHidden(true)
                    Group {
                        if showMonitor {
                            CompactMonitorBadge(model: model)
                        } else if peek.kind == .running || peek.kind == .completed {
                            CollapsedAgentPulse(active: peek.kind == .running, waiting: false, completed: peek.kind == .completed,
                                                activity: agent.activity, agentID: agent.id, toolEvents: agent.toolEvents, toolObservedAt: agent.toolObservedAt)
                                .id(agent.sessionKey)
                        } else {
                            Text("\(agent.providerName) \(label)").font(.system(size: 11, weight: .medium))
                                .lineLimit(1).minimumScaleFactor(0.7)
                        }
                    }
                    .scaleEffect(CGFloat(rustAgentPeekEntranceScale(statusVisible ? 1 : 0, reduceMotion ? 1 : 0)))
                    .opacity(statusVisible ? 1 : 0)
                    .frame(width: min(side, agentPeekLabelWidth), height: geometry.size.height, alignment: .trailing)
                    .frame(width: side, height: geometry.size.height, alignment: .trailing).clipped()
                }
            }
            .frame(height: model.floatingIslandPlacement != nil ? 33 : min(33, max(0, model.currentNotchSize.height - 2)))
            .contentShape(Rectangle())
        }
        .buttonStyle(.plain).accessibilityLabel(showMonitor ? "\(agent.providerName) \(label), \(model.monitorSummary)" : "\(agent.providerName) \(label)")
        .task(id: peek.id) {
            let elapsed = ProcessInfo.processInfo.systemUptime - peek.started
            let wait = rustAgentPeekStatusWaitNanoseconds(elapsed, peek.kind == .running ? 1 : 0, reduceMotion ? 1 : 0)
            if wait > 0 {
                do { try await Task.sleep(nanoseconds: wait) } catch { return }
            }
            guard !Task.isCancelled, model.visibleAgentTransientPeek?.id == peek.id else { return }
            if wait == 0 || reduceMotion { rightEntranceVisible = true }
            else {
                withAnimation(.timingCurve(0.16, 1, 0.3, 1, duration: 0.32)) {
                    rightEntranceVisible = true
                }
            }
            if CommandLine.arguments.contains("--self-test-notch-animation") {
                agentStatusRevealProbe.append((peek.id, ProcessInfo.processInfo.systemUptime - peek.started))
            }
        }
        .onChange(of: reduceMotion) { _, reduced in
            if reduced { rightEntranceVisible = true }
        }
    }
}

private struct CollapsedPermissionTarget {
    let identifier: String
    let summary: String
    let payload: [String: Any]
    let channel: String
    var fingerprint: String? {
        guard JSONSerialization.isValidJSONObject(payload),
              let data = try? JSONSerialization.data(withJSONObject: payload, options: [.sortedKeys, .withoutEscapingSlashes]),
              let text = String(data: data, encoding: .utf8) else { return nil }
        return channel + ":" + identifier + ":" + text
    }
}

private func murmurVisibleCharacterCount(referenceCount: Int32, textCount: Int) -> Int {
    guard referenceCount > 0, textCount > 0 else { return 0 }
    return min(textCount, 1 + Int((Double(min(referenceCount, 23) - 1) * Double(textCount - 1) / 22).rounded()))
}
private func murmurPrefixAdvance(_ text: String, line: CTLine, visible: Int) -> CGFloat {
    let count = min(text.count, max(0, visible))
    let index = text.index(text.startIndex, offsetBy: count).utf16Offset(in: text)
    return CGFloat(CTLineGetOffsetForStringIndex(line, index, nil))
}

private struct MurmurPixelWord {
    let text: String
    let font: NSFont
    let line: CTLine
    let size: CGSize
    let image: CGImage?
}

private func murmurPixelWord(_ text: String) -> MurmurPixelWord {
    let font = NSFont(name: "HelveticaNeue", size: 14) ?? NSFont.systemFont(ofSize: 14)
    let attributed = NSAttributedString(string: text, attributes: [.font: font, .foregroundColor: NSColor.white])
    let line = CTLineCreateWithAttributedString(attributed as CFAttributedString)
    let measured = attributed.size()
    let size = CGSize(width: max(1, ceil(measured.width)), height: max(1, ceil(measured.height)))
    let image: CGImage? = {
        guard size.width.isFinite, size.height.isFinite, size.width <= 4096, size.height <= 256,
              let context = CGContext(data: nil, width: Int(size.width * 3), height: Int(size.height * 3),
                                      bitsPerComponent: 8, bytesPerRow: 0, space: CGColorSpaceCreateDeviceRGB(),
                                      bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue) else { return nil }
        context.scaleBy(x: 3, y: 3)
        context.textPosition = CGPoint(x: 0, y: -font.descender)
        CTLineDraw(line, context)
        return context.makeImage()
    }()
    return MurmurPixelWord(text: text, font: font, line: line, size: size, image: image)
}

private func murmurKeepsActivityProgress(previous: String?, next: String) -> Bool {
    let activity = ["작업 중", "도구 실행 중"]
    return previous != next && previous.map { activity.contains($0) } == true && activity.contains(next)
}

private struct MurmurApprovalText: View {
    let text: String
    var continuousActivity = false
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @State private var started = ProcessInfo.processInfo.systemUptime
    @State private var settled = false
    @State private var cachedWord: MurmurPixelWord?

    // Each tuple is a column, row and accent flag from the reference's twelve mosaic shapes.
    private static let shapes: [[(Int, Int, Bool)]] = [
        [(0,1,true),(0,2,true),(0,3,true),(1,2,false),(2,2,false),(3,2,false),(4,2,false),(4,1,false)],
        [(0,2,false),(0,3,false),(1,2,false),(1,3,false)],
        [(0,2,false),(0,3,false),(3,2,false),(2,4,true)],
        [(0,1,false),(0,2,false),(0,3,false)], [(0,3,false)],
        [(0,2,false),(0,3,false),(4,2,false)], [(1,2,false),(0,3,false),(2,3,false)],
        [(1,1,false),(2,1,false),(0,2,false),(0,3,true),(3,2,false),(3,3,false)],
        [(1,1,false),(0,2,false),(0,3,false),(3,2,false),(2,3,false)],
        [(2,1,false),(0,2,false),(0,3,false),(3,2,false),(3,3,false)],
        [(0,2,false),(0,3,false)], [(2,0,false),(3,0,false),(3,2,true),(3,3,true)]
    ]

    var body: some View {
        TimelineView(.animation(minimumInterval: 1.0 / 30.0, paused: reduceMotion || settled)) { _ in
            let elapsed = max(0, ProcessInfo.processInfo.systemUptime - started)
            Canvas { context, size in
                guard !text.isEmpty, size.width > 0, size.height > 0 else { return }
                var frame: [Int32] = [23, -1, 0]
                let characters = Int32(clamping: text.count), still = reduceMotion || settled ? Int32(1) : Int32(0)
                _ = frame.withUnsafeMutableBufferPointer { rustMurmurPixelFrame(elapsed, characters, still, $0.baseAddress) }
                let rawZoom = rustMurmurPixelScale(elapsed, characters, still)
                let zoom = CGFloat(rawZoom.isFinite ? rawZoom : 1)
                let count = text.count
                let visible = murmurVisibleCharacterCount(referenceCount: frame[0], textCount: count)
                let word = cachedWord.flatMap { $0.text == text ? $0 : nil } ?? murmurPixelWord(text)
                let font = word.font, fullWidth = word.size.width
                let prefixWidth = visible >= count ? fullWidth : murmurPrefixAdvance(text, line: word.line, visible: visible)
                let scale = min(1, size.width / max(1, fullWidth))
                let height = word.size.height
                let x = max(0, size.width - fullWidth * scale)
                let y = max(0, (size.height - height * scale) / 2)
                var ink = context
                ink.translateBy(x: x, y: y); ink.scaleBy(x: scale, y: scale)
                if visible > 0 {
                    var letters = context
                    letters.translateBy(x: x + (1 - zoom) * fullWidth * scale / 2,
                                        y: y + (1 - zoom) * height * scale / 2)
                    letters.scaleBy(x: scale * zoom, y: scale * zoom)
                    letters.clip(to: Path(CGRect(x: 0, y: -2, width: prefixWidth + 1, height: height + 4)))
                    if let image = word.image {
                        letters.draw(Image(decorative: image, scale: 3), in: CGRect(origin: .zero, size: word.size))
                    } else {
                        letters.draw(Text(text).font(.custom(font.fontName, fixedSize: 14)).foregroundColor(.white),
                                     at: .zero, anchor: .topLeading)
                    }
                }
                let shape = Int(frame[1])
                if Self.shapes.indices.contains(shape) {
                    // shortcut: Korean glyph alignment and compositing need reference-frame comparison.
                    let cellWidth: CGFloat = 14 * 0.129, cellHeight: CGFloat = 14 * 0.229
                    let sourceOrigin = CGFloat(frame[2]) - (409 - (zoom - 1) * 1425 / 2)
                    let mappedOrigin = sourceOrigin / 1425 * fullWidth + (1 - zoom) * fullWidth / 2
                    let origin = (mappedOrigin / cellWidth).rounded() * cellWidth
                    let mosaicY = height - 14 * 1.2
                    var primary = Path(), accent = Path()
                    for (column, row, isAccent) in Self.shapes[shape] {
                        let rect = CGRect(x: origin + CGFloat(column) * cellWidth, y: mosaicY + CGFloat(row) * cellHeight,
                                          width: cellWidth, height: cellHeight)
                        if isAccent { accent.addRect(rect) } else { primary.addRect(rect) }
                    }
                    let middle = Color(red: 1, green: 0.25, blue: 0.025)
                    var nearGlow = ink; nearGlow.opacity = 0.3
                    nearGlow.stroke(primary, with: .color(middle), style: StrokeStyle(lineWidth: 14 * 0.32, lineCap: .round, lineJoin: .round))
                    var farGlow = ink; farGlow.opacity = 0.1
                    farGlow.stroke(primary, with: .color(middle), style: StrokeStyle(lineWidth: 14 * 0.72, lineCap: .round, lineJoin: .round))
                    let gradient = Gradient(stops: [
                        .init(color: Color(red: 1, green: 0.015, blue: 0.055), location: 0),
                        .init(color: middle, location: 0.35),
                        .init(color: Color(red: 1, green: 0.73, blue: 0.015), location: 1)
                    ])
                    let shade = GraphicsContext.Shading.linearGradient(gradient,
                        startPoint: CGPoint(x: 0, y: mosaicY), endPoint: CGPoint(x: 0, y: mosaicY + 14 * 0.916))
                    ink.fill(primary, with: shade)
                    var accents = ink; accents.opacity = 0.22
                    accents.fill(accent, with: shade)
                }
            }.frame(height: 17).accessibilityLabel(text)
        }
        .task(id: text) {
            let now = ProcessInfo.processInfo.systemUptime
            let keepProgress = continuousActivity && murmurKeepsActivityProgress(previous: cachedWord?.text, next: text)
            cachedWord = murmurPixelWord(text)
            if !keepProgress { started = now; settled = reduceMotion }
            guard !settled else { return }
            let duration = rustMurmurPixelDuration(Int32(clamping: text.count))
            let total = duration.isFinite ? max(0, duration) + 0.04 : 1.6
            let delay = max(0, total - max(0, now - started))
            do { try await Task.sleep(nanoseconds: UInt64(delay * 1_000_000_000)) } catch { return }
            guard !Task.isCancelled else { return }
            settled = true
        }
        .onChange(of: reduceMotion) { _, reduced in
            if reduced { settled = true }
        }
    }
}

private func assistantCloudMoment(indicator: AssistantIndicator, toolRunning: Bool, listening: Bool = false, speaking: Bool = false) -> Int32 {
    if listening || speaking { return 0 }
    switch indicator {
    case .off: return 4
    case .working: return toolRunning ? 2 : 1
    case .approval, .question: return 3
    }
}

// shortcut: OrganicAudioCloud's particles and the original palette require further recovery.
private enum LiveCloudField {
    struct Speck {
        let column: Int
        let x: Double
        let y: Double
        let density: Double
        let variation: Double
    }
    static let field: [Speck] = {
        var result: [Speck] = []
        for row in 0..<19 {
            for column in 0..<47 {
                var values = [Double](repeating: 0, count: 4)
                let status = values.withUnsafeMutableBufferPointer {
                    rustAssistantCloudSpeck(Int32(column), Int32(row), $0.baseAddress)
                }
                if status == 1 {
                    result.append(Speck(column: column, x: values[0], y: values[1], density: values[2], variation: values[3]))
                }
            }
        }
        return result
    }()
}

func dictationWritingCloudSample(age: TimeInterval, writingAge: TimeInterval, initialLevel: Double, reduceMotion: Bool) -> [Double]? {
    var sample = [Double](repeating: 0, count: 4)
    guard sample.withUnsafeMutableBufferPointer({ rustDictationWritingCloudSample(age, writingAge, initialLevel, reduceMotion ? 0 : 1, $0.baseAddress) }) == 0 else { return nil }
    return sample
}

private func drawLiveCloud(context: inout GraphicsContext, size: CGSize, particleTime: TimeInterval,
                           level: Double, completion: Double, listening: Bool, approval: Bool,
                           reduceMotion: Bool, appearance: Double, organicSample: [Double]? = nil) {
    var palette = [Double](repeating: 1, count: 41 * 3)
    let paletteStatus = palette.withUnsafeMutableBufferPointer {
        rustAssistantCloudPalette(particleTime, approval ? 1 : 0,
                                  reduceMotion ? 1 : 0, 0, $0.baseAddress)
    }
    let columns: [[Double]] = (0..<47).map { index in
        var values = [Double](repeating: 0, count: 4)
        let result = values.withUnsafeMutableBufferPointer {
            rustAssistantCloudColumn(Int32(index), particleTime, reduceMotion ? 1 : 0, $0.baseAddress)
        }
        return result == 0 ? values : [0, 0, 0, 0]
    }
    var paths: [UInt32: Path] = [:]
    var frame = [Double](repeating: 0, count: 5)
    for particle in LiveCloudField.field {
        let values = columns[particle.column]
        let result = values.withUnsafeBufferPointer { column in
            frame.withUnsafeMutableBufferPointer { output in
                if let sample = organicSample, sample.count == 4 {
                    return sample.withUnsafeBufferPointer {
                        rustAssistantCloudParticle(particle.x, particle.y, particle.density, particle.variation,
                            particleTime, Double(size.width), Double(size.height), column.baseAddress, $0.baseAddress, output.baseAddress)
                    }
                }
                return rustAssistantLiveParticle(particle.x, particle.y, particle.density, particle.variation,
                    particleTime, Double(size.width), Double(size.height), column.baseAddress,
                    level, completion, listening ? 1 : 0, reduceMotion ? 0 : 1, output.baseAddress)
            }
        }
        guard result == 0 else { continue }
        let paletteIndex = particle.column * 40 / 46 * 3
        let red = paletteStatus == 0 ? palette[paletteIndex] : 1
        let green = paletteStatus == 0 ? palette[paletteIndex + 1] : 1
        let blue = paletteStatus == 0 ? palette[paletteIndex + 2] : 1
        let whiten = frame[4]
        let bucket = rustAssistantCloudColorBucket(red + (1 - red) * whiten,
            green + (0.97 - green) * whiten, blue + (0.96 - blue) * whiten, frame[3] * appearance)
        guard bucket >= 0 else { continue }
        let rect = CGRect(x: frame[0], y: frame[1], width: frame[2], height: frame[2])
        paths[UInt32(bucket), default: Path()].addRect(rect)
    }
    for (bucket, path) in paths {
        let tint = Color(red: Double((bucket >> 15) & 31) / 31,
                         green: Double((bucket >> 10) & 31) / 31,
                         blue: Double((bucket >> 5) & 31) / 31)
        context.fill(path, with: .color(tint.opacity(Double(bucket & 31) / 16)))
    }
}

private struct AssistantNotchPreview: View {
    @ObservedObject var model: Model
    let label: String
    let flightNamespace: Namespace.ID?
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @State private var started = ProcessInfo.processInfo.systemUptime
    @State private var momentStarted = ProcessInfo.processInfo.systemUptime

    var body: some View {
        Button { model.select(.assistant); model.expanded = true } label: {
            GeometryReader { geometry in
                let metrics = agentPeekBandMetrics(width: geometry.size.width, cameraWidth: model.cameraExclusion,
                                                   floating: model.floatingIslandPlacement != nil)
                let side = metrics.side
                HStack(spacing: 0) {
                    MurmurApprovalText(text: label, continuousActivity: true).frame(width: min(116, side), alignment: .trailing)
                        .frame(width: side, height: 33, alignment: .trailing).clipped()
                    Color.clear.frame(width: metrics.gap).allowsHitTesting(false).accessibilityHidden(true)
                    HStack(spacing: 3) {
                      if side > 0 {
                        CollapsedAgentFace(waiting: agentNeedsAttention(label), state: label,
                                           agentID: model.assistantAnimationID, size: min(notchStatusCharacterSize, side))
                            .modifier(AgentFlightGeometry(namespace: flightNamespace,
                                      session: AgentSessionKey(source: "", id: model.assistantAnimationID), enabled: true))
                      }
                      if side > 33 {
                       TimelineView(.animation(minimumInterval: 1.0 / 30.0, paused: reduceMotion)) { _ in
                        let now = ProcessInfo.processInfo.systemUptime
                        Canvas { context, size in
                            let clock = max(0, now - started)
                            let exitAge = model.assistantSpeaking ? -1 : (model.assistantFinishStarted.map { max(0, now - $0) } ?? -1)
                            var envelope = [Double](repeating: 0, count: 4)
                            let envelopeStatus = envelope.withUnsafeMutableBufferPointer {
                                rustAssistantCloudEnvelope(clock, exitAge, reduceMotion ? 0 : 1, $0.baseAddress)
                            }
                            guard envelopeStatus == 0 else { return }
                            let appearance = min(1, max(0, envelope[0] * (1 - envelope[1]) + 0.18 * envelope[2]))
                            let particleTime = reduceMotion ? 0.6 : max(0, now - momentStarted)
                            let moment = assistantCloudMoment(indicator: model.assistantIndicator, toolRunning: model.assistantToolRunning, listening: model.assistantListening, speaking: model.assistantSpeaking)
                            let voiceLevel = model.assistantListening ? model.dictationLevel :
                                (model.assistantSpeaking ? (reduceMotion ? 0.3 : rustAssistantSpeechPulse(max(0, now - model.assistantSpeechWordAt))) : 0)
                            let level = rustAssistantLiveLevel(moment, particleTime, voiceLevel)
                            guard level.isFinite else { return }
                            let donePhase = exitAge >= 0 ? (reduceMotion ? 1 : min(1, exitAge / 0.45)) : 0
                            let completion = donePhase * donePhase * (3 - 2 * donePhase)
                            drawLiveCloud(context: &context, size: size, particleTime: particleTime,
                                          level: level, completion: completion, listening: moment == 0,
                                          approval: model.assistantIndicator == .approval,
                                          reduceMotion: reduceMotion, appearance: appearance)
                        }.frame(width: min(38, side - 33), height: 24).accessibilityHidden(true)
                       }
                      }
                    }
                    .frame(width: min(116, side), height: 33, alignment: .leading)
                    .frame(width: side, alignment: .leading).clipped()
                }
            }.frame(height: 33)
        }.buttonStyle(.plain).accessibilityLabel("AI 대화 \(label)").help("AI 대화 열기")
        .onChange(of: assistantCloudMoment(indicator: model.assistantIndicator, toolRunning: model.assistantToolRunning, listening: model.assistantListening, speaking: model.assistantSpeaking)) { _, _ in
            momentStarted = ProcessInfo.processInfo.systemUptime
        }
    }
}

private struct CollapsedPermissionPreview: View {
    @ObservedObject var model: Model
    @ObservedObject var voice: VoiceApprovalController
    let item: AgentActivity
    let flightNamespace: Namespace.ID?
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @State private var orbStarted = ProcessInfo.processInfo.systemUptime
    @State private var symbolProgress: CGFloat = 0
    @State private var entranceVisible = false
    @State private var target: CollapsedPermissionTarget?
    @State private var fetching = false
    @State private var visible = false
    @State private var generation = 0
    @State private var attempted: Set<String> = []
    @State private var sending = false
    @State private var responseStatus = ""
    @AppStorage("rium.voice.enabled") private var voiceEnabled = false
    @AppStorage("rium.voice.allowWords") private var allow = "네, 응, 허용, 좋아, ok, go, valide, approuve, accepte, oui, yes"
    @AppStorage("rium.voice.denyWords") private var deny = "아니요, 아니, 거절, 취소, stop, non, refuse, annule, no, skip"
    @AppStorage("rium.voice.openWords") private var open = "열어, 열기, ouvre, open, montre, affiche, app"
    private let timer = Timer.publish(every: 1, on: .main, in: .common).autoconnect()
    init(model: Model, voice: VoiceApprovalController, item: AgentActivity, flightNamespace: Namespace.ID? = nil) {
        self.model = model; self.voice = voice; self.item = item; self.flightNamespace = flightNamespace
    }
    private var isClaude: Bool { item.source == "claude" }
    private var session: String { isClaude ? String(item.id.dropFirst("claude-".count)) : item.id }
    private var owner: String { permissionPeekVoiceOwner(item) }

    var body: some View {
        Button {
            model.select(.agents); model.expanded = true
        } label: {
            GeometryReader { geometry in
                let metrics = agentPeekBandMetrics(width: geometry.size.width, cameraWidth: model.cameraExclusion,
                                                   floating: model.floatingIslandPlacement != nil)
                let character = true
                HStack(spacing: 0) {
                    Group {
                        if character {
                            CollapsedAgentFace(waiting: true, source: item.source, state: item.state,
                                               agentID: item.id, size: 30)
                                .modifier(AgentFlightGeometry(namespace: flightNamespace, session: item.sessionKey, enabled: true))
                        } else {
                            TimelineView(.animation(minimumInterval: 1.0 / 30.0, paused: reduceMotion)) { _ in
                                ZStack {
                                    AgentOrbPreview(time: max(0, ProcessInfo.processInfo.systemUptime - orbStarted),
                                                    reduceMotion: reduceMotion, style: .permission)
                                    let light = AgentOrbStyle.permission.colors[2]
                                    Image(systemName: "exclamationmark").font(.system(size: 12, weight: .bold))
                                        .foregroundStyle(light).shadow(color: light.opacity(0.82), radius: 2)
                                        .scaleEffect(0.72 + 0.28 * symbolProgress).opacity(symbolProgress)
                                }
                            }.frame(width: 30, height: 30).accessibilityHidden(true)
                        }
                    }
                    // The reference permission avatar uses a 0.32-second entrance with no delay.
                    .scaleEffect(CGFloat(rustAgentPeekEntranceScale(entranceVisible ? 1 : 0, reduceMotion ? 1 : 0)))
                    .opacity(entranceVisible ? 1 : 0)
                    .frame(width: min(metrics.side, 34), height: 34, alignment: .leading)
                    .frame(width: metrics.side, height: 33, alignment: .leading)
                    Color.clear.frame(width: metrics.gap).allowsHitTesting(false).accessibilityHidden(true)
                    HStack(spacing: 4) {
                        if voice.active && voice.owner == owner {
                            HStack(alignment: .center, spacing: 2) {
                                ForEach(0..<5) { index in
                                    let pattern = [0.55, 0.8, 1.0, 0.75, 0.5][index]
                                    Capsule().fill(Color.white.opacity(0.8))
                                        .frame(width: 2, height: 3 + CGFloat(voice.inputLevel * pattern) * 13)
                                }
                            }.frame(width: 18, height: 18).accessibilityHidden(true)
                        }
                        VStack(alignment: .trailing, spacing: 1) {
                            MurmurApprovalText(text: voice.active && voice.owner == owner ? "듣는 중" : (responseStatus.isEmpty ? "승인 필요" : responseStatus))
                            if let summary = target?.summary, !FeedbackSound.quietForPrivacy {
                                Text(summary).font(.system(size: 8)).foregroundStyle(.secondary).lineLimit(1)
                            }
                        }
                    }
                    .frame(width: min(metrics.side, 72), height: 33, alignment: .trailing)
                    .frame(width: metrics.side, height: 33, alignment: .trailing).clipped()
                }
            }.frame(height: 33).contentShape(Rectangle())
        }.buttonStyle(.plain).accessibilityLabel("\(item.providerName) 승인 요청 열기")
            .accessibilityValue(FeedbackSound.quietForPrivacy ? "요청 내용 숨김" : (target?.summary ?? "요청 내용을 확인하세요"))
            .onAppear {
                visible = true; orbStarted = ProcessInfo.processInfo.systemUptime
                entranceVisible = false
                symbolProgress = 0
                if reduceMotion {
                    symbolProgress = 1
                    withAnimation(.easeOut(duration: 0.12)) { entranceVisible = true }
                }
                else {
                    withAnimation(.easeOut(duration: 0.42).delay(0.1)) { symbolProgress = 1 }
                    withAnimation(.timingCurve(0.16, 1, 0.3, 1, duration: 0.32)) { entranceVisible = true }
                }
                refresh()
            }
            .onDisappear {
                visible = false; generation += 1; fetching = false; target = nil; voice.cancel(owner: owner)
            }
            .onReceive(timer) { _ in synchronizeVoice(); refresh() }
            .onChange(of: voice.active) { _, _ in synchronizeVoice() }
            .onChange(of: reduceMotion) { _, reduced in
                if reduced { entranceVisible = true; symbolProgress = 1 }
            }
            .onChange(of: voiceEnabled) { _, _ in synchronizeVoice() }
            .onChange(of: model.dictationDisplayActive) { _, _ in synchronizeVoice() }
            .onChange(of: allow) { _, _ in voice.cancel(owner: owner) }
            .onChange(of: deny) { _, _ in voice.cancel(owner: owner) }
            .onChange(of: open) { _, _ in voice.cancel(owner: owner) }
    }

    private func summary(_ value: [String: Any]) -> String {
        let name = value["tool_name"] as? String ?? value["kind"] as? String ?? "승인 요청"
        let input = value["tool_input"] as? [String: Any] ?? value["details"] as? [String: Any] ?? [:]
        let detail = ["command", "path", "file_path", "title", "reason"].compactMap { input[$0] as? String }.first ?? ""
        let clean: (String) -> String = { text in String(text.unicodeScalars.filter { !CharacterSet.controlCharacters.contains($0) }.prefix(220)) }
        return detail.isEmpty ? clean(name) : "\(clean(name)) · \(clean(detail))"
    }

    private func refresh() {
        guard visible, !fetching, !sending, !model.expanded,
              (!isClaude || item.id.hasPrefix("claude-")),
              let input = try? JSONSerialization.data(withJSONObject: ["sessionId": session]) else { return }
        fetching = true; generation += 1
        let expected = generation
        model.run([isClaude ? "claude-approval-list-strict" : "codex-approval-list-strict"], input: input, timeout: 8) { event in
            guard let kind = event["event"] as? String, kind == "result" || kind == "error",
                  visible, generation == expected else { return }
            guard kind == "result", let data = event["data"] as? [String: Any],
                  let hook = data["approvals"] as? [[String: Any]] else { fetching = false; setTarget(nil); return }
            if isClaude { apply(hook: hook, desktop: [], expected: expected); return }
            model.run(["desktop-native-list-strict"], input: input, timeout: 8) { event in
                guard let kind = event["event"] as? String, kind == "result" || kind == "error",
                      visible, generation == expected else { return }
                guard kind == "result", let data = event["data"] as? [String: Any],
                      let desktop = data["requests"] as? [[String: Any]] else { fetching = false; setTarget(nil); return }
                apply(hook: hook, desktop: desktop, expected: expected)
            }
        }
    }

    private func apply(hook: [[String: Any]], desktop: [[String: Any]], expected: Int) {
        guard visible, generation == expected else { return }
        fetching = false
        guard hook.count + desktop.count == 1 else { setTarget(nil); return }
        if let row = hook.first, let token = row["token"] as? String, let request = row["request"] as? [String: Any],
           request["tool_name"] as? String != "AskUserQuestion" {
            setTarget(CollapsedPermissionTarget(identifier: token, summary: summary(request), payload: row, channel: isClaude ? "claude" : "codex"))
        } else if let row = desktop.first, let shown = row["shown"] as? [String: Any],
                  let token = shown["token"] as? String, shown["kind"] as? String != "question" {
            setTarget(CollapsedPermissionTarget(identifier: token, summary: summary(shown), payload: row, channel: "desktop"))
        } else { setTarget(nil) }
    }

    private func setTarget(_ next: CollapsedPermissionTarget?) {
        if target?.fingerprint != next?.fingerprint { voice.cancel(owner: owner) }
        target = next
        synchronizeVoice()
    }

    private func synchronizeVoice() {
        guard visible, voiceEnabled, !model.expanded, !model.dictationDisplayActive, !model.interview.active,
              !FeedbackSound.quietForPrivacy, VoiceApprovalController.hasAuthorization, !sending, let current = target,
              let fingerprint = current.fingerprint else { voice.cancel(owner: owner); return }
        guard !voice.active, !attempted.contains(fingerprint) else { return }
        attempted.insert(fingerprint)
        let language = model.dictation.languageID, allowedWords = allow, deniedWords = deny, openWords = open
        model.stopAssistantSpeech()
        voice.begin(owner: owner, language: language, allow: allowedWords, deny: deniedWords, open: openWords, automatic: true) { answer in
            guard visible, voiceEnabled, VoiceApprovalController.hasAuthorization, !model.expanded,
                  !model.dictationDisplayActive, !model.interview.active, !FeedbackSound.quietForPrivacy,
                  model.dictation.languageID == language, allow == allowedWords, deny == deniedWords, open == openWords,
                  target?.fingerprint == fingerprint, let answer = answer else { return }
            switch answer {
            case .open:
                if isClaude { model.select(.agents); model.expanded = true }
                else { model.openCodexThread(item) }
            case .allow, .deny:
                let decision = answer == .allow ? "allow" : "deny"
                guard let input = try? JSONSerialization.data(withJSONObject: ["sessionId": session, "channel": current.channel,
                                                                                "shown": current.payload, "decision": decision]) else { return }
                sending = true; responseStatus = "응답 전달 중…"
                model.run(["voice-approval-submit"], input: input) { event in
                    guard let kind = event["event"] as? String, kind == "result" || kind == "error" else { return }
                    sending = false
                    let state = (event["data"] as? [String: Any])?["status"] as? String
                    responseStatus = state == "claimed" || state == "submitted" ? "응답 요청됨" : "앱에서 요청 확인 필요"
                    model.refreshAgents()
                }
            }
        }
    }
}

func hookApprovalRows(_ event: [String: Any]) -> [[String: Any]]? {
    guard event["event"] as? String == "result", let data = event["data"] as? [String: Any],
          let rows = data["approvals"] as? [[String: Any]] else { return nil }
    return rows
}

private struct AgentHookApprovalPanel: View {
    @ObservedObject var model: Model
    let item: AgentActivity
    @Binding var hasLiveQuestion: Bool
    @State private var approvals: [ClaudeApproval] = []
    @State private var fetching = false
    @State private var lookupFailed = false
    @State private var visible = false
    @State private var generation = 0
    @State private var sending: Set<String> = []
    @State private var finished: Set<String> = []
    @State private var expanded: Set<String> = []
    @State private var status = ""
    private let timer = Timer.publish(every: 2, on: .main, in: .common).autoconnect()
    private var isClaude: Bool { item.source == "claude" }
    private var session: String { isClaude ? String(item.id.dropFirst("claude-".count)) : item.id }

    var body: some View {
        VStack(alignment: .leading, spacing: 8) {
            ForEach(approvals) { approval in
                VStack(alignment: .leading, spacing: 7) {
                    Text(approval.isQuestion && isClaude ? "Claude 질문" : "\(item.providerName) 승인 요청").font(.system(size: 12, weight: .semibold))
                    if FeedbackSound.quietForPrivacy {
                        Text("화면 공유 또는 다른 앱의 마이크·카메라 사용이 감지되어 요청 내용을 숨겼습니다.")
                            .font(.caption).foregroundStyle(.secondary)
                    } else if approval.isQuestion && isClaude {
                        if let questions = ClaudeQuestion.parse(approval.request) {
                            ClaudeQuestionForm(questions: questions, disabled: sending.contains(approval.id) || finished.contains(approval.id)) { answers in
                                answer(approval, answers: answers)
                            }.id(approval.id)
                        } else { Text("Claude에서 직접 답변해 주세요.").font(.caption).foregroundStyle(.secondary) }
                    } else {
                        DisclosureGroup(isExpanded: Binding(get: { expanded.contains(approval.id) }, set: { value in
                            if value { expanded.insert(approval.id) } else { expanded.remove(approval.id) }
                        })) {
                            ScrollView([.horizontal, .vertical]) {
                                Text(approval.display).font(.system(size: 11, design: .monospaced))
                                    .textSelection(.enabled).frame(maxWidth: .infinity, alignment: .leading)
                            }.frame(maxHeight: 200).padding(6).background(.black.opacity(0.25), in: RoundedRectangle(cornerRadius: 6))
                        } label: { Text("요청 전체 내용 확인").font(.caption.weight(.medium)) }
                        HStack {
                            Button("거절") { decide(approval, decision: "deny") }
                            Button("허용") { decide(approval, decision: "allow") }
                        }.buttonStyle(.bordered)
                            .disabled(!expanded.contains(approval.id) || sending.contains(approval.id) || finished.contains(approval.id))
                    }
                    Button("\(item.providerName)에서 처리") { release(approval) }.buttonStyle(.plain).font(.caption)
                        .foregroundStyle(.secondary).disabled(sending.contains(approval.id) || finished.contains(approval.id))
                }.padding(9).frame(maxWidth: .infinity, alignment: .leading)
                    .background(.white.opacity(0.06), in: RoundedRectangle(cornerRadius: 10))
            }
            if lookupFailed { Text("연결 상태를 확인하지 못해 요청을 숨겼습니다. \(item.providerName)에서 확인해 주세요.").font(.caption).foregroundStyle(.secondary) }
            if !status.isEmpty { Text(status).font(.caption).foregroundStyle(.secondary).fixedSize(horizontal: false, vertical: true) }
        }
        .onAppear { visible = true; refresh() }
        .onReceive(timer) { _ in refresh() }
        .onDisappear { visible = false; generation += 1; fetching = false; approvals.removeAll(); lookupFailed = false; hasLiveQuestion = false }
    }

    private func refresh() {
        guard visible, (!isClaude || item.id.hasPrefix("claude-")), !fetching,
              agentNeedsAttention(item.state) || !approvals.isEmpty || lookupFailed,
              let input = try? JSONSerialization.data(withJSONObject: ["sessionId": session]) else { return }
        fetching = true; generation += 1
        let expected = generation
        model.run([isClaude ? "claude-approval-list-strict" : "codex-approval-list-strict"], input: input, timeout: 8) { event in
            guard let kind = event["event"] as? String, kind == "result" || kind == "error",
                  visible, generation == expected else { return }
            fetching = false
            guard let rows = hookApprovalRows(event) else {
                approvals.removeAll(); lookupFailed = true; hasLiveQuestion = isClaude; return
            }
            lookupFailed = false
            approvals = rows.compactMap { row in
                guard let token = row["token"] as? String, !finished.contains(token),
                      let request = row["request"] as? [String: Any], JSONSerialization.isValidJSONObject(request),
                      let data = try? JSONSerialization.data(withJSONObject: request, options: [.prettyPrinted, .sortedKeys, .withoutEscapingSlashes]),
                      let text = String(data: data, encoding: .utf8) else { return nil }
                return ClaudeApproval(id: token, request: request, display: text)
            }
            hasLiveQuestion = visible && isClaude && (lookupFailed || approvals.contains { $0.isQuestion })
        }
    }

    private func decide(_ approval: ClaudeApproval, decision: String) {
        guard expanded.contains(approval.id), !sending.contains(approval.id), !finished.contains(approval.id),
              let input = try? JSONSerialization.data(withJSONObject: ["sessionId": session, "token": approval.id,
                  "request": approval.request, "decision": decision]) else { return }
        model.holdExpandedNotchAfterAgentAction()
        sending.insert(approval.id); status = "\(item.providerName)에 응답 전달 중…"
        model.run([isClaude ? "claude-approval-decide" : "codex-approval-decide"], input: input) { event in
            guard let kind = event["event"] as? String, kind == "result" || kind == "error" else { return }
            sending.remove(approval.id); finished.insert(approval.id)
            approvals.removeAll { $0.id == approval.id }
            hasLiveQuestion = visible && isClaude && (lookupFailed || approvals.contains { $0.isQuestion })
            if (event["data"] as? [String: Any])?["status"] as? String == "claimed" {
                status = "응답을 요청했습니다. \(item.providerName)에서 처리 결과를 확인해 주세요."
            } else {
                status = "전달 여부를 확인할 수 없습니다. \(item.providerName)에서 직접 확인해 주세요."
            }
            model.refreshAgents()
        }
    }

    private func answer(_ approval: ClaudeApproval, answers: [[String]]) {
        guard approval.isQuestion, !sending.contains(approval.id), !finished.contains(approval.id),
              let input = try? JSONSerialization.data(withJSONObject: ["sessionId": session, "token": approval.id,
                  "request": approval.request, "answers": answers]) else { return }
        model.holdExpandedNotchAfterAgentAction()
        sending.insert(approval.id); status = "Claude에 답변 전달 중…"
        model.run(["claude-question-answer"], input: input) { event in
            guard let kind = event["event"] as? String, kind == "result" || kind == "error" else { return }
            sending.remove(approval.id); finished.insert(approval.id)
            approvals.removeAll { $0.id == approval.id }
            hasLiveQuestion = visible && (lookupFailed || approvals.contains { $0.isQuestion })
            if (event["data"] as? [String: Any])?["status"] as? String == "claimed" {
                status = "답변을 요청했습니다. Claude에서 처리 결과를 확인해 주세요."
            } else { status = "전달 여부를 확인할 수 없습니다. Claude에서 직접 확인해 주세요." }
            model.refreshAgents()
        }
    }

    private func release(_ approval: ClaudeApproval) {
        guard !sending.contains(approval.id), !finished.contains(approval.id),
              let input = try? JSONSerialization.data(withJSONObject: ["sessionId": session, "token": approval.id,
                  "request": approval.request]) else { return }
        sending.insert(approval.id); status = "\(item.providerName)로 전환 중…"
        model.run([isClaude ? "claude-request-release" : "codex-request-release"], input: input) { event in
            guard let kind = event["event"] as? String, kind == "result" || kind == "error" else { return }
            sending.remove(approval.id); finished.insert(approval.id)
            approvals.removeAll { $0.id == approval.id }
            hasLiveQuestion = visible && isClaude && (lookupFailed || approvals.contains { $0.isQuestion })
            if (event["data"] as? [String: Any])?["status"] as? String == "claimed" {
                status = "노치 요청을 닫았습니다. \(item.providerName)에서 계속해 주세요."
            } else { status = "전환 여부를 확인할 수 없습니다. \(item.providerName)에서 직접 확인해 주세요." }
            model.refreshAgents()
        }
    }
}

private struct CodexDesktopRequest: Identifiable {
    let connection: String
    let workspace: String
    let shown: [String: Any]
    let display: String
    var token: String { shown["token"] as? String ?? "" }
    var id: String { connection + ":" + token }
    var isQuestion: Bool { shown["kind"] as? String == "question" }
    var canAllow: Bool { shown["canAllow"] as? Bool == true }
    var canDeny: Bool { shown["canDeny"] as? Bool == true }

    var questions: [ClaudeQuestion]? {
        guard isQuestion, let form = shown["questions"] as? [[String: Any]],
              let details = shown["details"] as? [String: Any],
              let original = details["questions"] as? [[String: Any]], form.count == original.count,
              (1...3).contains(form.count) else { return nil }
        var questions: [ClaudeQuestion] = []
        for (row, raw) in zip(form, original) {
            guard let id = row["id"] as? String, let rawID = raw["id"] as? String, id == rawID,
                  let title = row["question"] as? String, let rawTitle = raw["question"] as? String, title == rawTitle,
                  let labels = row["options"] as? [String] else { return nil }
            let rawOptions = raw["options"] as? [[String: Any]] ?? []
            let options = rawOptions.compactMap { entry -> ClaudeQuestionOption? in
                guard let label = entry["label"] as? String else { return nil }
                return ClaudeQuestionOption(label: label, detail: entry["description"] as? String ?? "")
            }
            guard options.map(\.label) == labels else { return nil }
            questions.append(ClaudeQuestion(title: title, header: raw["header"] as? String ?? "", options: options,
                                            multiple: false, allowsCustom: labels.isEmpty || row["isOther"] as? Bool == true))
        }
        return questions
    }
}

func desktopRequestRows(_ event: [String: Any]) -> [[String: Any]]? {
    guard event["event"] as? String == "result", let data = event["data"] as? [String: Any],
          data["status"] as? String == "ok", let rows = data["requests"] as? [[String: Any]] else { return nil }
    return rows
}

private struct CodexDesktopPanel: View {
    @ObservedObject var model: Model
    let item: AgentActivity
    @State private var requests: [CodexDesktopRequest] = []
    @State private var fetching = false
    @State private var lookupFailed = false
    @State private var sending: Set<String> = []
    @State private var finished: Set<String> = []
    @State private var expanded: Set<String> = []
    @State private var status = ""
    @State private var lastAttempt: TimeInterval = -Double.infinity
    private let timer = Timer.publish(every: 2, on: .main, in: .common).autoconnect()

    var body: some View {
        VStack(alignment: .leading, spacing: 8) {
            ForEach(requests) { request in
                VStack(alignment: .leading, spacing: 7) {
                    Text(request.isQuestion ? "Codex 질문" : "Codex 승인 요청").font(.system(size: 12, weight: .semibold))
                    if FeedbackSound.quietForPrivacy {
                        Text("화면 공유 또는 다른 앱의 마이크·카메라 사용이 감지되어 요청 내용을 숨겼습니다.")
                            .font(.caption).foregroundStyle(.secondary)
                    } else {
                        if request.isQuestion {
                            if let questions = request.questions {
                                ClaudeQuestionForm(questions: questions, disabled: sending.contains(request.id) || finished.contains(request.id)) { answers in
                                    respond(request, action: "question", answer: answers)
                                }.id(request.id)
                            } else { Text("Codex에서 직접 답변해 주세요.").font(.caption).foregroundStyle(.secondary) }
                        }
                        DisclosureGroup(isExpanded: Binding(get: { expanded.contains(request.id) }, set: { value in
                            if value { expanded.insert(request.id) } else { expanded.remove(request.id) }
                        })) {
                            ScrollView([.horizontal, .vertical]) {
                                Text(request.display).font(.system(size: 11, design: .monospaced))
                                    .textSelection(.enabled).frame(maxWidth: .infinity, alignment: .leading)
                            }.frame(maxHeight: 200).padding(6).background(.black.opacity(0.25), in: RoundedRectangle(cornerRadius: 6))
                        } label: { Text("요청 전체 내용 확인").font(.caption.weight(.medium)) }
                        if !request.isQuestion {
                            HStack {
                                Button("거절") { respond(request, action: "approval", answer: "deny") }.disabled(!request.canDeny)
                                Button("허용") { respond(request, action: "approval", answer: "allow") }.disabled(!request.canAllow)
                            }.buttonStyle(.bordered)
                                .disabled(!expanded.contains(request.id) || sending.contains(request.id) || finished.contains(request.id))
                        }
                    }
                }.padding(9).frame(maxWidth: .infinity, alignment: .leading)
                    .background(.white.opacity(0.06), in: RoundedRectangle(cornerRadius: 10))
            }
            if lookupFailed { Text("연결 상태를 확인하지 못해 요청을 숨겼습니다. Codex에서 확인해 주세요.").font(.caption).foregroundStyle(.secondary) }
            if !status.isEmpty { Text(status).font(.caption).foregroundStyle(.secondary).fixedSize(horizontal: false, vertical: true) }
        }
        .onAppear { refresh() }
        .onReceive(timer) { _ in refresh() }
    }

    private func refresh() {
        let active = agentNeedsAttention(item.state) || agentIsRunning(item.state) || !requests.isEmpty
        let now = ProcessInfo.processInfo.systemUptime
        guard !fetching, !["완료", "실패", "중단됨"].contains(item.state) || !requests.isEmpty || lookupFailed,
              now - lastAttempt >= (active ? 2 : 12),
              let input = try? JSONSerialization.data(withJSONObject: ["sessionId": item.id]) else { return }
        lastAttempt = now
        fetching = true
        model.run(["desktop-native-list-strict"], input: input, timeout: 8) { event in
            guard let kind = event["event"] as? String, kind == "result" || kind == "error" else { return }
            fetching = false
            guard let rows = desktopRequestRows(event) else {
                requests.removeAll(); lookupFailed = true; return
            }
            lookupFailed = false
            requests = rows.compactMap { row in
                guard let connection = row["connection"] as? String, let workspace = row["workspace"] as? String,
                      let shown = row["shown"] as? [String: Any], let token = shown["token"] as? String, !token.isEmpty,
                      !finished.contains(connection + ":" + token), JSONSerialization.isValidJSONObject(shown),
                      let bytes = try? JSONSerialization.data(withJSONObject: shown, options: [.prettyPrinted, .sortedKeys, .withoutEscapingSlashes]),
                      let text = String(data: bytes, encoding: .utf8) else { return nil }
                return CodexDesktopRequest(connection: connection, workspace: workspace, shown: shown, display: text)
            }
        }
    }

    private func respond(_ request: CodexDesktopRequest, action: String, answer: Any) {
        guard !sending.contains(request.id), !finished.contains(request.id),
              request.isQuestion || expanded.contains(request.id),
              let input = try? JSONSerialization.data(withJSONObject: ["sessionId": item.id, "connection": request.connection,
                  "workspace": request.workspace, "shown": request.shown, "action": action, "answer": answer]) else { return }
        model.holdExpandedNotchAfterAgentAction()
        sending.insert(request.id); status = "Codex에 응답 전달 중…"
        model.run(["desktop-native-answer"], input: input) { event in
            guard let kind = event["event"] as? String, kind == "result" || kind == "error" else { return }
            sending.remove(request.id); finished.insert(request.id)
            requests.removeAll { $0.id == request.id }
            if (event["data"] as? [String: Any])?["status"] as? String == "submitted" {
                status = "응답을 요청했습니다. Codex에서 처리 결과를 확인해 주세요."
            } else { status = "요청이 끝났거나 전달 여부를 확인할 수 없습니다. Codex에서 확인해 주세요." }
            model.refreshAgents()
        }
    }
}

private struct AgentStatusSweep: View {
    let text: String
    let tint: Color
    var baseTint: Color? = nil
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    var body: some View {
        TimelineView(.animation(minimumInterval: 1.0 / 30.0, paused: reduceMotion)) { timeline in
            let fraction = rustAgentStatusSweep(timeline.date.timeIntervalSinceReferenceDate, reduceMotion ? 1 : 0)
            Text(text).font(.system(size: 11, weight: .medium))
                .foregroundStyle(baseTint ?? .secondary)
                .overlay {
                    Text(text).font(.system(size: 11, weight: .medium)).foregroundStyle(tint)
                        .mask {
                            GeometryReader { geometry in
                                // shortcut: tint and compositing await reference-frame comparison.
                                Rectangle().fill(.white)
                                    .frame(width: 12, height: geometry.size.height * 2.4)
                                    .rotationEffect(.degrees(-24)).blur(radius: 2.5)
                                    .offset(x: (geometry.size.width + 18) * CGFloat(fraction.isFinite ? fraction : 0.46))
                            }
                        }.accessibilityHidden(true)
                }
        }
    }
}

private struct AgentKeyboardSwitcherView: View {
    @ObservedObject var model: Model

    var body: some View {
        VStack(alignment: .leading, spacing: 8) {
            HStack {
                Text("작업 전환").font(.headline)
                Spacer()
                Button("닫기") { (NSApp.delegate as? AppDelegate)?.closeAgentSwitcher() }
                    .buttonStyle(.plain)
