                                .buttonStyle(.plain)
                                .accessibilityAddTraits(model.agentSwitcherSelection == item.sessionKey ? .isSelected : [])
                                .id(item.sessionKey)
                            }
                        }
                    }
                    .onChange(of: model.agentSwitcherSelection) { _, selection in
                        if let selection { proxy.scrollTo(selection) }
                    }
                }
            }
            Text(model.agentSwitcherNotice.isEmpty
                 ? "위·아래 방향키로 선택하고 Return 키로 엽니다. Esc 키로 닫습니다."
                 : model.agentSwitcherNotice)
                .font(.caption).foregroundStyle(.secondary)
        }
        .font(.system(size: 12))
        .padding(.bottom, 6)
    }
}

struct AgentView: View {
    @ObservedObject var model: Model
    var flightNamespace: Namespace.ID? = nil
    @State private var drafts: [AgentSessionKey: String] = [:]
    @State private var sending: Set<AgentSessionKey> = []
    @State private var uncertain: Set<AgentSessionKey> = []
    @State private var messages: [AgentSessionKey: String] = [:]
    @State private var questionDrafts: [AgentQuestionKey: String] = [:]
    @State private var answering: Set<AgentQuestionKey> = []
    @State private var answeredOrUncertain: Set<AgentQuestionKey> = []
    @State private var questionMessages: [AgentQuestionKey: String] = [:]
    @State private var stopping: Set<AgentSessionKey> = []
    @State private var stopAccepted: Set<AgentSessionKey> = []
    @State private var stopUncertain: Set<AgentSessionKey> = []
    @State private var stopMessages: [AgentSessionKey: String] = [:]
    @State private var liveClaudeQuestions: Set<AgentSessionKey> = []
    private var riumSession: AgentSessionKey? { model.homeRiumSession }
    var body: some View {
        ScrollView {
            LazyVStack(alignment: .leading, spacing: 8) {
                if model.assistantIndicator != .off || model.assistantFinishing {
                    Button { model.select(.assistant) } label: {
                        HStack(spacing: 7) {
                            if riumSession == AgentSessionKey(source: "", id: model.assistantAnimationID) {
                                CollapsedAgentFace(waiting: agentNeedsAttention(model.assistantStateLabel), state: model.assistantStateLabel,
                                                   agentID: model.assistantAnimationID)
                                    .modifier(AgentFlightGeometry(namespace: flightNamespace, session: AgentSessionKey(source: "", id: model.assistantAnimationID), enabled: true))
                            } else {
                                Circle().fill(agentStateColor(model.assistantStateLabel)).frame(width: 7, height: 7).frame(width: 19, height: 18)
                            }
                            Text("Codex").fontWeight(.semibold)
                            Text("· AI 대화").foregroundStyle(.secondary)
                            Spacer(minLength: 4)
                            Circle().fill(agentStateColor(model.assistantStateLabel)).frame(width: 5, height: 5)
                            Text(model.assistantStateLabel).foregroundStyle(.secondary)
                            Image(systemName: "chevron.right").foregroundStyle(.secondary)
                        }.font(.system(size: 12)).frame(maxWidth: .infinity, alignment: .leading).riumGlassTile()
                    }.buttonStyle(.plain).accessibilityLabel("Codex AI 대화 \(model.assistantStateLabel) 열기")
                }
                if model.externalAgentItems.isEmpty && model.assistantIndicator == .off && !model.assistantFinishing {
                    Text(model.agentStatus).font(.caption).foregroundStyle(.secondary)
                        .frame(maxWidth: .infinity, minHeight: 80)
                }
                ForEach(model.externalAgentItems, id: \.sessionKey) { item in
                    VStack(alignment: .leading, spacing: 9) {
                        HStack(spacing: 7) {
                            if riumSession == item.sessionKey {
                                CollapsedAgentFace(waiting: agentNeedsAttention(item.state), source: item.source, state: item.state, agentID: item.id)
                                    .modifier(AgentFlightGeometry(namespace: flightNamespace, session: item.sessionKey, enabled: true))
                            } else {
                                Circle().fill(agentStateColor(item.state)).frame(width: 7, height: 7).frame(width: 19, height: 18)
                            }
                            Text(item.providerName).fontWeight(.semibold)
                            Text("· \(item.project)").foregroundStyle(.secondary).lineLimit(1)
                            Spacer(minLength: 4)
                            if let age = item.ageSeconds { Text(age < 60 ? "\(age)초 전" : "\(age / 60)분 전").foregroundStyle(.secondary) }
                        }
                        HStack(spacing: 6) {
                            ForEach(Array(item.recentActivities.enumerated()), id: \.offset) { _, activity in
                                Label(activity, systemImage: activity == "웹 확인" || activity == "웹 검색" ? "globe" : (activity == "검색" ? "magnifyingglass" : (activity == "파일 수정" ? "pencil" : (activity == "파일 확인" ? "doc.text.magnifyingglass" : "terminal"))))
                                    .font(.caption).lineLimit(1).padding(.horizontal, 7).padding(.vertical, 4)
                                    .background(.white.opacity(0.06), in: Capsule())
                            }
                            Spacer(minLength: 0)
                        }
                        AgentHookApprovalPanel(model: model, item: item, hasLiveQuestion: Binding(
                            get: { liveClaudeQuestions.contains(item.sessionKey) },
                            set: { if $0 { liveClaudeQuestions.insert(item.sessionKey) } else { liveClaudeQuestions.remove(item.sessionKey) } }))
                        if item.source == "codex" { CodexDesktopPanel(model: model, item: item) }
                        if item.source != "claude" || !liveClaudeQuestions.contains(item.sessionKey) {
                            ForEach(item.pendingQuestions) { question in
                                questionView(question, for: item)
                            }
                        }
                        if item.source == "codex" && !agentNeedsAttention(item.state) {
                            HStack(alignment: .bottom, spacing: 7) {
                                TextField("Codex에 후속 메시지", text: Binding(
                                    get: { drafts[item.sessionKey] ?? "" }, set: { drafts[item.sessionKey] = $0 }), axis: .vertical)
                                    .textFieldStyle(.roundedBorder).lineLimit(1...3)
                                    .disabled(sending.contains(item.sessionKey) || uncertain.contains(item.sessionKey))
                                Button("전송") { sendFollowup(item) }.buttonStyle(.plain)
                                    .disabled(sending.contains(item.sessionKey) || uncertain.contains(item.sessionKey)
                                        || (drafts[item.sessionKey] ?? "").trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
                            }
                            if let message = messages[item.sessionKey] {
                                Text(message).font(.caption).foregroundStyle(.secondary).fixedSize(horizontal: false, vertical: true)
                            }
                        }
                        HStack(spacing: 8) {
                            Circle().fill(agentStateColor(item.state)).frame(width: 5, height: 5)
                            if agentIsRunning(item.state) {
                                AgentStatusSweep(text: item.state, tint: agentStateColor(item.state))
                            } else { Text(item.state).foregroundStyle(.secondary) }
                            Spacer()
                            if item.source == "codex", codexThreadURL(item.id) != nil {
                                Button("대화 열기") { model.openCodexThread(item) }
                                    .buttonStyle(.plain).help("Codex에서 이 대화 열기")
                            }
                            Image(systemName: "infinity").foregroundStyle(.secondary.opacity(0.5)).help("지속 권한 변경은 제공하지 않습니다").accessibilityLabel("지속 권한 변경 미지원")
                            if item.source == "codex" || item.source == "claude" {
                                Button(action: { stopTurn(item) }) { Image(systemName: "stop.fill") }
                                    .buttonStyle(.plain).help("이 \(item.source == "claude" ? "Claude" : "Codex") 작업 중단").accessibilityLabel("이 \(item.source == "claude" ? "Claude" : "Codex") 작업 중단")
                                    .disabled(stopping.contains(item.sessionKey) || stopAccepted.contains(item.sessionKey) || stopUncertain.contains(item.sessionKey)
                                        || !agentCanInterrupt(item.state))
                            } else {
                                Image(systemName: "stop.fill").foregroundStyle(.secondary.opacity(0.5)).help("작업 중단 제어 연결 필요").accessibilityLabel("작업 중단 제어 연결 필요")
                            }
                        }
                        if let message = stopMessages[item.sessionKey] {
                            Text(message).font(.caption).foregroundStyle(.secondary).fixedSize(horizontal: false, vertical: true)
                        }
                    }.font(.system(size: 12)).riumGlassTile()
                        .onAppear {
                            releaseFinishedStop(item.sessionKey)
                        }
                        .onChange(of: item.state) { _, _ in
                            releaseFinishedStop(item.sessionKey)
                        }
                }
            }
        }
    }
    private func questionView(_ question: PendingAgentQuestion, for item: AgentActivity) -> some View {
        let key = AgentQuestionKey(session: item.sessionKey, question: question.id)
        return VStack(alignment: .leading, spacing: 6) {
            Text(question.title).font(.system(size: 12, weight: .medium)).fixedSize(horizontal: false, vertical: true)
            ForEach(Array(question.options.enumerated()), id: \.offset) { _, option in
                Button { sendAnswer(item, question: question, answer: option) } label: {
                    HStack(alignment: .top, spacing: 6) {
                        Image(systemName: "circle").font(.system(size: 9)).padding(.top, 3).accessibilityHidden(true)
                        Text(option).font(.system(size: 11)).fixedSize(horizontal: false, vertical: true)
                    }.frame(maxWidth: .infinity, alignment: .leading).contentShape(Rectangle())
                }.buttonStyle(.plain).foregroundStyle(.secondary)
                    .disabled(item.source != "codex" || answering.contains(key) || answeredOrUncertain.contains(key))
            }
            if item.source == "codex" {
                HStack(alignment: .bottom, spacing: 7) {
                    TextField(question.options.isEmpty ? "답변 입력" : "직접 답변 입력", text: Binding(get: { questionDrafts[key] ?? "" }, set: { questionDrafts[key] = $0 }), axis: .vertical)
                        .textFieldStyle(.roundedBorder).lineLimit(1...3)
                        .disabled(answering.contains(key) || answeredOrUncertain.contains(key))
                    Button("답변") { sendAnswer(item, question: question, answer: questionDrafts[key] ?? "") }
                        .buttonStyle(.plain).disabled(answering.contains(key) || answeredOrUncertain.contains(key)
                            || (questionDrafts[key] ?? "").trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
                }
            }
            if let message = questionMessages[key] { Text(message).font(.caption).foregroundStyle(.secondary).fixedSize(horizontal: false, vertical: true) }
            if item.source == "claude" { Text("Claude에서 답변해 주세요").font(.caption).foregroundStyle(.secondary) }
            if item.source == "codex", codexThreadURL(item.id) != nil {
                Button("Codex에서 답변") { model.openCodexThread(item) }.buttonStyle(.plain)
                    .font(.system(size: 11, weight: .semibold)).foregroundStyle(.blue)
            }
        }.padding(9).frame(maxWidth: .infinity, alignment: .leading)
            .background(.white.opacity(0.06), in: RoundedRectangle(cornerRadius: 10))
    }
    private func releaseFinishedStop(_ session: AgentSessionKey) {
        guard !stopStillPending(session, in: model.agentItems) else { return }
        stopAccepted.remove(session)
        if stopUncertain.remove(session) != nil { stopMessages[session] = "작업 종료가 확인됐습니다." }
    }
    private func stopTurn(_ item: AgentActivity) {
        guard item.source == "codex" || item.source == "claude" else { return }
        let sessionID = item.source == "claude" && item.id.hasPrefix("claude-") ? String(item.id.dropFirst("claude-".count)) : item.id
        let provider = item.source == "claude" ? "Claude" : "Codex"
        guard !stopping.contains(item.sessionKey), !stopAccepted.contains(item.sessionKey), !stopUncertain.contains(item.sessionKey),
              let input = try? JSONSerialization.data(withJSONObject: ["sessionId": sessionID]) else { return }
        model.holdExpandedNotchAfterAgentAction()
        stopping.insert(item.sessionKey); stopMessages[item.sessionKey] = "작업 확인 중…"
        model.run([item.source == "claude" ? "claude-interrupt" : "agent-interrupt"], input: input) { event in
            guard let kind = event["event"] as? String, kind == "result" || kind == "error" else { return }
            stopping.remove(item.sessionKey)
            if agentCommandOutcome(event) == .accepted {
                if stopStillPending(item.sessionKey, in: model.agentItems) { stopAccepted.insert(item.sessionKey) }
                stopMessages[item.sessionKey] = "중단 요청을 전달했습니다. 작업 상태는 \(provider)에서 확인해 주세요."
                model.refreshAgents()
            } else if agentCommandOutcome(event) == .unknown {
                if stopStillPending(item.sessionKey, in: model.agentItems) {
                    stopUncertain.insert(item.sessionKey)
                    stopMessages[item.sessionKey] = "중단 요청 결과를 확인할 수 없습니다. \(provider)에서 확인해 주세요."
                } else { stopMessages[item.sessionKey] = "작업 종료가 확인됐습니다." }
                model.refreshAgents()
            } else {
                stopMessages[item.sessionKey] = event["message"] as? String ?? "작업을 확인할 수 없습니다. \(provider)에서 직접 확인해 주세요."
            }
        }
    }
    private func sendFollowup(_ item: AgentActivity) {
        let text = (drafts[item.sessionKey] ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        guard !text.isEmpty, !sending.contains(item.sessionKey), !uncertain.contains(item.sessionKey) else { return }
        guard text.utf8.count <= 20_000 else {
            messages[item.sessionKey] = "메시지가 너무 깁니다. 내용을 나누어 보내 주세요."
            return
        }
        guard let input = try? JSONSerialization.data(withJSONObject: [
            "sessionId": item.id, "text": text, "messageId": UUID().uuidString
        ]) else { return }
        sending.insert(item.sessionKey); messages[item.sessionKey] = "전송 중…"
        model.run(["agent-followup"], input: input, timeout: 30) { event in
            guard let kind = event["event"] as? String, kind == "result" || kind == "error" else { return }
            sending.remove(item.sessionKey)
            let outcome = agentCommandOutcome(event)
            if outcome == .accepted || outcome == .queued {
                if (drafts[item.sessionKey] ?? "").trimmingCharacters(in: .whitespacesAndNewlines) == text { drafts[item.sessionKey] = "" }
                messages[item.sessionKey] = outcome == .queued ? "Codex 대기열에 추가했습니다." : "Codex에 전달했습니다."
                model.refreshAgents()
            } else if outcome == .unknown {
                uncertain.insert(item.sessionKey)
                messages[item.sessionKey] = "전송 여부를 확인할 수 없습니다. Codex 대화에서 확인해 주세요."
            } else {
                messages[item.sessionKey] = event["message"] as? String ?? "전송할 수 없습니다. Codex에서 직접 확인해 주세요."
            }
        }
    }
    private func sendAnswer(_ item: AgentActivity, question: PendingAgentQuestion, answer: String) {
        let value = answer.trimmingCharacters(in: .whitespacesAndNewlines)
        let key = AgentQuestionKey(session: item.sessionKey, question: question.id)
        guard item.source == "codex", !value.isEmpty, value.utf8.count <= 2000,
              !answering.contains(key), !answeredOrUncertain.contains(key),
              let input = try? JSONSerialization.data(withJSONObject: ["sessionId": item.id, "questionId": question.id,
                  "question": question.title, "options": question.options, "answer": value]) else { return }
        model.holdExpandedNotchAfterAgentAction()
        answering.insert(key); questionMessages[key] = "답변 확인 중…"
        model.run(["agent-answer"], input: input) { event in
            guard let kind = event["event"] as? String, kind == "result" || kind == "error" else { return }
            answering.remove(key)
            if agentCommandOutcome(event) == .accepted {
                answeredOrUncertain.insert(key); questionDrafts[key] = ""
                questionMessages[key] = "Codex에 답변을 전달했습니다."
                model.refreshAgents()
            } else if agentCommandOutcome(event) == .unknown {
                answeredOrUncertain.insert(key)
                questionMessages[key] = "전달 여부를 확인할 수 없습니다. Codex 대화에서 확인해 주세요."
            } else {
                questionMessages[key] = event["message"] as? String ?? "답변할 수 없습니다. Codex에서 확인해 주세요."
            }
        }
    }
}

struct MediaTransportGlyph: View {
    let playing: Bool
    var body: some View {
        Canvas { context, size in
            let scale = min(size.width, size.height) / 16
            if playing {
                for x in [3.5, 9.5] {
                    let rect = CGRect(x: x * scale, y: 2.5 * scale, width: 3 * scale, height: 11 * scale)
                    context.fill(Path(roundedRect: rect, cornerRadius: 0.7 * scale), with: .color(.black))
                }
            } else {
                var triangle = Path(); triangle.move(to: CGPoint(x: 4.5 * scale, y: 2 * scale))
                triangle.addLine(to: CGPoint(x: 13 * scale, y: 8 * scale)); triangle.addLine(to: CGPoint(x: 4.5 * scale, y: 14 * scale)); triangle.closeSubpath()
                context.fill(triangle, with: .color(.black))
            }
        }.frame(width: 16, height: 16).accessibilityHidden(true)
    }
}

struct MediaProgressTimeline<Content: View>: View {
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @ObservedObject var model: Model
    var isScrubbing = false
    @ViewBuilder var content: (Double) -> Content

    var body: some View {
        if reduceMotion || isScrubbing || !model.mediaPlaying || !model.mediaPositionKnown
            || model.mediaDuration <= 0 || model.mediaPlaybackRate == 0 {
            content(model.mediaElapsed)
        } else {
            TimelineView(.animation(minimumInterval: 1.0 / 15.0)) { _ in
                content(model.currentMediaElapsed(at: ProcessInfo.processInfo.systemUptime))
            }
        }
    }
}

struct MusicView: View {
    @ObservedObject var model: Model
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @AppStorage("rium.card.style") private var cardStyle = "liquid"
    @GestureState private var seekGestureActive = false
    @State private var seekGestureStarted = false
    var body: some View {
        GeometryReader { geometry in
            let artSize = min(168, max(64, geometry.size.width * 0.21))
            HStack(spacing: 8) {
                HStack(spacing: 14) {
                    Group {
                        if let artwork = model.mediaArtwork { Image(nsImage: artwork).resizable().scaledToFill() }
                        else {
                            ZStack {
                                Color.white.opacity(0.07)
                                Image(systemName: "music.note").resizable().scaledToFit().padding(artSize * 0.27).foregroundStyle(.white.opacity(0.65))
                            }
                        }
                    }.frame(width: artSize, height: artSize).clipShape(RoundedRectangle(cornerRadius: min(24, artSize * 0.15)))
                    VStack(alignment: .leading, spacing: 6) {
                        HStack(alignment: .top) {
                            VStack(alignment: .leading, spacing: 2) {
                                Text(!model.mediaAvailable ? "재생 중인 미디어 없음" : (model.mediaPlaying ? "지금 재생 중" : "일시 정지"))
                                Text("음악")
                            }.font(.caption).foregroundStyle(.secondary).lineLimit(1)
                            Spacer(minLength: 0)
                            if !model.showLyricsPanel {
                                Button(action: { withAnimation(.easeInOut(duration: 0.2)) { model.showLyricsPanel = true } }) {
                                    Image(systemName: "text.quote").frame(width: 24, height: 24).background(.white.opacity(0.08), in: Circle()).contentShape(Rectangle())
                                }.buttonStyle(.plain).help("가사 패널 열기").accessibilityLabel("가사 패널 열기")
                            }
                        }
                        Spacer(minLength: 4)
                        Text(model.mediaTitle).font(.system(size: 18, weight: .medium)).lineLimit(2)
                        if !model.mediaArtist.isEmpty { Text(model.mediaArtist).font(.caption).foregroundStyle(.secondary).lineLimit(1) }
                        if model.mediaDuration > 0 {
                            GeometryReader { bar in
                                let position = mediaDisplayPosition(known: model.mediaPositionKnown, editing: model.mediaEditingPosition,
                                                                    elapsed: model.mediaElapsed, edited: model.mediaEditedPosition, duration: model.mediaDuration)
                                let canSeek = !model.mediaSeekPending && !model.mediaControlPending
                                ZStack(alignment: .leading) {
                                    Capsule().fill(.white.opacity(0.20)).frame(height: 3)
                                    MediaProgressTimeline(model: model, isScrubbing: model.mediaEditingPosition) { elapsed in
                                        let display = mediaDisplayPosition(known: model.mediaPositionKnown, editing: model.mediaEditingPosition,
                                                                           elapsed: elapsed, edited: model.mediaEditedPosition, duration: model.mediaDuration)
                                        let fraction = (display ?? 0) / model.mediaDuration
                                        Capsule().fill(Color(red: 0.96, green: 0.48, blue: 0.65)).frame(width: bar.size.width * fraction, height: 3)
                                    }
                                }
                                .frame(maxWidth: .infinity, maxHeight: .infinity)
                                .contentShape(Rectangle())
                                .gesture(DragGesture(minimumDistance: 0)
                                    .updating($seekGestureActive) { _, active, _ in active = true }
                                    .onChanged { value in
                                        if !seekGestureStarted {
                                            seekGestureStarted = true
                                            model.mediaEditingPosition = canSeek && bar.size.width > 0
                                        }
                                        guard model.mediaEditingPosition, canSeek, bar.size.width > 0 else { return }
                                        let fraction = min(1, max(0, value.location.x / bar.size.width))
                                        model.mediaEditedPosition = model.mediaDuration * fraction
                                    }
                                    .onEnded { _ in
                                        seekGestureStarted = false
                                        guard model.mediaEditingPosition else { return }
                                        model.mediaEditingPosition = false
                                        model.seekMedia(model.mediaEditedPosition)
                                    })
                                .onChange(of: seekGestureActive) { _, active in
                                    if !active {
                                        seekGestureStarted = false
                                        model.mediaEditingPosition = false
                                    }
                                }
                                .accessibilityRepresentation {
                                    Slider(value: Binding(get: { position ?? 0 }, set: { model.seekMedia($0) }), in: 0...model.mediaDuration)
                                        .disabled(!canSeek)
                                        .accessibilityLabel("재생 위치")
                                        .accessibilityValue(position.map { mediaTime($0) } ?? "확인할 수 없음")
                                }
                                .onDisappear {
                                    seekGestureStarted = false
                                    model.mediaEditingPosition = false
                                }
                            }.frame(height: 14)
                            HStack { Text(model.mediaPositionKnown || model.mediaEditingPosition ? mediaTime(model.mediaEditingPosition ? model.mediaEditedPosition : model.mediaElapsed) : "--:--"); Spacer(); Text(mediaTime(model.mediaDuration)) }.font(.caption2).foregroundStyle(.secondary).monospacedDigit()
                        }
                        if !model.mediaError.isEmpty { Text(model.mediaError).font(.caption2).foregroundStyle(.secondary).lineLimit(1).help(model.mediaError) }
                        HStack {
                            Button(action: { model.controlMedia("previous") }) { Image(systemName: "backward.fill").frame(width: 32, height: 32).overlay(Circle().stroke(.white.opacity(0.18), lineWidth: 1)).contentShape(Rectangle()) }.help("이전 곡")
                            Spacer(minLength: 4)
                            Button(action: { model.controlMedia("toggle") }) { MediaTransportGlyph(playing: model.mediaPlaying).frame(width: 40, height: 40).background(.white, in: Circle()).contentShape(Rectangle()) }
                                .help(model.mediaPlaying ? "일시 정지" : "재생").accessibilityLabel(model.mediaPlaying ? "일시 정지" : "재생")
                            Spacer(minLength: 4)
                            Button(action: { model.controlMedia("next") }) { Image(systemName: "forward.fill").frame(width: 32, height: 32).overlay(Circle().stroke(.white.opacity(0.18), lineWidth: 1)).contentShape(Rectangle()) }.help("다음 곡")
                        }.buttonStyle(.plain).disabled(!model.mediaAvailable || model.mediaControlPending).padding(.top, 4)
                    }
                }
                .frame(width: max(1, geometry.size.width * (model.showLyricsPanel ? 0.55 : 1) - 26), height: max(1, geometry.size.height - 22), alignment: .leading)
                .riumGlassTile(artwork: model.mediaAtmosphere, artworkOpacity: 0.09, radius: 24)
                if model.showLyricsPanel {
                VStack(alignment: .leading, spacing: 8) {
                    HStack {
                        Text("가사").font(.caption).foregroundStyle(.secondary); Spacer()
                        AudioOutputMenu(model: model.audioOutputs)
                        Button(action: { withAnimation(.easeInOut(duration: 0.2)) { model.showLyricsPanel = false } }) {
                            Image(systemName: "xmark").frame(width: 24, height: 24).background(.white.opacity(0.08), in: Circle())
                        }.buttonStyle(.plain).help("가사 패널 닫기").accessibilityLabel("가사 패널 닫기")
                    }
                    if !model.lyricsEnabled {
                        Spacer()
                        VStack(alignment: .leading, spacing: 8) {
                            Text("가사를 켜면 곡 제목과 아티스트, 재생 시간이 LRCLIB에 전송됩니다.").font(.caption).foregroundStyle(.secondary)
                            Button("가사 켜기") { model.setLyricsEnabled(true) }.buttonStyle(.plain)
                        }
                        Spacer()
                    } else if model.lyricLines.isEmpty {
                        Spacer(); Text(model.lyricsStatus).font(.caption).foregroundStyle(.secondary); Spacer()
                    } else {
                        let active = activeLyricLine(model.lyricLines, positionKnown: model.mediaPositionKnown, elapsed: model.mediaElapsed)?.id
                        ScrollViewReader { proxy in
                            ScrollView { VStack(alignment: .leading, spacing: 10) {
                                ForEach(model.lyricLines) { line in
                                    Text(line.text.isEmpty ? " " : line.text).font(.system(size: 12, weight: active == line.id ? .semibold : .regular))
                                        .foregroundStyle(active == line.id ? Color.white : Color.white.opacity(0.52)).id(line.id)
                                }
                            }.frame(maxWidth: .infinity, alignment: .leading) }
                            .onChange(of: active, initial: true) { _, value in
                                if let value = value { withAnimation(reduceMotion ? nil : .easeInOut(duration: 0.3)) { proxy.scrollTo(value, anchor: .center) } }
                            }
                        }
                    }
                    if model.lyricsEnabled {
                        HStack {
                            Text("가사 제공: LRCLIB").font(.caption2).foregroundStyle(.secondary)
                            Spacer()
                            Button("가사 끄기") { model.setLyricsEnabled(false) }.buttonStyle(.plain).font(.caption2)
                        }
                    }
                }.frame(width: max(1, geometry.size.width * 0.45 - 26), height: max(1, geometry.size.height - 22), alignment: .topLeading).riumGlassTile(radius: 24)
                }
            }
            .background {
                if cardStyle == "liquid", let artwork = model.mediaAtmosphere {
                    GeometryReader { backdrop in
                        Image(nsImage: artwork).resizable().scaledToFill()
                            .frame(width: backdrop.size.width, height: backdrop.size.height)
                            .opacity(0.20)
                            .mask(LinearGradient(stops: [
                                .init(color: .clear, location: 0),
                                .init(color: .white, location: 0.14),
                                .init(color: .white.opacity(0.80), location: 0.80),
                                .init(color: .clear, location: 1)
                            ], startPoint: .leading, endPoint: .trailing))
                            .mask(LinearGradient(stops: [
                                .init(color: .clear, location: 0),
                                .init(color: .white, location: 0.22),
                                .init(color: .white, location: 0.80),
                                .init(color: .clear, location: 1)
                            ], startPoint: .top, endPoint: .bottom))
                            .clipped()
                    }.allowsHitTesting(false).accessibilityHidden(true)
                }
            }
        }
    }
    private func mediaTime(_ seconds: Double) -> String {
        let value = Int(min(max(seconds, 0), 86_400))
        return value >= 3600 ? String(format: "%d:%02d:%02d", value / 3600, value / 60 % 60, value % 60) : String(format: "%d:%02d", value / 60, value % 60)
    }
}

