// Card surface choices reflect the static Glance preview assets. The exact
// physical rasterization and dashboard-specific content still need visual
// comparison against the running reference application.
private struct RiumCardSurface: ViewModifier {
    @AppStorage("rium.card.style") private var style = "liquid"
    let artwork: NSImage?
    let tint: Color
    let artworkOpacity: Double
    let radius: CGFloat
    let homeSurface: Bool
    @ViewBuilder func body(content: Content) -> some View {
        if style == "classic" || style == "physical" {
            content.padding(11)
                .background(Color(white: 0.045), in: RoundedRectangle(cornerRadius: radius, style: .continuous))
                .overlay(RoundedRectangle(cornerRadius: radius, style: .continuous).stroke(.white.opacity(0.09), lineWidth: 0.7))
                .overlay {
                    if style == "physical" {
                        RiumPhysicalGrid().clipShape(RoundedRectangle(cornerRadius: radius, style: .continuous))
                            .allowsHitTesting(false).accessibilityHidden(true)
                    }
                }
        } else if style == "dashboard" {
            content.padding(11)
                .background(LinearGradient(colors: [Color(white: 0.27), Color(white: 0.18)], startPoint: .top, endPoint: .bottom),
                            in: RoundedRectangle(cornerRadius: radius, style: .continuous))
                .overlay(RoundedRectangle(cornerRadius: radius, style: .continuous)
                    .stroke(LinearGradient(colors: [.white.opacity(0.22), .white.opacity(0.06)], startPoint: .top, endPoint: .bottom), lineWidth: 1))
                .shadow(color: .black.opacity(0.4), radius: 5, y: 3)
        } else {
            content.padding(11)
            .background {
                ZStack {
                    Color.white.opacity(0.075)
                    if let artwork = artwork {
                        GeometryReader { geometry in
                            Image(nsImage: artwork).resizable().scaledToFill()
                                .frame(width: geometry.size.width, height: geometry.size.height)
                                .opacity(artworkOpacity)
                        }.clipped()
                    } else {
                        LinearGradient(colors: [tint.opacity(0.20), .white.opacity(0.07), tint.opacity(0.10)], startPoint: .topLeading, endPoint: .bottomTrailing)
                    }
                    LinearGradient(colors: [.white.opacity(homeSurface ? 0.08 : 0.15), .clear, homeSurface ? .white.opacity(0.03) : .black.opacity(0.12)], startPoint: .top, endPoint: .bottom)
                }.clipShape(RoundedRectangle(cornerRadius: radius))
                    .riumNativeHomeGlass(homeSurface, tint: tint, radius: radius)
            }
            .overlay {
                if homeSurface {
                    RoundedRectangle(cornerRadius: radius).strokeBorder(.white.opacity(0.11), lineWidth: 2).blur(radius: 2.5)
                        .clipShape(RoundedRectangle(cornerRadius: radius)).allowsHitTesting(false)
                }
            }
            .overlay(RoundedRectangle(cornerRadius: radius).stroke(LinearGradient(colors: [.white.opacity(homeSurface ? 0.43 : 0.36), .white.opacity(0.10), .white.opacity(homeSurface ? 0.27 : 0.23)], startPoint: .top, endPoint: .bottom), lineWidth: 0.8))
        }
    }
}

private struct RiumPhysicalGrid: View {
    var body: some View {
        Canvas { context, size in
            var grid = Path()
            stride(from: CGFloat(0), through: size.width, by: 2).forEach { x in
                grid.move(to: CGPoint(x: x, y: 0)); grid.addLine(to: CGPoint(x: x, y: size.height))
            }
            stride(from: CGFloat(0), through: size.height, by: 2).forEach { y in
                grid.move(to: CGPoint(x: 0, y: y)); grid.addLine(to: CGPoint(x: size.width, y: y))
            }
            context.stroke(grid, with: .color(.black.opacity(0.32)), lineWidth: 0.45)
        }
    }
}

extension View {
    func riumGlassTile(artwork: NSImage? = nil, tint: Color = .clear, artworkOpacity: Double = 0.38, radius: CGFloat = 15, homeSurface: Bool = false) -> some View {
        modifier(RiumCardSurface(artwork: artwork, tint: tint, artworkOpacity: artworkOpacity, radius: radius, homeSurface: homeSurface))
    }
    @ViewBuilder func riumNativeHomeGlass(_ enabled: Bool, tint: Color, radius: CGFloat) -> some View {
        #if compiler(>=6.2)
        if #available(macOS 26.0, *), enabled {
            self.glassEffect(.clear.tint(tint.opacity(0.12)), in: RoundedRectangle(cornerRadius: radius, style: .continuous))
        } else { self }
        #else
        self
        #endif
    }
    func riumTile(_ tint: Color = .clear) -> some View {
        padding(11).background(RoundedRectangle(cornerRadius: 15).fill(LinearGradient(colors: [tint.opacity(0.20), Color.white.opacity(0.06)], startPoint: .topLeading, endPoint: .bottomTrailing)))
            .overlay(RoundedRectangle(cornerRadius: 15).stroke(Color.white.opacity(0.12), lineWidth: 0.7))
    }
}

struct Sparkline: Shape {
    let samples: [Double?]
    func path(in rect: CGRect) -> Path {
        var path = Path(); guard samples.count > 1 else { return path }
        var continuing = false
        for (index, value) in samples.enumerated() {
            guard let value = value, value.isFinite else { continuing = false; continue }
            let x = rect.width * CGFloat(index) / CGFloat(samples.count - 1)
            let y = rect.height * (1 - CGFloat(min(max(value, 0), 100)) / 100)
            if continuing { path.addLine(to: CGPoint(x: x, y: y)) } else { path.move(to: CGPoint(x: x, y: y)) }
            continuing = true
        }
        return path
    }
}

@_silgen_name("rium_weather_sky_photograph")
private func rustWeatherSkyPhotograph(_ bytes: UnsafePointer<UInt8>?, _ count: Int) -> Int32

private enum LocalWeatherSky {
    static let names = ["clearDay", "clearNight", "cloudy", "partlyCloudy", "fog", "rain", "snow", "storm"]
    static let images: [String: NSImage] = {
        var result: [String: NSImage] = [:]
        for name in names {
            if let url = Bundle.main.url(forResource: "sky-\(name)", withExtension: "jpg"),
               let image = NSImage(contentsOf: url) { result[name] = image }
        }
        return result
    }()
    static func image(symbol: String) -> NSImage? {
        let bytes = Array(symbol.utf8)
        let index = bytes.withUnsafeBufferPointer { rustWeatherSkyPhotograph($0.baseAddress, $0.count) }
        guard index >= 0, Int(index) < names.count else { return nil }
        return images[names[Int(index)]]
    }
}

// Keep all available future samples in the detail page. Later MET samples
// can be farther apart than an hour, so their actual date and time is shown.
func detailWeatherForecast(_ hours: [WeatherHour], now: Date) -> [WeatherHour] {
    hours.filter { $0.date.addingTimeInterval(3600) > now }
}

