                            HStack {
                                VStack(alignment: .leading) {
                                    Text(item.title)
                                    Text(item.subtitle).font(.caption).foregroundStyle(.secondary)
                                }
                                Spacer()
                                Button("완료") { model.completeReminder(item.id) }.buttonStyle(.plain)
                            }.transition(reminderTransition)
