extension Notification.Name {
    static let notchSizeChanged = Notification.Name("notchSizeChanged")
    static let notchDisplayChanged = Notification.Name("notchDisplayChanged")
}

// Keep every notch overlay visible in spaces, fullscreen and app sets.
private let notchOverlayBehavior: NSWindow.CollectionBehavior = [
    .canJoinAllSpaces, .fullScreenAuxiliary, .stationary, .ignoresCycle, .canJoinAllApplications
]

// Distinguish the app's own synthetic paste from a user shortcut so that a
// global monitor cannot start a second identical effect for the same action.
private let riumPasteEventMarker: Int64 = 0x5249554d50415354
let agentSwitcherShortcutPreference = "rium.notch.agentSwitcherShortcut"

// The reference panel leaves the requested frame unchanged, including the
// menu-bar region. AppKit's default constraint can otherwise shift the notch
// away from the physical display edge during window or Space transitions.
private final class NotchPanel: NSPanel {
    override var canBecomeKey: Bool { true }
    override var canBecomeMain: Bool { false }

    override func constrainFrameRect(_ frameRect: NSRect, to screen: NSScreen?) -> NSRect {
        frameRect
    }
}

// shortcut: Separate effect windows are our architecture; their alignment
// across Spaces and displays still needs runtime comparison with the reference.
private final class NotchEffectPanel: NSPanel {
    override var canBecomeKey: Bool { false }
    override var canBecomeMain: Bool { false }

    override func constrainFrameRect(_ frameRect: NSRect, to screen: NSScreen?) -> NSRect {
        frameRect
    }
}

final class AppDelegate: NSObject, NSApplicationDelegate {
    let model = Model()
    var panel: NSPanel!
    private var edgeWavePanel: NSPanel?
    private var cordPanel: NSPanel?
    private var cordHoverUntil: TimeInterval = 0
    var status: NSStatusItem!
    private var statusAppearanceObservation: NSKeyValueObservation?
    var settingsWindow: NSWindow?
    private var interviewWindow: NSPanel?
    private var interviewWindowObserver: NSObjectProtocol?
    private var menuTrackingObservers: [NSObjectProtocol] = []
    private var screenObserver: NSObjectProtocol?
    private var workspaceObservers: [NSObjectProtocol] = []
    private var screenLockObservers: [NSObjectProtocol] = []
    private var screenLocked = false
    private var workspaceSessionInactive = false
    private var screenAccessBlocked: Bool { screenLocked || workspaceSessionInactive }
    private var workspaceSleeping = false
    private var screensSleeping = false
    private var displaySleeping: Bool { workspaceSleeping || screensSleeping }
    private var spaceResyncGeneration: UInt64 = 0
    private var screenRetry: DispatchWorkItem?
    private var notchCutoutCache = NotchCutoutCache()
    private var globalMouseMonitor: Any?
    private var localMouseMonitor: Any?
    private var globalShortcutMonitor: Any?
    private var localShortcutMonitor: Any?
    private var globalMediaKeyMonitor: Any?
    private var localMediaKeyMonitor: Any?
    private var shiftHoldWork: DispatchWorkItem?
    private var shiftConsumed = false
    private var shortcutMonitorGeneration: UInt64 = 0
    private var shortcutCaptureObservation: AnyCancellable?
    private var agentSwitcherTookActivation = false
    private weak var agentSwitcherPreviousKeyWindow: NSWindow?
    private var pointerPollTimer: Timer?
    private var mouseInsideNotch = false
    private var preparingDropEntry = false
    private var lastDeliveredHover = false
    private var hoverDeferredForPreview = false
    private var floatingIslandEnabled = UserDefaults.standard.bool(forKey: "rium.notch.floatingIsland")
    func applicationWillFinishLaunching(_ notification: Notification) {
        observeWorkspaceSessionChanges()
    }

    func applicationDidFinishLaunching(_ notification: Notification) {
        NSApp.setActivationPolicy(CommandLine.arguments.contains("--ui-test") ? .regular : .accessory)
        EdgeWaveMetal.prepare()
        model.refreshDisplayChoices()
        model.onCordChange = { [weak self] in self?.updateCordPanel() }
        model.onEdgeWaveChange = { [weak self] in self?.updateEdgeWavePanel() }
        model.onOpenInterviewWindow = { [weak self] in self?.showInterviewWindow() }
        model.onReturnInterviewToNotch = { [weak self] in self?.returnInterviewToNotch() }
        panel = NotchPanel(contentRect: NSRect(x: 0, y: 0, width: 405, height: notchHeight(expanded: false, section: .home)), styleMask: [.borderless, .nonactivatingPanel], backing: .buffered, defer: false)
        panel.isOpaque = false; panel.backgroundColor = .clear; panel.hasShadow = false
        panel.hidesOnDeactivate = false
        panel.animationBehavior = .none
        panel.acceptsMouseMovedEvents = true
        // REA's native observer accepts layer-zero windows only. This opt-in
        // diagnostic keeps the same view and geometry while temporarily
        // lowering the window for observation; ordinary launches stay on top.
        panel.level = CommandLine.arguments.contains("--rea-inspect") ? .normal : .statusBar
        // The notch belongs to the screen, not to a document window: Exposé
        // and Show Desktop must not slide it away from the physical camera.
        panel.collectionBehavior = notchOverlayBehavior
        observeScreenLock()
        let initialScreen = targetScreen()
        let showsNotchOnLaunch = notchCanReflow(screenLocked: screenAccessBlocked, sleeping: displaySleeping)
        // Give the first layout the final screen frame and camera geometry.
        if let initialScreen, showsNotchOnLaunch {
            alignNotchPanels(to: initialScreen)
        }
        let hosting = NSHostingView(rootView: NotchContainer(model: model)
            .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .top))
        hosting.sizingOptions = []
        panel.contentView = hosting
        model.onClipboardSearchKeyChange = { [weak panel = panel] editing in
            if editing { panel?.makeKey() }
            else if panel?.isKeyWindow == true { panel?.resignKey() }
        }
        let notifications = NotificationCenter.default
        menuTrackingObservers.append(notifications.addObserver(forName: NSMenu.didBeginTrackingNotification, object: nil, queue: .main) { [weak self] _ in
            self?.model.beginMenuTracking()
        })
        menuTrackingObservers.append(notifications.addObserver(forName: NSWindow.didResignKeyNotification, object: panel, queue: .main) { [weak self] _ in
            self?.closeAgentSwitcher(restoreFocus: false)
            self?.model.setClipboardSearchEditing(false)
        })
        menuTrackingObservers.append(notifications.addObserver(forName: NSMenu.didEndTrackingNotification, object: nil, queue: .main) { [weak self] _ in
            guard let self = self else { return }
            self.model.endMenuTracking(pointerInside: self.pointIsInsideNotch(NSEvent.mouseLocation))
        })
        if initialScreen != nil, showsNotchOnLaunch {
            panel.orderFrontRegardless()
        }
        configureShortcutMonitor()
        installMediaKeyMonitor()
        installMouseInterception()
        observeDisplayChanges()
        if initialScreen == nil { scheduleScreenRetry() }
        // Give the run loop an opportunity to present the notch before
        // initializing speech locales, EventKit and filesystem watchers.
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.1) { [weak self] in
            guard let self else { return }
            self.model.startDeferredServices()
            self.shortcutCaptureObservation = self.model.preparedDictation?.$capturingShortcut.sink { [weak self] capturing in
                if capturing { self?.resetShiftKeyFeedback() }
            }
            if CommandLine.arguments.contains("--report-windows"), let dictation = self.model.preparedDictation {
                let access = dictation.access
                print("RIUM_AGENDA calendar_full=\(EKEventStore.authorizationStatus(for: .event) == .fullAccess) reminders_full=\(EKEventStore.authorizationStatus(for: .reminder) == .fullAccess)")
                print("RIUM_DICTATION accessibility=\(access.accessibility) speech=\(access.speech.rawValue) microphone=\(access.microphone.rawValue) input_monitoring=\(access.inputMonitoring) enabled=\(dictation.enabled) status=\(dictation.status)")
                fflush(stdout)
            }
        }
        if CommandLine.arguments.contains("--verify-reflow") {
            DispatchQueue.main.asyncAfter(deadline: .now() + 1) { [weak self] in
                guard let self = self else { return }
                let notchFrame = self.panel.frame
                NotificationCenter.default.post(name: NSApplication.didChangeScreenParametersNotification, object: NSApp)
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.3) { [weak self] in
                    guard let self = self else { return }
                    print("RIUM_REFLOW stable=\(self.panel.frame == notchFrame)")
                    fflush(stdout)
                }
            }
        }
        if CommandLine.arguments.contains("--report-windows") {
            print("RIUM_WINDOWS notch=\(panel.windowNumber) lighting=\(panel.windowNumber)")
            if let frame = NSScreen.main?.frame { print("RIUM_GEOMETRY screen=\(frame) panel=\(panel.frame)") }
            fflush(stdout)
            DispatchQueue.main.asyncAfter(deadline: .now() + 1) { [weak self] in
                if let frame = NSScreen.main?.frame, let panel = self?.panel { print("RIUM_GEOMETRY_READY screen=\(frame) panel=\(panel.frame)"); fflush(stdout) }
            }
        }
        if CommandLine.arguments.contains("--report-space-geometry") {
            // Short opt-in trace for a later Show Desktop / Space transition check.
            for sample in 0...20 {
                DispatchQueue.main.asyncAfter(deadline: .now() + Double(sample) * 0.5) { [weak self] in
                    guard let self = self, let screen = self.targetScreen(), let panel = self.panel else { return }
                    let lightVisible = panel.isVisible && !self.model.hoverSuspended
                    print("RIUM_SPACE sample=\(sample) screen=\(screen.frame) notch=\(panel.frame) notch_visible=\(panel.isVisible) notch_active_space=\(panel.isOnActiveSpace) light=\(panel.frame) light_visible=\(lightVisible) light_active_space=\(panel.isOnActiveSpace)")
                    fflush(stdout)
                }
            }
        }
        NotificationCenter.default.addObserver(forName: .notchSizeChanged, object: nil, queue: .main) { [weak self] _ in self?.updateMouseInterception(notifyHover: false) }
        NotificationCenter.default.addObserver(forName: .notchDisplayChanged, object: nil, queue: .main) { [weak self] _ in self?.reflowDisplays() }
        status = NSStatusBar.system.statusItem(withLength: NSStatusItem.variableLength)
        if let button = status.button {
            statusAppearanceObservation = button.observe(\.effectiveAppearance, options: [.initial, .new]) { [weak self, weak button] _, _ in
                DispatchQueue.main.async { [weak self, weak button] in
                    self?.model.menuBarIsLight = menuBarSurfaceIsLight(button?.effectiveAppearance)
                }
            }
        }
        if let url = Bundle.main.url(forResource: "AppIcon", withExtension: "icns"), let icon = NSImage(contentsOf: url) {
            icon.size = NSSize(width: 18, height: 18); icon.isTemplate = false; status.button?.image = icon
        } else { status.button?.title = "R" }
        let menu = NSMenu(); let showItem = NSMenuItem(title: "노치 표시", action: #selector(show), keyEquivalent: ""); showItem.target = self; menu.addItem(showItem)
        let switcherItem = NSMenuItem(title: "작업 전환", action: #selector(showAgentSwitcher), keyEquivalent: "")
        switcherItem.target = self; menu.addItem(switcherItem)
        let settingsItem = NSMenuItem(title: "설정…", action: #selector(showSettings), keyEquivalent: ""); settingsItem.target = self; menu.addItem(settingsItem)
        menu.addItem(NSMenuItem.separator()); menu.addItem(NSMenuItem(title: "Rium Notch 종료", action: #selector(NSApplication.terminate(_:)), keyEquivalent: "q")); status.menu = menu
    }
    private func targetScreen() -> NSScreen? {
        let screens = NSScreen.screens.filter { notchScreenFrameUsable($0.frame) }
        let ids = screens.compactMap(displayIdentifier)
        let primary = CGMainDisplayID()
        let preferred = preferredNotchDisplayID(key: model.preferredDisplayKey, available: model.availableDisplays)
        if let selected = resolvedDisplayID(preferred: preferred, available: ids, primary: primary),
           let screen = screens.first(where: { displayIdentifier($0) == selected }) {
            return screen
        }
        return screens.first
    }
    func setFloatingIslandEnabled(_ enabled: Bool) {
        guard floatingIslandEnabled != enabled else { return }
        model.invalidateRenderedNotchOutline()
        floatingIslandEnabled = enabled
        UserDefaults.standard.set(enabled, forKey: "rium.notch.floatingIsland")
        if !enabled { model.recordFloatingIslandGeometry(nil); model.floatingIslandPlacement = nil }
        reflowDisplays()
    }
    private func refreshFloatingIsland(screen: NSScreen, cutout: NotchCutoutGeometry) {
        guard floatingIslandEnabled, let displayID = displayIdentifier(screen), displayID != 0 else {
            model.recordFloatingIslandGeometry(nil)
            model.floatingIslandPlacement = nil
            return
        }
        let frame = screen.frame
        let topInset = max(0, frame.maxY - screen.visibleFrame.maxY)
        let menuHeight = max(cutout.height, min(64, max(topInset, NSStatusBar.system.thickness)))
        let bounds = FloatingIslandPositionBounds(screen: frame, menuHeight: menuHeight, virtualNotch: cutout.virtualNotch)
        let camera = cutout.width > 0
            ? CGRect(x: frame.midX - cutout.width / 2, y: frame.maxY - cutout.height, width: cutout.width, height: cutout.height) : nil
        let resolved = resolveFloatingIslandPlacement(displayID: displayID, bounds: bounds,
            camera: camera, previous: model.floatingIslandPlacement, positions: FloatingIslandPositions())
        if model.floatingIslandPlacement?.displayID != resolved?.displayID || model.floatingIslandPlacement?.bounds.screen != resolved?.bounds.screen {
            model.recordFloatingIslandGeometry(nil)
        }
        if model.floatingIslandPlacement != resolved { model.floatingIslandPlacement = resolved }
    }
    private func updateCordPanel(bringToFront: Bool = true, screen selectedScreen: NSScreen? = nil) {
        guard notchCanReflow(screenLocked: screenAccessBlocked, sleeping: displaySleeping),
              model.cordEnabled, !model.cordItems.isEmpty, let screen = selectedScreen ?? targetScreen() else {
            cordPanel?.orderOut(nil)
            model.cordMotion.stop()
            return
        }
        if cordPanel == nil {
            let cord = NSPanel(contentRect: .zero, styleMask: [.borderless, .nonactivatingPanel], backing: .buffered, defer: false)
            cord.isOpaque = false; cord.backgroundColor = .clear; cord.hasShadow = true
            cord.hidesOnDeactivate = false
            cord.ignoresMouseEvents = true
            cord.level = .statusBar
            cord.collectionBehavior = notchOverlayBehavior
            let hosting = NSHostingView(rootView: ScreenshotCordView(model: model, motion: model.cordMotion))
            hosting.sizingOptions = []
            cord.contentView = hosting
            cordPanel = cord
        }
        let frame = screen.visibleFrame
        let height = max(0, frame.height - 10)
        let capacity = rustScreenshotLineCapacity(Double(height))
        if capacity > 0 { model.cordCapacity = Int(capacity) }
        model.cordMotion.start(height: height, model: model)
        let cordFrame = NSRect(x: screen.frame.maxX - ScreenshotCordLayout.panelWidth,
                               y: frame.minY + 6, width: ScreenshotCordLayout.panelWidth, height: height)
        if let cordPanel, cordPanel.frame != cordFrame { cordPanel.setFrame(cordFrame, display: true) }
        if bringToFront || cordPanel?.isVisible == false { cordPanel?.orderFrontRegardless() }
        updateCordPointer()
    }
    private func updateEdgeWavePanel(bringToFront: Bool = true, screen selectedScreen: NSScreen? = nil) {
        guard notchCanReflow(screenLocked: screenAccessBlocked, sleeping: displaySleeping),
              !model.edgeWaves.isEmpty || !model.notchScreenWaves.isEmpty, let screen = selectedScreen ?? targetScreen() else {
            edgeWavePanel?.orderOut(nil)
            return
        }
        if edgeWavePanel == nil {
            let wave = NotchEffectPanel(contentRect: screen.frame, styleMask: [.borderless, .nonactivatingPanel], backing: .buffered, defer: false)
            wave.isOpaque = false; wave.backgroundColor = .clear; wave.hasShadow = false
            wave.hidesOnDeactivate = false; wave.ignoresMouseEvents = true
            wave.animationBehavior = .none
            wave.level = NSWindow.Level(rawValue: NSWindow.Level.statusBar.rawValue + 2)
            wave.collectionBehavior = notchOverlayBehavior
            let hosting = NSHostingView(rootView: FullScreenEdgeWave(model: model))
            hosting.sizingOptions = []
            wave.contentView = hosting
            edgeWavePanel = wave
        }
        if let edgeWavePanel, edgeWavePanel.frame != screen.frame {
            edgeWavePanel.setFrame(screen.frame, display: true)
        }
        if bringToFront || edgeWavePanel?.isVisible == false { edgeWavePanel?.orderFrontRegardless() }
    }
    private func alignNotchPanels(to screen: NSScreen) {
        let frame = screen.frame
        let displayID = displayIdentifier(screen)
        model.selectDisplay(displayID)
        let key = model.availableDisplays.first(where: { $0.id == displayID })?.key
        let safeTop = screen.safeAreaInsets.top
        let measuredWidth = cameraExclusionWidth(screen: frame, topInset: safeTop, left: screen.auxiliaryTopLeftArea, right: screen.auxiliaryTopRightArea)
        let cutout = notchCutoutCache.resolve(key: key, size: frame.size, scale: screen.backingScaleFactor,
                                             safeAreaTop: safeTop, measuredWidth: measuredWidth)
        let exclusion = cutout.width, cameraHeight = cutout.height
        if model.displayWidth != frame.width || model.displayHeight != frame.height || model.cameraExclusion != exclusion || model.cameraHeight != cameraHeight {
            model.invalidateRenderedNotchOutline()
        }
        if model.displayWidth != frame.width { model.displayWidth = frame.width }
        if model.displayHeight != frame.height { model.displayHeight = frame.height }
        if model.cameraExclusion != exclusion { model.cameraExclusion = exclusion }
        if model.cameraHeight != cameraHeight { model.cameraHeight = cameraHeight }
        refreshFloatingIsland(screen: screen, cutout: cutout)
        // Repeated Space notifications should not resize an aligned window.
        let floating = model.floatingIslandPlacement != nil
        // AppKit's window shadow adds a bright rim at the display's top edge.
        if panel.hasShadow != floating { panel.hasShadow = floating }
        let overlay = floating ? frame : notchOverlayFrame(screen: frame)
        if panel.frame != overlay { panel.setFrame(overlay, display: true, animate: false) }
    }

    func pointIsInsideNotch(_ point: NSPoint, screen selectedScreen: NSScreen? = nil) -> Bool {
        if let rendered = model.currentRenderedFloatingIslandGeometry { return rendered.contains(screenPoint: point) }
        if let island = model.floatingIslandGeometry { return island.contains(screenPoint: point) }
        guard let screen = (selectedScreen ?? targetScreen())?.frame else { return false }
        return notchContainsInteractivePoint(point, screen: screen, expanded: model.expanded, section: model.section,
                                             renderedSize: model.renderedNotchOutlineSize, renderedCorners: model.renderedNotchCorners,
                                             targetSize: model.currentNotchOutlineSize, targetCorners: model.currentNotchCorners)
    }
    private func pointIsInsideTargetNotch(_ point: NSPoint, screen selectedScreen: NSScreen? = nil) -> Bool {
        if let island = model.floatingIslandGeometry { return island.contains(screenPoint: point) }
        guard let screen = (selectedScreen ?? targetScreen())?.frame else { return false }
        return notchContainsScreenPoint(point, screen: screen, expanded: model.expanded, section: model.section,
                                        size: model.currentNotchOutlineSize, corners: model.currentNotchCorners)
    }
    private func updateCordPointer() {
        guard let cord = cordPanel, cord.isVisible, !screenAccessBlocked, !displaySleeping else { return }
        let point = NSEvent.mouseLocation
        let local = CGPoint(x: point.x - cord.frame.minX, y: cord.frame.maxY - point.y)
        let end = ScreenshotCordLayout.top + CGFloat(max(0, model.cordItems.count - 1)) * ScreenshotCordLayout.spacing + ScreenshotCordLayout.cardSize.height + 30
        let inLine = local.y >= 0 && local.y <= min(end, cord.frame.height)
        let onCard = model.cordMotion.cards.contains { $0.contains(local) }
        let inEdge = local.x >= ScreenshotCordLayout.panelWidth - 3 && local.x <= ScreenshotCordLayout.panelWidth && inLine
        let inExpandedArea = model.cordExpanded && local.x >= ScreenshotCordLayout.panelWidth - 228 && local.x <= ScreenshotCordLayout.panelWidth && inLine
        let now = ProcessInfo.processInfo.systemUptime
        if onCard || inEdge || inExpandedArea || model.cordMotion.isGrabbing { cordHoverUntil = now + 0.7 }
        let expanded = now < cordHoverUntil
        if model.cordExpanded != expanded { model.cordExpanded = expanded }
        let buttonDown = NSEvent.pressedMouseButtons != 0
        // Once AppKit owns the drag, the overlay must let it reach windows underneath.
        if model.cordMotion.systemDraggingURL != nil {
            cord.ignoresMouseEvents = true
        } else if !buttonDown {
            cord.ignoresMouseEvents = !onCard
        }
    }
    private func updateMouseInterception(notifyHover: Bool = true, screen selectedScreen: NSScreen? = nil, leftDrag: Bool = false) {
        guard panel != nil else { return }
        updateCordPointer()
        guard !screenAccessBlocked, !displaySleeping else {
            preparingDropEntry = false
            panel.ignoresMouseEvents = true
            return
        }
        let point = NSEvent.mouseLocation
        let inside = pointIsInsideNotch(point, screen: selectedScreen)
        let buttons = NSEvent.pressedMouseButtons
        let buttonDown = buttons != 0
        let ignoring = panel.ignoresMouseEvents || preparingDropEntry
        // WindowServer needs the panel ready before the first drag update inside the cutout.
        if !inside, ignoring, buttons & 1 != 0, leftDrag || preparingDropEntry,
           !model.expanded, model.floatingIslandPlacement == nil, let screen = (selectedScreen ?? targetScreen())?.frame {
            preparingDropEntry = notchContainsDropApproach(point, screen: screen, size: model.currentNotchOutlineSize,
                                                           corners: model.currentNotchCorners)
        } else {
            preparingDropEntry = false
        }
        if model.shelfOutgoingDragActive && !buttonDown { model.endShelfConfirmationDrag() }
        let decision = notchPointerDecision(inside: inside, wasInside: mouseInsideNotch,
            ignoring: ignoring, buttonDown: buttonDown, notifyHover: notifyHover, preparingDrop: preparingDropEntry)
        // Even if an earlier silent reflow updated mouseInsideNotch, preserve an
        // active drag until mouse-up before delivering an outside transition.
        let deferHoverExit = buttonDown && !ignoring && !inside
        let deferHoverEntry = buttonDown && inside && !model.expanded
        let expansionBlocked = decision.inside && model.hoverExpansionBlocked
        if inside && expansionBlocked { hoverDeferredForPreview = true; lastDeliveredHover = false }
        if !inside { hoverDeferredForPreview = false }
        let deferPreview = hoverPreviewDefersEntry(inside: decision.inside, blocked: expansionBlocked,
            wasDeferred: hoverDeferredForPreview, targetInside: pointIsInsideTargetNotch(point, screen: selectedScreen))
        if let hover = pendingNotchHoverChange(inside: decision.inside, lastDelivered: lastDeliveredHover, notifyHover: notifyHover && !deferHoverExit && !deferHoverEntry && !deferPreview) {
            lastDeliveredHover = hover
            if hover { hoverDeferredForPreview = false }
            model.handleHover(hover)
        }
        mouseInsideNotch = decision.inside
        if panel.ignoresMouseEvents != decision.ignoresMouse {
            panel.ignoresMouseEvents = decision.ignoresMouse
        }
    }
    private func reconcileHoverAfterSession() {
        guard panel != nil, !screenAccessBlocked, !displaySleeping else { return }
        lastDeliveredHover = !pointIsInsideNotch(NSEvent.mouseLocation)
        updateMouseInterception()
    }
    private func handlePointerEvent(_ event: NSEvent) {
        updateMouseInterception(leftDrag: event.type == .leftMouseDragged)
        if event.type == .leftMouseUp || event.type == .rightMouseUp || event.type == .otherMouseUp {
            // A local monitor can run before AppKit updates pressedMouseButtons.
            // Recheck after delivery so releasing outside cannot leave the
            // large transparent panel intercepting subsequent clicks.
            DispatchQueue.main.async { [weak self] in self?.updateMouseInterception() }
        }
    }
    private func installMouseInterception() {
        let events: NSEvent.EventTypeMask = [.mouseMoved, .leftMouseDragged, .rightMouseDragged, .otherMouseDragged, .leftMouseUp, .rightMouseUp, .otherMouseUp]
        globalMouseMonitor = NSEvent.addGlobalMonitorForEvents(matching: events) { [weak self] event in self?.handlePointerEvent(event) }
        localMouseMonitor = NSEvent.addLocalMonitorForEvents(matching: events) { [weak self] event in self?.handlePointerEvent(event); return event }
        // The original controller also polls every 0.08 s. This recovers when
        // an event is missed, including a mouse-up outside the panel.
        let timer = Timer(timeInterval: 0.08, repeats: true) { [weak self] _ in self?.updateMouseInterception() }
        RunLoop.main.add(timer, forMode: .common)
        pointerPollTimer = timer
        updateMouseInterception(notifyHover: false)
    }
    private func shortcutAction(for event: NSEvent) -> ShortcutAction? {
        guard event.type == .keyDown, !event.isARepeat else { return nil }
        if event.cgEvent?.getIntegerValueField(.eventSourceUserData) == riumPasteEventMarker { return nil }
        return shortcutActionForKey(keyCode: event.keyCode, characters: event.charactersIgnoringModifiers, flags: event.modifierFlags)
    }
    private func handleCaseKeyEvent(_ type: NSEvent.EventType, keyCode: UInt16, flags: NSEvent.ModifierFlags) {
        guard model.caseKeysEnabled else { return }
        let modifiers = flags.intersection([.shift, .control, .option, .command, .function])
        if !modifiers.contains(.shift) { shiftHoldWork?.cancel(); shiftHoldWork = nil; shiftConsumed = false; model.endShiftKeyPeek() }
        if type == .keyDown {
            if modifiers.contains(.shift) { shiftHoldWork?.cancel(); shiftHoldWork = nil; shiftConsumed = true; model.endShiftKeyPeek() }
            return
        }
        guard type == .flagsChanged else { return }
        if keyCode == 57 { model.showCaseKeyPeek(flags.contains(.capsLock) ? .capsOn : .capsOff) }
        if modifiers.contains(.shift) && modifiers != .shift {
            shiftHoldWork?.cancel(); shiftHoldWork = nil; shiftConsumed = true; model.endShiftKeyPeek()
        }
        guard (keyCode == 56 || keyCode == 60), modifiers == .shift, !shiftConsumed, shiftHoldWork == nil else { return }
        let work = DispatchWorkItem { [weak self] in
            guard let self = self else { return }
            self.shiftHoldWork = nil
            guard self.model.caseKeysEnabled, !self.shiftConsumed,
                  shortcutFeedbackAllowed(screenLocked: self.screenAccessBlocked, sleeping: self.displaySleeping, capturingShortcut: self.model.preparedDictation?.capturingShortcut == true),
                  NSEvent.modifierFlags.intersection([.shift, .control, .option, .command, .function]) == .shift else { return }
            self.shiftConsumed = true; self.model.showCaseKeyPeek(.shiftHeld)
        }
        shiftHoldWork = work
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.5, execute: work)
    }
    private func handleShortcutEvent(_ type: NSEvent.EventType, keyCode: UInt16, flags: NSEvent.ModifierFlags, action: ShortcutAction?) {
        handleCaseKeyEvent(type, keyCode: keyCode, flags: flags)
        if model.screenshotEnabled && type == .keyDown {
            if keyCode == 53 { model.screenshotMonitor.cancelShortcutCapture() }
            if action == .screenshotFull || action == .screenshotArea {
                if flags.contains(.control) { model.screenshotMonitor.cancelShortcutCapture() }
                else { model.screenshotMonitor.armShortcutCapture() }
            }
        }
        guard let action else { return }

        let preferences = UserDefaults.standard
        let lights = preferences.object(forKey: "rium.light.enabled") as? Bool ?? true
        let clipboardLight = preferences.object(forKey: "rium.light.clipboard") as? Bool ?? true
        let feedback = shortcutFeedback(action, previews: model.shortcutPeeksEnabled && shortcutActionEnabled(action),
                                        lights: lights, clipboardLight: clipboardLight)
        if action == .paste { model.handleClipboardPasteShortcut(feedback) }
        else if feedback == .preview { model.showShortcutPeek(action) }
    }
    private func resetShiftKeyFeedback() {
        shortcutMonitorGeneration &+= 1
        shiftHoldWork?.cancel(); shiftHoldWork = nil; shiftConsumed = false
        model.endShiftKeyPeek()
    }
    @objc private func showAgentSwitcher() {
        guard let panel, !screenAccessBlocked, !displaySleeping, model.beginAgentSwitcher() else { return }
        agentSwitcherTookActivation = !NSApp.isActive
        agentSwitcherPreviousKeyWindow = NSApp.keyWindow
        if agentSwitcherTookActivation { NSApp.activate(ignoringOtherApps: true) }
        panel.makeKeyAndOrderFront(nil)
    }

    fileprivate func closeAgentSwitcher(restoreFocus: Bool = true) {
        guard model.agentSwitcherVisible else { return }
        model.endAgentSwitcher()
        if panel?.isKeyWindow == true { panel.resignKey() }
        if restoreFocus && NSApp.isActive {
            if agentSwitcherTookActivation { NSApp.deactivate() }
            else if let prior = agentSwitcherPreviousKeyWindow, prior.isVisible, prior !== panel { prior.makeKey() }
        }
        agentSwitcherTookActivation = false
        agentSwitcherPreviousKeyWindow = nil
        if model.expanded { model.handleHover(pointIsInsideNotch(NSEvent.mouseLocation)) }
    }

    fileprivate func openSwitcherAgent(_ item: AgentActivity) {
        guard model.agentSwitcherVisible,
              model.externalAgentItems.contains(where: { $0.sessionKey == item.sessionKey }) else { return }
        let bundleIDs = item.source == "claude" ? ["com.anthropic.claudefordesktop"] : ["com.openai.codex", "com.openai.chat"]
        let workspace = NSWorkspace.shared
        guard let app = bundleIDs.lazy.compactMap(workspace.urlForApplication(withBundleIdentifier:)).first else {
            model.agentSwitcherNotice = "\(item.providerName) 앱을 찾을 수 없습니다."
            return
        }
        closeAgentSwitcher()
        if item.source == "codex", let thread = codexThreadURL(item.id) {
            workspace.open([thread], withApplicationAt: app, configuration: .init()) { _, _ in }
        } else {
            workspace.openApplication(at: app, configuration: .init()) { _, _ in }
        }
    }

    private func handleAgentSwitcherKey(_ key: AgentSwitcherKey) {
        switch key {
        case .open: showAgentSwitcher()
        case let .move(direction): model.moveAgentSwitcherSelection(by: direction)
        case .confirm:
            if let agent = model.selectedSwitcherAgent { openSwitcherAgent(agent) }
        case .cancel: closeAgentSwitcher()
        }
    }

    func configureShortcutMonitor() {
        if let monitor = globalShortcutMonitor { NSEvent.removeMonitor(monitor); globalShortcutMonitor = nil }
        if let monitor = localShortcutMonitor { NSEvent.removeMonitor(monitor); localShortcutMonitor = nil }
        resetShiftKeyFeedback()
        let preferences = UserDefaults.standard
        let pasteLight = (preferences.object(forKey: "rium.light.enabled") as? Bool ?? true)
            && (preferences.object(forKey: "rium.light.clipboard") as? Bool ?? true)
        let agentSwitcherShortcut = preferences.bool(forKey: agentSwitcherShortcutPreference)
        var events: NSEvent.EventTypeMask = [.keyDown]
        if model.caseKeysEnabled { events.insert(.flagsChanged) }
        if agentSwitcherShortcut || model.shortcutPeeksEnabled || model.caseKeysEnabled || pasteLight || model.screenshotEnabled {
            globalShortcutMonitor = NSEvent.addGlobalMonitorForEvents(matching: events) { [weak self] event in
                guard let self = self,
                      shortcutFeedbackAllowed(screenLocked: self.screenAccessBlocked, sleeping: self.displaySleeping, capturingShortcut: self.model.preparedDictation?.capturingShortcut == true) else { return }
                let action = self.shortcutAction(for: event), type = event.type, code = event.keyCode, flags = event.modifierFlags
                let opensSwitcher = agentSwitcherShortcut && type == .keyDown
                    && AgentSwitcherKey(code: code, flags: flags, repeated: event.isARepeat, active: false) == .open
                let generation = self.shortcutMonitorGeneration
                DispatchQueue.main.async { [weak self] in
                    guard let self = self, generation == self.shortcutMonitorGeneration,
                          shortcutFeedbackAllowed(screenLocked: self.screenAccessBlocked, sleeping: self.displaySleeping, capturingShortcut: self.model.preparedDictation?.capturingShortcut == true) else { return }
                    if opensSwitcher { self.showAgentSwitcher(); return }
                    self.handleShortcutEvent(type, keyCode: code, flags: flags, action: action)
                }
            }
        }
        localShortcutMonitor = NSEvent.addLocalMonitorForEvents(matching: events) { [weak self] event in
            if let self = self,
               shortcutFeedbackAllowed(screenLocked: self.screenAccessBlocked, sleeping: self.displaySleeping, capturingShortcut: self.model.preparedDictation?.capturingShortcut == true) {
                if event.type == .keyDown,
                   let key = AgentSwitcherKey(code: event.keyCode, flags: event.modifierFlags, repeated: event.isARepeat,
                                              active: self.model.agentSwitcherVisible && (event.window ?? NSApp.keyWindow) === self.panel),
                   key != .open || agentSwitcherShortcut {
                    self.handleAgentSwitcherKey(key)
                    return nil
                }
                self.handleShortcutEvent(event.type, keyCode: event.keyCode, flags: event.modifierFlags, action: self.shortcutAction(for: event))
            }
            return event
        }
    }
    private func installMediaKeyMonitor() {
        // shortcut: macOS may consume system-defined keys before AppKit monitors; verify on hardware.
        globalMediaKeyMonitor = NSEvent.addGlobalMonitorForEvents(matching: .systemDefined) { [weak self] event in
            guard let self = self, !self.screenAccessBlocked, !self.displaySleeping, event.type == .systemDefined,
                  let keyEvent = systemMediaKeyEvent(subtype: Int(event.subtype.rawValue), data: event.data1) else { return }
            let generation = self.shortcutMonitorGeneration
            DispatchQueue.main.async { [weak self] in
                guard let self = self, generation == self.shortcutMonitorGeneration,
                      !self.screenAccessBlocked, !self.displaySleeping else { return }
                self.model.observeSystemMediaKey(keyEvent)
            }
        }
        localMediaKeyMonitor = NSEvent.addLocalMonitorForEvents(matching: .systemDefined) { [weak self] event in
            if let self = self, !self.screenAccessBlocked, !self.displaySleeping, event.type == .systemDefined,
               let keyEvent = systemMediaKeyEvent(subtype: Int(event.subtype.rawValue), data: event.data1) {
                self.model.observeSystemMediaKey(keyEvent)
            }
            return event
        }
    }
    private func observeWorkspaceSessionChanges() {
        let workspace = NSWorkspace.shared
        for (name, inactive) in [(NSWorkspace.sessionDidResignActiveNotification, true),
                                 (NSWorkspace.sessionDidBecomeActiveNotification, false)] {
            workspaceObservers.append(workspace.notificationCenter.addObserver(forName: name, object: workspace, queue: .main) { [weak self] _ in
                guard let self, self.workspaceSessionInactive != inactive else { return }
                if !inactive { self.refreshScreenLockSnapshot() }
                self.setScreenAccess(locked: self.screenLocked, sessionInactive: inactive)
            })
        }
    }
    private func observeDisplayChanges() {
        screenObserver = NotificationCenter.default.addObserver(forName: NSApplication.didChangeScreenParametersNotification, object: nil, queue: .main) { [weak self] _ in self?.reflowDisplays() }
        let center = NSWorkspace.shared.notificationCenter
        for name in [NSWorkspace.activeSpaceDidChangeNotification, NSWorkspace.didWakeNotification,
                     NSWorkspace.willSleepNotification, NSWorkspace.screensDidSleepNotification,
                     NSWorkspace.screensDidWakeNotification] {
            workspaceObservers.append(center.addObserver(forName: name, object: nil, queue: .main) { [weak self] event in
                self?.handleWorkspaceDisplayEvent(event.name)
            })
        }
    }
    private func handleWorkspaceDisplayEvent(_ name: Notification.Name) {
        switch name {
        case NSWorkspace.screensDidSleepNotification:
            guard !screensSleeping else { return }
            screensSleeping = true
            model.setDictationScreenSleeping(true)
            suspendNotchPresentation()
        case NSWorkspace.willSleepNotification:
            workspaceSleeping = true
            suspendNotchPresentation()
            model.suspendMediaObservation()
            model.setSystemNotificationSleeping(true)
        case NSWorkspace.screensDidWakeNotification, NSWorkspace.didWakeNotification:
            if name == NSWorkspace.screensDidWakeNotification {
                if screensSleeping { model.clearTransientLights() }
                screensSleeping = false
            } else {
                workspaceSleeping = false
            }
            refreshScreenLockSnapshot()
            if name == NSWorkspace.didWakeNotification {
                model.refreshWallClock(forceRefresh: true)
                model.resumeMediaObservation()
                model.setSystemNotificationSleeping(false)
            } else {
                model.setDictationScreenSleeping(false)
            }
            model.setHoverSuspended(screenAccessBlocked || displaySleeping)
            scheduleSpaceResync()
            reconcileHoverAfterSession()
        default:
            scheduleSpaceResync()
        }
    }
    private func suspendNotchPresentation() {
        // Discard delayed Space resyncs from before sleep; wake schedules new ones.
        spaceResyncGeneration &+= 1
        resetShiftKeyFeedback()
        closeAgentSwitcher(restoreFocus: false)
        if model.screenshotEnabled { model.screenshotMonitor.cancelShortcutCapture() }
        model.setHoverSuspended(true)
        if panel?.isVisible == true { panel.orderOut(nil) }
        updateMouseInterception()
        updateCordPanel()
        updateEdgeWavePanel()
    }
    private func observeScreenLock() {
        let center = DistributedNotificationCenter.default()
        for (name, locked) in [("com.apple.screenIsLocked", true), ("com.apple.screenIsUnlocked", false)] {
            let observer = center.addObserver(forName: Notification.Name(name), object: nil, queue: .main) { [weak self] _ in
                self?.setScreenLocked(locked)
            }
            screenLockObservers.append(observer)
        }
        refreshScreenLockSnapshot()
    }
    private func refreshScreenLockSnapshot() {
        // shortcut: this session-dictionary key is used by the reference but is not a documented public key.
        if let session = CGSessionCopyCurrentDictionary() as? [String: Any], let locked = session["CGSSessionScreenIsLocked"] as? Bool {
            setScreenLocked(locked)
        }
    }
    private func setScreenLocked(_ locked: Bool) {
        setScreenAccess(locked: locked, sessionInactive: workspaceSessionInactive)
    }
    private func setScreenAccess(locked: Bool, sessionInactive: Bool) {
        let wasBlocked = screenAccessBlocked
        let leavingSession = sessionInactive && !workspaceSessionInactive
        screenLocked = locked
        workspaceSessionInactive = sessionInactive
        if leavingSession { model.clearSystemNotificationPeek() }
        guard screenAccessBlocked != wasBlocked else { return }
        model.setSystemNotificationScreenLocked(screenAccessBlocked)
        if screenAccessBlocked {
            suspendNotchPresentation()
        } else {
            model.setHoverSuspended(displaySleeping)
            scheduleSpaceResync()
            reconcileHoverAfterSession()
        }
    }
    private func scheduleSpaceResync() {
        guard notchCanReflow(screenLocked: screenAccessBlocked, sleeping: displaySleeping) else { return }
        spaceResyncGeneration &+= 1
        let generation = spaceResyncGeneration
        reflowDisplays(bringToFront: false)
        // The reference refreshes geometry without raising the panel at 0,
        // 0.18 and 0.60 s, then raises it once after the last 0.42 s interval.
        for (delay, bringToFront) in [(0.18, false), (0.60, false), (1.02, true)] {
            DispatchQueue.main.asyncAfter(deadline: .now() + delay) { [weak self] in
                guard let self = self, self.spaceResyncGeneration == generation else { return }
                self.reflowDisplays(bringToFront: bringToFront)
            }
        }
    }
    private func scheduleScreenRetry() {
        guard screenRetry == nil, notchCanReflow(screenLocked: screenAccessBlocked, sleeping: displaySleeping) else { return }
        let work = DispatchWorkItem { [weak self] in
            guard let self else { return }
            self.screenRetry = nil
            self.reflowDisplays(bringToFront: false)
        }
        screenRetry = work
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.5, execute: work)
    }

    private func reflowDisplays(bringToFront: Bool = true) {
        guard panel != nil, notchCanReflow(screenLocked: screenAccessBlocked, sleeping: displaySleeping) else { return }
        model.refreshDisplayChoices()
        guard let screen = targetScreen() else { scheduleScreenRetry(); return }
        screenRetry?.cancel(); screenRetry = nil
        alignNotchPanels(to: screen)
        updateMouseInterception(notifyHover: false, screen: screen)
        if bringToFront || !panel.isVisible { panel.orderFrontRegardless() }
        // shortcut: the separate effect panels are Rium's implementation;
        // their Space transition order has not been compared with the reference.
        updateCordPanel(bringToFront: bringToFront, screen: screen)
        updateEdgeWavePanel(bringToFront: bringToFront, screen: screen)
        if CommandLine.arguments.contains("--report-windows") { print("RIUM_REFLOW_EVENT notch=\(panel.frame) lighting=\(panel.frame)"); fflush(stdout) }
    }
    @objc func show() { reflowDisplays() }
    func applicationDidResignActive(_ notification: Notification) {
        closeAgentSwitcher(restoreFocus: false)
    }
    private func showInterviewWindow() {
        if interviewWindow == nil {
            let window = NSPanel(contentRect: NSRect(x: 0, y: 0, width: 500, height: 560),
                                 styleMask: [.titled, .closable, .resizable, .utilityWindow], backing: .buffered, defer: false)
            window.title = "면접 코파일럿"; window.isReleasedWhenClosed = false
            window.minSize = NSSize(width: 340, height: 300)
            window.level = .floating; window.hidesOnDeactivate = false
            window.collectionBehavior = [.canJoinAllSpaces, .fullScreenAuxiliary, .canJoinAllApplications]
            window.sharingType = .none
            window.contentView = NSHostingView(rootView: InterviewView(model: model, interview: model.interview,
                suggestions: model.interview.suggestions, detached: true).padding(16).preferredColorScheme(.dark))
            window.center()
            interviewWindow = window
            interviewWindowObserver = NotificationCenter.default.addObserver(forName: NSWindow.willCloseNotification,
                object: window, queue: .main) { [weak self] _ in self?.model.interviewDetached = false }
        }
        model.interviewDetached = true
        interviewWindow?.makeKeyAndOrderFront(nil)
        NSApp.activate(ignoringOtherApps: true)
    }
    private func returnInterviewToNotch() {
        interviewWindow?.close()
        model.interviewDetached = false
    }
    @objc func showSettings() {
        presentSettings(page: nil)
    }
    fileprivate func presentSettings(page: SettingsPage?) {
        if settingsWindow == nil {
            let window = NSWindow(contentRect: NSRect(x: 0, y: 0, width: 1080, height: 780), styleMask: [.titled, .closable, .miniaturizable, .fullSizeContentView], backing: .buffered, defer: false)
            window.title = "Rium Notch 설정"; window.center(); window.isReleasedWhenClosed = false
            window.titleVisibility = .hidden; window.titlebarAppearsTransparent = true
            window.contentView = NSHostingView(rootView: SettingsView(model: model, initialPage: page?.rawValue)); settingsWindow = window
            if CommandLine.arguments.contains("--report-windows") { print("RIUM_SETTINGS window=\(window.windowNumber)"); fflush(stdout) }
        } else if let page, let hosting = settingsWindow?.contentView as? NSHostingView<SettingsView> {
            hosting.rootView.navigate(to: page)
        }
        settingsWindow?.makeKeyAndOrderFront(nil); NSApp.activate(ignoringOtherApps: true)
    }
    func applicationDidBecomeActive(_ notification: Notification) {
        guard model.deferredServicesStarted else { return }
        model.agenda.refreshIfAuthorizationChanged(); model.dictation.restoreIfAuthorized()
        model.refreshTimerNotificationPermission(); model.refreshAgentNotificationPermission(); model.musicSpectrum.retryIfAuthorized()
    }
    func applicationWillTerminate(_ notification: Notification) {
        spaceResyncGeneration &+= 1
        screenRetry?.cancel(); screenRetry = nil
        model.observeBrightness(on: nil)
        if model.deferredServicesStarted { model.airDropSendWatcher.stop() }
        model.stopMediaWatching()
        model.stopSystemNotifications()
        model.assistant.disconnect()
        model.assistant.flushHistory()
        model.voiceApproval.cancel()
        if model.interview.suggestions.busy { model.interview.suggestions.cancel() }
        model.interview.stop()
        model.stopAgentWatching()
        model.musicSpectrum.stop()
        model.teleprompter.flush()
        model.notes.finishEditing()
        model.flushClipboard()
        model.flushShelf()
        model.preparedDictation?.disable(persist: false)
        if let screenObserver = screenObserver { NotificationCenter.default.removeObserver(screenObserver) }
        if let interviewWindowObserver = interviewWindowObserver { NotificationCenter.default.removeObserver(interviewWindowObserver) }
        for observer in menuTrackingObservers { NotificationCenter.default.removeObserver(observer) }
        pointerPollTimer?.invalidate()
        shiftHoldWork?.cancel()
        if let monitor = globalMouseMonitor { NSEvent.removeMonitor(monitor) }
        if let monitor = localMouseMonitor { NSEvent.removeMonitor(monitor) }
        if let monitor = globalShortcutMonitor { NSEvent.removeMonitor(monitor) }
        if let monitor = localShortcutMonitor { NSEvent.removeMonitor(monitor) }
        if let monitor = globalMediaKeyMonitor { NSEvent.removeMonitor(monitor) }
        if let monitor = localMediaKeyMonitor { NSEvent.removeMonitor(monitor) }
        for observer in workspaceObservers { NSWorkspace.shared.notificationCenter.removeObserver(observer) }
        for observer in screenLockObservers { DistributedNotificationCenter.default().removeObserver(observer) }
    }
}

private func publishedReceiveFixture(_ file: URL) -> Progress {
    let progress = Progress(parent: nil, userInfo: [
        .fileURLKey: file, .fileOperationKindKey: Progress.FileOperationKind.receiving.rawValue
    ])
    progress.kind = .file
    progress.totalUnitCount = 100
    progress.isCancellable = true
    progress.publish()
    return progress
}

if CommandLine.arguments.contains("--self-test-helper-pipe") {
    let pipe = Pipe()
    guard suppressBrokenPipeSignal(pipe.fileHandleForWriting) else { fatalError("pipe signal setup failed") }
    try pipe.fileHandleForReading.close()
    do {
        try pipe.fileHandleForWriting.write(contentsOf: Data([1]))
        fatalError("writing to a closed pipe unexpectedly succeeded")
    } catch { try? pipe.fileHandleForWriting.close() }
    for command in ["agent-followup", "agent-answer", "agent-interrupt", "claude-interrupt"] {
        let failure = helperFailureAfterLaunch([command], message: "fixture")
        guard failure["event"] as? String == "error", (failure["data"] as? [String: Any])?["status"] as? String == "unknown" else { fatalError("ambiguous helper result was not retained") }
    }
    precondition(helperFailureAfterLaunch(["weather"], message: "fixture")["data"] == nil)
    precondition(helperFailureAfterLaunch(["media", "get"], message: "fixture")["data"] == nil)
    let mediaFailure = helperFailureAfterLaunch(["media", "toggle"], message: "fixture")
    precondition((mediaFailure["data"] as? [String: Any])?["status"] as? String == "unknown")
    precondition((mediaFailure["message"] as? String)?.contains("전달 여부를 확인할 수 없습니다") == true)
    let eventGate = HelperEventGate()
    precondition(eventGate.accepts("login_url") && !eventGate.terminal)
    precondition(eventGate.accepts("result") && eventGate.terminal)
    precondition(!eventGate.accepts("error") && !eventGate.accepts("result") && !eventGate.accepts("login_url"))
    let timedOutGate = HelperEventGate()
    precondition(timedOutGate.accepts("error") && !timedOutGate.accepts("result"))
    print("helper pipe failure self-test passed")
} else if CommandLine.arguments.contains("--self-test-assistant-controller") {
    final class FakeAssistantTransport: AssistantTransport {
        var onEvent: ((Data, TimeInterval) -> Void)?
        var onDisconnect: (() -> Void)?
        var sent: [[String: Any]] = []
        func connect() throws {}
        func send(_ object: [String: Any]) throws { sent.append(object) }
        func disconnect() {}
        func emit(_ object: [String: Any], receivedAt: TimeInterval = ProcessInfo.processInfo.systemUptime) throws {
            onEvent?(try JSONSerialization.data(withJSONObject: object), receivedAt)
        }
    }
    let transport = FakeAssistantTransport(), assistant = AssistantController(connection: transport)
    var completedMessages = 0
    assistant.onMessageCompleted = { _ in completedMessages += 1 }
    assistant.connect(workingDirectory: URL(fileURLWithPath: "/tmp", isDirectory: true))
    guard transport.sent.first?["method"] as? String == "initialize" else { fatalError("assistant initialization missing") }
    try transport.emit(["id": 1, "result": [:]])
    guard transport.sent.last?["method"] as? String == "thread/start" else { fatalError("assistant thread start missing") }
    try transport.emit(["id": 2, "result": ["thread": ["id": "thread"]]])
    guard assistant.phase == .ready else { fatalError("assistant thread did not become ready") }
    assistant.draft = "hello"; assistant.send("hello")
    try transport.emit(["method": "item/started", "params": ["threadId": "thread", "turnId": "turn", "item": ["type": "webSearch", "id": "early-tool"]]],
                       receivedAt: max(0, ProcessInfo.processInfo.systemUptime - 2))
    try transport.emit(["method": "item/agentMessage/delta", "params": ["threadId": "thread", "turnId": "turn", "itemId": "item", "delta": "hi"]])
    try transport.emit(["id": "foreign", "method": "item/commandExecution/requestApproval", "params": ["threadId": "thread", "turnId": "other"]])
    try transport.emit(["id": "approval", "method": "item/commandExecution/requestApproval", "params": ["threadId": "thread", "turnId": "turn"]])
    guard assistant.requests.count == 2, !assistant.stopping, !assistant.canRespond(to: assistant.requests[1].id) else { fatalError("early assistant requests were not held safely") }
    guard personalAssistantIndicator(phase: assistant.phase, requests: assistant.requests) == .approval else { fatalError("assistant approval indicator missing") }
    try transport.emit(["id": 3, "result": ["turn": ["id": "turn"]]])
    guard assistant.requests.count == 1, assistant.canRespond(to: assistant.requests[0].id), assistant.toolRunning,
          assistant.toolBeatAt == nil else { fatalError("assistant did not bind early tool safely") }
    try transport.emit(["method": "item/completed", "params": ["threadId": "thread", "turnId": "turn", "item": ["type": "webSearch", "id": "early-tool"]]])
    guard !assistant.toolRunning else { fatalError("early tool completion was missed") }
    try transport.emit(["method": "item/started", "params": ["threadId": "thread", "turnId": "other", "item": ["type": "commandExecution", "id": "foreign-tool"]]])
    guard !assistant.toolRunning else { fatalError("foreign tool changed assistant light state") }
    let toolReceivedAt = ProcessInfo.processInfo.systemUptime
    try transport.emit(["method": "item/started", "params": ["threadId": "thread", "turnId": "turn", "item": ["type": "commandExecution", "id": "tool"]]], receivedAt: toolReceivedAt)
    guard assistant.toolRunning, assistant.toolBeatAt == toolReceivedAt else { fatalError("assistant tool start was missed") }
    try transport.emit(["method": "item/completed", "params": ["threadId": "thread", "turnId": "turn", "item": ["type": "commandExecution", "id": "tool"]]])
    guard !assistant.toolRunning else { fatalError("assistant tool completion was missed") }
    try transport.emit(["method": "item/started", "params": ["threadId": "thread", "turnId": "turn", "item": ["type": "commandExecution", "id": "tool"]]])
    guard !assistant.toolRunning, assistant.toolBeatAt == toolReceivedAt else { fatalError("late start revived a completed tool") }
    try transport.emit(["id": "late-foreign", "method": "item/commandExecution/requestApproval", "params": ["threadId": "thread", "turnId": "other"]])
    guard assistant.requests.count == 1 else { fatalError("assistant accepted a request for another turn") }
    try assistant.respond(to: assistant.requests[0].id, action: 0)
    guard let decision = transport.sent.last?["result"] as? [String: Any], decision["decision"] as? String == "decline",
          assistant.requests[0].isSubmitted, personalAssistantIndicator(phase: assistant.phase, requests: assistant.requests) == .working else { fatalError("assistant approval response did not preserve the pending request") }
    let light = combinedAgentLightState([], assistant: .question)
    guard light.active, light.waiting, light.question, !light.acting,
          !combinedAgentLightState([], assistant: .off).active,
          combinedAgentLightState([], assistant: .off, assistantSpeaking: true).active,
          !combinedAgentLightState([], assistant: .off, assistantSpeaking: true).acting,
          combinedAgentLightState([], assistant: .question, assistantSpeaking: true).question,
          combinedAgentLightState([], assistant: .working, assistantToolRunning: true).acting,
          !combinedAgentLightState([], assistant: .question, assistantToolRunning: true).acting,
          !combinedAgentLightState([], assistant: .off, assistantToolRunning: true).acting else { fatalError("assistant light priority failed") }
    guard assistantTerminalLight(outcome: "completed", status: "응답 완료") == .agentDone,
          assistantTerminalLight(outcome: "completed", status: "전송 실패") == nil else { fatalError("assistant completion cue mismatch") }
    let optionParameters: [String: Any] = ["questions": [["id": "q", "options": [["label": "선택", "description": "선택 설명"]]]]]
    guard assistantRequestTitle("item/tool/requestUserInput") == "답변 요청",
          assistantOptionDescription(parameters: optionParameters, questionID: "q", index: 0, label: "선택") == "선택 설명",
          assistantOptionDescription(parameters: optionParameters, questionID: "q", index: 0, label: "다른 선택") == nil else { fatalError("assistant question presentation failed") }
    var assistantScroll = AssistantScrollTracker()
    precondition(assistantScroll.update(AssistantScrollMeasurement(bottom: 100, contentHeight: 100), viewportHeight: 100))
    precondition(assistantScroll.update(AssistantScrollMeasurement(bottom: 150, contentHeight: 150), viewportHeight: 100))
    precondition(!assistantScroll.update(AssistantScrollMeasurement(bottom: 100, contentHeight: 150), viewportHeight: 100) && assistantScroll.following)
    precondition(!assistantScroll.update(AssistantScrollMeasurement(bottom: 145, contentHeight: 150), viewportHeight: 100) && !assistantScroll.following)
    precondition(!assistantScroll.update(AssistantScrollMeasurement(bottom: 165, contentHeight: 170), viewportHeight: 100) && !assistantScroll.following)
    precondition(!assistantScroll.update(AssistantScrollMeasurement(bottom: 100, contentHeight: 170), viewportHeight: 100) && assistantScroll.following)
    precondition(!assistantScroll.update(AssistantScrollMeasurement(bottom: .nan, contentHeight: 170), viewportHeight: 100))
    try transport.emit(["method": "serverRequest/resolved", "params": ["threadId": "thread", "requestId": "approval"]])
    guard assistant.phase == .running, assistant.messages.last?.text == "hi", assistant.requests.isEmpty, assistant.draft.isEmpty else { fatalError("assistant early stream or request handling failed") }
    guard completedMessages == 0 else { fatalError("streaming assistant text triggered a completion cue") }
    let messageCompletion: [String: Any] = ["method": "item/completed", "params": ["threadId": "thread", "turnId": "turn", "item": ["type": "agentMessage", "id": "item", "text": "hi"]]]
    try transport.emit(messageCompletion); try transport.emit(messageCompletion)
    guard completedMessages == 1 else { fatalError("assistant completion cue was missing or duplicated") }
    try transport.emit(["id": "question", "method": "item/tool/requestUserInput", "params": ["threadId": "thread", "turnId": "turn", "questions": [["id": "secret", "question": "?", "isSecret": true]]]])
    guard assistant.requests.first?.preview == nil, personalAssistantIndicator(phase: assistant.phase, requests: assistant.requests) == .question else { fatalError("unsupported assistant question indicator missing") }
    try transport.emit(["method": "serverRequest/resolved", "params": ["threadId": "thread", "requestId": "question"]])
    for index in 0..<32 {
        try transport.emit(["id": "batch-\(index)", "method": "item/commandExecution/requestApproval", "params": ["threadId": "thread", "turnId": "turn"]])
    }
    try transport.emit(["id": "batch-0", "method": "item/commandExecution/requestApproval", "params": ["threadId": "thread", "turnId": "turn"]])
    try transport.emit(["id": "foreign-overflow", "method": "item/commandExecution/requestApproval", "params": ["threadId": "thread", "turnId": "other"]])
    guard assistant.requests.count == 32, !assistant.requestOverflow else { fatalError("duplicate or foreign request triggered overflow") }
    try transport.emit(["id": "overflow", "method": "item/commandExecution/requestApproval", "params": ["threadId": "thread", "turnId": "turn"]])
    for index in 0..<32 {
        try transport.emit(["method": "serverRequest/resolved", "params": ["threadId": "thread", "requestId": "batch-\(index)"]])
    }
    guard assistant.requests.isEmpty, assistant.requestOverflow,
          personalAssistantIndicator(phase: assistant.phase, requests: assistant.requests, overflow: assistant.requestOverflow) == .approval else { fatalError("unretained request was hidden") }
    assistant.interrupt()
    guard assistant.stopping, transport.sent.last?["method"] as? String == "turn/interrupt" else { fatalError("assistant interruption missing") }
    try transport.emit(["method": "turn/completed", "params": ["threadId": "thread", "turn": ["id": "turn", "status": "interrupted"]]])
    try transport.emit(["id": 4, "result": [:]])
    guard assistant.phase == .ready, !assistant.stopping, !assistant.requestOverflow else { fatalError("late interruption reply relocked assistant") }
    assistant.draft = "retry"; assistant.send("retry")
    try transport.emit(["id": 5, "error": ["code": -1]])
    guard assistant.phase == .ready, assistant.draft == "retry", assistant.messages.last?.text == "hi" else { fatalError("rejected assistant message lost the draft") }
    assistant.disconnect()
    assistant.connect(workingDirectory: URL(fileURLWithPath: "/tmp", isDirectory: true))
    try transport.emit(["id": 6, "result": [:]])
    guard transport.sent.last?["method"] as? String == "thread/resume" else { fatalError("assistant did not resume its existing thread") }
    try transport.emit(["id": 7, "result": ["thread": ["id": "thread", "status": ["type": "idle"]]]])
    guard assistant.phase == .ready, assistant.messages.last?.text == "hi" else { fatalError("assistant history did not survive reconnect") }
    assistant.send("recover")
    try transport.emit(["method": "turn/started", "params": ["threadId": "thread", "turn": ["id": "recovered-turn"]]])
    transport.onDisconnect?()
    guard assistant.phase == .uncertain else { fatalError("lost assistant connection was not marked uncertain") }
    assistant.disconnect()
    assistant.connect(workingDirectory: URL(fileURLWithPath: "/tmp", isDirectory: true))
    try transport.emit(["id": 9, "result": [:]])
    try transport.emit(["id": 10, "result": ["thread": ["id": "thread", "status": ["type": "idle"]]]])
