    guard assistant.phase == .ready, assistant.messages.last?.text == "recovered" else { fatalError("assistant turn recovery failed") }
    assistant.draft = "no-turn"; assistant.send("no-turn")
    guard let sentParams = transport.sent.last?["params"] as? [String: Any], let clientID = sentParams["clientUserMessageId"] as? String else { fatalError("assistant client message id missing") }
    transport.onDisconnect?(); assistant.disconnect()
    assistant.connect(workingDirectory: URL(fileURLWithPath: "/tmp", isDirectory: true))
    try transport.emit(["id": 13, "result": [:]])
    try transport.emit(["id": 14, "result": ["thread": ["id": "thread", "status": ["type": "idle"]]]])
    try transport.emit(["id": 15, "result": ["thread": ["id": "thread", "status": ["type": "idle"], "turns": [["id": "found-turn", "status": "completed", "itemsView": "full", "items": [["type": "userMessage", "clientId": clientID], ["type": "agentMessage", "id": "next", "text": "found"]]]]]]])
