        guard assistant.messages.last?.text == "found" else { fatalError("assistant removed another conversation's history") }
        assistant.removeTurnHistory(messageID: answer.id, conversationID: assistant.activeConversationID)
        guard !assistant.messages.contains(where: { $0.text == "found" || $0.text == "no-turn" }),
