    let fallbackTransport = FakeAssistantTransport(), fallbackAssistant = AssistantController(connection: fallbackTransport)
    var fallbackCues = 0, completedTurns = 0, completedText = ""
    var speechUpdates: [(String, String, Bool)] = []
    fallbackAssistant.onMessageUpdate = { speechUpdates.append(($0, $1, $2)) }
    fallbackAssistant.onMessageCompleted = { text in fallbackCues += 1; completedText = text }
    fallbackAssistant.onTurnCompleted = { completedTurns += 1 }
    fallbackAssistant.connect(workingDirectory: URL(fileURLWithPath: "/tmp", isDirectory: true))
    try fallbackTransport.emit(["id": 1, "result": [:]])
