    try fallbackTransport.emit(["method": "item/agentMessage/delta", "params": ["threadId": "fallback-thread", "turnId": "fallback-turn", "itemId": "fallback-item", "delta": "hi"]])
    let fastCompletion: [String: Any] = ["method": "turn/completed", "params": ["threadId": "fallback-thread", "turn": ["id": "fallback-turn", "status": "completed"]]]
    try fallbackTransport.emit(fastCompletion); try fallbackTransport.emit(fastCompletion)
    guard fallbackCues == 1, completedText == "hi", completedTurns == 1, fallbackAssistant.phase == .ready,
