    let afterFailure = try saved()
    precondition(store.dirty && !store.error.isEmpty && afterFailure.first?.title == "작업 메모")
    store.update(note, title: "제목 수정")
    store.finishEditing()
    let afterRetry = try saved()
    precondition(!store.dirty && store.error.isEmpty && afterRetry.first?.title == "제목 수정" && afterRetry.first?.text == latest)

    let empty = store.create()!
    store.finishEditing()
    precondition(!store.entries.contains { $0.id == empty })
