    provider.loadDataRepresentation(forTypeIdentifier: UTType.png.identifier) { data, error in
        precondition(error == nil && data == png)
        finished.signal()
    }
    let timeout = Date().addingTimeInterval(2)
    while finished.wait(timeout: .now()) != .success {
        precondition(Date() < timeout, "clipboard image drag timed out")
        RunLoop.current.run(until: Date().addingTimeInterval(0.01))
    }
