            sessionItems.append(items)
        }
    }

    _ = NSApplication.shared
    let urls = ["먼저.pdf", "두 번째.txt", "참고.png"].map { URL(fileURLWithPath: "/tmp/\($0)") }
    let window = NSWindow(contentRect: NSRect(x: 0, y: 0, width: 160, height: 44),
                          styleMask: .borderless, backing: .buffered, defer: false)
    let view = TestDragView(frame: window.contentView!.bounds)
    window.contentView = view
    view.urls = urls
    var clicks = 0
    view.onClick = { clicks += 1 }
    func event(_ type: NSEvent.EventType, x: CGFloat) -> NSEvent {
        NSEvent.mouseEvent(with: type, location: NSPoint(x: x, y: 16), modifierFlags: [],
                          timestamp: ProcessInfo.processInfo.systemUptime, windowNumber: window.windowNumber,
                          context: nil, eventNumber: 0, clickCount: 1, pressure: 1)!
    }
    view.mouseDown(with: event(.leftMouseDown, x: 24))
    view.mouseDragged(with: event(.leftMouseDragged, x: 26))
    view.mouseUp(with: event(.leftMouseUp, x: 26))
    precondition(clicks == 1 && view.sessionItems.isEmpty)
    view.mouseDown(with: event(.leftMouseDown, x: 24))
    view.mouseDragged(with: event(.leftMouseDragged, x: 45))
    view.mouseDragged(with: event(.leftMouseDragged, x: 52))
    view.mouseUp(with: event(.leftMouseUp, x: 52))
