    defer { board.releaseGlobally() }
    precondition(board.writeObjects(writers))
    let received = board.readObjects(forClasses: [NSURL.self], options: [.urlReadingFileURLsOnly: true]) as? [URL]
    precondition(received == urls, "native receiver lost a grouped file")
