    notchAnimationProbe.removeAll()
    let start = model.currentNotchOutlineSize
    model.expanded = true
    let end = model.currentNotchOutlineSize
    RunLoop.current.run(until: Date().addingTimeInterval(0.6))
    let opening = notchAnimationProbe.filter { $0.width > start.width + 5 && $0.width < end.width - 5 && $0.height > start.height + 2 && $0.height < end.height - 2 }
    notchAnimationProbe.removeAll()
    model.expanded = false
    RunLoop.current.run(until: Date().addingTimeInterval(0.6))
    let closing = notchAnimationProbe.filter { $0.width > start.width + 5 && $0.width < end.width - 5 && $0.height > start.height + 2 && $0.height < end.height - 2 }
    guard !opening.isEmpty, !closing.isEmpty else { fatalError("notch shape did not interpolate: open=\(opening.count) close=\(closing.count) samples=\(notchAnimationProbe.prefix(12))") }
    let accentDeadline = Date(timeIntervalSinceNow: 0.45)
    while !model.closedAgentAccentReady && Date() < accentDeadline {
        RunLoop.current.run(until: Date(timeIntervalSinceNow: 0.01))
    }
    guard model.closedAgentAccentReady else {
        fatalError("mounted notch did not restore its closed accent: rendered=\(String(describing: model.renderedNotchOutlineSize)) target=\(model.currentNotchOutlineSize)")
    }
    let accentFixture = Model(startServices: false)
    accentFixture.expanded = true
    accentFixture.noteRenderedNotchOutline(accentFixture.currentNotchOutlineSize, corners: accentFixture.currentNotchCorners)
    accentFixture.expanded = false
    RunLoop.current.run(until: Date(timeIntervalSinceNow: 0.08))
    precondition(!accentFixture.closedAgentAccentReady, "closed accent appeared while the outline was still wide")
    accentFixture.noteRenderedNotchOutline(accentFixture.currentNotchOutlineSize, corners: accentFixture.currentNotchCorners)
    precondition(!accentFixture.closedAgentAccentReady, "closed accent appeared on the settling frame")
    accentFixture.expanded = true
    accentFixture.noteRenderedNotchOutline(accentFixture.currentNotchOutlineSize, corners: accentFixture.currentNotchCorners)
    accentFixture.expanded = false
    RunLoop.current.run(until: Date(timeIntervalSinceNow: 0.08))
    precondition(!accentFixture.closedAgentAccentReady, "a previous close restored the current accent")
    accentFixture.noteRenderedNotchOutline(accentFixture.currentNotchOutlineSize, corners: accentFixture.currentNotchCorners)
    RunLoop.current.run(until: Date(timeIntervalSinceNow: 0.1))
    precondition(accentFixture.closedAgentAccentReady, "closed accent did not restore after the outline settled")
    print("notch animation intermediate shapes: open=\(opening.count) close=\(closing.count)")
    print("closed accent waited for the outline and ignored an interrupted close")

    func clickNotch(at x: CGFloat) {
        for type: NSEvent.EventType in [.leftMouseDown, .leftMouseUp] {
            let event = NSEvent.mouseEvent(with: type, location: NSPoint(x: x, y: view.frame.height - 13), modifierFlags: [],
                timestamp: ProcessInfo.processInfo.systemUptime, windowNumber: window.windowNumber, context: nil, eventNumber: 0, clickCount: 1, pressure: 1)!
            window.sendEvent(event)
            RunLoop.current.run(until: Date().addingTimeInterval(0.005))
        }
    }
    model.hoverEnabled = false
    model.expanded = true
    RunLoop.current.run(until: Date().addingTimeInterval(0.5))
    notchAnimationProbe.removeAll()
    model.expanded = false
    let closeDeadline = Date().addingTimeInterval(0.4)
    var collapsing: CGSize?
    repeat {
        RunLoop.current.run(until: Date().addingTimeInterval(0.005))
        collapsing = notchAnimationProbe.last { $0.width > start.width + 30 && $0.width < end.width - 5 }
    } while collapsing == nil && Date() < closeDeadline
    guard let collapsing else { fatalError("expected a drawn shrinking wing: \(notchAnimationProbe.prefix(12))") }
    let center = view.frame.midX
    clickNotch(at: center + (collapsing.width + start.width) / 4)
    precondition(!model.expanded, "shrinking wing reopened the notch")
    precondition((notchAnimationProbe.last?.width ?? 0) > start.width + 2, "click test missed the closing transition")
    clickNotch(at: center)
    precondition(model.expanded, "compact center click was lost during collapse")
    RunLoop.current.run(until: Date().addingTimeInterval(0.45))
    notchContentRetentionProbe.removeAll()
    model.expanded = false
    func waitForRetention(_ retaining: Bool) {
        let deadline = Date().addingTimeInterval(0.25)
        while notchContentRetentionProbe.last != retaining && Date() < deadline {
            RunLoop.current.run(until: Date().addingTimeInterval(0.005))
        }
        precondition(notchContentRetentionProbe.last == retaining, "outgoing content did not update")
    }
    waitForRetention(true)
    model.mediaPlaying = true
    waitForRetention(false)
    precondition(model.notchGeometryInMotion, "media fixture missed the closing transition")
    model.mediaPlaying = false
    RunLoop.current.run(until: Date().addingTimeInterval(0.45))
    precondition(notchContentRetentionProbe == [true, false], "expanded content returned after a short media event")

    let previewRun = AgentActivity(id: "preview-timing", project: "test", state: "작업 중", activity: "")
    let previewDone = AgentActivity(id: previewRun.id, project: "test", state: "완료", activity: "")
    model.agentItems = [previewRun]
    agentStatusRevealProbe.removeAll()
    model.showAgentTransientPeek(previewRun, kind: .running)
    guard let runningID = model.visibleAgentTransientPeek?.id else { fatalError("running status fixture unavailable") }
    func waitForStatusReveal(_ id: UUID) -> TimeInterval {
        let deadline = Date(timeIntervalSinceNow: 1)
        while !agentStatusRevealProbe.contains(where: { $0.id == id }) && Date() < deadline {
            RunLoop.current.run(until: Date(timeIntervalSinceNow: 0.015))
        }
        guard let reveal = agentStatusRevealProbe.first(where: { $0.id == id }) else {
            fatalError("mounted status preview did not reveal: \(agentStatusRevealProbe)")
        }
        return reveal.elapsed
    }
    let runningLead = waitForStatusReveal(runningID)
    precondition(runningLead >= 0.08, "running status appeared before its outline lead")
    model.agentItems = [AgentActivity(id: previewRun.id, project: "updated", state: previewRun.state, activity: "")]
    RunLoop.current.run(until: Date(timeIntervalSinceNow: 0.15))
    precondition(agentStatusRevealProbe.filter { $0.id == runningID }.count == 1, "refresh replayed the running status")
    model.showAgentTransientPeek(previewRun, kind: .running)
    guard let supersededID = model.visibleAgentTransientPeek?.id else { fatalError("replacement fixture unavailable") }
    RunLoop.current.run(until: Date(timeIntervalSinceNow: 0.025))
    model.agentItems = [previewDone]
    model.showAgentTransientPeek(previewDone, kind: .completed)
    guard let doneID = model.visibleAgentTransientPeek?.id else { fatalError("completed status fixture unavailable") }
    let completedLead = waitForStatusReveal(doneID)
    precondition(completedLead >= 0.10 && !agentStatusRevealProbe.contains(where: { $0.id == supersededID }),
                 "completion appeared early or a superseded preview appeared")
    print("mounted status reveal waited \(Int(runningLead * 1_000))/\(Int(completedLead * 1_000)) ms and discarded the replaced preview")

    model.expanded = true
    RunLoop.current.run(until: Date().addingTimeInterval(0.45))
    let screenshot = URL(fileURLWithPath: NSTemporaryDirectory()).appendingPathComponent("rium-screenshot-\(UUID().uuidString).png")
    model.showScreenshotConfirmation(screenshot)
    notchContentRetentionProbe.removeAll()
    model.expanded = false
    precondition(model.shelfRevealVisible && model.collapsedIsIdle, "shelf fixture no longer exercises the old idle rule")
    RunLoop.current.run(until: Date().addingTimeInterval(0.1))
    precondition(!notchContentRetentionProbe.contains(true), "expanded content obscured the screenshot shelf")
    window.orderOut(nil)
    print("click during collapse: wing ignored, compact center reopened with hover disabled")
    print("transients during collapse: media took over once and screenshot shelf was never covered")
} else if CommandLine.arguments.contains("--self-test-notch-outline") {
    let notificationFixture: [String: Any] = ["req": ["titl": "보낸 사람", "subt": "대화", "body": "새 메시지"]]
