    suspendSystemNotification(suspended, into: &notificationQueue)
    precondition(notificationQueue.count == 32 && notificationQueue.first?.id == suspended.id &&
                 notificationQueue[1].title == "4" && notificationQueue.last?.title == "34")
    let notificationSuite = "app.rium.notch.notification-test.\(UUID().uuidString)"
    let notificationPreferences = UserDefaults(suiteName: notificationSuite)!
