    let firstNotice = systemNotificationPayload(notificationHex, source: "", databaseIdentity: notificationDB, recordID: 44, deliveredTime: 103)!
    let repeatedNotice = systemNotificationPayload(notificationHex, source: "", databaseIdentity: notificationDB, recordID: 44, deliveredTime: 103)!
    precondition(repeatedNotice.id != firstNotice.id)
    let secondNotice = SystemNotificationPeek(source: "", title: "둘째 알림", body: "")
    queuedNotificationModel.showSystemNotification(firstNotice)
    precondition(queuedNotificationModel.hoverExpansionBlocked)
