    let firstNoticeLight = queuedNotificationModel.lightCue?.id
    queuedNotificationModel.showSystemNotification(repeatedNotice)
    guard queuedNotificationModel.visibleNotificationUnreadCount == 1, queuedNotificationModel.pendingSystemNotificationPeeks.isEmpty,
          queuedNotificationModel.lightCue?.id == firstNoticeLight else { fatalError("duplicate notification replayed a compact alert or light") }
    queuedNotificationModel.showSystemNotification(secondNotice)
    precondition(queuedNotificationModel.systemNotificationPeek?.id == firstNotice.id &&
                 queuedNotificationModel.pendingSystemNotificationPeeks.count == 1 &&
                 queuedNotificationModel.lightCue?.kind == .systemNotification && queuedNotificationModel.lightCue?.id != firstNoticeLight)
    RunLoop.current.run(until: Date().addingTimeInterval(4.3))
    precondition(queuedNotificationModel.systemNotificationPeek?.id == secondNotice.id &&
                 queuedNotificationModel.pendingSystemNotificationPeeks.isEmpty && queuedNotificationModel.lightCue == nil)
    queuedNotificationModel.openNotificationsPage()
    precondition(queuedNotificationModel.expanded && queuedNotificationModel.section == .notifications &&
                 queuedNotificationModel.systemNotificationPeek == nil &&
                 queuedNotificationModel.homeNotification(for: .calendar) == nil)
    queuedNotificationModel.select(.home)
    precondition(queuedNotificationModel.homeNotification(for: .calendar)?.id == firstNotice.id)
    queuedNotificationModel.dismissHomeNotification(firstNotice)
    queuedNotificationModel.dismissHomeNotification(secondNotice)
    queuedNotificationModel.showSystemNotification(repeatedNotice)
    precondition(queuedNotificationModel.visibleHomeNotifications.isEmpty && queuedNotificationModel.lightCue == nil)
    let weatherNotice = SystemNotificationPeek(source: "com.apple.weather", title: "날씨", body: "")
    queuedNotificationModel.showSystemNotification(weatherNotice)
    precondition(queuedNotificationModel.homeNotification(for: .weather)?.id == weatherNotice.id &&
                 queuedNotificationModel.homeNotification(for: .calendar) == nil)
    precondition(NotchTab.notifications.section == .notifications &&
                 !NotchTab.defaultTabs.contains(.notifications) &&
