    queuedNotificationModel.select(.notifications)
    precondition(queuedNotificationModel.section == .notifications && queuedNotificationModel.visibleHomeNotifications.count == 1)
    queuedNotificationModel.setSystemNotificationScreenLocked(true)
    precondition(queuedNotificationModel.homeNotification(for: .weather) == nil &&
                 queuedNotificationModel.visibleHomeNotifications.isEmpty && queuedNotificationModel.visibleNotificationUnreadCount == 0)
    queuedNotificationModel.select(.home); queuedNotificationModel.expanded = false
