    let blueNotice = NotchLightCue(kind: .systemNotification, started: Date(), notificationTint: .blue)
    precondition(redNotice.notificationTint == NSColor.red && blueNotice.notificationTint == NSColor.blue)
    precondition(NotchLightCue(kind: .systemNotification, started: Date()).notificationTint == nil)
    precondition(abs(NotchLightCue(kind: .systemNotification, started: Date()).duration - 2.18) < 0.00001)
