    precondition(abs(raisedNotice.redComponent - 0.44) < 0.00001 && abs(raisedNotice.greenComponent - 0.65) < 0.00001 &&
                 raisedNotice.blueComponent == 1 && raisedNotice.alphaComponent == 1)
    let fallbackNotice = notificationGlowColor(nil).usingColorSpace(.sRGB)!
