    precondition(constrainedSides.gap == 193 && constrainedSides.side == 0)
    precondition(collapsedHeaderPadding(width: 200, cameraWidth: 185) == 3.5)
    for timer in [false, true] {
        for height: CGFloat in [32, 38] {
            let size = calculateCollapsedNotchSize(cameraWidth: 185, cameraHeight: height, screenWidth: 1512,
                                                   agent: false, timer: timer, music: true)
            let shell = NotchSilhouette(corners: notchCorners(for: 0)).path(in: CGRect(origin: .zero, size: size))
            let metrics = collapsedHeaderMetrics(width: size.width, cameraWidth: 185, padding: 8)
            let startOfGap = 8 + metrics.side
            let leftWidth: CGFloat = timer ? 24.92 + 2 + 20 : 24.92
            let rightStart = startOfGap + metrics.gap
            precondition(shell.contains(CGPoint(x: startOfGap - leftWidth - 2, y: (height + 24.92) / 2)))
            precondition(shell.contains(CGPoint(x: rightStart + 20 + 2, y: (height + 24) / 2)))
        }
    }
    let narrowerThanCamera = collapsedHeaderMetrics(width: 160, cameraWidth: 185)
    precondition(narrowerThanCamera.gap == 160 && narrowerThanCamera.side == 0)
    let offsetRight = NSRect(x: 868.5, y: 950, width: 643.5, height: 32)
    precondition(cameraExclusionWidth(screen: screen, topInset: 32, left: leftArea, right: offsetRight) == 225)
    precondition(notchContainsScreenPoint(NSPoint(x: 756, y: 962), screen: screen, expanded: false, section: .home))
    for expanded in [false, true] {
        let top = CGPoint(x: screen.midX, y: screen.maxY)
        precondition(notchContainsScreenPoint(top, screen: screen, expanded: expanded, section: .home))
        precondition(!notchContainsScreenPoint(CGPoint(x: screen.minX + 1, y: top.y), screen: screen, expanded: expanded, section: .home))
        precondition(!notchContainsScreenPoint(CGPoint(x: top.x, y: top.y + 1), screen: screen, expanded: expanded, section: .home))
    }
    precondition(!notchContainsScreenPoint(NSPoint(x: 100, y: 832), screen: screen, expanded: false, section: .home))
    let shoulderPoint = NSPoint(x: screen.midX - 17.7, y: screen.maxY - 37.5)
    precondition(notchContainsScreenPoint(shoulderPoint, screen: screen, expanded: false, section: .home,
                                          size: CGSize(width: 185, height: 35), corners: NotchCorners(bottom: 3, shoulder: 75)))
    precondition(!notchContainsScreenPoint(NSPoint(x: 756, y: 900), screen: screen, expanded: false, section: .home))
    precondition(notchContainsScreenPoint(NSPoint(x: 756, y: 900), screen: screen, expanded: true, section: .home))
    let shortScreen = NSRect(x: -200, y: 100, width: 400, height: 100)
    let tallOutline = CGSize(width: 300, height: 200)
    precondition(notchContainsScreenPoint(NSPoint(x: 0, y: 150), screen: shortScreen, expanded: true, section: .home, size: tallOutline))
    precondition(!notchContainsScreenPoint(NSPoint(x: 0, y: 50), screen: shortScreen, expanded: true, section: .home, size: tallOutline))
    precondition(!notchContainsScreenPoint(NSPoint(x: 0, y: 150), screen: shortScreen, expanded: true, section: .home, size: CGSize(width: CGFloat.nan, height: 200)))
    let enter = notchPointerDecision(inside: true, wasInside: false, ignoring: true, buttonDown: false, notifyHover: true)
    precondition(!enter.ignoresMouse && enter.inside && enter.hoverChange == true)
    let dragOut = notchPointerDecision(inside: false, wasInside: true, ignoring: false, buttonDown: true, notifyHover: true)
    precondition(!dragOut.ignoresMouse && dragOut.inside && dragOut.hoverChange == nil)
    let releaseOut = notchPointerDecision(inside: false, wasInside: dragOut.inside, ignoring: dragOut.ignoresMouse, buttonDown: false, notifyHover: true)
    precondition(releaseOut.ignoresMouse && !releaseOut.inside && releaseOut.hoverChange == false)
    precondition(shelfConfirmationDuration(.shelf) == 2 && shelfConfirmationDuration(.airDrop) == 2 && shelfConfirmationDuration(.screenshot) == 20)
    precondition(shelfDropResolutionCurrent(generation: 4, current: 4, finished: false))
    precondition(!shelfDropResolutionCurrent(generation: 4, current: 5, finished: false))
    precondition(!shelfDropResolutionCurrent(generation: 4, current: 4, finished: true))
    precondition(shelfCatchLightEnabled(zone: .shelf, light: true, shelf: true, airDrop: false))
    precondition(!shelfCatchLightEnabled(zone: .shelf, light: true, shelf: false, airDrop: true))
    precondition(shelfCatchLightEnabled(zone: .airDrop, light: true, shelf: false, airDrop: true))
    precondition(!shelfCatchLightEnabled(zone: .airDrop, light: true, shelf: true, airDrop: false))
    precondition(!shelfCatchLightEnabled(zone: .airDrop, light: false, shelf: true, airDrop: true))
    precondition(shelfDropZone(atX: 160, width: 320, split: true) == .shelf)
    precondition(shelfDropZone(atX: 161, width: 320, split: true) == .airDrop)
    precondition(shelfDropZone(atX: 300, width: 320, split: false) == .shelf)
    precondition(shelfDropZone(atX: .nan, width: 320, split: true) == .shelf)
    let outsideDragIn = notchPointerDecision(inside: true, wasInside: false, ignoring: true, buttonDown: true, notifyHover: true)
    precondition(!outsideDragIn.ignoresMouse && outsideDragIn.hoverChange == true)
    let dragApproach = NSPoint(x: 584, y: 934)
    let compactOutline = CGSize(width: 420, height: 35)
    precondition(!notchContainsScreenPoint(dragApproach, screen: screen, expanded: false, section: .home, size: compactOutline))
    precondition(notchContainsDropApproach(dragApproach, screen: screen, size: compactOutline, corners: .legacy))
    precondition(!notchContainsDropApproach(NSPoint(x: 584, y: 930), screen: screen, size: compactOutline, corners: .legacy))
    let armDrop = notchPointerDecision(inside: false, wasInside: false, ignoring: true, buttonDown: true, notifyHover: true, preparingDrop: true)
    precondition(!armDrop.ignoresMouse && !armDrop.inside && armDrop.hoverChange == nil)
    let releaseBeforeDrop = notchPointerDecision(inside: false, wasInside: false, ignoring: true, buttonDown: false, notifyHover: true, preparingDrop: true)
    precondition(releaseBeforeDrop.ignoresMouse && releaseBeforeDrop.hoverChange == nil)
    let silentEnter = notchPointerDecision(inside: true, wasInside: false, ignoring: true, buttonDown: false, notifyHover: false)
    precondition(pendingNotchHoverChange(inside: silentEnter.inside, lastDelivered: false, notifyHover: false) == nil)
    let afterReflow = notchPointerDecision(inside: true, wasInside: silentEnter.inside, ignoring: silentEnter.ignoresMouse, buttonDown: false, notifyHover: true)
    precondition(afterReflow.hoverChange == nil && pendingNotchHoverChange(inside: afterReflow.inside, lastDelivered: false, notifyHover: true) == true)
    precondition(pendingNotchHoverChange(inside: false, lastDelivered: true, notifyHover: true) == false)
    precondition(pendingNotchHoverChange(inside: true, lastDelivered: true, notifyHover: true) == nil)
    precondition(hoverPreviewDefersEntry(inside: true, blocked: true, wasDeferred: false, targetInside: true))
    precondition(hoverPreviewDefersEntry(inside: true, blocked: false, wasDeferred: true, targetInside: false))
    precondition(!hoverPreviewDefersEntry(inside: true, blocked: false, wasDeferred: true, targetInside: true))
    func unexpectedHoverTarget() -> Bool { fatalError("outside pointer queried the target outline") }
    precondition(!hoverPreviewDefersEntry(inside: false, blocked: true, wasDeferred: true, targetInside: unexpectedHoverTarget()))
    precondition(hoverSettingNeedsReconciliation(enabled: true, expanded: false, autoHide: true, inside: true))
    precondition(!hoverSettingNeedsReconciliation(enabled: true, expanded: false, autoHide: true, inside: false))
    precondition(hoverSettingNeedsReconciliation(enabled: true, expanded: true, autoHide: true, inside: false))
    precondition(hoverSettingNeedsReconciliation(enabled: false, expanded: true, autoHide: true, inside: false))
    precondition(!hoverSettingNeedsReconciliation(enabled: false, expanded: true, autoHide: false, inside: false))
    print("pointer interception self-test passed")
} else if CommandLine.arguments.contains("--self-test-dictation-timeout") {
    guard DictationController.testPermissionPreparation() else { fatalError("dictation permission routing failed") }
    guard DictationController.testFinalizationTimeout() else { fatalError("dictation finalization timeout failed") }
    guard DictationController.testRecognitionCallbackIsolation() else { fatalError("dictation callback isolation failed") }
    guard DictationController.testCompatibleTextInsertion() else { fatalError("dictation insertion compatibility failed") }
    guard DictationController.testSleepInterruption() else { fatalError("dictation sleep interruption failed") }
    guard DictationController.testModifierGestureInterruption() else { fatalError("dictation modifier interleaving did not cancel the pending result") }
    guard DictationController.testSelectionContentValidation() else { fatalError("dictation accepted changed text at the same selected range") }
    guard DictationController.testAssistantCaptureCancellation() else { fatalError("assistant capture cancellation failed") }
    print("dictation finalization timeout self-test passed")
} else if CommandLine.arguments.contains("--self-test-power-feedback") {
    let suite = "app.rium.notch.power-test.\(UUID().uuidString)"
    let preferences = UserDefaults(suiteName: suite)!
    preferences.set(true, forKey: "rium.light.battery")
    defer { preferences.removePersistentDomain(forName: suite) }
    let model = Model(startServices: false)
    let observer = PowerModel(observeSystem: false)
    var events = 0
    observer.onEvent = { event in
        events += 1
        model.showBatteryEvent(event, preferences: preferences)
    }
    observer.record(percent: 9, charging: false, external: false, warning: 1)
    observer.record(percent: 10, charging: false, external: false, warning: 0)
    observer.record(percent: 9, charging: false, external: false, warning: 1)
    precondition(events == 0 && model.batteryPeek == nil, "initial or repeated battery warning flashed")
    observer.record(percent: 9, charging: true, external: true, warning: 1)
    precondition(events == 1 && model.batteryPeek?.external == true &&
                 model.lightCue?.kind == .batterySource(9, true) && model.lightCue?.duration == 1.35)
    RunLoop.current.run(until: Date().addingTimeInterval(1.55))
    precondition(model.batteryPeek == nil && model.lightCue == nil, "source preview did not expire")

    observer.record(percent: 9, charging: false, external: false, warning: 1)
    precondition(events == 2 && model.batteryPeek?.critical == false &&
                 model.lightCue?.kind == .batteryWarning(false) && model.lightCue?.duration == 4)
    RunLoop.current.run(until: Date().addingTimeInterval(1.75))
    observer.record(percent: 4, charging: false, external: false, warning: 2)
    precondition(events == 3 && model.batteryPeek?.critical == true &&
                 model.lightCue?.kind == .batteryWarning(true) && model.lightCue?.duration == 5 &&
                 model.activeLightCues.filter(\.isBatteryFeedback).count == 1)
    observer.record(percent: 5, charging: false, external: false, warning: 1)
    observer.record(percent: 4, charging: false, external: false, warning: 2)
    RunLoop.current.run(until: Date().addingTimeInterval(2.45))
    precondition(events == 3 && model.batteryPeek?.critical == true, "old battery warning cleared its successor")
    RunLoop.current.run(until: Date().addingTimeInterval(2.75))
    precondition(model.batteryPeek == nil && model.lightCue == nil, "critical preview did not expire")
    observer.record(percent: 4, charging: true, external: true, warning: 2)
    model.setSystemNotificationScreenLocked(true)
    observer.record(percent: 4, charging: false, external: false, warning: 2)
    precondition(model.batteryPeek == nil && model.lightCue == nil, "locked screen retained power feedback")
    let physical = PowerModel(observeSystem: false)
    physical.refresh()
    if let percent = physical.percentage {
        precondition((0...100).contains(percent))
        print("read-only battery snapshot available")
    }
    print("power feedback self-test passed")
} else if CommandLine.arguments.contains("--self-test-brightness-watch") {
    _ = NSApplication.shared
    guard let screen = NSScreen.main, let id = displayIdentifier(screen) else { fatalError("main display unavailable") }
    let model = Model(startServices: false); model.selectDisplay(id)
    guard model.brightness != "밝기 조회 불가" else { fatalError("brightness unavailable") }
    print("RIUM_BRIGHTNESS_READY"); fflush(stdout)
    let deadline = Date().addingTimeInterval(8)
    while model.overlaySymbol != "sun.max.fill" && Date() < deadline { RunLoop.current.run(until: Date().addingTimeInterval(0.1)); model.sampleBrightness() }
    guard model.overlaySymbol == "sun.max.fill", model.volumeOverlay.hasPrefix("밝기 ") else { fatalError("brightness change was not surfaced") }
    print("brightness change observation passed"); fflush(stdout)
} else if CommandLine.arguments.contains("--self-test-brightness") {
    let unchanged = Model(startServices: false)
    unchanged.recordVolume(percent: 30, muted: false, device: 1)
    unchanged.recordBrightness(display: 1, percent: 40)
    var publishedChanges = 0
    let observation = unchanged.objectWillChange.sink { publishedChanges += 1 }
    for _ in 0..<5 {
        unchanged.recordVolume(percent: 30, muted: false, device: 1)
        unchanged.recordBrightness(display: 1, percent: 40)
        unchanged.expireControlOverlay(at: ProcessInfo.processInfo.systemUptime)
    }
    precondition(publishedChanges == 0, "unchanged hardware readings redrew the notch")
    unchanged.recordBrightness(display: 1, percent: nil)
    precondition(publishedChanges == 1, "brightness becoming unavailable must update the display")
    unchanged.recordBrightness(display: 1, percent: nil)
    precondition(publishedChanges == 1, "repeated unavailable readings must not trigger another update")
    observation.cancel()
    let model = Model(startServices: false)
    model.recordBrightness(display: 1, percent: 40)
    guard model.brightness == "밝기 40%", model.volumeOverlay.isEmpty else { fatalError("initial brightness incorrectly emitted an event") }
    model.recordBrightness(display: 1, percent: 42)
    guard model.lightCue?.previousSystemLevel == 40, model.lightCue?.systemDirection == 1, model.lightCue?.restoringSound == false else { fatalError("brightness transition missed its previous value") }
    guard model.volumeOverlay == "밝기 42%", model.overlaySymbol == "sun.max.fill", model.lightCue?.kind == .brightness(42) else { fatalError("brightness change not displayed") }
    model.showLight(.airDrop); model.recordBrightness(display: 1, percent: 43)
    guard model.lightCue?.kind == .brightness(43), model.activeLightCues.filter(\.isSystemHUD).count == 1,
          model.activeLightCues.contains(where: { $0.kind == .airDrop }) else { fatalError("latest system cue or overlapping AirDrop cue was lost") }
    model.volumeOverlay = ""; model.recordBrightness(display: 2, percent: 80)
    guard model.volumeOverlay.isEmpty else { fatalError("display change emitted a brightness event") }
    model.recordBrightness(display: 2, percent: nil); model.recordBrightness(display: 2, percent: 75)
    guard model.volumeOverlay.isEmpty else { fatalError("brightness recovery emitted a false event") }
    model.recordBrightness(display: 2, percent: 74)
    guard model.lightCue?.kind == .brightness(74), model.lightCue?.systemDirection == -1 else { fatalError("brightness decrease lost its direction") }
    model.volumeOverlay = ""
    model.recordVolume(percent: 30, muted: false)
    guard model.volumeOverlay.isEmpty else { fatalError("initial volume emitted an event") }
    let overlayStart = ProcessInfo.processInfo.systemUptime
    model.recordVolume(percent: 45, muted: false)
    guard model.lightCue?.kind == .systemLevel(45), model.lightCue?.previousSystemLevel == 30, model.lightCue?.restoringSound == false, model.volumeOverlay == "음량 45%" else { fatalError("volume level event failed") }
    model.expireControlOverlay(at: overlayStart + 1)
    guard !model.volumeOverlay.isEmpty else { fatalError("control overlay expired too early") }
    model.expireControlOverlay(at: ProcessInfo.processInfo.systemUptime + 1.45)
    guard model.volumeOverlay.isEmpty else { fatalError("control overlay did not expire") }
    model.recordVolume(percent: 45, muted: true)
    guard model.lightCue?.kind == .mute(true), model.volumeOverlay == "음소거" else { fatalError("mute event failed") }
    model.clearControlOverlay()
    guard model.volumeOverlay.isEmpty, !model.activeLightCues.contains(where: \.isSystemHUD),
          model.activeLightCues.contains(where: { $0.kind == .airDrop }) else { fatalError("sleep did not clear only the control overlay") }
    model.recordVolume(percent: 45, muted: false)
    guard model.lightCue?.kind == .systemLevel(45), model.lightCue?.previousSystemLevel == nil, model.lightCue?.restoringSound == true,
          model.activeLightCues.filter(\.isSystemHUD).count == 1 else { fatalError("unmute did not show the restored volume level") }
    model.volumeOverlay = ""; model.recordVolume(percent: nil, muted: nil); model.recordVolume(percent: 60, muted: false)
    guard model.volumeOverlay.isEmpty else { fatalError("volume recovery emitted a false event") }
    let deviceModel = Model(startServices: false)
    deviceModel.recordVolume(percent: 30, muted: false, device: 1)
    deviceModel.recordVolume(percent: 40, muted: false, device: 1)
    deviceModel.recordVolume(percent: 80, muted: true, device: 2)
    guard deviceModel.volume == "음소거", deviceModel.volumeOverlay.isEmpty,
          !deviceModel.activeLightCues.contains(where: \.isSystemHUD) else { fatalError("output device switch retained a stale volume event") }
    deviceModel.recordVolume(percent: 80, muted: false, device: 2)
    guard deviceModel.lightCue?.kind == .systemLevel(80) else { fatalError("volume events did not resume on the new device") }
    deviceModel.recordBrightness(display: 1, percent: 40)
    deviceModel.recordBrightness(display: 1, percent: 50)
    let brightnessCue = deviceModel.lightCue?.id
    deviceModel.recordVolume(percent: 30, muted: false, device: 3)
    guard deviceModel.lightCue?.id == brightnessCue, deviceModel.volumeOverlay == "밝기 50%" else { fatalError("output device switch cleared brightness feedback") }
    let muteOnly = Model(startServices: false)
    muteOnly.recordVolume(percent: nil, muted: false, device: 3)
    guard muteOnly.volume == "음소거 해제", muteOnly.lightCue == nil else { fatalError("initial mute-only state was not retained") }
    muteOnly.recordVolume(percent: nil, muted: true, device: 3)
    guard muteOnly.lightCue?.kind == .mute(true) else { fatalError("mute-only device missed mute") }
    muteOnly.recordVolume(percent: nil, muted: false, device: 3)
    guard muteOnly.volumeOverlay == "음소거 해제", muteOnly.lightCue?.kind == .mute(false) else { fatalError("mute-only device missed unmute") }
    muteOnly.clearControlOverlay()
    muteOnly.recordVolume(percent: 50, muted: false, device: 3)
    guard muteOnly.lightCue == nil else { fatalError("volume availability emitted a false event") }
    muteOnly.recordVolume(percent: 55, muted: false, device: 3)
    guard muteOnly.lightCue?.kind == .systemLevel(55) else { fatalError("volume change after availability was missed") }
    let waking = Model(startServices: false)
    waking.recordVolume(percent: 30, muted: false, device: 1)
    waking.recordBrightness(display: 1, percent: 40)
    waking.setSystemNotificationSleeping(true); waking.setSystemNotificationSleeping(false)
    waking.recordVolume(percent: 60, muted: true, device: 1)
    waking.recordBrightness(display: 1, percent: 70)
    guard waking.lightCue == nil, waking.volumeOverlay.isEmpty else { fatalError("wake baseline emitted a stale event") }
    waking.recordVolume(percent: 60, muted: false, device: 1)
    guard waking.lightCue?.kind == .systemLevel(60) else { fatalError("volume events did not resume after wake") }
    waking.recordBrightness(display: 1, percent: 71)
    guard waking.lightCue?.kind == .brightness(71) else { fatalError("brightness events did not resume after wake") }
    let lockedControls = Model(startServices: false)
    lockedControls.recordVolume(percent: 30, muted: false, device: 1)
    lockedControls.recordBrightness(display: 1, percent: 40)
    lockedControls.recordBrightness(display: 1, percent: 45)
    lockedControls.setSystemNotificationScreenLocked(true)
    lockedControls.recordVolume(percent: 60, muted: true, device: 1)
    lockedControls.recordBrightness(display: 1, percent: 70)
    guard lockedControls.lightCue == nil, lockedControls.volumeOverlay.isEmpty else { fatalError("locked controls generated a cue") }
    lockedControls.setSystemNotificationScreenLocked(false)
    lockedControls.recordVolume(percent: 60, muted: true, device: 1)
    lockedControls.recordBrightness(display: 1, percent: 70)
    guard lockedControls.lightCue == nil else { fatalError("unlock replayed a locked control change") }
    lockedControls.recordBrightness(display: 1, percent: 71)
    guard lockedControls.lightCue?.kind == .brightness(71) else { fatalError("control events did not resume after unlock") }

    let limited = Model(startServices: false)
    limited.recordVolume(percent: 100, muted: false, device: 10, limitDirection: 1)
    precondition(limited.volumeOverlay.isEmpty, "unconfirmed volume baseline emitted a limit event")
    limited.recordVolume(percent: 100, muted: false, device: 10, limitDirection: -1)
    precondition(limited.volumeOverlay.isEmpty, "volume key away from the limit emitted an event")
    limited.recordVolume(percent: 100, muted: false, device: 10, limitDirection: 1)
    precondition(limited.volumeOverlay == "음량 100%" && limited.lightCue?.kind == .systemLevel(100))
    limited.recordVolume(percent: 100, muted: true, device: 11, limitDirection: 1)
    precondition(limited.volumeOverlay.isEmpty, "output replacement reused an earlier limit")
    limited.recordVolume(percent: 100, muted: true, device: 11, limitDirection: 1)
    precondition(limited.volumeOverlay.isEmpty, "muted output emitted a volume limit")
    limited.recordBrightness(display: 1, percent: 0.1)
    limited.recordBrightness(display: 1, percent: 0.1, limitDirection: -1)
    precondition(limited.volumeOverlay.isEmpty, "rounded brightness triggered an early limit")
    limited.recordBrightness(display: 1, percent: 0)
    limited.recordBrightness(display: 1, percent: 0, limitDirection: -1)
    precondition(limited.volumeOverlay == "밝기 0%" && limited.lightCue?.kind == .brightness(0))
    let firstLimit = limited.lightCue?.id
    RunLoop.current.run(until: Date().addingTimeInterval(0.75))
    limited.recordBrightness(display: 1, percent: 0, limitDirection: -1)
    precondition(limited.lightCue?.id != firstLimit, "brightness key repeat failed to refresh the HUD")
    RunLoop.current.run(until: Date().addingTimeInterval(0.75))
    precondition(limited.volumeOverlay == "밝기 0%", "previous deadline cleared the newer HUD")
    RunLoop.current.run(until: Date().addingTimeInterval(0.75))
    precondition(limited.volumeOverlay.isEmpty && !limited.activeLightCues.contains(where: \.isSystemHUD),
                 "system HUD did not expire without polling")
    _ = NSApplication.shared
    if let screen = NSScreen.main, let id = displayIdentifier(screen) {
        var value = -1.0; let result = displayBrightness(id, &value)
        guard result == 0 || (result == 1 && value.isFinite && (0...100).contains(value)) else { fatalError("invalid brightness result") }
        print(result == 1 ? "brightness read available" : "brightness read unavailable on this display")
    }
    print("brightness self-test passed")
} else if CommandLine.arguments.contains("--self-test-monitoring") {
    guard memoryUsagePercent(used: 8, total: 16, available: true) == 50,
          memoryUsagePercent(used: 1, total: 0, available: true) == nil,
          memoryUsagePercent(used: 17, total: 16, available: true) == nil,
          memoryUsagePercent(used: 8, total: 16, available: false) == nil else { fatalError("memory percentage calculation failed") }
    var history: [Double?] = []
    for _ in 0..<31 { appendMonitorSample(25, to: &history) }
    appendMonitorSample(nil, to: &history)
    guard history.count == 30, history.last! == nil else { fatalError("monitor history bounds or gaps failed") }
    let path = Sparkline(samples: [10, 20, nil, 50, 60]).path(in: CGRect(x: 0, y: 0, width: 100, height: 20)).cgPath
    var moves = 0, lines = 0
    path.applyWithBlock { element in
        if element.pointee.type == .moveToPoint { moves += 1 }
        if element.pointee.type == .addLineToPoint { lines += 1 }
    }
    guard moves == 2, lines == 2 else { fatalError("monitor graph bridged missing data") }
    let model = Model(startServices: false); model.sample()
    RunLoop.current.run(until: Date().addingTimeInterval(0.25)); model.sample()
    guard model.cpuHistory.count == 2, model.memoryHistory.count == 2 else { fatalError("live monitoring sample failed") }
    print("monitoring self-test passed; CPU=\(model.cpu), RAM=\(model.memoryPercent), pressure=\(model.pressure)")
} else if CommandLine.arguments.contains("--self-test-teleprompter-playback") {
    _ = NSApplication.shared
    let root = FileManager.default.temporaryDirectory.appendingPathComponent("rium-prompt-playback-\(UUID().uuidString)", isDirectory: true)
    let suite = "app.rium.notch.prompt-playback-test.\(UUID().uuidString)"
    guard let preferences = UserDefaults(suiteName: suite) else { fatalError("isolated preferences unavailable") }
    defer { try? FileManager.default.removeItem(at: root); preferences.removePersistentDomain(forName: suite) }
    let controller = TeleprompterController(root: root, preferences: preferences)
    let size = CGSize(width: 710, height: 420)
    let window = NSPanel(contentRect: NSRect(origin: CGPoint(x: -2000, y: -2000), size: size),
                         styleMask: [.borderless, .nonactivatingPanel], backing: .buffered, defer: false)
    let holder = NSView(frame: NSRect(origin: .zero, size: size))
    window.contentView = holder; controller.attach(to: holder)
    func views(_ root: NSView) -> [NSView] { [root] + root.subviews.flatMap { views($0) } }
    let all = views(holder)
    let buttons = all.compactMap { $0 as? NSButton }
    guard let scroll = all.compactMap({ $0 as? NSScrollView }).first,
          let text = scroll.documentView as? NSTextView,
          let play = buttons.first(where: { $0.accessibilityIdentifier() == "teleprompter-play" }),
          let edit = buttons.first(where: { $0.title == "원고 편집" }),
          let rewind = buttons.first(where: { $0.title == "처음으로" }) else { fatalError("teleprompter playback controls unavailable") }
    let script = (1...100).map { "리움 프롬프터 원고 \($0)" }.joined(separator: "\n")
    text.string = script; text.didChangeText()
