    if let manager = text.layoutManager, let container = text.textContainer { manager.ensureLayout(for: container) }
    let limit = text.bounds.height - scroll.contentView.bounds.height
    precondition(limit > 500, "fixture script is not scrollable")
    func press(_ button: NSButton) {
        guard let action = button.action, NSApp.sendAction(action, to: button.target, from: button) else {
            fatalError("teleprompter action unavailable")
        }
    }
    func wheel(_ amount: Int32, units: CGScrollEventUnit) -> NSEvent {
        guard let event = CGEvent(scrollWheelEvent2Source: nil, units: units, wheelCount: 1, wheel1: amount, wheel2: 0, wheel3: 0),
              let appEvent = NSEvent(cgEvent: event) else { fatalError("synthetic wheel event unavailable") }
        return appEvent
    }
