    let mouseWheel = wheel(-2, units: .line)
    precondition(!mouseWheel.hasPreciseScrollingDeltas && mouseWheel.scrollingDeltaY < 0)
    let beforeMouse = scroll.contentView.bounds.minY
    scroll.scrollWheel(with: mouseWheel)
