    guard transitions.lightCue?.kind == .musicPlayback(true) else { fatalError("starting from no player missed playback cue") }
    let playingCue = transitions.lightCue?.id
    transitions.refreshMedia(); transitionReplies.removeFirst()(["event":"result", "data":["playing":true]])
    guard transitions.lightCue?.id == playingCue else { fatalError("unchanged playback repeated a cue") }
    transitions.refreshMedia(); transitionReplies.removeFirst()(["event":"result", "data":[:]])
    guard transitions.lightCue?.kind == .musicPlayback(false) else { fatalError("player disappearance missed stop cue") }
    let stoppedCue = transitions.lightCue?.id
    transitions.refreshMedia(); transitionReplies.removeFirst()(["event":"result", "data":[:]])
    guard transitions.lightCue?.id == stoppedCue else { fatalError("unchanged empty state repeated a cue") }
    transitions.refreshMedia(); transitionReplies.removeFirst()(["event":"result", "data":["playing":true, "duration":100.0]])
