    guard !transitions.mediaPositionKnown, transitions.mediaElapsed == 0, !transitions.showsMusicProgress else { fatalError("missing position fabricated playback progress") }
    transitions.refreshMedia(); transitionReplies.removeFirst()(["event":"result", "data":["playing":true, "duration":100.0, "elapsedTime":25.0]])
    guard transitions.mediaPositionKnown, transitions.mediaElapsed == 25, transitions.showsMusicProgress else { fatalError("valid playback position not restored") }
    transitions.refreshMedia(); transitionReplies.removeFirst()(["event":"result", "data":["playing":true, "duration":100.0, "elapsedTime":-1.0]])
    guard !transitions.mediaPositionKnown, !transitions.showsMusicProgress else { fatalError("invalid playback position retained progress") }
