    transitions.refreshMedia(); transitionReplies.removeFirst()(["event":"result", "data":[:]])
    guard transitions.lightCue?.id == beforeError else { fatalError("media recovery emitted a false pause cue") }
    var streamReplies: [([String: Any]) -> Void] = []
    let streamModel = Model(startServices: false, mediaRequester: { _, _, reply in streamReplies.append(reply) })
    let streamAnchor = ProcessInfo.processInfo.systemUptime
