    var trackReplies: [([String: Any]) -> Void] = []
    let trackModel = Model(startServices: false, mediaRequester: { _, _, reply in trackReplies.append(reply) })
    trackModel.refreshMedia(); trackReplies.removeFirst()(["event":"result", "data":["title":"같은 제목", "trackIdentifier":"one", "playing":true, "duration":100.0]])
    trackModel.mediaEditingPosition = true
