    guard trackModel.lightCue?.kind == .musicTrack, !trackModel.mediaEditingPosition else { fatalError("track identifier change was missed") }
    let skipOld = MediaTrackIdentity(identifier: "one", source: "player", title: "첫 곡", artist: "")
    let skipNew = MediaTrackIdentity(identifier: "two", source: "player", title: "다음 곡", artist: "")
    let otherPlayer = MediaTrackIdentity(identifier: "two", source: "other", title: "다음 곡", artist: "")
    precondition(mediaSkipLanded(from: skipOld, to: skipNew, age: 1))
