    precondition(!mediaSkipLanded(from: skipOld, to: otherPlayer, age: 1))
    precondition(mediaSkipLanded(from: skipOld, to: skipNew, age: 4))
    precondition(!mediaSkipLanded(from: skipOld, to: skipNew, age: 4.6))
    precondition(!mediaSkipLanded(from: skipOld, to: skipNew, age: -.infinity))
    precondition(trackSkipLandingDuration(shownFor: 0) == 1.5)
    precondition(abs(trackSkipLandingDuration(shownFor: 0.2) - 1.3) < 0.0001)
    precondition(trackSkipLandingDuration(shownFor: 2) == 1.1)
    precondition(trackSkipLandingDuration(shownFor: .nan) == 1.5)
    var skipReplies: [([String: Any]) -> Void] = []
