    skipModel.refreshMedia(); skipReplies.removeFirst()(["event":"result", "data":["bundleIdentifier":"player", "trackIdentifier":"two",
           "title":"다음 곡", "artist":"가수", "playing":true, "duration":120.0, "elapsedTime":2.0]])
    guard skipModel.lightCue?.kind == .musicSkipArrival, skipModel.visibleTrackSkipPeek?.id == skipPreviewID,
