    keyModel.observeSystemMediaKey(.skip(forward: true, key: 17))
    guard keyModel.lightCue?.kind == .musicSkip(true) else { fatalError("system media key missed skip pass") }
    keyModel.refreshMedia(); keyReplies.removeFirst()(["event":"result", "data":["bundleIdentifier":"player", "trackIdentifier":"two", "playing":true]])
