    RunLoop.main.run(until: Date().addingTimeInterval(0.02))
    startupModel.setDictationScreenSleeping(true)
    startupModel.setSystemNotificationScreenLocked(true)
    startupModel.setSystemNotificationSleeping(true)
    guard startupModel.preparedDictation == nil else { fatalError("passive startup initialized dictation") }
    let startupDictation = startupModel.dictation
    guard startupModel.dictation === startupDictation, startupDictation.sessionInactive else {
        fatalError("lazy dictation lost the current session state")
    }
    startupModel.setSystemNotificationScreenLocked(false)
    guard startupDictation.sessionInactive else { fatalError("unlock cleared dictation sleep state") }
    startupModel.setSystemNotificationSleeping(false)
