    precondition(dictationWritingCloudSample(age: 2, writingAge: 0.38, initialLevel: 0.7, reduceMotion: false)?[0] == 1)
    precondition(dictationWritingCloudSample(age: 0, writingAge: 0, initialLevel: 0.7, reduceMotion: true)?[0] == 1)
    precondition(dictationWritingCloudSample(age: .nan, writingAge: 0, initialLevel: 0.7, reduceMotion: false) == nil)
