    guard let preferences = UserDefaults(suiteName: domain) else { fatalError("isolated preferences unavailable") }
    defer {
        preferences.removePersistentDomain(forName: domain); preferences.synchronize()
        let url = FileManager.default.homeDirectoryForCurrentUser.appendingPathComponent("Library/Preferences/\(domain).plist")
        if let data = try? Data(contentsOf: url),
           let contents = try? PropertyListSerialization.propertyList(from: data, format: nil) as? [String: Any], contents.isEmpty {
            try? FileManager.default.removeItem(at: url)
        }
    }
    let first = DictationController(preferences: preferences)
    guard first.autoStart else { fatalError("default dictation preference is not enabled") }
    first.disable(persist: false)
    guard first.autoStart else { fatalError("temporary shutdown changed preference") }
    first.disable()
    guard !DictationController(preferences: preferences).autoStart else { fatalError("disabled preference was not retained") }
    guard DictationShortcut.fn.requiredFlags == .function, DictationShortcut.controlOption.requiredFlags == [.control, .option] else { fatalError("shortcut flags are incorrect") }
    guard DictationController.isHandsFreeCombination(keyCode: 49, flags: .maskSecondaryFn),
          !DictationController.isHandsFreeCombination(keyCode: 49, flags: [.maskSecondaryFn, .maskCommand]),
          !DictationController.isHandsFreeCombination(keyCode: 49, flags: []),
          !DictationController.isHandsFreeCombination(keyCode: 0, flags: .maskSecondaryFn) else { fatalError("hands-free key filtering failed") }
    guard !first.handsFreeEnabled else { fatalError("hands-free default must be off") }
    first.setHandsFreeEnabled(true)
    guard DictationController(preferences: preferences).handsFreeEnabled else { fatalError("hands-free preference was not retained") }
    first.setShortcut(.controlOption)
    guard DictationController(preferences: preferences).shortcut == .controlOption else { fatalError("shortcut preference was not retained") }
    let control = UInt64(NSEvent.ModifierFlags.control.rawValue)
    guard let recorded = RecordedDictationShortcut(keyCode: 8, modifiers: control, keyLabel: "C"),
          recorded.label == "Control + C", recorded.matchesKeyDown(keyCode: 8, flags: .maskControl, repeated: false),
          recorded.matchesModifiers(.maskControl), !recorded.matchesModifiers([]),
          !recorded.matchesKeyDown(keyCode: 8, flags: [.maskControl, .maskShift], repeated: false),
          !recorded.matchesKeyDown(keyCode: 8, flags: .maskControl, repeated: true),
          !recorded.matchesKeyDown(keyCode: 9, flags: .maskControl, repeated: false),
          RecordedDictationShortcut(keyCode: 53, modifiers: control, keyLabel: "Escape") == nil,
          RecordedDictationShortcut(keyCode: 8, modifiers: 0, keyLabel: "C") == nil,
          RecordedDictationShortcut(keyCode: 8, modifiers: control | UInt64(NSEvent.ModifierFlags.shift.rawValue), keyLabel: "C") == nil,
