    let dayEnd = now.addingTimeInterval(86_400)
    precondition(eventIntersectsCalendarDay(start: now.addingTimeInterval(-30), end: now.addingTimeInterval(30), dayStart: now, dayEnd: dayEnd))
    precondition(!eventIntersectsCalendarDay(start: now.addingTimeInterval(-30), end: now, dayStart: now, dayEnd: dayEnd))
    precondition(eventIntersectsCalendarDay(start: now, end: now, dayStart: now, dayEnd: dayEnd))
    precondition(!eventIntersectsCalendarDay(start: dayEnd, end: dayEnd, dayStart: now, dayEnd: dayEnd))
    precondition(eventIsUpcoming(start: now.addingTimeInterval(-60), end: now.addingTimeInterval(60), now: now, through: dayEnd))
    precondition(!eventIsUpcoming(start: dayEnd, end: dayEnd.addingTimeInterval(3600), now: now, through: dayEnd))
    let fixtureCalendar = Calendar(identifier: .gregorian)
    precondition(eventIsRemainingToday(start: now, end: now.addingTimeInterval(30), now: now, calendar: fixtureCalendar))
    precondition(!eventIsRemainingToday(start: now, end: now, now: now, calendar: fixtureCalendar))
    precondition(eventIsRemainingToday(start: now.addingTimeInterval(-86_400), end: now.addingTimeInterval(60), now: now, calendar: fixtureCalendar))
    let tomorrow = fixtureCalendar.date(byAdding: .day, value: 1, to: fixtureCalendar.startOfDay(for: now))!
    precondition(!eventIsRemainingToday(start: tomorrow, end: tomorrow.addingTimeInterval(60), now: now, calendar: fixtureCalendar))
    precondition(!eventIsRemainingToday(start: now.addingTimeInterval(120), end: now.addingTimeInterval(60), now: now, calendar: fixtureCalendar))
    func item(start: TimeInterval, end: TimeInterval, allDay: Bool = false) -> AgendaModel.Item {
        AgendaModel.Item(id: "fixture", title: "fixture", subtitle: "fixture", start: now.addingTimeInterval(start), end: now.addingTimeInterval(end), allDay: allDay)
    }
    var timelineCalendar = Calendar(identifier: .gregorian)
    timelineCalendar.timeZone = TimeZone(secondsFromGMT: 0)!
    let timelineDay = timelineCalendar.startOfDay(for: now)
    let early = AgendaModel.Item(id: "early", title: "early", subtitle: "", start: timelineDay.addingTimeInterval(6 * 3600), end: timelineDay.addingTimeInterval(9 * 3600))
    let late = AgendaModel.Item(id: "late", title: "late", subtitle: "", start: timelineDay.addingTimeInterval(19 * 3600), end: timelineDay.addingTimeInterval(23 * 3600))
    let allDay = AgendaModel.Item(id: "all-day", title: "all-day", subtitle: "", start: timelineDay, end: timelineDay.addingTimeInterval(86400), allDay: true)
    let continuing = AgendaModel.Item(id: "continuing", title: "continuing", subtitle: "", start: timelineDay.addingTimeInterval(-3600), end: timelineDay.addingTimeInterval(3600))
    let selected = homeCalendarTimedEvents([allDay, continuing, early, late], now: now, calendar: timelineCalendar)
    guard selected.map(\.id) == ["early", "late"] else { fatalError("home calendar day selection failed") }
    guard let normalWindow = homeCalendarTimelineBounds(events: [allDay], now: now, calendar: timelineCalendar),
          normalWindow.start == timelineDay.addingTimeInterval(8 * 3600), normalWindow.end == timelineDay.addingTimeInterval(20 * 3600),
          let expandedWindow = homeCalendarTimelineBounds(events: [early, late, allDay], now: now, calendar: timelineCalendar),
          expandedWindow.start == early.start, expandedWindow.end == late.end else { fatalError("home calendar timeline bounds failed") }
    let earlyFraction = AgendaModel.Item(id: "early-fraction", title: "early", subtitle: "", start: timelineDay.addingTimeInterval(6 * 3600 + 37 * 60), end: timelineDay.addingTimeInterval(7 * 3600 + 15 * 60))
    guard let roundedWindow = homeCalendarTimelineBounds(events: [earlyFraction], now: now, calendar: timelineCalendar),
          roundedWindow.start == timelineDay.addingTimeInterval(6 * 3600),
          roundedWindow.end == timelineDay.addingTimeInterval(20 * 3600) else { fatalError("early calendar timeline rounding failed") }
    guard agendaRelativeLabel(item(start: 30, end: 3600), now: now) == "곧 시작",
          agendaRelativeLabel(item(start: 30 * 60, end: 3600), now: now) == "30분 후",
          agendaRelativeLabel(item(start: 90 * 60, end: 7200), now: now) == "1시간 30분 후",
          agendaRelativeLabel(item(start: -10, end: 3600), now: now) == "진행 중",
          agendaTimeLabel(item(start: 0, end: 86400, allDay: true)) == "종일" else { fatalError("agenda label test failed") }
    let utc = TimeZone(secondsFromGMT: 0)!
    let dateOnly = reminderDueComponents(now, includeTime: false, timeZone: utc)
    let timed = reminderDueComponents(now, includeTime: true, timeZone: utc)
    guard dateOnly.calendar?.identifier == .gregorian, dateOnly.year == 2023, dateOnly.month == 11, dateOnly.day == 14,
          dateOnly.hour == nil, dateOnly.minute == nil, dateOnly.timeZone == nil,
          timed.calendar?.identifier == .gregorian, timed.hour == 22, timed.minute == 13, timed.timeZone == utc else { fatalError("reminder due-date components failed") }
    print("agenda self-test passed")
} else if CommandLine.arguments.contains("--self-test-current-artwork") {
    guard let helper = Bundle.main.url(forAuxiliaryExecutable: "rium-notch-core") else { fatalError("media helper unavailable") }
    let process = Process(); let pipe = Pipe()
    process.executableURL = helper; process.arguments = ["media", "get"]
    process.standardOutput = pipe; process.standardError = FileHandle.nullDevice
    try process.run(); let output = pipe.fileHandleForReading.readDataToEndOfFile(); process.waitUntilExit()
    let lines = String(data: output, encoding: .utf8)?.split(separator: "\n") ?? []
    let records = lines.compactMap { try? JSONSerialization.jsonObject(with: Data($0.utf8)) as? [String: Any] }
    let row = records.compactMap { $0["data"] as? [String: Any] }.first
    if let encoded = row?["artworkData"] as? String, !encoded.isEmpty {
        guard let data = Data(base64Encoded: encoded), artworkLightColor(data) != nil else { fatalError("current artwork tint failed") }
        print("current artwork tint test passed")
    } else { print("current artwork unavailable; tint test skipped") }
