    let conversationB = AgentSessionKey(source: "", id: personalAssistantAnimationID(UUID(uuidString: "00000000-0000-0000-0000-000000000002")!))
    precondition(AgentFaceIdentity(session: conversationB, mood: 1).change(from: AgentFaceIdentity(session: conversationA, mood: 1)) == .session)
