    precondition(moodMemory.observe(conversationB, mood: 4, now: 110) == 110)
    precondition(moodMemory.observe(codexMood, mood: 4, now: 100) == 100)
    precondition(moodMemory.observe(codexMood, mood: 4, now: 110) == 100)
    precondition(moodMemory.observe(claudeMood, mood: 4, now: 110) == 110)
    precondition(moodMemory.observe(codexMood, mood: 1, now: 111) == 111)
    precondition(moodMemory.observe(codexMood, mood: 1, now: 90) == 90)
