    precondition(moodMemory.resumeWeight(codexMood, mood: 1, now: 102.0) == 1)
    precondition(abs(moodMemory.resumeWeight(codexMood, mood: 1, now: 102.25) - 0.5) < 0.0001)
    precondition(moodMemory.resumeWeight(codexMood, mood: 1, now: 102.4) == 0)
    precondition(moodMemory.resumeWeight(claudeMood, mood: 1, now: 102.25) == 0)
