    precondition(!moodMemory.isResuming(codexMood, mood: 1, now: 100.9))
    precondition(!moodMemory.isResuming(claudeMood, mood: 1, now: 101.5))
    _ = moodMemory.observe(codexMood, mood: 3, now: 103)
    _ = moodMemory.observe(codexMood, mood: 1, now: 104)
