    precondition(moodMemory.previousResumeWeight(codexMood, old: 2, new: 5) == 0)
    precondition(moodMemory.previousResumeWeight(claudeMood, old: 1, new: 5) == 0)
    _ = moodMemory.observe(codexMood, mood: 5, now: 105.3)
    precondition(abs(moodMemory.previousResumeWeight(codexMood, old: 1, new: 5) - 0.5) < 0.0001)
    _ = moodMemory.observe(codexMood, mood: 0, now: 105.4)
    precondition(moodMemory.previousResumeWeight(codexMood, old: 1, new: 5) == 0)
    for index in 0..<140 { _ = moodMemory.observe(AgentSessionKey(source: "codex", id: "fixture-\(index)"), mood: 1, now: 200) }
    precondition(moodMemory.count <= 128)
    let timedCue = NotchLightCue(kind: .clipboard, started: cueReference.addingTimeInterval(-0.3),
                                 referenceDate: cueReference, referenceUptime: 20)
    guard abs(timedCue.elapsed(at: 20) - 0.3) < 0.0001,
          abs(timedCue.elapsed(at: 20.4) - 0.7) < 0.0001,
          timedCue.elapsed(at: 19) == 0 else { fatalError("light cue monotonic timing failed") }
    let heldCue = NotchLightCue(kind: .caseKey(.shiftHeld), started: cueReference,
                                referenceDate: cueReference, referenceUptime: 20)
    let releasedCue = heldCue.releasingShift(at: 30)
    guard heldCue.duration.isInfinite, heldCue.shiftReleaseFade(at: 30) == 1,
          releasedCue.id == heldCue.id, abs(releasedCue.duration - 10.2) < 0.0001,
          abs(releasedCue.shiftReleaseFade(at: 30.1) - 0.5) < 0.0001,
          releasedCue.shiftReleaseFade(at: 30.3) == 0 else { fatalError("shift light release timing failed") }
    precondition(notchEventEnvelope(heldCue, at: 30) == 1)
    precondition(notchEventEnvelope(releasedCue, at: 30) == 1)
    precondition(abs(notchEventEnvelope(releasedCue, at: 30.1) - 0.5) < 0.0001)
    precondition(notchEventEnvelope(releasedCue, at: 30.3) == 0)
    precondition(notchEventEnvelope(releasedCue, at: .nan) == 0)
    let enabledEffect = NotchLightCue(kind: .agentQuestion, started: Date())
    let hiddenCopy = NotchLightCue(kind: .clipboard, started: Date())
    let hiddenPaste = NotchLightCue(kind: .shortcut(.paste), started: Date())
    precondition(lightCueEvictionIndex([heldCue, enabledEffect, hiddenCopy], isEnabled: { $0 != .clipboard }) == 2)
    precondition(lightCueEvictionIndex([heldCue, enabledEffect, hiddenPaste], isEnabled: { $0 != .shortcut(.paste) }) == 2)
    precondition(lightCueEvictionIndex([heldCue, enabledEffect, hiddenCopy], isEnabled: { _ in true }) == 1)
    precondition(lightCueEvictionIndex([heldCue], isEnabled: { _ in false }) == nil)
    let hiddenScreenshot = NotchLightCue(kind: .screenshot, started: Date())
    precondition(lightCueEvictionIndex([heldCue, enabledEffect, hiddenScreenshot], isEnabled: { $0 != .screenshot }) == 2)
    shortcutDefaults.set(false, forKey: "rium.light.screenshot")
    precondition(!lightCueEnabled(.screenshot, defaults: shortcutDefaults) && lightCueEnabled(.agentQuestion, defaults: shortcutDefaults))
    shortcutDefaults.set(false, forKey: "rium.light.agent")
    precondition(!lightCueEnabled(.agentQuestion, defaults: shortcutDefaults))
    let heldModel = Model(startServices: false)
    heldModel.caseKeysEnabled = true
    heldModel.showCaseKeyPeek(.shiftHeld)
    guard heldModel.caseKeyPeek == .shiftHeld, heldModel.activeLightCues.last?.duration.isInfinite == true else { fatalError("shift hold did not start") }
    let heldID = heldModel.activeLightCues.last?.id
    heldModel.showCaseKeyPeek(.shiftHeld)
    guard heldModel.activeLightCues.count == 1, heldModel.activeLightCues.last?.id == heldID else { fatalError("duplicate shift hold was installed") }
    heldModel.showCaseKeyPeek(.capsOn)
    RunLoop.current.run(until: Date().addingTimeInterval(1.2))
    guard heldModel.caseKeyPeek == .shiftHeld else { fatalError("temporary caps preview hid a held shift") }
    for _ in 0..<7 { heldModel.showLight(.calendarAdded) }
    guard heldModel.activeLightCues.count == 6,
          heldModel.activeLightCues.contains(where: { $0.kind == .caseKey(.shiftHeld) && $0.duration.isInfinite }) else { fatalError("shift hold was evicted by overlapping cues") }
    heldModel.endShiftKeyPeek()
    guard heldModel.caseKeyPeek == nil,
          heldModel.activeLightCues.contains(where: { $0.kind == .caseKey(.shiftHeld) && $0.duration.isFinite }) else { fatalError("shift hold did not release") }
    let releasedHold = heldModel.activeLightCues.first { $0.kind == .caseKey(.shiftHeld) }
    heldModel.endShiftKeyPeek()
    guard heldModel.activeLightCues.filter({ $0.kind == .caseKey(.shiftHeld) }).count == 1,
          heldModel.activeLightCues.first(where: { $0.kind == .caseKey(.shiftHeld) })?.id == releasedHold?.id else { fatalError("repeated shift reset changed its release") }
    model.showLight(.clipboard)
    let first = model.lightCue?.id
    RunLoop.current.run(until: Date().addingTimeInterval(0.1))
    model.showLight(.airDrop)
    guard model.lightCue?.id != first else { fatalError("new light cue was not installed") }
    RunLoop.current.run(until: Date().addingTimeInterval(0.9))
    guard model.lightCue?.kind == .airDrop else { fatalError("old cue cleared newer light") }
    RunLoop.current.run(until: Date().addingTimeInterval(1.2))
    guard model.lightCue == nil else { fatalError("light did not stop") }
