} else if CommandLine.arguments.contains("--self-test-hover") {
    let model = Model(startServices: false)
    let suspendedModel = Model(startServices: false)
    suspendedModel.autoHideDelay = 0.1; suspendedModel.expanded = true; suspendedModel.handleHover(false)
    suspendedModel.setHoverSuspended(true); suspendedModel.handleHover(false)
    RunLoop.current.run(until: Date().addingTimeInterval(0.2))
    guard suspendedModel.expanded else { fatalError("suspended hover changed the notch") }
    suspendedModel.setHoverSuspended(false); suspendedModel.handleHover(false)
    RunLoop.current.run(until: Date().addingTimeInterval(0.2))
    guard !suspendedModel.expanded else { fatalError("hover did not resume") }
    precondition(hoverTransitionAllowed(inside: true, expanded: false, hoverEnabled: true, autoHide: true, interactionLocked: false, pointerInside: true))
    precondition(!hoverTransitionAllowed(inside: true, expanded: false, hoverEnabled: true, autoHide: true, interactionLocked: false, pointerInside: false))
    precondition(!hoverTransitionAllowed(inside: false, expanded: true, hoverEnabled: true, autoHide: true, interactionLocked: false, pointerInside: true))
    precondition(!hoverTransitionAllowed(inside: false, expanded: true, hoverEnabled: true, autoHide: true, interactionLocked: true, pointerInside: false))
    precondition(!hoverTransitionAllowed(inside: false, expanded: true, hoverEnabled: true, autoHide: false, interactionLocked: false, pointerInside: false))
    precondition(hoverTransitionAllowed(inside: false, expanded: true, hoverEnabled: false, autoHide: true, interactionLocked: false, pointerInside: nil))
    let reference: TimeInterval = 1000
    guard hoverReopenWait(lastCollapse: nil, now: reference) == 0,
          abs(hoverReopenWait(lastCollapse: reference, now: reference + 0.1) - 0.24) < 0.0001,
          hoverReopenWait(lastCollapse: reference, now: reference - 3600) == 0,
          hoverReopenWait(lastCollapse: reference, now: reference + 0.33) == 0 else { fatalError("hover cooldown calculation failed") }
    model.handleHover(true)
    guard model.expanded else { fatalError("initial hover did not open immediately") }
    model.handleHover(false); RunLoop.current.run(until: Date().addingTimeInterval(0.1)); model.handleHover(true)
    RunLoop.current.run(until: Date().addingTimeInterval(0.45)); guard model.expanded else { fatalError("reentered hover collapsed") }
    model.handleHover(false); RunLoop.current.run(until: Date().addingTimeInterval(0.5))
    guard !model.expanded else { fatalError("hover collapse failed") }
    model.handleHover(true); guard !model.expanded else { fatalError("reopen cooldown skipped") }
    model.handleHover(false); RunLoop.current.run(until: Date().addingTimeInterval(0.4))
    guard !model.expanded else { fatalError("cancelled reopen expanded") }
    model.handleHover(true); guard model.expanded else { fatalError("hover did not reopen after cooldown") }
    model.autoHideEnabled = false; model.handleHover(false); RunLoop.current.run(until: Date().addingTimeInterval(0.5))
    guard model.expanded else { fatalError("disabled auto-hide collapsed") }
    model.expanded = false; model.hoverEnabled = false; model.handleHover(true); RunLoop.current.run(until: Date().addingTimeInterval(0.4))
    guard !model.expanded else { fatalError("disabled hover expanded") }
    model.expanded = true; model.autoHideEnabled = true; model.handleHover(false)
    RunLoop.current.run(until: Date().addingTimeInterval(0.5))
    guard !model.expanded else { fatalError("automatic close incorrectly depended on hover opening") }
    model.hoverEnabled = true; model.autoHideEnabled = true; model.expanded = true
    model.handleHover(false); model.beginMenuTracking(); model.beginMenuTracking()
    RunLoop.current.run(until: Date().addingTimeInterval(0.5))
    guard model.expanded else { fatalError("pending hover closed a tracking menu") }
    model.handleHover(false); model.endMenuTracking(pointerInside: false)
    RunLoop.current.run(until: Date().addingTimeInterval(0.5))
    guard model.expanded else { fatalError("nested menu closed before root menu") }
    model.endMenuTracking(pointerInside: false)
    RunLoop.current.run(until: Date().addingTimeInterval(0.5))
    guard !model.expanded else { fatalError("notch stayed open after menu tracking ended outside") }
    model.expanded = true; model.beginMenuTracking(); model.handleHover(false); model.endMenuTracking(pointerInside: true)
    RunLoop.current.run(until: Date().addingTimeInterval(0.5))
    guard model.expanded else { fatalError("notch closed after menu ended inside") }
    model.beginHomeEdit(); model.handleHover(false)
    model.finishEditing(pointerInside: false)
    RunLoop.current.run(until: Date().addingTimeInterval(0.5))
    guard !model.expanded else { fatalError("notch stayed open after editing finished outside") }
    model.expanded = true; model.handleHover(false)
    model.expanded = false; model.expanded = true
    RunLoop.current.run(until: Date().addingTimeInterval(0.5))
    guard model.expanded else { fatalError("stale hover close overrode a newer expansion") }
    model.expanded = false; model.handleHover(true)
    model.expanded = true; model.expanded = false
    RunLoop.current.run(until: Date().addingTimeInterval(0.4))
    guard !model.expanded else { fatalError("stale hover open overrode a newer collapse") }
    model.expanded = true; model.handleHover(false); model.expanded = true
    RunLoop.current.run(until: Date().addingTimeInterval(0.5))
