        if let savedDelay = savedDelay { UserDefaults.standard.set(savedDelay, forKey: "rium.notch.autoHideDelay") }
        else { UserDefaults.standard.removeObject(forKey: "rium.notch.autoHideDelay") }
    }
    model.expanded = true; model.autoHideDelay = 0.1; model.handleHover(false)
    model.setAutoHideDelay(0.5, pointerInside: false)
