    guard model.expanded else { fatalError("old auto-hide delay closed the notch") }
    RunLoop.current.run(until: Date().addingTimeInterval(0.4))
    guard !model.expanded else { fatalError("updated auto-hide delay did not close the notch") }
    let savedAutoHide = UserDefaults.standard.object(forKey: "rium.notch.autoHide")
    defer {
        if let savedAutoHide = savedAutoHide { UserDefaults.standard.set(savedAutoHide, forKey: "rium.notch.autoHide") }
        else { UserDefaults.standard.removeObject(forKey: "rium.notch.autoHide") }
    }
