    model.handleHover(true); model.setAutoHideEnabled(false)
    RunLoop.current.run(until: Date().addingTimeInterval(0.4))
    guard model.expanded else { fatalError("disabling auto-hide cancelled a pending hover open") }
    model.autoHideEnabled = true; model.handleHover(false); model.setAutoHideEnabled(false)
    RunLoop.current.run(until: Date().addingTimeInterval(0.6))
    guard model.expanded else { fatalError("disabling auto-hide did not cancel a pending close") }
