    guard editor.expanded else { fatalError("home editor closed at the normal delay") }
    editor.handleHover(true)
    RunLoop.current.run(until: Date(timeIntervalSinceNow: 2.65))
    guard editor.expanded else { fatalError("home editor closed after pointer returned") }
    editor.handleHover(false)
    RunLoop.current.run(until: Date(timeIntervalSinceNow: 3.2))
    guard !editor.expanded, editor.homeEditing, layout.string(forKey: "rium.home.background") == "aurora" else {
