    try data.write(to: URL(fileURLWithPath: output), options: .atomic); print("light render self-test passed")
} else if CommandLine.arguments.contains("--self-test-timer-alarm-light") {
    _ = NSApplication.shared
    let model = Model(startServices: false)
    model.startTimer(1)
    RunLoop.current.run(until: Date().addingTimeInterval(1.1))
    model.updateTimer()
    guard let started = model.timerAlarmStartedAt else { fatalError("timer alarm did not start") }
    let content = TimerNotchLight(model: model, thickness: 2) { rect in
        Path { path in
            path.move(to: CGPoint(x: 10, y: rect.midY))
            path.addLine(to: CGPoint(x: rect.maxX - 10, y: rect.midY))
        }
    }
    let view = NSHostingView(rootView: content)
    let panel = NSPanel(contentRect: NSRect(x: -2000, y: -2000, width: 520, height: 60),
                        styleMask: [.borderless, .nonactivatingPanel], backing: .buffered, defer: false)
    panel.isOpaque = false
    panel.backgroundColor = .clear
    panel.contentView = view
    panel.orderFrontRegardless()
    defer { panel.orderOut(nil) }
    func litSpan(at age: TimeInterval) -> Int {
        let wait = max(0, started + age - ProcessInfo.processInfo.systemUptime)
        RunLoop.current.run(until: Date().addingTimeInterval(wait))
        guard let bitmap = view.bitmapImageRepForCachingDisplay(in: view.bounds) else { fatalError("alarm light render unavailable") }
        view.cacheDisplay(in: view.bounds, to: bitmap)
        let lit = (0..<bitmap.pixelsWide).filter { x in
            guard let color = bitmap.colorAt(x: x, y: bitmap.pixelsHigh / 2)?.usingColorSpace(.sRGB) else { return false }
            return (color.redComponent - color.blueComponent) * color.alphaComponent > 0.07
        }
        guard let first = lit.first, let last = lit.last else { fatalError("alarm light did not render") }
        precondition(abs(first + last - bitmap.pixelsWide) < 8, "alarm light drained off center")
        return last - first + 1
    }
    let early = litSpan(at: 2)
    let middle = litSpan(at: 15)
    let late = litSpan(at: 27)
    precondition(early > 0 && Double(middle) / Double(early) < 0.7 &&
                 Double(middle) / Double(early) > 0.35 && Double(late) / Double(early) < 0.25,
                 "alarm light failed to contract: \(early), \(middle), \(late)")
    print("alarm light rendered spans: \(early), \(middle), \(late) pixels")
} else if CommandLine.arguments.contains("--self-test-render-timer") || CommandLine.arguments.contains("--self-test-render-media-only") || CommandLine.arguments.contains("--self-test-render-media-timer") || CommandLine.arguments.contains("--self-test-render-monitor-badge") {
