            AgentActivity(id: "claude-01234567-89ab-cdef-0123-456789abcdef", project: "예시 프로젝트", state: "활동 감지", activity: "", source: "claude", recentActivities: ["파일 확인", "파일 수정", "웹 확인"], ageSeconds: 12)
